-- 경기도의회 행정사무감사 회의록(경기연구원 관련) 이관 데이터 (자동 생성: tools/import_audit.py)
-- 게시판 코드 audit. 여러 번 실행해도 중복되지 않습니다.
insert into public.boards (code,name,members_only,admin_only_write) values ('audit','행정사무감사',false,true) on conflict (code) do nothing;
create unique index if not exists posts_legacy_idx on public.posts ((attachments->>'legacy_id')) where attachments ? 'legacy_id';
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2025.11.11. 화요일] 기획조정실, 경기연구원 — 기획재정위원회 2025년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제11대 경기도의회 기획재정위원회</b> · 2025년도 행정사무감사(2025. 11. 07. ~ 2025. 11. 20.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=15289" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2025년도 경기도의회 행정사무감사
</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관: 기획조정실, 경기연구원
</p>
<p><hr /></p>
<p>일  시: 2025년 11월 11일(화)
</p>
<p>장  소: 기획재정위원회 회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시00분 감사개시)
</p>
<p><b>○ 위원장 조성환 </b> 의석을 정돈해 주시기 바랍니다. 계속해서 지방자치법 제49조 및 동법 시행령 제41조, 경기도의회 행정사무감사 및 조사에 관한 조례에 따라 어제에 이어 기획조정실, 경기연구원 소관에 관한 2025년도 행정사무감사를 시작하겠습니다.
</p>
<p style="padding-left:1.2em">  감사위원 여러분 그리고 공직자 여러분! 안녕하십니까? 기획재정위원회 위원장 조성환입니다. 어제에 이어 감사에 임해 주시는 위원님들과 허승범 기획조정실장님 그리고 경기도의 싱크탱크인 우리 경기연구원 정책개발과 도정개발에 힘쓰고 계시는데 우리 강성천 원장님과 관계공직자 여러분께 감사를 드립니다.
</p>
<p style="padding-left:1.2em">  오늘 이 자리에는 어제에 이어서 언론인이신 전국매일신문의 한영민 기자님, 일간경기의 김인창 기자님께서 취재 중이십니다. 감사말씀드립니다.
</p>
<p style="padding-left:1.2em">  그러면 감사 시작에 앞서 새로 출석하신 경기연구원장 및 관계자분들의 증인선서가 있겠습니다. 감사를 받는 강성천 경기연구원장과 각 부서장께서는 증인의 자격으로 소관 업무보고와 질의 답변에 앞서 선서를 하셔야 합니다. 선서를 하는 이유는 경기도의회가 2025년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위함입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제49조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조 규정에 의해 고발될 수 있으며 정당한 사유 없이 선서 또는 증언을 거부한 때에는 동법 규정 및 동 조례 제31조에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 아울러 형사소송법 제148조 근친자의 형사책임과 증언 거부 또는 제149조 업무상비밀과 증언거부에 해당하는 때에는 선서와 증언 그리고 서류제출을 거부할 수 있음을 함께 알려드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 증인 출석 여부를 확인하겠습니다. 새로 출석하신 피감사기관의 증인들께서는 모두 자리에서 일어나 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  강성천 경기연구원장님 나오셨습니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 박경철 경기연구원 부원장님 나오셨습니까?
</p>
<p><b>○ 경기연구원부원장 박경철 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 정대영 연구기획실장 나오셨습니까?
</p>
<p><b>○ 경기연구원연구기획실장 정대영 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 유정균 인구사회연구실장 나오셨습니까?
</p>
<p><b>○ 경기연구원인구사회연구실장 유정균 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 남지현 북부발전연구실장 나오셨습니까?
</p>
<p><b>○ 경기연구원북부발전연구실장 남지현 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 최준규 미래전략연구실장 나오셨습니까?
</p>
<p><b>○ 경기연구원미래전략연구실장 최준규 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 민철기 감사실장 나오셨습니까?
</p>
<p><b>○ 경기연구원감사실장 민철기 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 박인숙 행정지원실장 나오셨습니까?
</p>
<p><b>○ 경기연구원행정지원실장 박인숙 </b>네.
</p>
<p><b>○ 위원장 조성환 </b> 류시균 공공투자관리센터 소장 나오셨습니까?
</p>
<p><b>○ 경기연구원경기도공공투자관리센터소장 류시균 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 다음은 선서의 요령에 대해서 설명드리겠습니다. 선서는 증인들을 대표하여 강성천 경기연구원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하겠습니다. 다른 증인들께서는 그 자리에서 오른손을 들어주시면 되겠습니다. 그러면 증인들께서는 선서를 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 강성천 </b> 선서! 본인은 경기도의회가 지방자치법 제49조, 같은 법 시행령 제41조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2025년도 행정사무감사를 실시함에 있어 증인으로서 성실하게 감사를 받을 것이며 또한 증언을 함에 있어서는 지방자치법 시행령 제46조제6항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2025년 11월 11일 경기연구원장 강성천.
</p>
<p><b>○ 위원장 조성환 </b> 모두 자리에 앉아 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  이상으로 증인선서를 마치고 간부소개와 업무보고를 받도록 하겠습니다. 강성천 경기연구원장 나오셔서 간부소개와 업무보고를 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장 강성천 </b> 먼저 저희 경기연구원 발전을 위해 관심을 가지시고 항상 성원해 주시는 조성환 위원장님을 비롯한 기획재정위원회 위원님들께 깊이 감사드립니다. 오늘 기획재정위원회 위원님들을 모시고 2025년도 경기연구원 제387회 정례회 업무보고를 드리게 되어 매우 뜻깊게 생각합니다. 
</p>
<p style="padding-left:1.2em">  보고에 앞서 저희 연구원의 주요간부를 소개해 드리겠습니다.
</p>
<p style="padding-left:1.2em">  박경철 부원장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  류시균 경기도공공투자관리센터 소장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  정대영 연구기획실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  유정균 인구사회연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  남지현 북부발전연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  민철기 감사실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  최준규 미래전략연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박인숙 행정지원실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 경기연구원의 주요업무를 보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  제1쪽 일반현황입니다. 경기연구원은 1995년에 개원하여 경기도의 정책개발 기능을 수행하고 있습니다. 현재 연구원의 조직은 본원이 1부원장 12실 6부 5센터로 구성되어 있고 부설기관인 경기도공공투자관리센터가 3개 부로 구성되어 있습니다. 경기연구원의 인력은 정규직 정원 187명에 현원 166명, 비정규직인 기간제근로자 38명 등 총 204명이 현재 근무하고 있습니다. 조직도는 자료를 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  2쪽 예산현황에 대해 보고드리겠습니다. 올해 총예산 규모는 297억 원으로 일반회계 241억 원, 공공투자관리센터 특별회계 22억 원입니다. 일반회계 수입ㆍ지출 내역을 세부적으로 말씀드리겠습니다. 수입항목은 일반회계 241억 원 중 경기도 출연금이 200억 원으로 일반회계 예산의 82.9%를 차지하고 있습니다. 지출항목으로는 인건비가 119억 원으로 일반회계 예산의 49.1%를 차지하고 있으며 연구사업비는 62억 원으로 25.7%를 차지하고 있습니다.
</p>
<p style="padding-left:1.2em">  3쪽입니다. 경기연구원의 미션은 정책연구 및 개발을 통해 경기도민 삶의 질 향상과 경기도정 발전에 기여하는 것입니다. 연구원의 경영목표, 핵심가치, 전략과제 등은 자료로 갈음하겠습니다.
</p>
<p style="padding-left:1.2em">  4쪽입니다. 제가 경기연구원장으로 취임한 이후 30주년을 맞이하여 새로운 도약을 위해 경기연구원의 GRI 3대 혁신 방향인 GRI 2.0을 제시한 바 있습니다. 첫 번째는 네트워킹으로 국내외 연구 네트워크를 구축하여 글로벌 수준의 역량으로 업그레이드하는 것입니다. 
</p>
<p style="padding-left:1.2em">  5쪽입니다. 두 번째는 엑셀러레이팅으로 경기연구원이 경기도의 정책적 지원 기능을 대폭 강화하는 것입니다. 마지막으로 리포밍으로 연구원의 조직, 인사, 운영 시스템의 혁신을 통해 경기연구원이 정책환경 변화에 기민하게 대응하는 역동적인 싱크탱크로 재편하는 것입니다.
</p>
<p style="padding-left:1.2em">  6쪽 주요사업 추진현황에 대해 보고드리겠습니다. 연구과제사업 추진현황입니다. 저희 연구원의 연구과제사업은 연구과제와 이슈분석으로 구분됩니다. 먼저 연구과제는 경기도 및 경기도의회, 시군의 정책수요를 반영하여 총 183건을 수행하고 있으며 연말까지 정책수요에 따라 추가적인 연구과제에 착수할 예정입니다. 2025년 연구과제 운영현황은 아래 표를 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  7쪽입니다. 다음은 부서별 연구과제 추진현황을 간략히 보고드리겠습니다. 먼저 미래전략연구실은 도정 중점과제, 미래 이슈 발굴, 현안 분석 등의 연구를 수행하고 있으며 국내외 네트워크 구축, 경기도 미래 비전 및 중장기 전략 도출, 국제협력 연구 및 정책현안 대응 등을 담당하고 있습니다.
</p>
<p style="padding-left:1.2em">  8쪽입니다. 미래전략연구실의 주요 연구과제로는 공공부문 혁신을 위한 ESG 경영활성화 및 지표 연구, 근로시간 단축제도 정책실험 방안 연구 등이 있으며 총 20건의 연구과제를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음으로 9쪽과 10쪽입니다. 북부발전연구실은 균형발전지원센터, 경기북부특별자치도연구센터로 구성되어 있으며 경기북부 전략산업, 균형발전, DMZ 접경지역 등 경기북부 관련 주요 현안에 대한 연구를 수행하고 있습니다. 주요 연구과제로는 경기북부 평화경제특구 단계적 발전방안, 경기도형 역세권 고밀도 복합개발 모델 개발 및 사업화 방안 마련 용역 등이 있으며 총 15건의 연구를 수행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음으로 11쪽과 12쪽입니다. 산업통상연구실은 미래산업 대응, 산업정책 및 산업입지 관련 연구, 통상 및 국제경제 등의 연구를 수행하고 있습니다. 주요 연구과제로는 경기도 노후산업단지 진단과 활성화 추진전략, 경기북부 스마트 축산단지 조성방안 등이 있으며 총 19건의 연구를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  13쪽 그리고 14쪽입니다. 인구사회연구실과 인구영향평가센터는 저출생ㆍ고령화 대응을 위한 인구정책과 사회ㆍ복지ㆍ문화 등의 연구를 수행하고 있습니다. 주요 연구 과제로는 저출생에 따른 경기도 인구구조 변화 전망 및 대응방안, 안산시 1인가구 청년 지원 정책 방향 연구 등이 있으며 총 20건의 과제를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음으로 15쪽과 16쪽입니다. 기후환경에너지연구실은 탄소중립 및 재생에너지, 환경계획, ESG 등의 연구를 수행하고 있습니다. 주요 연구과제로는 경기 RE100 플랫폼 구축, 도민 참여형 에너지 수요관리 활성화 방안 등이 있으며 총 31건의 연구를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  17쪽과 18쪽입니다. 자치혁신연구실은 지방행정기구 및 제도 관련 연구, 인사조직, 지방재정, 재난안전관리체계 등의 연구를 수행하고 있습니다. 주요 연구과제로는 경기도 도비보조금제도 보조율의 효율성 개선방안 연구, 경기도 주민자치 활성화 방안 연구 등이 있으며 총 31건의 연구과제를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  19쪽과 20쪽입니다. 도시주택연구실은 도시계획, 도시재생 및 지역균형발전 등의 연구를 수행하고 있습니다. 주요 연구과제로는 경기도 빈집정보 활성화 방안 연구, 도심복합개발사업 지구지정 방안 연구 등이 있으며 총 18건의 연구를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  21쪽과 22쪽입니다. 모빌리티연구실은 교통 SOC, 대중교통, 첨단모빌리티 등에 관한 연구를 수행하고 있습니다. 주요 연구과제로는 The 경기패스 시행에 따른 사회ㆍ경제적 효과 분석, 수도권 내 시외버스 효율적 관리 방안 연구 등이 있으며 총 28건의 연구를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  23쪽 AI연구실에 대해 보고드리겠습니다. AI연구실은 AI 분야의 최신 트렌드와 연구수요에 대응하기 위해 신설된 연구실이며 현재 연구인력 채용을 진행하고 있습니다. AI연구실이 본격 가동되기 전까지 전 부서가 AI 연구에 전사적으로 대응하고 있으며 2026년 인력 보강 후 다양한 정책 분야에 AI 기술을 접목한 연구 기반을 구축하고자 합니다.
</p>
<p style="padding-left:1.2em">  24쪽입니다. 다음은 연구과제사업 중 이슈분석에 대해 보고드리겠습니다. 이슈분석은 도내ㆍ외 환경변화에 대한 선제적 대응을 위한 이슈&진단과 그리고 경기도 주요 현안에 대한 즉시적 대응을 위한 GRI리포트로 구성되어 있습니다. 현재 9월 말 기준 이슈&진단은 Policy Initiative를 포함하여 5건, GRI리포트는 기존 이슈브리프를 포함하여 132건이 완료되었습니다. 주요 GRI리포트 발간현황은 24쪽에 제시하였습니다. 
</p>
<p style="padding-left:1.2em">  25쪽 연구부대사업 추진현황에 대해 보고드리겠습니다. 연구부대사업은 정책세미나 및 포럼 운영, 의정연구 교류, 대외협력 교류, GRI 학술지 발간 등으로 구성됩니다. 먼저 저희 연구원은 AI, 국제통상, 스테이블 코인 등 주요 이슈에 대해 다양한 분야의 전문가들과 논의하는 정책세미나를 금년도는 총 40회 개최하였습니다. 추진현황은 25쪽에서 27쪽까지 표를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  28쪽입니다. 경기연구원은 의정역량 강화를 위한 경기의정포럼을 운영하고 있습니다. 올해는 총 4회를 운영하면서 경기도의회와 경기연구원 간 정책소통을 강화하였습니다. 또한 경기도의회와 경기연구원이 다양한 전문가들과 지역 현안을 논의하는 지역현안토론회는 총 10회를 개최하였으며 연구 네트워크 구축을 위한 MOU는 총 4건을 체결하였습니다. 추진현황 내역은 28쪽, 29쪽 표를 참조해 주시기 바랍니다.  
</p>
<p style="padding-left:1.2em">  30쪽입니다. 경기연구원은 사회적 책임을 위한 활동으로서 경기도교육청과 협업해 교육재능기부 프로그램을 운영하고 있습니다. 박사급 연구위원들이 도내 중고등학생들에게 다양한 분야의 교육강연을 기부하는 프로그램으로 올해 총 54건을 수행할 예정입니다. 또한 연구원은 한국연구재단 등 학술지 GRI 연구논총을 연 4회 발간하고 있으며 올해는 9월 말까지 총 39편이 게재되었습니다. 추진현황은 30쪽과 31쪽 표를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 32쪽 연구지원사업 추진현황입니다. 경기연구원은 연구지원사업의 디지털 혁신을 위해 디지털경영부를 신설하고 AI 기반 연구지원체계 고도화, 연구정보 디지털화, 노후 전산장비 교체 등을 추진하였습니다. 특히 전 직원에게 생성형 AI 서비스를 제공하여 연구 및 행정업무의 효율성을 강화하고 홈페이지에는 AI 챗봇 기반 연구자료 검색 서비스를 도입하여 연구자료에 대한 도민들의 접근성과 활용성을 제고하였습니다. 또한 전자책 서비스 확대, 연구보고서 인쇄 부수 최소화 등 ESG 경영 실천을 위한 노력도 지속적으로 기울이고 있습니다. 자세한 내용은 32쪽에서 34쪽 내용을 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  35쪽 연구기반사업 추진현황에 대해 보고드리겠습니다. 연구원은 직원들의 연구 및 행정업무 역량 강화를 위해 직무교육을 실시하였습니다. AI, 빅데이터 활용 등 수요가 많은 교육은 원내 집체교육을 실시하고 개인별로 직무에 필요한 교육은 별도 신청을 통해 수강하도록 운영하도록 하였습니다. 또한 직원 근무평가 시스템 구축을 통해 성과평가 과정을 전산화하고 성과평가체계 개선을 위한 용역도 추진하였습니다. 자세한 내용은 35쪽 자료를 참조해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  36쪽입니다. 다음으로 경기도공공투자관리센터에 대해 보고드리겠습니다. 공공투자관리센터는 투자사업 및 재정사업에 대한 심사 및 평가를 핵심으로 관련 네트워크 사업을 추진하고 있습니다. 경기도공공투자관리센터는 현재 투자심사 사전검토 및 관련 지원업무를 총 192건 수행하였습니다.
</p>
<p style="padding-left:1.2em">  37쪽입니다. 센터는 재정사업 평가를 통해 경기도가 추진하는 재정사업 총 717건을 평가하여 구조조정 및 정책 개선방안을 제시하였습니다. 민간투자사업에 대한 조사 및 지원도 수행하고 있습니다. 마지막으로 센터에서는 공공투자관리센터의 업무 역량 향상을 위하여 관련 주제를 선정하여 정책 및 지침연구를 총 7건 수행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  38쪽입니다. 경기도공공투자관리센터에서는 올해부터 수행사업에 대한 만족도 조사를 수행하고 있으며 전국지방공공투자관리센터 협의회 등 대내외 네트워크 확대 및 정보교류 강화도 추진하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 39쪽부터 41쪽입니다. 2024년도 행정사무감사 주요 조치결과에 대한 내용입니다. 관련 조치결과는 39쪽에서 41쪽을 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  42쪽부터 59쪽은 2024년, 2025년 연구과제 수행실적이며 마지막으로 60쪽부터 62쪽은 부서장 명단을 첨부하였습니다. 
</p>
<p style="padding-left:1.2em">  이상으로 저희 연구원의 제387회 정례회 업무보고를 모두 마치겠습니다. 오늘 행정사무감사에서 제기해 주실 위원님들의 귀중한 지적사항에 대해서는 기관 운영에 적극 반영하도록 하겠습니다. 경청해 주셔서 감사합니다.
</p>
<p><hr /></p>
<p>업무보고서(경기연구원) 
</p>
<p><hr /></p>
<p><b>○ 위원장 조성환 </b> 강성천 경기연구원장 수고하셨습니다.
</p>
<p style="padding-left:1.2em">  다음은 경기연구원의 2024년도 행정사무감사 지적사항에 대한 처리결과 보고 시간입니다만 효율적인 회의진행을 위해 의정자료 전자유통시스템에 업로드한 자료를 참고해 주시면 되겠습니다.
</p>
<p><hr /></p>
<p>검토보고서(2024년도 행정사무감사 지적사항 처리결과(총괄)) 
</p>
<p><hr /></p>
<p style="padding-left:1.2em">  다음은 질의 답변 순서입니다. 질의 답변은 기획조정실과 경기연구원 소관에 대해서 일괄적으로 실시하겠습니다. 오늘 본질의는 10분 이내로 하고 보충질의는 5분으로 하겠습니다. 일문일답 형식입니다, 참조해 주시고요. 위원님들의 질의사항 중에 구체적이고 실무적인 내용은 소관 부서장이 답변하셔도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후에 발언대로 나와 소속과 직ㆍ성명을 밝히고 답변을 해 주시면 되겠습니다. 그럼 질의에 앞서 자료 요청하실 위원님께서는 거수로 신청해 주시기 바랍니다. 이석균 위원님.
</p>
<p><b>○ 이석균 위원 </b> 남양주 이석균 위원입니다. 먼저 기획전략담당관의 지방소멸대응기금 24년~25년 집행률하고 역시 24년~25년 주민참여예산 성과율. 그리고 24년~25년에 명칭 공모사업하신 게 있으시면 공모사업명과 결과, 예산 집행내역 그리고 역시 24년~25년 기회전략담당관에서 발주한 경기도업체 계약 비율을 제출해 주시고요. 인구정책담당관께는 경기청년 기회사다리 금융사업 24년ㆍ25년 그리고 아빠스쿨, 베이비부머, 둘째 아이 돌보미 30만 원 지원사업에 대해서 해 주시고 AI 노인돌봄사업 결과보고서 해 주시기 부탁드립니다.
</p>
<p style="padding-left:1.2em">  경기연구원은 지난 3년 동안, 그러니까 24년 결과를 이제 25년 올해 발표한 것까지 해서 3년 동안 기관장과 기관의 경영평가 결과, 그거는 세부내역까지는 안 주셔도 돼요. 그냥 표로 간단하게 해서 등급 나온 거 얘기를 해 주시고요. 경기연구원 북부 이전에 대한 계획서하고 예산 부분을 해 주시기 바랍니다. 경기 RE100 플랫폼에 관한 임차내역하고 예산금액 이것까지 제출해 주시면 좋겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 이석균 위원님 수고하셨습니다. 또 자료 신청하실 위원님 계십니까? 이경혜 부위원장님.
</p>
<p><b>○ 이경혜 위원 </b> 고양 이경혜입니다. 기조실에 요청하겠습니다. 공공기관 이전에 관련해서 지금 현재 경기도에서 계획되고 있는 공공기관 이전 대상기관하고 그 기관에 대한 토지매입비 그리고 건축비 그리고 이전비용. 거기에 이전하는 인원ㆍ부서 이 내용을 넣고 거기에 그 부서가 이동을 하거나 전체가 가든 이사를 했을 경우에 그 이사에 대한 직원들의 처우ㆍ복지계획까지 넣어서. 그리고 계획하는 이전계획이 몇 년도에 해서 언제 끝나는지 이 연도 수까지 다 넣어서 구체적으로 세세하게 정리하셔 갖고 자료 부탁드리겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 이경혜 부위원장님 수고하셨습니다. 또 자료 요청하실 위원님, 박상현 위원님.
</p>
<p><b>○ 박상현 위원 </b> 최근 3년간 정규직을 포함한 무기계약직, 연구원, 행정직 인건비 및 복리후생 비교표하고요. 최근 3년간 이직률 및 사유별 적시해서 주시면 감사할 것 같고 세 번째로는 연구성과 도정 반영 현황 물론 지금 자료에 있지만 현황 및 인센티브 지급실적을 포함해서 좀 부탁드리겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 박상현 위원님 수고하셨습니다. 또 자료 요청하실 위원님 계십니까?
</p>
<p style="padding-left:1.2em">  위원님들께서 요구하신 자료는 신속히 작성하여 의정자료 전자유통시스템에 업로드하신 후에 우리 해당 위원님들께 알려주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  기조실장님, 이게 자료 요구 받으시면 부담되시죠? 회의 중간에 받으시면.
</p>
<p><b>○ 기획조정실장 허승범 </b> 뭐 그래도 최대한 빨리 신속하게 작성해서 제출하겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 이 자료들은 다 갖고 있는 거잖아요, 집행부에서? 데이터들이 다 있는 거지 않습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그런데 여기저기 이제 아마 그 기관별로 나눠져 있는 거라서요. 조금 시간은 걸릴 수 있는데 최대한 빨리 제출하겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그래서 어제도 말씀드렸지만 이 데이터 관리가 잘 되면 위원님들이 AI를 활용 자료 요구를 검색하시면 바로 자료가 나올 수 있는 시대지 않습니까? 챗GPT나 뭐 제미나이나 이런 AI를 활용하면 그 데이터만 공유되고 활용되는 시스템만 갖춰 놓으면 얼마나 간편하겠어요. 그래서 이런 부분들을 좀 기조실에서 방향을 잡고 AI국과 협력하셔서 자료 관리를 잘 해 주시면 좋겠다라는 말씀을 다시 한번 드립니다. 효율성이 상당히 증대될 수 있는 사안이거든요. 잘 그런 부분도 염두에 두시면 좋겠습니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 알겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그러면 본질의와 답변을 시작하도록 하겠습니다. 저희 사전에 협의한 대로 오늘은 이성호 위원님께서 먼저 질의해 주시겠습니다.
</p>
<p><b>○ 이성호 위원 </b> 용인 출신 이성호 위원입니다. 기조실장님께 질의드리겠습니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 기조실장입니다.
</p>
<p><b>○ 이성호 위원 </b> 요구자료 답변서 512페이지를 보시면 이번 소송심의위원회 개선사항 중에는 중요소송의 상소 여부 결정을 소송심의위원회에서 결정할 수 있도록 한 내용도 있는 거 아십니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 맞습니다.
</p>
<p><b>○ 이성호 위원 </b> 그런데 지금 소송사무처리 규칙 22조2항에서는 “소송주관부서장이 중요소송 지정을 소송총괄부서장에게 요청해야 한다.”고 되어 있습니다. 그런데 소송주관부서장의 요청이 없으면 중요소송의 지정을 할 수 없는 걸로 지금 그렇게 운영이 되고 있습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 아직 저희 소송심의위원회에서 중요소송 지정을 실제로 한 사례는 없는 건데요. 위원님 말씀하신 형태로라고 하면…….
</p>
<p><b>○ 이성호 위원 </b> 왜냐하면 이게 중요소송 지정은 이번부터 한 게 아니라 중요소송에 대한 지정은 계속 해 온 거거든요. 이번에 개정된 사항이 아니고요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 제가 말씀드린 건 소송심의위원회에서 결정하는 거를 아직 해 본 사례가 없다라는 말씀을 드린 거고요.
</p>
<p><b>○ 이성호 위원 </b> 근데 소송심의위원회 결정사항 중에는 중요소송에 대한 지정은 원래 있었습니다. 512페이지에 개선 전에 보시면 심의사항 중요소송 지정 있잖아요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 그렇습니다.
</p>
<p><b>○ 이성호 위원 </b> 지정 말고 이번에 바뀐 건 중요소송의 상소 여부 결정입니다. 지정은 원래부터 하고 있었던 거예요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네.
</p>
<p><b>○ 이성호 위원 </b> 그러니까 기존에 어떻게 하고 계셨냐는 거예요. 내용 파악을 좀 하고 계셔야죠, 지금.
</p>
<p style="padding-left:2.4em">    (관계공무원, 기획조정실장에게 개별설명)
</p>
<p style="padding-left:1.2em">  지금 여기 와서 이렇게 의논을 하시면 어떡합니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 죄송합니다. 담당 법무담당관 말에 따르면 소송 사업부서하고 총괄부서 법무담당관하고 협의해서 그렇게 진행했다고 합니다.
</p>
<p><b>○ 이성호 위원 </b> 그러니까 제가 지금 여쭤본 거는 소송주관부서장의 요청이 없으면 중요소송 지정을 못 하느냐고 그걸 물어본 거 아닙니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 지금 규정에는 그렇게 있다고 말씀 주셨고요. 제가 답변드리기로는 그래도 협의를 해서, 소송총괄부서장하고 사업부서장하고 협의를 해서 진행을 해 왔습니다.
</p>
<p><b>○ 이성호 위원 </b> 일단 그 규정상에는 요청이 있어야 하도록 되어 있지 않습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네.
</p>
<p><b>○ 이성호 위원 </b> 그래서 지금 2025년 1월부터 9월까지 항소 및 상고가 42건이나 있었는데 그중 중요소송이 1건도 없어서 상소 여부에 대해 1건도 심의를 하지 않았다고 돼 있지 않습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네.
</p>
<p><b>○ 이성호 위원 </b> 이거는 소송주관부서장 요청이 없었기 때문 아닙니까, 지금?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그래도 쟁점이 되는 주요 사업들은 저희 총괄부서에서도 다 확인을 하고 있기 때문에 필요하다고 했으면 협의를 통해서 지정을 할 수 있었던 걸로 생각되는데 특별히 쟁점이 되는 게 없었던 게 아닌가 싶습니다.
</p>
<p><b>○ 이성호 위원 </b> 지금 이 규정상으로는 결국 중요소송의 항소 및 상고 여부 결정에 대해서 소송주관부서장에게만 맡겨져 있는 걸로 보이는데 이에 대해서 좀 개선할 방안이 있습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 말씀하신 것처럼 현재로서는 원활하게 협의를 해서 진행을 하고 있지만 관련 규칙에, 관련 규정에 명확하게 정해 놓는 게 필요하다고 생각됩니다. 위원님 지적하신 대로 사업부서뿐만 아니라 총괄부서에서도 중요소송 지정과 관련해서는 의견을 제출할 수 있고 그게 협의가 될 수 있도록 그렇게 명문화하는 것을 고민하겠습니다.
</p>
<p><b>○ 이성호 위원 </b> 네, 그런 방향으로 좀 추진해 주시기 바라고요. 지금 중요소송의 기준이 뭔지는 아십니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 재정적으로 큰 영향이 있거나 행정적으로 도정에 큰 영향을 미칠 때 또 특별한 전문적인 지식이 필요한 사건 등이 중요소송으로 지정하는 요건이 되겠습니다.
</p>
<p><b>○ 이성호 위원 </b> 소송사무처리 규칙 22조1항에는 도의 행정 또는 재정에 중대한 영향을 미치는 사건, 소가가 30억 원 이상인 소송사건, 법규의 해석 또는 적용에 특별한 전문적 지식을 필요로 하는 소송을 위원회 심의를 거쳐 중요소송으로 지정할 수 있다고 되어 있습니다. 즉, 이와 같은 기준에 해당하더라도 소송주관부서장의 요청이 없거나 위원회에서 중요소송으로 판단하지 않으면 중요소송으로 지정하지 못하게 되어 있는 겁니다. 그래서 항소 및 상고 사건이 42건이나 있었음에도 중요소송은 1건도 지정되지 않은 것이고 이것은 항소나 상고 여부를 소송주관부서장이 결정했다는 것을 의미합니다. 지금 이 중요소송의 기준에 있어서 문제점이 뭐라고 생각하십니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> …….
</p>
<p><b>○ 이성호 위원 </b> 본 위원이 생각하기로는 중요소송의 기준 중에서 법규의 해석 또는 적용에 특별한 전문적 지식을 필요로 하는 소송이라고 되어 있는데 이 의미가 명확하지 않다고 생각이 듭니다. 어떤 의미입니까, 이게?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그 글자 그대로 그냥 일반적인 행정 사건하고 조금 달리 전문 분야와 관련된 그래서…….
</p>
<p><b>○ 이성호 위원 </b> 특별한 전문적 지식이라는 거는 규정하기가 어려운 거거든요, 이게. 누가 이걸 판단을 할 수가 있습니까? 불명확하고 자의적인 개념이 될 수밖에 없어요. 그리고 중요소송 지정을 모두 임의적 사항으로 해 놓죠, 지금. 소가 30억 이상이라도 중요하지 않다고 판단해 버리면 아무도 이거는 중요소송이 되지가 않습니다, 지금.
</p>
<p><b>○ 기획조정실장 허승범 </b> 위원님도 잘 아시겠지만 하천부지 편입과 관련된 거라든가 일반화된, 루틴화된 거는 금액이 크더라도 뭐 중요소송 지정하지 않아도 될 사안들이 많기 때문에 그런 것들을 고려한 게 아닌가 싶습니다.
</p>
<p><b>○ 이성호 위원 </b> 물론 이제 공동사업 시행자로 되어 있긴 하지만 그런 종류의 소송이라도 예를 들어서 여기 보면 270몇억짜리의 소가가 있는 것도 있고 그거는 이제 지금 이 소송뿐 아니라고 하더라도 그 결과가 향후에 어떤 동일한 이런 소송들 중에도 다 법적인 쟁점이 다른 것들이 많기 때문에 별도의 검토가 필요한 것들도 많고 소가가 몇백억이 되는 것도 있잖아요. 그걸 동일하게 그렇게 취급을 할 수는 없는 겁니다. 그래서 객관적으로 예를 들어 100억 이상이라든지 그런 명확한 기준으로 중요소송으로 지정될 요건을 지정하는 게 바람직하다고 생각이 듭니다. 그냥 이렇게 임의적으로 다 정해놔서 어떤 소송이든지 다 중요소송으로 지정 안 하면 끝나는 이런 식으로 하면 소송사무가 제대로 될 수가 없다고 생각이 드는데 이에 대해서 어떻게 생각하십니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 중요소송 지정과 관련해서 조금 더 체계적으로 그다음에 정작 중요한 게 관련 요건이나 사업부서의 제안이 없으면 누락되는 일이 발생하지 않아야 된다는 취지의 의견이신 것 같은데요. 그러면 저희 관련 규정 다시 한번 좀 타 기관이라든가 이런 것까지 다 고려를 해서 지정요건이나 지정방식과 관련해서는 개선이 필요한지 검토해 보고 위원님께도 다시 보고드리도록 하겠습니다.
</p>
<p><b>○ 이성호 위원 </b> 즉, 소가가 얼마 이상이라든지 소송결과에 따라서 도에 얼마 이상의 피해가 온다든지 뭐 파급효과 또 유사 소송에 따른 도의 피해가 얼마 예상된다든지 하는 객관적인 기준에 따라서 중요소송을 판단하고 그 기준에 해당할 경우에는 필요적으로 중요소송으로 지정하는 것이 필요합니다. 이에 대해서 적극적으로 검토해 주시기 바랍니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 알겠습니다.
</p>
<p><b>○ 이성호 위원 </b> 다음으로 이제 공공기관담당관님께 질문드리겠습니다.
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 네, 공공기관담당관 이문환입니다.
</p>
<p><b>○ 이성호 위원 </b> 답변서 387페이지를 보시면 최근 4개년 공공기관 경영평가 결과에 따른 성과급 지급내역에서 경기도주식회사의 경우에 기관 경영평가에 있어서는 2022년부터 2024년까지 도 지분 25% 미만을 이유로 평가대상에서 제외되었다가 2025년 평가대상에 포함됐죠?
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 네, 그렇습니다.
</p>
<p><b>○ 이성호 위원 </b> 그 이유는 뭔 겁니까?
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 25% 미만이더라도 그다음에 지자체가 한 2분의 1 정도 지원금이 지원되거나 아니면 출자ㆍ출연 심의위원회에서 평가할 필요성이 있다고 판단되면 심의를 거쳐서 대상에 포함될 수 있습니다.
</p>
<p><b>○ 이성호 위원 </b> 그중에 어떤 거에 포함이 되죠, 경기도주식회사?
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 지금 그거는 두 가지 다 포함됩니다, 코리아주식회사는요.
</p>
<p><b>○ 이성호 위원 </b> 그렇게 경기도주식회사의 경우에는 이제 기관 경영평가에 있어서는 평가대상에 포함됐지만 기관장 경영평가에 있어서는 아직도 평가대상에서 제외되고 있는 이유는 뭡니까?
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 그거는 출자ㆍ출연법에 지분 50% 미만 기관에 대해서는 기관장 평가를 하지 않도록 되어 있습니다.
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p><b>○ 이성호 위원 </b> 관련해서 추가질의 때 하겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 이성호 위원님 수고 많으셨습니다. 다음은 오창준 위원님 질의하시겠습니다.
</p>
<p><b>○ 오창준 위원 </b> 광주 출신 오창준 위원입니다. 기조실장님께 일단 질의드리겠습니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 기조실장입니다.
</p>
<p><b>○ 오창준 위원 </b> 기조실장님께서는 경기도청 직원게시판 ‘와글와글’이라고 알고 계십니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 알고 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 어떻게 글 좀 이렇게 올라오면 보세요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 뭐 종종 보고 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 그 게시판 존재 이유가 혹시 뭐라고 생각하시나요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 직원들 특히 이제 하위직급 직원들의 원활한 의사표시 또 의사소통 뭐 이런 거라고 생각하고 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 그게 바람직하게 잘 이루어지고 있다고 생각하시나요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 뭐 일부 부정적인 측면도 있지만 제가 판단하기로는 그 안에서 자정 작용도 이루어지고 있다고 생각합니다. 서로 오해하고 있던 부분이 해결되는 경우도 있고 물론 오해가 확산되거나 조금 안 좋은 방향으로 흐르기도 하는데 그거는 저희가 내부규정을 갖고 적절히 제어하고 있다고 생각합니다.
</p>
<p><b>○ 오창준 위원 </b> 내부규정을 가지고 적정히 조정하신다고 말씀하셨는데 제가 이번에 행정감사 준비하면서 자료 요청드렸을 때는 내부 관리하는 규정이나 뭐 그런 게 없다고 답변 주셨거든요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 그게 훈령 형태로 이렇게 명문화된 게 있는 건 아니고요. 게시판 앞에 가이드라인 형태로 돼 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 글의 삭제 규정이라든지 이런 규정들이 있으신데 안 주신 거예요? 그럼 왜 자료 요청했을 때 주시면 되는데. 공개할 수 없는 부분인가요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 아닙니다. 저희가 아예 그 게시판 첫 회에 삭제되거나 이래야 될 기준과 관련해서는 명문화해 놓은 게 있기 때문에 그건 제가 바로 제출하도록 하겠습니다.
</p>
<p><b>○ 오창준 위원 </b> 네. 제가 글 목록을 받았어요. 올해 한 9개월 치를 받았는데 그래서 이제 쭉 봤어요. 한 2,200개 정도 글이 있더라고요, 올해 올라온 게. 근데 글의 한 절반 이상은 이제 뭐 특정인을 욕을 하는 또는 뭐 불만을 토로하는 그런 내용의 글이었고 아까 실장님께서 말씀하셨던 그런 어떤 갈등 해소라든지 개선 요구라든지 이런 부분에 대해서는 그리 비중이 제가 이렇게 세어 봤을 때 그렇게 많지 않았어요. 한 30% 되지 않았는데 사실 그 정도면 순기능보다 좀 이렇게 악기능이 훨씬 비율상 많은 부분이 아닌가 그런 생각이 좀 들었거든요. 그래서 게시판이 관리가 되고 있는 게 맞는가 하는 생각이 좀 들더라고요. 이게 삭제 게시물도 제가 받아봤는데 몇 개 되지 않더라고요. 삭제 게시물이, 이 기준을 제가 못 받아봤으니까 정확히 어떤 기준으로 삭제하는지는 모르겠으나 이게 실시간으로 모니터링하면, 혹시 이 게시판을 실시간으로 모니터링하고 관리하시는 인원이 있나요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 담당 팀과 담당 직원이 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 담당 팀이 있어요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네.
</p>
<p><b>○ 오창준 위원 </b> 근데 그런 것 치고는 관리가 너무 안 된다는 생각이 들어서 이 게시물의 수위나 뭐, 제가 내용까지 보지는 못했어요. 저는 이제 직원이 아니라서 그런지 접근 권한이 없어서. 그런데 제목만 봤을 때도 이게 누구 특정인을 지정하고 뭐 약간 확인되지 않은 사실이 이렇게 무분별하게 올라와 있음에도 불구하고 그런 게시물들이 버젓이 남아 있다라고 생각이 드는데 그런 것들에 대해서 왜 관리가 안 되는지 한번 이유를 말씀 주시겠어요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 저희가 내부 관련된 규정을 만들어 놓기는 하지만 이해관계에 있는 사람들 또는 보기에 그 규정을 해석하는 데 있어서 조금씩은 다르게 해석할 수 있는 여지는 있다고 생각됩니다. 다만 저희가 특정인을 근거 없이 비방하거나 모욕하거나 이런 것들은 발견되는 즉시 다 삭제를 하고 있고요. 최대한 부작용은 최소화하면서 원활한 의사소통이 이루어지기 위해서 노력은 하고 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 그럼 하나 여쭤볼게요. 게시물에서 개선 요구나 이런 것들이 올라와서 그것들이 실사례로 반영된 예시를 좀 들어주실 수 있어요? 생각나시는 게 있나요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 제가 얼른 기억나는 건 없지만 총무부서나 인사부서와 관련해서 직원들 불편해하는 것들, 이런 것들은 바로바로 해당 부서에서 답변해 주고 필요한 부분은 고치기도 하고 그러는 걸로 알고 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 지금 게시판을 운영한 지가 5년이 넘었습니다. 이게 2019년인가 18년도, 18년도 말인가요? 그때 만들어진 걸로, 이재명 전 지사 임기 초에 만들어졌던 걸로 기억하는데…….
</p>
<p><b>○ 기획조정실장 허승범 </b> 그렇습니다.
</p>
<p><b>○ 오창준 위원 </b> 그럼 거의 7년 가까이 됐는데, 6~7년 됐는데 실장님께서 생각나는 개선점이 하나도 없다라고 말씀하시는 건…….
</p>
<p><b>○ 기획조정실장 허승범 </b> 하나도 없다고 말씀드리지는 않았습니다.
</p>
<p><b>○ 오창준 위원 </b> 아니, 생각나는 게 없다고 말씀하셨어요. 저 하나도라고 말씀드리지 않았어요. 생각나는 건이 없다라고 말씀하신 건 그만큼 어떤 임팩트 있는 개선이나 이런 것들이 없었다 그렇게 볼 수 있지 않겠습니까? 지금 말씀하셨지만 기억나시는 거 없다고 하셨잖아요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 근데 그 게시판을 통해서 얼마나 큰 이슈를 제기하고 해결해야 되는 건지는 좀 의문입니다만 직원…….
</p>
<p><b>○ 오창준 위원 </b> 아니요, 개선사항이 아까 말씀드렸지만 굉장히, 그래도 2,100개 중에 한 20~30%면 그래도 200개~300개에 대한 요구 글이나 이런 것들이 올라오는데 그런 것 중에서 어쨌든 관리자 직급에 계신 실장님께서 이렇게 뭘 개선하겠다, 어떤. 거기에 그렇다고 지사님이 직접 글을 다 치는 것도 아니잖아요. 그러면은 보시는 분들이 아무리 봐야 실장님, 국장님 정도 선에서 보는 건데 그걸 가지고 지사님께 보고를 한다, 이런 것들이 요구가 있었으니 바꿔 주십시오라고 얘기를 한다든지 그런 쪽으로 긍정적으로 활용되는 부분이 제가 보기에는 지금 미미, 실장의 답변을 들어보니까 더 그런 생각이 들거든요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 저는 뭐 그렇게 생각하지는 않습니다. 작은 불편이라도 직원들 입장에서는 공직생활하는 데 그걸 개선하는 게 큰 도움이 될 수 있는 거기 때문에 제가 기억을 못 한다고 그래서 그런 것들이 중요하지 않다거나 이렇게 생각하지는 않습니다.
</p>
<p><b>○ 오창준 위원 </b> 그러니까 저도 이 게시판을 당장 없애라 내일 폐지해라 이런 말씀을 드리는 게 아니라 잘 쓰겠다고 만들었는데 전혀 긍정적으로 활용되지 못하게 관리나 그런 부분들에서 많이 미흡한 것 같다. 그런 생각이 들어서 제가 말씀드리는 거고 일단 관리 규정이나 이런 거 주시는 자료는 제가 봐야겠습니다만 그 인원도 지금 팀이 한 팀이 담당을 해서 하고 있다고 하시는데……. 
</p>
<p><b>○ 기획조정실장 허승범 </b> 한 팀 전체가 하는 건 아닙니다.
</p>
<p><b>○ 오창준 위원 </b> 한 팀 전체는 아니고 그냥 관련 팀이 있고. 그러면 뭐 많아야 한 2명, 3명 있겠네요, 직접적으로 관리하시는 직원은.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 그거를……. 
</p>
<p><b>○ 오창준 위원 </b> 인원은 제가 1명인지 2명인지는 여쭙진 않겠지만 어쨌든 소수의 인원이 관리하고 있다 그렇게 이해를 하겠습니다. 일단은 그래서 그런 부분들 좀 신경 써서 이게 그러니까 아무리 좋은 기능이 있다고 좋은 순기능 이런 거 강조를 해도 이거에 의해서 누군가 1명이 피해를 보면 사실 굳이 그 게시판을 운영해야 될 이유가 없, 사실 작년에 행안부에서도 이슈가 한 번 있어서 언론에도 한 번 탄 적이 있었고 이게 와글와글을 제가 딱 포털에 검색을 했을 때 대부분 이슈가 되거나 언론화된 거는 다 거기서 나온 누군가에 대한 비방, 부정적인 것들만 사람들이 자극적인 거에 관심을 많이 가지셔서 그런지는 모르겠지만 그런 것들만 이슈가 돼요. 어떤 순기능에 대해서 이거를 칭찬하고 뭐 하는 글이 한 개도 없더라고요. 외부에서 시선으로, 언론이라는 외부의 시선으로 봤을 때는. 그런 부분들을 좀, 이게 잘 운영되려면 우리가 이런이런 개선들, 이 게시판을 통해서 이런이런 효과를 얻었고 이런 걸 개선했다 이런 것들을 알려야 존재의 필요성이 있구나 이게 인식이 되는데 밖에서 보는 인식은 내부에선 누구 욕하고 누구 비방하고 막 나쁜 거 확인되지 않은 사실 퍼뜨리고 이런 용도로만 쓰인다라고 지금 생각을 하니까 언론에서도 그렇게만 보도를 하는 거거든요. 그래서 그런 부분들 잘 챙기셔 가지고 관리하셨으면 좋겠고 그다음에 저희가 의회랑 도청이 인사권 분리된 지가 얼마나 됐습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 정확한 횟수로는……. 
</p>
<p><b>○ 오창준 위원 </b> 3년 좀 넘었습니다, 22년도에 저희가 분리가 됐으니까, 지방재정법 이후에. 지방관리 뭐야, 법 개정 이후에 바뀌었으니까. 근데 아직도 저희 게시판 같은 경우에는 같이 써요, 의회랑 도청이랑.
</p>
<p><b>○ 기획조정실장 허승범 </b> 와글와글 말씀하시는 건가요?
</p>
<p><b>○ 오창준 위원 </b> 네, 계속 이어서 질의드리는 겁니다. 근데 저희 사실 의회랑 도청은 협업을 하는 기관이긴 하지만 별도의 기관이거든요, 의회와 도청은. 근데 하나의 익명 게시판을 공유해서 저희가 쓰는 것도 사실 바람직하지는 않다. 이렇게 서로 어떤 내부적인 소식이나 이런 것들이 있을 것인데 그런 거를 공유하는, 근데 사실 그런 게시판을 통해서 공유하는 건 바람직하지 않지 않습니까? 저희가 내부의 소식이나 이런 걸 공문으로 서로 주고받고 이렇게 소통하는 거는 당연히 업무의 일환이지만 업무 외의 그 게시판을 통해서 서로 내부적인 얘기가 왔다 갔다 하는 게 의원으로서는 바람직하지 않은 것 같다, 의회 내부의 얘기도 그렇고 도청 내부의 얘기도 그렇고. 그래서 그 부분을 검토해 주셨으면 좋겠어요, 망을 좀 분리하는 거.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 말씀 주셨던 것들 장단점하고 또 직원분들 의견도 더 이렇게 다 감안해서 검토해 보도록 하겠습니다.
</p>
<p><b>○ 오창준 위원 </b> 네, 알겠습니다. 질의 마치겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 오창준 위원님 수고 많으셨습니다. 다음은 박상현 위원님 질의해 주십시오.
</p>
<p><b>○ 박상현 위원 </b> 부천 오쇠리 출신 박상현입니다. 존경하고 친애하는 오창준 위원님께서 와글와글 게시판에 대해서 일단 질의를 해 주셨기 때문에 여기에 대해서 조금 더 추가적인 질의를 통해서 진행을 해 보도록 하겠습니다. 실제로 경기도가 운영하는 와글와글 게시판들은 직원들이 조직에 있는 문제라든지 어떠한 개인에 관련된 문제를 직접적으로 제기하는 익명 게시판이지 않습니까? 그래서 이 자료를 먼저 보았을 때 이 자료에 게시된 건수가 2,188건이 와 있더라고요, 9개월간. 한 달에 한 200건 정도가 올라온다고 보여지고요. 하지만 이 많은 목소리들 중에서 우리 경기도청이 조직적으로 그런 목소리에 대해서 대응하는 것이 그닥 보이지가 않아서 이 대답이 없는 메아리 속에서 우리 직원분들에 관련돼서 그냥 그때그때마다 나오는 생각이나 분노와 이런 표출 방식이 현재 와글와글 게시판을 표방하는 것 같습니다. 게시판은 있는데 응답 체계가 없으니까 직원들은 불만이 좀 많아질 수가 있을 것 같고 실질적으로 조금 글도 일부 삭제가 되는 것도 확인됐으며 그런 것들이 비판적인 의견으로 치부되기도 하고 있죠. 그래서 이런 조직문화가 어떻게 보면 우리 상부, 위에 있는 분들께 외침을 하고 있는데 상부에 계시는 우리 고위공직자분들은 그것을 침묵으로 일관하는 일종의 약간의 조직문화가 그렇게 되어 있지 않을까라는 생각을 조금 하고 있었습니다. 다음 슬라이드를 한번 보여주세요. 
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  이 슬라이드는 2,000개의 제목을 가지고 한 겁니다. 약간 혹시 오해를 할 수 있지만 제가 이거 표를 작성한 것에 대해서 정확하게 말씀을 좀 드리면 이 표는 제가, 그러니까 오창준 위원님께서 받은 자료를 가지고 제목을 보고 내용을 유추하라라고 인공지능에게 시켰습니다. 그럼 제목을 보고 내용을 유추하게 되고요. 그러면 유추된 내용에 대해서 연관성이 50%가 넘는 글들이 있다면 연관 게시물로 분류를 하도록 했습니다. 그랬을 때 첫 번째로 가장 많은 것들이 어떤 거였냐 하면 청사환경 및 IT환경 개선이 총 360, 그러니까 추측입니다. 절대 내용은 아니고요. 360건이 청사환경 및 IT 관련된 문제 제기를 했고요. 두 번째가 210건으로 조직문화 및 인사 문제에 대해서 비판하는 글들이 좀 많이 올라왔던 것 같고 그다음에 195건이 도의회에 관련된 비판 내용이 좀 많이 있었습니다. 그다음에 185건이 복무수당 근무 제도인데 아까 오창준 위원님이 말씀하셨듯이 한 2,000건 중에서 한 1,000건 정도는 이렇게 우리 도의회나 도청에 관련된 불만이 가득한 게시물로 채워져 있는 것은 주지의 사실입니다. 우리가 그러면 이런 것을 인지하고 있다면 세부적인 내용들을 검토하면서 이렇게 체계적으로 분류하고 이것에 대해서 대응하는 조직이 있다면 좋았을 텐데 아직까지는 우리 직원분들에게 그 어떠한 솔루션이나 해결책을 제시하지 못하는 상황에 있는 것이 현재 와글와글 게시판 이 제도가 아닐까라고 생각이 됩니다.
</p>
<p style="padding-left:1.2em">  기조실장님께 여쭤보겠습니다. 혹시 이 와글와글 게시판에 대해서 모니터링하는 조직이 아마 3명 정도가 있다고 하는데 이 3명이서 실질적으로 개선하기 위한 회의 또는 보고 체계 또는 피드백 이러한 절차적으로 업무 매뉴얼이 있나요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 관리 운영계획은 내부 방침으로 정해놓은 게 있는데요. 지금 위원님이 말씀하셨던 문제로 받아들이고 이거를 관계부서랑 협의를 하고 솔루션까지 내는 그런 과정까지는 없는 걸로 알고 있습니다. 이게 직원들끼리 자유로운 의사소통 이 메인이고 그 안에서 이렇게 제시해 주신 것처럼 그런 불편들이 있으면 저희가 해당 부서에다 직원들이 이런 얘기 많이 하고 있으니까 “알려줘라.”, “답변 달아라.” 저희가 할 수 있는 건 저희가 달고. 이렇게 조금 느슨한 형태로 자연스럽게 하는 형태지 이거를 너무 형식화해서 운영하게 되면은 불필요한 일들도 많이 생기고 직원들도 좀 부담스러워하지 않을까 싶기도 합니다.
</p>
<p><b>○ 박상현 위원 </b> 어차피 익명 게시판이기 때문에 누가 올리는지는 알 수가 없지만 제가 말씀드리는 거는 이게 단발성, 일회성에 관련된 불만을 제기하는 글이라고 한다면 이렇게 한두 번 넘어갈 수 있는 일이지만 만약에 한 달에 200건씩 쌓이고 1년에 2,000~3,000건씩 쌓이는 불만 제기를 이런 식으로 DB화를 시켜서 체계화로 관리를 하게 된다면 우리 조직문화에 관련돼서 그 진단을 우리 기조실에서 할 수 있는 거고 그럼 기조실 입장에서는 다음과 같은 불만이 수천 건이 올라오니, 1년에 수천 건이고 5년만 돼도 수만 건이 될 수 있겠죠. 이런 것들에 대해서 파악을 하고 있으면 기조실 차원에서 우리 조직진단을 자연스럽게 할 수 있는 매우 소중한 데이터라고 생각이 되거든요. 그러면 이렇게 직원들에 관련된 이런 불만에 대해서 다수가 모인 의견들에 대해서는 다음과 같이 표로 분류할 수 있을 것 같은데 이런 것들에 대해서 어떻게 대응체계를 만들 수 있는 조직이나 아니면 매뉴얼이라든지 제도적으로 개선할 의지는 가지고 계십니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 사실 아까 위원님께서 이렇게 체계적으로 2,000여 건에 대해서 분석을 해 주시고 물론 속속들이 다 이렇게 읽어보고 하신 건 아니라고 하셨지만 그렇게 해 주신 걸 보고 사실 조금 깜짝 놀라고 진작에 저런 걸 했어야 되지 않을까 생각을 좀 했는데 이렇게 먼저 해 주셔서 감사드리고요. 
</p>
<p style="padding-left:1.2em">  내용 중에 진짜로 그냥 단순한 의견 교환이라든가 이런 게 아니고 반복적으로 계속되는 우리 조직이나 인사, 기타 업무환경과 관련된 거라면 그거는 저희가 정리를 해서 과연 이게 제대로 진짜 문제인지 확인을 하고 해결해야 될 이슈라고 생각하면 그거는 좀 따로 정리를 해서 관리를 하는 게 필요하다고 생각합니다.
</p>
<p><b>○ 박상현 위원 </b> 그래서 최소한 제가 요청드리는 건 어차피 저희가 생성형 AI 데이터 통합서버를 구축하고 있잖아요. 지금 많은 자료들이 계속 학습되고 있고 지금 시범 서비스까지 하고 있지 않습니까? 이런 상황에서 와글와글 게시판에도 굉장히 중요한 데이터, 익명이긴 하지만 매우 중요한 데이터이기 때문에 이런 불만 유형별로 통계적으로 분석을 해서 시스템적으로, 정기적으로 우리 와글와글 게시판에다가 보고를 하고 대체적으로 이번 달 우리 직원들에 관련된 의견이나 동향 같은 것들을 주기적으로 업데이트를 해 주고 이것에 관련된 대응 시스템 피드백 시스템을 만들면 매우 좋지 않을까 해서 이번에 좀 지적을 해 봤습니다. 
</p>
<p style="padding-left:1.2em">  그러면 우리 기조실장님이 와글와글 게시판에 대해서 AI국이랑 협조를 해서 그 데이터에 대해서 잘 정리해서 정기적으로 보고하는 시스템을 언제까지 마련할 수 있을지 그 대답을 좀 듣고 싶은데요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 지금 이제 문제 제기해 주신 거고 저도 처음 인식한 거라서 제가 이 자리에서 언제까지 하겠다고 말씀드리기는 어려울 것 같고요. 저희가 현황을 한번 좀 보고 이게 또 지금 위원님 말씀하신 형태로 일을 하게 되면 또 추가로 인력이 필요할 수도 있는 일이기 때문에 제가 한번 검토해 보고 다시 말씀드리겠습니다.
</p>
<p><b>○ 박상현 위원 </b> 네, 감사합니다. 
</p>
<p style="padding-left:1.2em">  그다음 경기연구원 부탁드리겠습니다.
</p>
<p><b>○ 경기연구원장 강성천 </b> 네.
</p>
<p><b>○ 박상현 위원 </b> 오전에 자료 요구를 한 것은 경기연구원에서 온 다양한 행정감사 자료를 보게 되면 제가 제일 먼저 지적하고 싶은 건 지난 2021년 감사 조치결과부터 2024년도까지 지속적으로 제기되어온 문제가 어떤 거냐 하면 직원들에 관련된 처우개선입니다. 우리 석사, 박사급 연구인력들에 관련된 처우가 좋지 않으면 경기연구원을 이끌어가고 있는, 실질적으로 정책 브레인 역할을 할 수 있는 석ㆍ박사 연구원님들에 관련된 유출, 이직률이 많게 되면 경기연구원에 관련된 능력이 떨어지게 되고 능력이 떨어지게 되면 경기도정에 관련된 정책 수준이 떨어지게 됩니다. 하지만 보내주신 행정감사 자료 보게 되면 직원 인센티브에 관련된 내용은 그 기준은 마련돼 있으나 실질적으로 우리 직원들에게 실지급된 인센티브에 관련된 금액이 적혀 있지는 않았었어요. 그래서 제가 자료 요구를 한 자료가 오게 되면 나중에 추가적인 질의를 하도록 하겠습니다, 원장님. 자료 빨리 부탁드리겠습니다.
</p>
<p><b>○ 경기연구원장 강성천 </b> 네, 알겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 박상현 위원님 수고하셨습니다. 
</p>
<p style="padding-left:1.2em">  실장님, 우리 오창준 위원님하고 박상현 위원님이 아주 저희가 미처 생각하지 못한 부분들을 잘 지적해 주신 것 같습니다. 커뮤니티의 기능은 소통을 활성화하고 정말 조직에 긍정적인 요인으로 잘 주는 부분의 순기능도 있지만 때로는 역기능, 부작용들도 발생할 수밖에 없거든요. 그래서 그런 부분들이 잘 관리돼야 되는데 시대가 지금 급속히 변하다 보니까 커뮤니티의 기능이라든지 내용이라든지 방향성도 급변하는 것 같아요, 사회의 흐름과 가치. 그런 차원에서 제가 올 4월에 가짜 뉴스의 폐해에 대한 지적과 5분발언을 한 적이 있는데 혹시 이런 커뮤니티를 통해서 가짜 뉴스들이 유포되거나 어떤 그로 인한 피해들이 발생하는 일들도 있나요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 일부 오해의 소지가 있었던 그런 게시물들은 있었던 걸로 알고 있습니다. 사회적으로 크게 문제가 되지는 않았지만 저희 도 집행부나 의회 쪽에서 특정 게시물로 인해서 조금 오해의 소지가 있어서 그런 것들은 저희가 삭제하고 그다음에 그런 것들이 다시 일어나지 않도록 이용자들한테 안내한 경우는 있었던 걸로 기억합니다.
</p>
<p><b>○ 위원장 조성환 </b> 그래서 그런 부분들이 주기적으로 좀 돼야 될 것 같다. 특히 가짜 뉴스 유포는 범죄행위입니다, 범죄. 가짜 뉴스로 인한 피해는 우리 누구나 될 수 있기 때문에 그런 것에 각별히 명심하시고 그거는 조직 내 문화 속에서도 그러한 위험성을 고지하고 미디어 리터러시 교육을 한다거나 이런 대책들이 꼭 수반돼야 되거든요. 그럴 때 그런 순기능들이 제대로 동작을 하는 거지 이런 역기능적인 부분들이 더 커지면 존립에 대한 고민까지도 할 수 있는 부분이니까 그런 부분들에 대해서는 특별히 미흡하면 조치를 해 주시고 앞으로의 대책도 좀 마련해 주시기 바랍니다. 말씀하실 거 있으면 말씀하십시오.
</p>
<p><b>○ 기획조정실장 허승범 </b> 아닙니다.
</p>
<p><b>○ 위원장 조성환 </b> 자료가 뭐 온 거 아니에요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 아닙니다. 위원장님이 약간 균형 있게 양쪽 다 순기능과 역기능 다 말씀해 주셔서 저희는 순기능 활성화하고 역기능은 최대한 억제하는 방향으로 필요한 조치를 좀 하도록 하겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그러니까 역기능을 해소하는 다양한 방법들도 있어요. 글에 대한 부정적인 글들을 평가를 하면 그게 해우소로 넘어간다든지 또 아니면 아까 말씀하신 어떤 조직의 긍정적인 발전을 위해서 분리하는 부분도 매우 중요한 것 같아요. 와글와글에 대항하는 또 새로운 신제품이 나와야 되지 않습니까? 저희가 농담처럼 얘기했지만 ‘부글부글 게시판도 좀 하나 있어야 되지 않냐. 와글와글만 하면 뭐 하냐.’ 이런 농담도 했는데 그런 것도 다양하게 좀 고민을 해 보시면 좋겠다 그렇게 말씀을 드리겠습니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 알겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 다음은 이혜원 부위원장님 질의하시겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 양평군 출신 이혜원 위원입니다. 먼저 기획조정실장님, 지방채 관련해서 질의를 좀 드리겠습니다. 지방재정법 제11조제2항에 “재정 상황과 채무 규모 등을 고려해서 대통령령으로 정하는 지방채 발행 한도액 범위 내에서 지방의회의 의결을 받아야 한다, 의결을 얻어야 한다.”라고 규정되어 있습니다. 그렇죠?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 그렇습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그런데 우리 경기도는 예산안에 포함해서 심의ㆍ의결을 하고 있는 것 같습니다. 저희가 기재위인데 별도로 기재위에서 지방채 관련된 심의를 한 적이 별도로 없거든요. 왜 그렇게 진행을 하고 계시는 걸까요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 행안부 가이드라인 훈령에 따르면 예산안 의결로 갈음할 수 있도록 돼 있어서 그렇게 진행해 왔습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그러니까 행정안전부 지방채 발행계획 수립 기준 말씀하시는 건가요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 지방채, 네.
</p>
<p><b>○ 이혜원 위원 </b> 근데 이게 상위법인 지방재정법에 저촉한다라고 느껴지는데 지방재정법이 상위법이잖아요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 그렇습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그러면은 이거 지방재정법에서는 심의ㆍ의결을 받아야 한다고만 되어 있고 별도라는 얘기가 없어서 그렇게 해석을 하시는지 모르겠으나 타 시도나 광역 같은 경우에 지방채의 경우에는 별도로 심의를 하는 곳이 많습니다, 지방의회도 그렇고. 그런데 경기도 같은 경우는 예산안을 진행할 때 하기 때문에 지금, 더군다나 경기도 같은 경우는 19년 만에 지방채가 다시 발행이 되고 있고 또 올해 같은 경우는 벌써 두 번째 발행이잖아요, 3회 추경까지 하게 되면. 내년에 또 계획이 있고 이렇게 되다 보면 이 규모가 상당하게 지금 커지고 있는 상황이고 또 이미 지방채로 인해서 상환에 대한 계획 수립이나 이런 것들도 필요한 부분이고 또 지방채를 어떻게 활용해야 될지에 대한 부분들도 명확해야 되기 때문에 별도의 심의가 좀 필요하다라고 고려를 해 볼 만한데 기조실장님 의견은 어떠십니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 위원님 말씀해 주셨던 것처럼 인천이나 제주 같은 경우는 우리 출자ㆍ출연기관 동의안처럼 예산 이전에 동의를 받고 있는 사례가 있습니다. 그래서 조금 더 의회의 재정 통제라든가 또 예측 가능성을 높이기 위해서는 의미 있는, 사전에 동의를 받는 것도 일리 있는 절차라고 생각합니다.
</p>
<p><b>○ 이혜원 위원 </b> 충분히 고려하셔서 이제는 이렇게 처음 있는 것이 아니라 지속적으로 발생되고 있고 규모가 커지고 있는 상황이기 때문에 지방채 발행계획안 형태에 대한 부분으로 안건을 별도로 상정해서 심의에 대한 부분을 의회에서 의결하고 심의할 수 있도록 이렇게 진행절차를 좀 정리해 봐 주셨으면 좋겠습니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 저희도 아까 말씀드렸듯이 법 해석하고 있는 행안부에서 그렇게 훈령으로 운영을 하고 있는데요. 위원님들 아예 그냥 조례로 명문화해서 그렇게 하는 것도 좋은 방법이 아닐까 생각됩니다.
</p>
<p><b>○ 이혜원 위원 </b> 네, 필요하면 제가 조례 검토해서, 조례에 대한 부분은 개정할 부분에 대해서 검토를 할 예정이고요. 어디에서는 이제 행안부 지침이 지방재정법에 저촉한다라고도 해석이 나오기도 하기 때문에 조례로 실장님 말씀대로 좀 정리를 해서 진행하는 것도 의미가 있을 것으로 사료가 됩니다. 진행을 할 때 기조실에서도 적극적으로 협조를 좀 해 주시기 바랍니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 알겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 다음은 경기연구원에 질의하도록 하겠습니다. 원장님, 지금 경기연구원이 임차와 업무환경 조성이 완료가 됐습니까? 북부 이전하는 부분에 대해서 질문드립니다.
</p>
<p><b>○ 경기연구원장 강성천 </b> 지금 진행을 하고 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 진행하고 있는 겁니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 임차는, 임차 계약은 체결했습니다. 그리고 근무환경 개선을 위한 인테리어 공사나 이런 부분들은 지금 절차가 진행 중입니다.
</p>
<p><b>○ 이혜원 위원 </b> 진행 중입니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 그렇습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그런데 인사는 결정이 됐나요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 인사는 아직 결정이 안 됐습니다.
</p>
<p><b>○ 이혜원 위원 </b> 안 됐고 지금 진행하고 계십니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 그렇습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그러면 지금 저한테 제출하신 내용에서 경기도의 의견이 있고 경기도연구원의 의견이 있습니다. 그 의견에 대한 부분에 대해서, 지금 제가 다른 위원님들도 마찬가지겠지만 제보가 너무 많이 들어왔어요. 시행하기 전에 업무환경이 결정되지 않은 상황에서 어떤 인사발령에 대한 부분들이 이루어지고 있고 그 기준에 대한 부분이 불분명해서 이 기준성에 대한 의구심도 들고 또 어떤 환경적인 부분이나 정주여건에 대한 부분들이 마무리가 안 된 상태에서 지금 진행되고 있다라는 부분들이거든요. 거기에 대해서 연구원장님으로서의 의견은 어떠신가요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 저희들은 부분이전 과정에서 직원들과 충분히 상의하면서 그리고 투명하게 진행하는 것을 원칙으로 하고 있고요. 그런 절차를 진행해 왔습니다. 다만 전 직원이 만족하는 인사방안이나 근무형태에 대한 안은 아직은 만들지는 못했습니다. 그래서 저희가 아직 시간이 조금 있기 때문에 더 협의를 해 나가겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그러면 질의 좀 드리겠습니다. 인사발령 방식이 직군별로 상이하다라는 의견도 좀 있고요.
</p>
<p><b>○ 경기연구원장 강성천 </b> 그렇습니다.
</p>
<p><b>○ 이혜원 위원 </b> 직군별로 근무형태가 좀 차등 적용이 되고 있다. 행정직은 주 1회, 연구직은 2~3개월 단위로, 이게 무슨 뜻일까요? 2~3개월 단위로 그럼 북부 이전을, 북부에서 근무했다가 본원에서 근무했다가…….
</p>
<p><b>○ 경기연구원장 강성천 </b> 아, 그게 이렇게 이해하시면 되겠습니다. 그래서 원칙은 원장을 포함한 원장 직속부서, 그러니까 미래전략실ㆍ감사실을 포함한 원장 직속부서는 원칙으로 이전을 하고 그리고 기타 부서에 있는 직원들은 순환근무 형태로 가겠다라는 것이 저희들이 당초에 정한 원칙이었고요. 그래서 순환근무를 그럼 어떤 형태로 할 것인가에 대한 여러 가지 대안들이 논의되었습니다. 그래서 직군에 따라서 또 업무의 특성에 따라서 근무하는 여러 가지 방식이 제안됐고요. 거기에 대한 의견들이 완전히 합의가 되어 있는 사항은 아닙니다.
</p>
<p><b>○ 이혜원 위원 </b> 그럼 지금 여기 절차를 노사단체 교섭회의하시고 전 직원 설명회도 한 번 있었고 또 전 직원 의견 수렴, 북부 이전에 관련된 것들 가서 직원 개인 면담도 하신 것 같고…….
</p>
<p><b>○ 경기연구원장 강성천 </b> 그렇습니다.
