<p><b>○ 이혜원 위원 </b> 이런 부분들, 개인 면담은 9월부터 10월까지 다 하신 건가요, 전 직원을?
</p>
<p><b>○ 경기연구원장 강성천 </b> 지금 우리 부원장이 개별 면담을 하고 있고요. 전 직원을 다 하지는 못했습니다.
</p>
<p><b>○ 이혜원 위원 </b> 지금 하고 계신 건가요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 네, 다 하지는 못했고요.
</p>
<p><b>○ 이혜원 위원 </b> 그런 상황에서 지금 얘기들이 오고 가는 상황인 것 같은데 그러면 정리되기 전에, 이런 부분에서 시행하기 전에 정리가 된 상태에서 진행을 해야 되는 게 맞다고 생각을 합니다. 기본적으로 업무라는 거는 업무환경이 조성돼야 업무가 진행이 되는 것인데 환경도 지금 조성이 되지 않은 상태에서 이전을 논한다는 것 자체가 어불성설이고요. 일단 규모적인 공간에 대한 업무환경 그리고 일할 수 있는 업무환경 그리고 정주에 대한 업무환경 이런 것들이 좀 정리가 된 다음에 논의가 돼야 된다고 생각을 하거든요.
</p>
<p style="padding-left:1.2em">  근데 저는 여기서 좀 이해할 수 없었던 것이 맞는지 확인해 주십시오. 초등학교 4학년 이하 자녀를 둔 직원의 경우에 6개월에 주 2회 근무라는 비정상적인 기준을 강요하고 있다. 이 부분에 대해서는 어떻게 생각하십니까? 맞습니까? 초등학교 4학년 이하 자녀를 둔 직원의 경우 이 안이 있습니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 그런 안이 내부적으로 검토된 건 사실입니다. 사실이고 저희가 4학년 이하의 자녀를 둔 연구직의 경우에는 아마 육아에 대한 부담이 있기 때문에 좀 더 유연하게 근무할 수 있도록 배려한다는 차원에서 논의가 된 거고요. 다만 저희가 논의 과정에서…….
</p>
<p><b>○ 이혜원 위원 </b> 그러면 주 2회 근무라는 게 본원에서 근무하다가 주 2회는 북부 가서 근무한다는 얘기예요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 그런 뜻으로 논의가 됐습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그리고 2~3개월 단위로 순환보직을 한다는 것도 본원에서 있다가 또 2~3개월 후에는 북부로 가서 순환보직을 한다?
</p>
<p><b>○ 경기연구원장 강성천 </b> 그렇습니다. 그런 안이…….
