<p><b>○ 이혜원 위원 </b> 그러면 이게 연결성이 있습니까, 업무에 대한 연결성이? 더군다나 연구원들 같은 경우는 연구에 집중을 해야 되는 상황인데 업무환경이 바뀌는 것 자체가 연구에 집중할 수 없는 환경이 되는 건데…….
</p>
<p><b>○ 경기연구원장 강성천 </b> 그래서 그런 부분에 대한 부작용도 분명히 있을 거라고 저희는 생각하고 있고요. 어찌 됐든 위원님 지적대로 저희가 최대한 더 의견 수렴을 해서 노력하겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 뭐 여러 가지 안들과 의견들이 많습니다. 이걸 다 전달해 드릴 수는 없고 별도로 연구원에서 부원장님이나 시간 되실 때 오셔서 의견을 충분히 저한테 들어주셨으면 좋겠고…….
</p>
<p><b>○ 경기연구원장 강성천 </b> 그렇게 하도록 하겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 이 의견이 나오는 것은 또 이야기가 많다는 것은 우리가 설명회나 여러 가지 연구원에서 고민을 하고 계시겠지만 정주여건이나 근무환경이 지금 방향성이 일하시는 직원들하고 생각이 많이 다르다라고 생각을 합니다. 그래서 그런 부분들에 있어서 정확하게 좀 의견을 청취해 주시고 우리 경기도의회에서도 지원하는 부분이 지금 전체로 이전하는 게 아니라 부분이전이잖아요. 그러면 경기연구원에서 말씀하시는 것도 일리가 있거든요. 부분이전이라면 부분이전에 관련된 내용들이나 환경이 조성이 돼야 되잖아요. 근데 제시하셨던 내용들은 전체 이전에 대한 부분이기 때문에 이 의견에 대한 부분을 좀 명확히 방향성을 다시 검토해야 되지 않을까 싶거든요, 초기부터. 그 부분에서는 어떻게 생각하십니까? 예산은 예산대로 지금 들어가고 있는 상황이고 이전 정리는 지금 안 되고 있는 상황인데 이 얘기들이 먼저도 우리 행감 할 때 연구원 북부 이전에 관련된 부분들에 대해서 행감 지적이 있었습니다. 그래서 TF팀 구성해서 진행을 하겠다, 완료 형태로 지금 와 있는데 제가 보기에는 완료가 아니에요. 지속적으로 검토하고 준비를 하셔야 될 상황입니다. 이거는 경기도와 경기연구원이 직원들의 업무환경, 박상현 위원님이 말씀하신 것처럼 이 연구환경에 대한 부분 자체가 우리 경기도의 연구성과와 또 관련이 되어 있고 발전과 연계가 되기 때문에 조금 급하게 서두르실 이유가 아니라고 생각합니다. 늦어지더라도 정확하게 여건이 정리된 후에 그리고 인사발령 기준도 좀 명확하게 하셔서 오해의 소지가 없도록 해결한 후에 진행을 해 주셨으면 좋겠다는 말씀을 드립니다.
</p>
<p><b>○ 경기연구원장 강성천 </b> 네, 말씀하신 대로 직원들과 충분히 대화를 해서 의견을 모아서 진행하도록 하겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 이혜원 부위원장님 수고하셨습니다. 다음은 이경혜 부위원장님 질의하시겠습니다.
</p>
<p><b>○ 이경혜 위원 </b> 고양 지역구를 둔 이경혜입니다. 존경하는 이혜원 부위원장님께서 앞서서 경기연구원 이전에 관해서 말씀을 하셨는데요. 저도 이어서 말씀을 좀 드리겠습니다. 내용에 대해서는 이혜원 부위원장님께서 충분히 검토가 될 수 있는 말씀들을 해 주셨기 때문에 그 부분에 대해서 연장으로 원장님께 여쭙겠습니다. 이 일이 원장님이 오시고 난 다음에 일어난 일이 아니잖아요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 네.
</p>
<p><b>○ 이경혜 위원 </b> 오시기 이전에 이미 공공기관 이전 검토가 끝난 상황이고 오셨을 때는 이미 예산도 편성돼 있었던 상황에서 오셨습니다. 그렇기 때문에 제가 볼 때는 원장님의 의사로 이 일들이 진행되어온 것은 아니어서 원장님께만 이런 부분에 대한 지적을 할 수 있는 일은 아니다 이렇게 저는 생각을 합니다.
</p>
<p style="padding-left:1.2em">  제가 2024년 저희 본예산에 경기연구원 이전 비용을 편성한 것을 보면서도 분명히 말씀을 드렸어요. 제가 원장님하고 기조실장님 두 분께 동시에 같이 말씀드리는 겁니다. 제가 분명히 말씀드렸던 거에 임차를 위해서 임대보증금을 쓰는 것도 그렇고 거기에 인테리어 비용이랑 기타 부대비용으로 들어가고 있는 돈이 12억 상당이 됩니다. 지금 현재 집행되지는 않았지만 보니까 11억 8,500 정도가 집행될 예정으로 있는데요. 이 부분을 이렇게 들여서 직원들은 갈 사람이 있는지 없는지도 모르는 상황에서 이 일들을 진행해야 될까. 그래서 분명히 그때도 말씀드렸어요. 좀 더 면밀하게 검토하고 경기연구원이 완벽하게 갈 수 있을 때, 전체가 함께 갈 수 있는 구조가 됐을 때 이전하는 것이 바람직하다. 40명이 가서 할 수 있는 경기도 지역 활성화는 쉽지 않다라고 말씀을 드렸었는데 그럼에도 어제 제가 보여드렸던 벽처럼 여전히 그 벽은 똑같이 있습니다. 그 벽을 통해서 지금도 여전히 가는 인원이 40명에서 35명으로 줄어들었다고 들었습니다. 그런데 가고자 신청한 인원이 2명밖에 없어요. 그 2명도 어떻게 갈까라고 생각했더니 살고 있는 거주지가 의정부여서 갈 수 있는 주거 요건이 가능하기 때문에 가는 겁니다. 그래서 원장님에게 부탁을 드리는 건 아닙니다. 원장님께서는 이 일을 어떻게 할지 끊임없이 고민하실 수밖에 없고 저는 그거에 대한 해답은 별로 없다고 생각합니다. 연구원의 어느 직원도 지금 주어지는 여건 속에서 간다라고 자발적으로 나서기엔 너무 어려운, 그렇다고 해서 공무원이니 무조건 강제해서 가야 한다. 직원으로서의 사명감으로 강제해서 가자라고 차출해서 갈 수 있는 일은 아니라고 생각합니다.
</p>
<p style="padding-left:1.2em">  그래서 기조실장님께 여쭙겠습니다. 경기연구원이 이전을 하게 됐을 경우에 경기연구원 직원들이 가져갈 수 있는 인센티브는 뭐라고 생각하십니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 저희가 공통 기준으로는 지방공무원 여비규정에 의해서 이사비를 지급하는 부분이 있고요. 그 이외에 한시적으로 임차를 해서 생활을 하실 때 임대료를 지원하거나 또는 기관 단위로 셔틀버스를 운행하실 경우 그 비용을 지원할 수 있습니다. 이게 이제 공통 기준이라고 보시면 되고요. 그다음에 개별 기관별로 좀 특수성이나 이런 것들이 있기 때문에 추가적인 부분은 조금 논의를 해서 필요한 부분은 반영할 수 있다고 봅니다.
</p>
<p><b>○ 이경혜 위원 </b> 제가 볼 때는, 지금 들어와 있는 이 여건의 이야기를 자료로 받아봤거든요. 경기연구원에서 이전하는 의정부로 갈 경우에 부부가 아이를 데리고 같이 이동할 수 있다라고 생각하십니까, 그런 여건으로? 만약에 맞벌이 부부인 경우는 거주를 이전하면 맞벌이하는 그 배우자는 어떻게 또 직장을 다니라고 하겠습니까? 그렇죠?
</p>
<p style="padding-left:1.2em">  또 그런 맞벌이를 하는 것 때문에 아내 배우자의 입장을 생각해서 지금 여건에서 셔틀버스를 타고 다닌다고 생각해 보세요. 셔틀버스 타고 매일 출퇴근하는 게 가능한 일인지는 잘 모르겠어요. 연구원들이 하는 활동들이 외부 활동들도 많이 있을 수 있는 걸로 알고 있는데 그랬을 경우에 낮에는 차를 어떻게 이동해서 움직일 것이며 이 셔틀버스 아침에 다니고 저녁에 가는 것 하나로 이게 가능한지에 대해서는 저는 도저히 불가능하다라고 생각을 해요. 이 여건이 경기도에 예산은 많이 주는 것 같은데 경기도는 나름 배려한다고 생각을 하셔서 지금 말씀을 주신 것 같아요. 이주 비용도 있고 주거 비용도 있고 준비되어 있는 것들이 있지만 이 부분으로는 불가하다.
</p>
<p style="padding-left:1.2em">  그리고 이렇게 여쭤볼게요. 경기연구원 40명에서 35명으로 줄여서 가는 상황이면, 35명이 경기도 의정부에 가게 되면 의정부의 경제 활성화는 얼마나 이루어질까요? 원래 예상했던 계획만큼의 활성화가 가능하다고 생각하십니까? 전체가 가는 게 아닌데.
</p>
<p><b>○ 기획조정실장 허승범 </b> 전체 갈 계획이 아시다시피 해당 부지가 소송에 걸려 있는 바람에 어쩔 수 없는 상황이고 지금은 임시적인 이전 진행 단계이기 때문에 위원님 말씀하셨던 것처럼 단순한 지역경제의 효과는 크지 않으리라고 생각됩니다.
</p>
<p><b>○ 이경혜 위원 </b> 그렇죠. 경제효과가 단순하게 지금 크지 않을 겁니다. 그럼에도 불구하고 전체 이전 부지를 확정하고 전체가 함께 가는 것이 더 빠른 방법이 아닐까요? 굳이 이렇게까지 한 부서만, 핵심 부서만 이동해서 소통도 안 되고 직원들이 가는 어려움도 있고 이 일을 해야 되는지에 대해서 고민을 해 봐야 된다고 생각하는데요.
</p>
<p style="padding-left:1.2em">  그런 차원에서 경기연구원과 함께 다시 또 공공기관 전체 이전에 대해서 좀 여쭤볼게요. 이 부분에 대해서는 우리 경기도의 균형발전과 공공기관에 대한 깊은 애정과 관심으로 도민께서 질의도 해 오셨어요. 도민의 관심과 참여는 경기도 행정의 투명한 공정성 효과를 높일 수 있다라고 생각하는데요. 이 도민의 제보 그리고 청원 그런 부분에 대해서도 함께 도민의 질의에 대해서 감사를 드리면서 질의 다시 드려보겠습니다.
</p>
<p style="padding-left:1.2em">  지금 경기도경제과학진흥원도 파주로 이전하잖아요. 이 부분 지금 어떻게 진행되고 있습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그 해당 물권을 수차례 확정을 지었다가 뒤에 이제 법률적인 문제라든가 채권, 채무 관련된 문제라든가 이런 걸로 인해서 취소를 하고 지금 다시 또 찾고 있는 중인 걸로 알고 있습니다.
</p>
<p><b>○ 이경혜 위원 </b> 그럼 그다음 경기도일자리재단 동두천 이전은 어떻습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 일자리재단 같은 경우는 아시다시피 부지 환경오염으로 인한 정화비용이 한 100억 원 규모로 소요되기 때문에 그 부분을 어떻게 처리해야 될지 지금 동두천시하고 일자리재단하고 좀 고민을 하고 있습니다. 그 부분을 결정짓는 대로 이전은 진행될 계획입니다.
</p>
<p><b>○ 이경혜 위원 </b> 그러면 광교 신사옥으로 이전한 GH는 또 이전을 어떻게 하실 겁니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> GH는 아시다시피 구리시로 이전할 계획이었으나 구리시가 서울 편입을 계속 주장하고 계셔서 그런 상황이라고 하면 GH의 이전을 추진하는 게 적절하지 않다라는 정책적 판단이 있어서 일단 잠정 중지돼 있는 상태입니다.
</p>
<p><b>○ 이경혜 위원 </b> 네. 제가 그 부분에 대해서 다시 한번 말씀을 드리려고 했어요. 구리시가 서울 편입되면 정말 어마어마한 이상한 일이 생기는 거잖아요. 거기에 GH가 안 그래도 신사옥으로 온 지 얼마 되지도 않았는데 또다시 이전을 얘기하는 것 자체도 어불성설이었는데, 그 일이 벌어질까 걱정이었는데 잠정 중단된 것이 아니라 아예 중단하시는 게 맞다고 생각합니다. 정리하시는 게 필요하다고 생각하고요.
</p>
<p style="padding-left:1.2em">  그러면 경기신보도 또 옮깁니다. 옮긴 지 1년밖에 안 됐는데 남양주로 또 옮긴다고 합니다. 여기는 어떻게 됩니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 신보는 남양주에서 지금 물권을 계속 찾고 있고요. 금년 중에 본부가 이전할 수 있는 물권을 찾아서 임차 이전할, 아마 임차 이전은 이제 내부 수리나 이런 게 필요할 것 같아서 내년 초가 되지 않을까 생각하고 있습니다.
</p>
<p><b>○ 이경혜 위원 </b> 지금 경기신보가 있는 곳이 임차입니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 자가 건물입니다.
</p>
<p><b>○ 이경혜 위원 </b> 그렇죠. 그리고 들어간 지 1년도 안 됐죠?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네.
</p>
<p><b>○ 이경혜 위원 </b> 근데 굳이 남양주로 지금 임차를 해서 가야 하는 가장 중요한 이유는 뭡니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 이제 개별적인 사안을 보면 조금 이해되지 않는 부분이 있을 수도 있고 효율성이 떨어지는 부분도 있습니다. 그런데 이제 전체적인 틀에서 공공기관이 지역 발전을 선도할 수 있다라는 취지에서 2019년부터 3개년 걸쳐서 결정된 사항이고 공공기관도 이사회 의결을 통해서 정해진 내용입니다. 그런데 이제 이게 제때에 잘 이루어지지 않다 보니까 여러 가지 조금 비효율적인 일이 발생돼 있는데요. 그래도 큰 뜻을 따라서 그렇게 진행돼야 되지 않을까. 다만 위원님 제시하셨던 것처럼 그런 비효율이라든가 직원들의 불편함이라든가 이런 거는 최대한 협의를 해서 최소화하면서 진행돼야 될 거라고 생각합니다.
</p>
<p><b>○ 이경혜 위원 </b> 이게 협의해서 될 일입니까? 필요 없는 예산을 낭비하면서 지역균형발전을 말씀하시는 게, 경기북부의 지역균형발전은 경기도의 예산을 함부로 낭비하면서 하라고 하는 발전은 아닙니다. 그리고 경기도민들은 그리고 더더군다나 경기북부 도민들은 공공기관들이 이전해 오는 것에 대한 적극적인 환영은 당연히 있습니다. 그럼에도 불구하고 내가 내는 혈세가 그렇게 쓰여지면서 그렇게 와지는 것을 원하는 건 아닙니다.
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p style="padding-left:1.2em">  그리고 아직 얘기를 끝내지 못해서 혹시 조금 더 시간 주실 수 있을까요? 아니면 보충질의로 그냥 질의를 할까요?
</p>
<p><b>○ 위원장 조성환 </b> 보충질의하셔야 되는데 혹시 기조실 소관인가요?
</p>
<p><b>○ 이경혜 위원 </b> 네, 기조실.
</p>
<p><b>○ 위원장 조성환 </b> 그러면 짧게 한 2분 정도만 더 하시죠.
</p>
<p><b>○ 이경혜 위원 </b> 그래서 지역균형발전 조례의 목적에 지역 발전 역량 증진을 통한 경쟁력 강화를 목적으로 이 일을 한다라고 하시는데 제가 볼 때는 예산을 이런 식으로 쓰면서 하는 것에 대해서는 적절하지 않다.
</p>
<p style="padding-left:1.2em">  그리고 일자리재단 60억 이상이 토지 정화하는 데 필요합니다. 이거 토지 정화가 당연히 필요할 수 있는 것은 예견된 일이라고 봅니다. 미군 반환공여지들의 그런 일들이 다 곳곳에 있기 때문에 그 토지 정화는 반드시 필요한 일이었을 거라고 생각하는데도 불구하고 그 일을 했다는 것 자체가 예견된 일을 그냥 한 것은 면밀한 검토를 안 했다라고 생각하고. 또 하나 마지막으로 직원들의 복지 그리고 기관의 안정성, 일의 효율을 위한 것들에 대해서의 완벽한 무시라고 저는 생각을 합니다.
</p>
<p style="padding-left:1.2em">  이렇게 졸속으로 이루어지는 경기도의 공공기관 이전에 대해서는 다시 한번 생각을 해 봐 주셔야 한다고 생각하고요. 어떠한 경우에도 예산이 이렇게 쓰여지는 것에 대해서는 아무리 경기도에서 내 지역에 예산이 오고 내 지역에 지역경제 활성화가 된다 해도 몇백억씩 함부로 쓰여지는 예산을 위해서 경기도민 모두가 그럼에도 공공기관을 임차해서 몇십 명씩만 와라 이렇게 할 데는 절대 없다라는 생각으로 모든 것을 다시 한번 검토해 주시기를 부탁드립니다.
</p>
<p style="padding-left:1.2em">  그리고 마지막으로 여쭙니다. 제가 기조실에 어제 말씀드렸어요. MOU 체결에 대해서 어떻게 하실 건지 여쭤봤거든요. 그 답 가지고 오셨나요? 누가 이 부분에 대해서 문제 정리를 못 하신 건지.
</p>
<p><b>○ 기획조정실장 허승범 </b> 부위원장님, 그거는 제가 특정인을 여기서 언급을 하는 거는 적절하지 않은 것……. 
</p>
<p><b>○ 이경혜 위원 </b> 해 주셔야 합니다. 아닙니다. 제가 요청한 거는 적절하게, 그거를 비공식적으로 해야 할 이유가 있으신 건가요, 지금?
</p>
<p><b>○ 기획조정실장 허승범 </b> 양해해 주시면 제가 이거 끝나는 대로 바로 부위원장님 말씀……. 
</p>
<p><b>○ 이경혜 위원 </b> 아니요. 개인적으로 듣고 싶은 게 아니라 공식적인 입장을 말씀드리는 겁니다. 저와의 MOU 체결에 대한 제안을 받지 않은 것이 도지사님인지, 비서실장이신지, 기조실장님인지, 공공기관담당관인지 제가 분명히 다시 여쭙습니다. 공식적으로 어떤 분께서 어떤 이유로 이 MOU 체결에 대한 답을 안 주시고 그렇게 3개월간을 끌었는지에 대해서 정확하게 이 자리에서 답을 주십시오.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 전에 말씀드렸듯이 시간이 여의치 않았던 부분도 분명히 있고요. 끝나고 제가 부위원장님 말씀드리겠습니다.
</p>
<p><b>○ 이경혜 위원 </b> 위원장님께 여쭙겠습니다. 저 이런 답변을 듣자고, 시간 이후에 다시 끝나고 따로 들으려고 이것을 공식적으로 제가 방송까지 나가는 것에서 말씀드렸던 건 아니고요. 이렇게는 계속해서 질의할 수 없습니다. 정회를 요청합니다.
</p>
<p><b>○ 위원장 조성환 </b> 실장님, 답변 어떻게 지금 어려우세요? 시간을 좀 드려요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 아니요. 지금 말씀드리겠습니다. 누가 계속 이렇게 지연됐느냐 처음에는 충분히 논의를 했습니다. 저도 직접 비서실장하고 만나서 의견도 나누고 했는데요. 결론적으로 말씀드리면 제가 판단하기로는 이미, 제가 판단해서 실무 의견을 비서실에 전달했고 비서실에서도 그 의견을 받아들였습니다. 그래서……. 
</p>
<p><b>○ 이경혜 위원 </b> MOU 체결에는 동의를 하시는 겁니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그 내용이 사실 이미 조례도 다 개정이 돼 있고 사안이 많이 진행돼서 실제로 관련된 규정들도 개정되고 있는 상황에서 지금 MOU를 또 하는 게 적절한지는 조금 퀘스천마크가 있었고요.
</p>
<p><b>○ 이경혜 위원 </b> 그럼 그렇게 저한테 얘기를 해 주셨어야죠. 그렇게 말씀 안 하시고 도지사님의 일정이 안 되신다고 끊임없이 계속 말씀하시고 3개월을 끌었고요. 저는 조례가 제정됐으면 MOU 체결을 굳이 해야 되는가에 대해서는 의원이 요청하면 해 주시는 것 그리고 그것에 대한 답변을 주시는 게 도의 입장이라고 생각하는데요. 그걸 이런 식으로 하실 거였다면은 경기도의원이 뭐 필요하겠습니까? 집행부만 갖고 일하시면 되지. 그렇지 않겠습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 죄송합니다. 저희가 위원님 말씀하셨던 걸 최대한 조금 이렇게 성사시켜 보려고 준비를, 노력을 했었는데요.
</p>
<p><b>○ 이경혜 위원 </b> 그래서 최종, 결정적으로 누가 그래서 거기까지만 하고 MOU 체결에 대해서는 잠정적으로 그냥 말씀 없이 끝내자라고 하신 게 누구십니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 제가 그랬습니다.
</p>
<p><b>○ 이경혜 위원 </b> 기조실장님이시라고요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그렇습니다. 
</p>
<p><b>○ 이경혜 위원 </b> 그런데 저한테 와서 말씀 안 하셨어요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 제가 끝까지 조금 더 노력은 해 봤는데요.
</p>
<p><b>○ 이경혜 위원 </b> 그러면 비서실에서는 일정은 줄 수 없다라는 얘기 안 하셨나요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그렇게 얘기는 하지 않았습니다.
</p>
<p><b>○ 이경혜 위원 </b> 일정 주실 수 있다고 하셨나요?
</p>
<p><b>○ 기획조정실장 허승범 </b> “일정이 바쁘다. 조금 보자.” 이렇게까지만 얘기가 됐습니다.
</p>
<p><b>○ 이경혜 위원 </b> 그러면 다시 요청드립니다. 비서실장님께 다시 말씀드려서 도지사님의 일정 주시고 저는 MOU 체결을 원합니다. 기조실장님이 무슨 권한으로 경기도의원이 하겠다고 하는 MOU 체결에 대해서 잠정적으로 하지 말자라고 끝을 내셨는지 저는 이해할 수 없고요. 기조실장님보다 경기도의회가 그렇게 역할이 없다라고 생각하시는 건지에 대해서 저는 여기서 다시 한번 묻겠습니다. 이 부분에 대해서 생각하시고 다시 오십시오. 정회를 요청합니다.
