<p><b>○ 위원장 조성환 </b> 지금 정회를 요청하셨는데요. 아직 발언을 오전에 못 하신 위원님들이 지금 한 다섯 분이 계셔서 일단은 부위원장님, 괜찮으시면 한 세 분 정도만……. 
