</p>
<p><b>○ 위원장 조성환 </b> 잠시만요. 본질의를 하고 그리고 정회를 한번 하면 어떨까 하는데 혹시 이 관련된 내용이신가요, 이석균 위원님? 말씀하세요.
</p>
<p><b>○ 이석균 위원 </b> 네. 지금 우리가 행정사무감사예요, 그냥 업무보고 자리나 다른 보고 자리가 아니고. 그런데 이런 상황에서 위원의 질의에 대한 답변을 이렇게 할 수 있음에도 불구하고 안 하는 이런 경우는 위원장님, 죄송하지만 잠시 정회하는 게 저는 맞다라고 생각합니다.
