<p><b>○ 위원장 조성환 </b> 의석을 정돈하여 주시기 바랍니다. 성원이 되었으므로 감사를 속개하겠습니다. 
</p>
<p style="padding-left:1.2em">  이전 질의에서 나온 내용과 여러 가지 상황들을 저희가 종합해서 아무래도 이번 행정사무감사에 추가 증인이 좀 필요한 것 같습니다. 그래서 이후에 양당 간사님들, 부위원장님들하고 협의해서 내용들을 좀 정리하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  그러면 이어서 질의 답변을 계속하도록 하겠습니다. 다음은 이채명 위원님 질의하여 주십시오.
</p>
<p><b>○ 이채명 위원 </b> 안양 출신 이채명 위원입니다. 실장님.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 기조실장입니다.
</p>
<p><b>○ 이채명 위원 </b> 연일 수고 많으십니다. 사실은 참고로 먼저 칭찬부터 해 드릴 팀이 있습니다. 법무담당관 같은 경우는요, 지금 딱 1년 됐습니다. 2024년 11월 11일 날 필수 조례 정비 관련해서 그 당시에 제가 도의회에 입성하자마자부터 지적했던 내용이 필수 정비 조례거든요. 그러니까 법령 개정이 됐는데도 불구하고 우리 경기도라든가 31개 시군에 위임된 사항에 대해서 조례가 개정되지 않았기 때문에 그 당시에 79.8%로 굉장히 저조했습니다. 그래서 14위를 했었거든요. 1년 후 지금 현재 시점은 보니까 1년 만에 94.2%로 굉장히 고무적입니다. 그 당시에 1위 세종시가 93.9%였는데요. 그 당시 1위보다도 지금 더 앞섰습니다. 그 정도로 우리 법무담당관에서 열심히 아무래도 우리 주민들이 제대로 체감할 수 있게끔 필수 조례 정비를 개정했다라는 말씀을 드리면서, 칭찬을 드리면서. 
</p>
<p style="padding-left:1.2em">  연이어서 사실은 아시다시피 행정의 기본은 저는 규정이다라고 말씀드리고 싶습니다. 맞죠? 그런 차원에서 오늘 우리 경기도 지방보조금 관리 조례 시행규칙 관련해서 실장님과 대화를 좀 나눠보고자 합니다. 지금 서울시의 지방보조금 관리 조례 시행규칙은 현재 2024년도에 전면적으로 개정이 돼서요. 지방보조금 보조사업의 실적보고뿐만 아니라 포상금 지급, 환수 등 해서 지금 아시다시피 굉장히 시행규칙 자체가 풍성하게 전면 개정이 됐습니다. 그럼에도 불구하고 우리 경기도의 지방보조금 관리 조례 시행규칙은 달랑 한 장에 그것도, 장수가 중요한 건 아니겠죠? 3조입니다. 여전히 기준보조율 중심의 굉장히 낡은 체계 위주로 이렇게 시행규칙이 되어 있어요. 앞서서 말씀드렸지만 위법한 조례는 위법한 행정으로 귀결이 됩니다. 그런 차원에서 몇 가지 제가 서울시 사례와 우리 경기도를 좀 분석해 봤습니다. 혹시 이 시행규칙을 한번 보신 적은 있으시나요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 서울시 것 말씀하시는 건가요?
</p>
<p><b>○ 이채명 위원 </b> 서울시와 우리 경기도. 왜냐하면 지방보조금 관련해서 지금 몇 년째 지적된 사항들이 굉장히 많습니다. 보조금 환수 조치뿐만 아니라 행감에서 지속적으로 매년 지적됐던 게 아마 지방보조금 관련했던 것 같아요. 각 상임위마다예요. 우리 기조실에서는 이거를 총괄하는 부서이기 때문에 조례가 있기 때문에 제가 시행규칙까지 이렇게 보게 되면서 분석을 했는데요. 지금 서울시는 보조사업 실적보고를 의무화를 했습니다. 그리고 포상금 환수, 성과 기반 관리 체계를 모두 반영을 했습니다. 예를 들면 보조사업 실적보고서에는 사업계획의 결과에 관한 내용이 포함되어야 한다, 의무 조항이겠죠. 이 경우에 보조사업이 폐지 또는 중단된 경우에는 중단된 사유를 보조사업 실적보고서에 포함하여야 한다라고 이렇게 강행규정으로 되어 있습니다. 그러면서 보고서에 만약에 미흡이란, 예를 들어서 미흡이 왜 미흡인지를, 어떤 개선이 필요한지에 대해서 사유서를 써서 평가자가 개선의견을 반드시 남기도록 하는 것을 의무화했습니다. 이런 부분에 대해서 혹시 들어보신 적 있으신가요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 의무화까지는 아니더라도 지금 이채명 위원님 말씀해 주셨던 것들을 저희도 보조사업 평가하면서, 나중에 결과 정리하면서 그런 부분들을 담아서 정리를 하고 있기는 합니다만 서울시 사례처럼 이렇게 딱 명문화하고 의무화하지는 않고 있습니다.
</p>
<p><b>○ 이채명 위원 </b> 네, 일단 그런 부분들이 시행규칙에 담겨 있습니다. 그런데 반면에 경기도 시행규칙은요, 2022년 개정 이후에 3년간 개정이 한 차례도 없습니다. 내용 또한 보시면 알겠지만 1조, 2조, 3조 기준보조율 적용 수준에 지금 머물러 있습니다. 경기도는 그간 지방보조금 관련해서 앞서 제가 말씀드렸습니다. 감사나 평가에서 반복적으로 지적된 문제에도 불구하고 이런 시행규칙 개정이 이루어지지 않은 이유가 무엇인지 짧게 답변해 주시기 바랍니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 지적하셨던 내용을 시행규칙 개정으로 풀어야 되는 거는 아마 충분히 검토를 못 해 본 것 같습니다. 동일한 문제가 반복된다고 그러면 말씀하셨던 것처럼 관련 규정을 개정해서 명문화하고 의무화하는 게 필요한 것 같은데요. 이참에 위원님 말씀해 주셨던 서울시 사례나 이런 것들을 한번 살펴보고 저희의 업무 행태도 좀 봐서 개정이 필요한지 검토해 보겠습니다.
</p>
<p><b>○ 이채명 위원 </b> 앞서 또 이 부분도 제가 지적했던 내용인데요. 서울시는 사업이 폐지나 중단된 경우에는 그 사유를 반드시 실적보고서에 포함하도록 했습니다. 그러나 우리 경기도는 이러한 조항이 없습니다. 그리고 사업 실패 원인이나 집행 부적정 사유가 명확히 기록되지 않습니다. 
</p>
<p style="padding-left:1.2em">  질문드리겠습니다. 경기도도 중단사업의 사유를 명시하도록 실적보고 기준을 강화할 계획이 있는지 성실히 답변해 주시기 바랍니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 저희도 보조사업과 관련해서는 다 사업부서에서 평가를 하도록 하고 있고 매년 1,000건 이상의 보조사업 평가가 이루어지고 있는데요. 말씀드렸듯이 그거를 조금 더 명문화하고 의무화하는 거는 한번 검토해 볼 필요성이 있다고 생각됩니다.
</p>
<p><b>○ 이채명 위원 </b> 네. 그다음엔 또 서울시 같은 경우는요, 보조사업 성과에 따라서 포상금을 지급하고 부당행위 시 환수 근거를 명확하게 명시했습니다. 그러나 우리 경기도는 또 포상금 환수 이의 신청 관련 조항이 전무합니다. 이 부분에 대해서는 또 실장님 어떤 방식으로 앞으로 진행하실 것인지. 왜냐하면 지적 사항이 너무 많습니다, 보조금 관련해서. 부적정한 보조금 환수 관련해서 아마 네이버에 쳐보면 우리 경기도 사례가 굉장히 많이 나올 겁니다. 이 부분에 대해서 어떻게 앞으로 시행할 것인지 답변 주시기 바랍니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 포상금이나 부적정한 보조금 사용 환수와 관련해서는 아마 타 법령, 상위법령에도 다 근거가 있어서 그걸 근거로 이루어지고 있다고 보는데요. 말씀 주신 것처럼 시행규칙상에도 조금 더 구체화해서 할 필요가 있는지는 같이 검토하겠습니다.
</p>
<p><b>○ 이채명 위원 </b> 그리고 참고로 혹시 성과가 우수한 그런 보조사업에 대해서는 인센티브를 지급하나요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 보조사업이라고 해서 별도로 포상하거나 인센티브를 주는 거는 없습니다.
</p>
<p><b>○ 이채명 위원 </b> 그것도 고민해 보시고요. 또한 부진사업에 대해서 감액이라든가 환수하는 그런 시스템 구축계획이 있는지도 한번 여쭤보도록 하겠습니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 그 부분에 대해서는 평가를 통해서 저희가 매우 미흡한 사업들은 차년도에 예산을 일몰한다든지 삭감하는 시스템은 있습니다.
</p>
<p><b>○ 이채명 위원 </b> 그리고 마지막 질문인데요. 행정안전부에서 지방보조금 관리 표준지침 2024년도에 보면은 지방보조금 통합관리시스템을 통한 실적보고 및 환류를 이렇게 권장을 하고 있습니다. 알고 계시죠? 
</p>
<p><b>○ 기획조정실장 허승범 </b> 알고 있습니다. 
</p>
<p><b>○ 이채명 위원 </b> 하지만 경기도 시행규칙에는 이러한 조항이 전혀 또 없습니다. 이 부분에 대해서도 앞으로 어떻게 하실 것인지 답변을 주시기 바랍니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 지금 주셨던 내용들을 시행규칙상에서 어떻게 담는 게 효율적인지 아니면 다른 방법이 있는지 다 종합적으로 한번 검토해 보겠습니다.
</p>
<p><b>○ 이채명 위원 </b> 앞으로 경기도도 향후에 이런 시스템 연계 근거를 조례 시행규칙에 반영하시기를 부탁드리면서 마무리하겠습니다. 경기도가 지금 앞서 우리 실장님도 말씀 주셨지만 몇천 건이죠, 한 천……. 
</p>
