<p><b>○ 박진영 위원 </b> 일단 제가 그림을 잘 못 그려 가지고 러프하게 그렸는데. 이번 행감 동안 저는 사실 경기도 10년 뒤의 미래를 어떻게 준비할 건지를 주로 테마를 기준으로 해 가지고 좀 보고 있었거든요. 제가 이제 달랬던 자료가 경기연구원의 최근 2년간 연구보고 실적에 대한 자료들이었어요. 이걸 왜 보려고 그랬냐면 개인적으로 정책목표가 있다라면 경기연구원은 그거에 따라서 분야별로 이렇게 나눠 가지고 연구보고서들이 만들어지고 또 하위 분야로 내려가고 하위 분야로 내려가서 연구보고서가 최소한 경기도와 관련해서 빈틈은 좀 없지 않을까라는 생각을 해서 좀 봤는데 실제로 제가 받았던 느낌은, 제가 일부러 몇 군데 이렇게 블랭크를 해 놨어요. 일부 분야들은 분야별로 좀 연구가 되어 있지 않은 내용들이 좀 있구나라는 느낌을 받았고요.
</p>
<p style="padding-left:1.2em">  또 하나는 제가 생각하는 경기연구원은 이제 타 기관들, 외부기관과의 유기적인 네트워크인데 동그라미가 큰 건 큰 기관, 작은 건 작은 기관들인데 이런 유기적인 네트워크들이 좀 잘 구성이 되어 있나라는 생각을 했는데 이 부분도 좀 많이 미약하지 않나라는 생각을 했습니다. 왜냐하면 기본적으로 경기연구원의 보고서들이 경기도와 관련해서 빠짐없이 분야들이 체계적으로 되어 있어야 그리고 경기연구원이 외부 네트워크가 충실하게 유기적으로 구성이 되어 있어야 이제 경기연구원이 경기도의 10년 뒤 미래를 바라봐 줄 수 있을 거라고 생각해서 그런 거고요.
</p>
<p style="padding-left:1.2em">  일단 그 기준안에 좀 지엽적으로 들어가겠습니다. 경기연구원 홈페이지를 들어가서, 찾기 되게 힘들었습니다. 이거 사실 주제 분야에 대한 게 상세 검색으로 들어가야 찾을 수 있더라고요. 이거 주제 분야에 대한 보고서 좀 메인 페이지에 올려주시길 부탁드리겠고요.
</p>
<p style="padding-left:1.2em">  경기연구원이 보고서를 주제 분야에 따라서 이렇게 나눠놨어요. 행정ㆍ자치분권 밑에 주제들, 경제ㆍ산업ㆍ일자리 밑에 주제들 이렇게 해서 쭉 주제로 나눠놨고요. 이 주제를 기준으로 제가 나름 보고서를 분류했습니다. 최근 2년간 보고서들인데 일단 주제 분야 안에 최근 2년간 보고서가 한 270건 정도 되는 것 같던데 주제 분야 안에 들어가 있지 않은 것들이 상당해 가지고 이것들을 다 분류해 주셔야 될 거고요. 있는 자료 기준만으로 했는데, 2년간 주신 자료를 기준으로 제가 분류를 했는데 사회ㆍ복지 분야에서 복지, 사회ㆍ복지 분야에서 사회 그리고 환경 분야에서 환경의 보고서들이 많이 있고요.
</p>
<p style="padding-left:1.2em">  그리고 제가 볼 때 이제 좀 하나의 초점은 경제ㆍ산업ㆍ일자리에 대한 보고서들이 좀 많지 않았을까라는 생각을 했는데 생각보다 R&D 과학기술에 대한 보고서는 적었고요. 산업에 대한 보고서도 어느 정도 수치는 나오지만 좀 적지 않았나라는 생각을 했습니다. 근데 세부내역을 보면 과연 이게 진짜 R&D 과학기술에 대한 보고서인가라는 생각이 좀 들어요. 그러니까 보고서가 문제가 됐다라는 게 아니라 분류를 억지로 이렇게 하긴 했는데 경기연구원이 진짜 경기도의 R&D 기술 분야에 대한 보고서를 많이 작성을 했는지에 대해서 좀 의문이라서 그런 거예요. 수원시 반도체산업 특화 발전 방안 연구, 보고서는 참 좋은데 이게 과연 경기도의 R&D 과학기술일까. 그나마 이제 뭐 미래산업 전망에 따른 경기도의 대응 방안은 좋은 분류된 것 같고요. 그리고 나머지 3개는 AI예요, AI. 이렇게 따지면 경기연구원이 과연 경기도의 R&D 과학기술에 대한 보고서들을 충분히 생산해 내는지에 대한 의문이 좀 들고요.
</p>
<p style="padding-left:1.2em">  산업에 대한 것들을 보시면 지엽적이라는 느낌을 좀 받긴 했었어요. 그러니까 경기도 산업 전반을 아우를 수 있는 메인 보고서가 있어야 되고 그거에 따라서 세부적인 산업 분야들에 대한 보고서들이 있어야 된다고 생각은 하는데 좀 세부적인 산업 분야에 대한 보고서들만 있는 것 같고요.
</p>
<p style="padding-left:1.2em">  경기도의 미래산업이 추구하는 현재의 방향을 저는 미래성장산업국의 조직도라고 보고 있는데 디지털혁신산업, 벤처스타트업산업, 반도체산업, 첨단모빌리티산업, 바이오산업을 경기도가 주력하겠다. 미래성장산업으로 주력하겠다고 했지만 실제로 이 산업 보고서에 보시면 없습니다.
</p>
<p style="padding-left:1.2em">  결국 아까 처음 말씀드렸던 그림으로 돌아오면 의구심이 좀 들긴 해요. 경기연구원이 지금 보고서를 체계적으로 생산해 내고 있느냐에 대한 의구심이 좀 들어서 이 부분을 한번 살펴봐 주셨으면 합니다. 그러니까 연구원들의 연구에 대한 자율성은 존중해야 된다라고 보지만 행정적인 체계안에 있다라면 경기연구원이 생산해 내는 보고서는 체계적으로 좀 만들어져야 된다라고 생각을 하거든요. 원장님이 이제 행정의 경험이 풍부하시니까 원장님 생각은 어떠신가요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 박진영 위원님 굉장히 좋은 지적을 해 주셨습니다. 저희 연구원이 종합연구원이긴 하지만 일부 편중된 연구 또 시대 트렌드의 변화에 따라서 좀 강화해야 될 분야가 있음에도 불구하고 거기에 적기 대응을 못 한 건 저도 사실이라고 생각합니다. 그래서 제가 취임한 이후에 했던 부분이 일단 실물 부분에 대한 연구기능이 저는 상대적으로 취약하다고 봤기 때문에 산업통상연구실, AI연구실을 제가 신설을 했고요. 또 한편으로는 연구원 전체의 연구기획 기능도 상당히 저는 취약하다고 봤습니다. 그래서 연구기획실을 만들어서 전반적으로 종합적 연구소이지만 균형 있는 연구를 할 수 있도록 하는 그 시스템은 갖췄습니다. 그럼에도 불구하고 아직 좀 취약합니다. 그래서 특히 취약한 산업 분야, 과학기술혁신 분야에 대해서 더 저희가 보강을 할 수 있도록 노력하고요.
</p>
<p style="padding-left:1.2em">  또 중요한 것은 인력입니다. 그래서 인력이 많이 부족했고 방금 지적하신 그런 분야에 대한 박사인력이 취약합니다. 그래서 저희가 지금 신규 박사인력을 채용 중에 있습니다. 17명을 채용 중에 있는데요. 그래서 연말까지 채용이 되면 상당히 연구기능이 보강될 것으로 기대를 하고 있습니다.
</p>
<p><b>○ 박진영 위원 </b> 네, 알겠습니다. 일단 이거는 요구드릴게요. 최근 5개년 기준으로 보고서를 전수해서 분류하고 아까 말씀드린 주제 분야 홈페이지 그거 메인으로 올려주시고요. 그리고 전수해서 분류한 내용들 그 안에다 포함시켜 주시길 부탁드리겠습니다. 그리고 전수해서 분류한 내용을 기준으로 연구보고서 중에 이제 메인이 되는, 큰 줄기가 되는 보고서 그리고 줄기 안에 가지가 되는 보고서들에 대한 체계도를 좀 확립해 주시기 바랍니다. 그리고 그 안에서 빠진 분야에 대한 연구들은 차츰차츰 좀 채워가 주시길 부탁드리겠습니다.
</p>
<p><b>○ 경기연구원장 강성천 </b> 네, 그렇게 하겠습니다.
