<p><b>○ 박진영 위원 </b> 그리고 저는 이제 처음 말씀드렸다시피 10년 뒤의 미래에 경기도에 가장 중요한 건 경기도의 산업이 어떻게 될까라고 보긴 하거든요. 물론 복지나 환경에 대한 부분들도 있겠지만 개인적으로 저는 일단 먹고사는 게 제일 중요한 문제라고 보기 때문에 경기도 산업 발전 연구의 로드맵을 좀 부탁드리겠습니다. 기존에 이제 경기도 산업 발전에 대한 전방위적인 연구가 있었다면 그 연구를 기준으로 각 산업 분야들에서 저희가 어떤 분야에 대한 연구가 빠졌는지 아니면 지역별 특색 산업에 대해서 어떤 분야의 연구가 빠졌는지를 체크해 봐 주시고 그런 분야에 대해서 앞으로 어떻게 채워갈지에 대한 로드맵을 작성해서 보고 부탁드리겠습니다.
