<p><b>○ 기획조정실장 허승범 </b> 네, 말씀 주셨던 것처럼 저희도 그 원칙에 맞춰서 조금 그 자료로 예산안이 제출됐어야 되는데 예외 규정을 적용하는 상황이 돼서 죄송스럽다는 말씀드리고요. 다만 3회 마무리 추경이 재원과 관련해서는 내년도 본예산과 일부 연계되는 부분이 있어서 본예산 확정하는 시기와 좀 맞추다 보니까 부득이하게 좀 늦춰졌습니다.
</p>
<p><b>○ 양우식 위원 </b> 실장님, 이거는 근데 어떠한 변명도 안 되는 것이 추경예산편성계획까지 해서 날짜까지 분명히 인지하고 있었어요, 기조실에서. 그런데 이걸 갖다가 날짜를, 만약에 앞으로 이게 조례 통과될 때, 기조실에서 운영위의 조례 통과될 때 의견도 내지도 않고 얘기도 안 하고 이런 문제가 있으면 그때그때 해서 규정을 좀 바꿔서 추경은 회기 시작 전이라도, 심사 일주일 전이든 예외조항을 만들어 달라고 의견을 개진하든. 기조실장님, 운영위 한번 방문하십니까? 거기 소통협력관들 일해요? 이렇게 하시면 안 돼요. 다시는 이런 조례 위반한 사태 벌어지지 않도록 철저히 업무에 해 주십시오.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 그렇게 하도록 하겠습니다. 
</p>
<p><b>○ 양우식 위원 </b> 네, 알겠습니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 또 위원님, 말씀 주신 것처럼 필요하면 규정 개정도 조금 검토해 보고 건의드리도록 하겠습니다.
</p>
<p><b>○ 양우식 위원 </b> 네, 그렇게 하세요. 일을 하시란 말이에요. 소통도 안 하시고.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 알겠습니다.
</p>
<p><b>○ 양우식 위원 </b> 그럼 연구원장님, 마지막으로 지금 우리 의정연구센터 추진하고 있죠? 
</p>
<p><b>○ 경기연구원장 강성천 </b> 그렇습니다.
</p>
<p><b>○ 양우식 위원 </b> 그거 개관식 아니면 명칭이 뭐죠? 센터 출범식은 언제 하나요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 지금 12월 중에 할 수 있을 거라고 생각하고 있습니다.
</p>
<p><b>○ 양우식 위원 </b> 12월 중에. 대략 일자는 나왔습니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 12월 한 중하순 정도 될 거라고 보여지고요. 관건은 지금 사람을 저희가 뽑아야 되는데 그걸 빨리 뽑아서……. 
</p>
<p><b>○ 양우식 위원 </b> 의정연구센터는 향후에 지난번 말씀드린 것처럼 독립할 기관이에요. 독립할 기관이니까 독립성 보장 반드시 해 주셔야 됩니다.
</p>
<p><b>○ 경기연구원장 강성천 </b> 그렇게 하도록 하겠습니다.
</p>
<p><b>○ 양우식 위원 </b> 그럼 마지막 총괄적으로 하나만 여쭤보면 지금 기조실장님, 자원 관리하는 것부터 시작해서 의정연구센터 하는 거에 대해 예산 문제가 가장 큰 문제라고 얘기합니다. 굉장히 중요한 사안이고 우리 기조실장님, 경기연구원 더 최고의 연구원으로 발돋움할 수 있게 각종 예산 지원, 인력 지원 보장 좀 해 주십시오. 부탁 좀 드리겠습니다.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 충분히 하도록 하겠습니다.
</p>
<p><b>○ 양우식 위원 </b> 협의하시고 그 내용에 대해서 저한테도 좀 알려주십시오.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 알겠습니다. 
</p>
<p><b>○ 경기연구원장 강성천 </b> 알겠습니다. 
</p>
<p><b>○ 양우식 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 양우식 위원님 수고하셨습니다. 
</p>
<p style="padding-left:1.2em">  중식을 위하여 14시 30분까지 감사를 중지하고자 합니다. 이의 없으십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  감사중지를 선포합니다.
</p>
<p class=''ar''>(12시27분 감사중지)
</p>
<p class=''ar''>(14시34분 감사계속)
</p>
<p><b>○ 위원장 조성환 </b> 의석을 정돈해 주십시오. 성원이 되었으므로 감사를 속개하겠습니다. 
</p>
<p style="padding-left:1.2em">  오전에 이어 본질의를 하도록 하겠습니다. 본질의 마지막인데요. 제가 몇 가지 우리 기조실에 여쭤보고 그다음에 우리 위원님들 보충질의를 좀 진행하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  기조실장님.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 기조실장입니다.
</p>
<p><b>○ 위원장 조성환 </b> 오전에 제가 자료 요청을 해서 일부 자료가 온 게 있습니다. 우리 기조실에서는 특히 기회전략담당관실에서는 도지사님의 핵심 공약들을 잘 이행하도록 관리하고 또 예산편성해서 추진하고 이런 일들을 하시는 거죠?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그렇습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 보통 매년 그 사업들의 규모가 어느 정도 됐습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 공약 관련된 사업 규모 말씀하시는 거죠?
</p>
<p><b>○ 위원장 조성환 </b> 네. 사업, 예산적인 측면으로 말씀해 주시면 이해가 편할 것 같아요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 올해 예산 기준으로 하면 국비사업 다 포함해서 3조 1,700억 원 규모 정도 됩니다.
</p>
<p><b>○ 위원장 조성환 </b> 그러면 우리 도 자체 비중은 어느 정도 돼요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그중에서 50%가 살짝 넘는 1조 6,000억 원 규모 정도 됩니다.
</p>
<p><b>○ 위원장 조성환 </b> 그럼 거의 반반 매칭한다고 치면 1조 5,000억 원 정도 되죠?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그렇습니다.
</p>
<p><b>○ 위원장 조성환 </b> 올해 내년도 예산편성 작업을 지금까지 쭉 해 오셨잖아요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 그 과정에서 여러 군데에서 내년도에 예산이 불충분하다. 또 3/4분기에 예산만 배정돼 있다. 여러 단체에서 또 항의도 하고 좀 과도하게는 여러 가지 요청을 하기도 하고 집회도 하고 지금 이런 상황입니다. 그 기조에는 내년도에 예산이 좀 부족하다 이런 판단이 있으셨던 거죠.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 그렇습니다. 세입 부분도 많이 전년 대비 줄어들었고요. 세출 부분도 국가보조사업 규모가 커짐에 따라서 매칭해야 되는 도비가 늘어나기 때문에 도 자체사업 추진할 수 있는 여력이 많이 부족한 상황입니다.
</p>
<p><b>○ 위원장 조성환 </b> 국가보조사업 중에 가장 비중이 큰 사업이 뭐였습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 제가 정확하게 개별사업으로는 기억은 안 나는데요. 올해 대비 매칭 도비가 약 한 3,000억 원 정도 더 소요가 되는 걸로 파악합니다.
</p>
<p><b>○ 위원장 조성환 </b> 그리고 지금 가장 많이 포션을 차지하고 있는 그 예산, 소비쿠폰?
</p>
<p><b>○ 기획조정실장 허승범 </b> 내년도 본예산에 소비쿠폰은 들어가 있지 않습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그건 들어가 있지 않고 그러면은……. 
</p>
<p><b>○ 기획조정실장 허승범 </b> 분야로 따지면 복지 분야가 아무래도 제일……. 
</p>
<p><b>○ 위원장 조성환 </b> 그러면 실제적으로 3,000억 원 정도가 증가해서 지금 이렇게 예산적인 부분으로 온 실국이 난리가 난 겁니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그렇지는 않고요. 그거는 제가 세출 부분에 있어서 국비 매칭하기 위해서 한 3,000억 원 정도 더 들어갔다고 말씀드린 거고요. 그다음에 이제 세입 부분에 있어서 지방세는 큰 차이는 없습니다. 그런데 내부 융통, 소위 말하는 저희가 순세계잉여금을 활용한다라든가, 통합재정안정화기금을 활용한다라든가 이런 부분이 전년에 비해서 거의 1조 원 가까이 줄어들었습니다. 그래서 세입 부분이 그렇게 많이 줄고 세출 부분은 아까 말씀드렸던 국가 매칭 자금이 많이 필요한 이런 상황이어서 저희 자체사업하는 데 많은 어려움이 있었습니다.
</p>
<p><b>○ 위원장 조성환 </b> 세입은 한 1조, 지금 몇천억 원 줄었다고 그랬죠?
</p>
<p><b>○ 기획조정실장 허승범 </b> 대략 1조 원 정도입니다.
</p>
<p><b>○ 위원장 조성환 </b> 1조 원 정도가 줄었고 국가에서 매칭이 더 내려와 가지고 추가로 부담해야 되는……. 
</p>
<p><b>○ 기획조정실장 허승범 </b> 한 3,000억 원.
</p>
<p><b>○ 위원장 조성환 </b> 3,000억 원. 그러면 1조 3,000억 원 정도가……. 
</p>
<p><b>○ 기획조정실장 허승범 </b> 심플하게 얘기하면……. 
</p>
<p><b>○ 위원장 조성환 </b> 작년에 비해서 부족해서 지금 예산상에 이렇게 어려움이 있었다는 거지 않습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 그렇습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그렇죠. 산술적으로 표현하면 1조 3,000억 정도가 부족해서 지금 그렇다는 거잖아요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 그렇습니다.
</p>
<p><b>○ 위원장 조성환 </b> 작년에 우리 도지사님 공약과 관련된 예산규모가 얼마였습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 아까 말씀, 25년도 예산 말고 24년도 말씀……. 
</p>
<p><b>○ 위원장 조성환 </b> 네, 26년도는 아까 자료로 주신 걸로 3조 1,200억 원이고요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 올해의 예산은 그거보다 한 500억 원 정도 더 많은 겁니다. 그러니까 내년도…….
</p>
<p><b>○ 위원장 조성환 </b> 얼추 비슷한 거죠?
</p>
<p><b>○ 기획조정실장 허승범 </b> 근데 거기도 이제 내용이 다른 게 국비 부분은 증가됐고 자체 도 아까 매칭하는 게 절반 정도인데 거기는 한 2,700억 원 정도 도비 부분은 줄어들었습니다, 도비 자체사업.
</p>
<p><b>○ 위원장 조성환 </b> 그럼 도비는 작년에 비해서 2,700억 정도가 줄었다. 그리고 전체적으로는 1조 3,000억 원 정도가 줄었다. 이렇게 돼 있지 않습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 지금 각 실국의 사업들은 실국에서 고심의 고심 끝에 편성한 사업들이 많잖아요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 그렇습니다.
</p>
<p><b>○ 위원장 조성환 </b> 쭉 해 왔던 사업들도 있고 또 그만큼 현장에서 정말로 이 사업은 꼭 필요하다라고 해서 요구를 했는데 결국에는 이렇게 저렇게 치면 1조 3,000억 원이 부족해서 다 지금 일괄 삭감 식으로 삭감을 시켰단 말이에요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 일괄 삭감이라고 표현…….
</p>
<p><b>○ 위원장 조성환 </b> 대부분 보면 지금 35%, 3분기 20% 이렇게 일괄 삭감된 부분들이 많잖아요, 특히 복지 분야라든지 이런 부분들에 대해서는.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 복지나 교통이나 일부 대규모 자금이 필요한 부분은 3/4분기까지만 담고 4/4분기는 추경으로 미뤄놓은 부분도 있습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그러면 이렇게 예산이 어려우면 누가 양보를 해야 되겠습니까, 예산적인 측면에서는?
</p>
<p><b>○ 기획조정실장 허승범 </b> 특정 계층이 양보해야 된다는 말씀이신지는…….
</p>
<p><b>○ 위원장 조성환 </b> 다 양보를 못 하지만 특히 도지사님 공약, 도정의 모든 사업들은 도지사님의 사업이죠?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그렇습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그리고 그 사업들로 인해서 도지사님의 도정이 평가받는 거고요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 맞습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그런데 실국들은 이렇게 지금 아우성을 치고 있는데 본인이 공약한 그 사업들의 예산은 거의 규모가 줄지 않고 아까 말씀하신 대로 국비 포함해서 3조 1,200억이면 1조 5,000억 원 이상의 예산이 다 반영돼 있단 말이에요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 위원장님 죄송한데요. 실국 사업하고 도지사 공약사업하고 완전 다른 별개의 사업은 아닙니다.
</p>
<p><b>○ 위원장 조성환 </b> 별개의 사업은 아니죠. 그러나 실국이 요구한 사업과 도지사 공약으로 정해져 있는 사업이 있을 거 아닙니까? 그러니까 우선순위를 도지사 공약사업에 두셨다는 거 아니에요, 예산편성할 때?
</p>
<p><b>○ 기획조정실장 허승범 </b> 꼭 그렇지는 않습니다. 방금 설명드렸듯이 도지사 공약사업도 25년도에 비해서 도 자체 재원을 2,700억 원 정도 덜 반영한 거고요. 그런 정도면 상당한 규모라고 생각합니다.
</p>
<p><b>○ 위원장 조성환 </b> 그런데 예산 때문에 이렇게 난리가 날 정도의 상황이 발생을 했는데 지금 말씀하시면 엊그저께, 지난주에 본회의 때도 도지사님께서 이런 예산들은 추가적으로 논의해서 편성할 수 있다, 추경에 편성할 수 있다 이렇게 말씀하셨어요.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 그럼 본인의 공약사업을 추경에 편성해 가지고 집행하면 이런 혼란이 없는 거 아닙니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 일부 그런 것도 있습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그래서 저는 궁금한 게 이러한 예산 세부적인 판단을 기조실장님이 하신 거예요, 예산부서의 총책임자로서?
</p>
<p><b>○ 기획조정실장 허승범 </b> 제가 판단하는 부분도 있고요. 제가 정리한 이후에 부지사나 지사께서도 판단하는 부분이 있습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그러면 처음에 초안을 잡았는데 보고하면서 이렇게 조정된 부분들이 있다라는 겁니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그렇습니다. 그거는 심의를 거치면서 계속 내부 편성을 하면서 여러 단계를 거치기 때문에 그 안에서 계속 변화는 변화무쌍하게 일어납니다.
</p>
<p><b>○ 위원장 조성환 </b> 실무부서의 판단은 어떤 판단이었습니까? 현장을 존중하는 판단이었습니까? 아니면 도지사 핵심 공약도 현장 사업이라고 안 볼 수는 없는 부분이 있지만 그럼에도 불구하고 이렇게 막대한 혼란이 발생할 걸 예상하셨어요? 못 했죠?
</p>
<p><b>○ 기획조정실장 허승범 </b> 저희가 현장에 대해서 좀 더 심사숙고하고 좀 더 세밀하게 살펴봤어야 되는데 그런 부분은 부족했던 것 같습니다.
</p>
<p><b>○ 위원장 조성환 </b> 많은 해당 과장님들, 실국장님들, 저에게 해당 부서에서 꼭 필요한 사업인데 이번에 예산실에서 다 삭감됐다, 살려달라, 이거는 꼭 해야 된다 이런 요청이 많았어요. 제가 그래서 말씀드린 사업들도 있지 않습니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 자살 유가족을 위한 사업이라든지 이런 것들. 지난번 상임위 할 때도 예산신문고라는 게 필요하다고 했잖아요. 예산을 배정할 때 힘없고 소외되고 약한 부분에서의 예산들은 쉽게 삭감이 될 수 있고 배정이 안 될 수 있고 그럴 수 있으니까 예산신문고를 운영해야 된다. 꼭 필요한 사업들은 별도의 트랙으로라도 보고를 받고 다시 살려야 된다라고 말씀을 드렸는데 이번 예산 과정에서 그런 과정이 있었어요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 별도의 신문고라고 해서 저희가 공식 채널을 만든 것은 아니지만 편성하는 과정에서 나름 다양하게 말씀을 많이 해 주셔서 공식적인 루트 이외에도…….
</p>
<p><b>○ 위원장 조성환 </b> 그러니까 결국에는 제가 볼 때에는 도지사의 핵심 공약사업이다 하면 그냥 반영된 확률이 높고 정말 현장부서의 안타깝고 시급한 사업들은 그냥 삭감됐을 가능성이 높아요. 배정이 안 됐을 사업이, 가능성이 높다는 말씀입니다. 제가 그래서 신규사업 자료가 오면 그걸 좀 분석해 보고 아까 주신 자료를 분석해 보려고 해요. 재정이 충분하고 여력이 있을 때에는 도지사님도 약속한 공약들 핵심적으로 추진하고 예산 많이 배정해서 가야 되겠죠. 그러나 어려운 상황에서는, 도지사님 사업들이 또 덩치도 크잖아요. 왜 본인 사업에 대해서만 이렇게 사업예산을 꼼꼼히 잘 챙기는 방향으로 하셨습니까? 물론 일부 삭감됐다고 하지만 비율적으로는…….
</p>
<p><b>○ 기획조정실장 허승범 </b> 위원장님 말씀 중에 죄송합니다만 지사님 사업이 사실 실국의 중요 핵심 사업입니다. 절대 그게 유리되거나 각각의 운영되는 건 아니기 때문에 그런 부분은 좀 이해해 주시면 좋겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그러면 처음에 예산실에서 예산을 수요조사했을 때 사업하고 지금 최종 결정된 사업하고 일일이 한번 다 분석해서 비교해 볼까요? 어떤 게 더 우선순위 시급하고 현장에서 필요한 사업들인지. 안 그랬으면 지금 복지예산 가지고 이렇게 많은 분들이 문자받고 전화받고 항의받고 살려 달라고 이게 온통 난리가 났겠습니까? 지금 밖에 소리 들리세요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 들립니다.
</p>
<p><b>○ 위원장 조성환 </b> 지금 그 시위 하는 거 아니에요? 생존권이 걸려 있어서 예산이 필요하다라고 하는 목소리가 이렇게 들리는 이 상황에서 우리 도지사님의 사업 3조 1,200억 원이 떡하니 올라와 있는 2026년도의 예산안 참 어떻게 고운 눈으로 바라볼 수 있겠습니까? 시간이 많이 지났으니까 이 정도 하고 그런 부분에 대해서는 조금 더 세부적으로 살핀 후에 다시 말씀을 드리도록 하겠습니다. 좀 안타깝습니다, 한말씀드리면, 그냥. 이번 예산안 편성에 대해서 상당히 안타깝다라는 말씀을 대신해서 드립니다. 이상입니다.
</p>
<p style="padding-left:1.2em">  이제 보충질의 시작하도록 하겠습니다. 우리 이혜원 부위원장님 먼저 보충질의해 주시죠.
</p>
<p><b>○ 이혜원 위원 </b> 양평군 출신 이혜원 부위원장입니다. 위원장님 말씀하신 거에 저도 100% 공감을 하고요. 저 또한 많은 예산 삭감에 대한 부분으로 도민들의 전화와 문자와 이메일과 할 수 있는 여러 가지 동원을 다 하셔서 말씀을 주고 계십니다. 제가 정확한 데이터는 아니지만 복지 쪽도 일몰사업만 64개 정도가 되고 그걸 따져보면 약 300억 이상이 된다고 합니다. 실질적으로 민생경제, 민생을 중심으로 예산편성하셨다고 하는데 그 부분이 좀 제대로 집행이 된 건지, 편성이 된 건지 면밀하게 검토를 하셔야 된다고 생각합니다. 지금 농업 쪽, 건설 쪽 다 난리입니다. 예산 때 좀 더 상세하게 말씀을 드리도록 하고요.
</p>
<p style="padding-left:1.2em">  일단 오전에 이어서 기조실에, 우리 기획조정실 김병연 기회전략담당관님 답변 주시죠. 위원장님, 그렇게 해도 되겠습니까?
</p>
<p><b>○ 위원장 조성환 </b> 나오셔서 답변하십시오.
</p>
<p><b>○ 이혜원 위원 </b> 내용을 담당관님이 더 잘 아실 것 같아서.
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 기회전략담당관 김병연입니다.
</p>
<p><b>○ 이혜원 위원 </b> 먼저 담당관님하고도 논의하고 제가 자료 요청하면서 검토했었던 내용이고요. 정책과제가 경기도의 운영에 대한 부분이 유명무실하다, 관리체계를 개선해야 한다라는 주장으로 제가 말씀을 드립니다. 지금도 정책에 관련된 부분이 얘기가 나왔지만 여기 정책과제 관련된 운영 및 지원에 관한 조례로만 제가 좀 말씀을 드려볼게요. 여기서 우선적으로 제4조 “도지사는 주요 정책 중 특별히 구체적인 목표나 수행 방안 등을 마련해서 효율적으로 추진ㆍ관리할 필요가 있는 업무를 정책과제로 선정할 수 있다.” 이렇게 되어 있습니다. 맞죠?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 그럼 여기서 특별히, 과제를 선정하는 데 있어서 이 ‘특별히’라는 부분을 어떻게 기준을 정해서 진행하고 계십니까?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 저희가 내부지침을 만들어서 과에서 의뢰가 들어오면 그 기준에 따라서 점수를 매겨서 지원대상으로 선정을 하고 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 내부지침에는 어떻게 돼 있습니까? 어떻게 결정하게 되어 있어요?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 잠깐만 자료를 좀 보고 말씀드리겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 네.
</p>
<p style="padding-left:2.4em">    (기획조정실기회전략담당관, 자료 확인 중)
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 연구 필요성, 활용 가능성이라든지 연구 적정성하고 공무원이 직접 수행 가능한지 여부들 그런 부분들을…….
</p>
<p><b>○ 이혜원 위원 </b> 그 부분을 누가 심사를 합니까?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 저희 부서에서 자체적으로 하고 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 부서에서 자체적으로 하시잖아요.
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 그러면 전반적으로 지금 관리 부서 형태로 하시는 거고 경기도 집행부의 전 부서에서 이 사안들이 올라오면 지금 기회전략담당관에서 이 내용 확인을, 심사를 하신다는 얘기죠, 자체적으로?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 그런데 여기에 제도를 보면 평가위원회가 있습니다, 제7조에. 정책과제 평가위원회의 설치, 설치되어 있습니까?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 조례에 보면 정책연구용역심의회에서 대행할 수 있도록 되어 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 하게 되어 있죠. 그 심의위원회가 기능을 대행하게 되어 있는데 대행하셨어요?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 죄송하지만 한 번도 못 했습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그러니까요. 지금 자료를 제가 요구했는데 세 번이 바뀌어서 올라왔습니다. 그렇죠? 먼저는 관리카드하고 세 가지로 구분을 해서 주셔서 내용을 확인하는 과정에서 지금 그 부분이 좀 잘못됐다 해서 다시 주셨고 세 번째 또 다시 주셨어요. 그래서 제가 세부내용까지 좀 확인해 보려고 보니까 이 세부내용은 더 엉망진창입니다. 보시면 연구결과 자체평가서인데 여기 담당자 서명이 있어야 되는 것 같고 그리고 직위에 평가자 서명이 있어야 되는데 평가자에 서명이 돼 있는 게 하나도 없어요. 22년부터 25년까지 지금 자료 제출된 거에. 그리고 내용도 관리카드와 또 활용실적서. 근데 이 부분은 이거를 수행하기 위한 매뉴얼인 거잖아요, 양식지이고.
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 저희가 위원님한테 드린 자료에도 쓰여 있지만 연구가 이것이 저희 공무원들이 용역을 주기에는 사이즈가 작고 자체로 하기에는 좀 전문성이 요구되는 거를 외부 전문가들을 통해서 자문이나 원고료 최대 한 300만 원 주는데 그거를 통해서 이제 자기 업무에다가 반영을 하는 겁니다. 그런데 이게…….
</p>
<p><b>○ 이혜원 위원 </b> 맞습니다. 거기에 대한 설명은 지금 시간이 없어서…….
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 그래서 연구가 끝…….
</p>
<p><b>○ 이혜원 위원 </b> 담당관님이 말씀하시는 게 맞는데요. 그러면 그거에 대한 수행 과정을 명확하게 하셔야 되잖아요. 제가 정확하게 여기 있는 것만 말씀드릴게요. 과제 선정은 지금 여기 제출한, 정책과제에 관련된 부분은 저한테 제출하신 자료가 다죠?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 여기 보면 정책과제물 자체평가표가 있고요. 그리고 관리카드나 활용실적서 두 가지 중에 한 가지가 있습니다. 그게 26년도부터 조금씩 23년도인가 관리카드로 운영하다가 활용실적서로 대체된 것도 있고 중복적으로 사용하지 않고 이거 하나, 이걸 쓰거나 저걸 쓰거나 하는 경우도 있어요. 근데 문제는 이 양식지를 말하는 게 아니고 여기에서 얘기하는 예산 낭비를 예방해야 되는 부분, 수시로 점검해야 되는 부분. 그리고 결과가 나왔으면 종료 후에도 결과를 평가해야 되고 결과에 대한 활용상황을 점검해야 됩니다. 조례에 의거해서 말씀드린 거예요, 1항부터 4항까지. 근데 그 부분이 여기에서는 찾아볼 수가 없어요. 차라리 관리카드에 대한 부분은 예산 절감부터 내용이 있습니다. 사후 평가가 없어요. 활용을 어떻게 했는지도 없어요. 근데 활용실적서는 더 합니다. 활용실적서에는 내용 자체가 없어요. 활용실적에 대한 내용만 있지 이거를 결과적으로 어떻게 활용했는지에 대한 게 없습니다. 과정을 거치셔야죠. 그리고 평가위원회가 있잖아요. 평가위원회 활용하셔서 제대로 평가하셔야죠, 반영하시고. 근데 그 부분이 진행이 안 됐는데 문제가 없다라고 말씀을 하시면…….
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 제가 문제없다는 말씀 안 드렸…….
</p>
<p><b>○ 이혜원 위원 </b> 저한테 개별적으로 설명하실 때 문제없음에 대한 부분으로 말씀하셨잖아요.
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 저희가 연구를 종료하면 3개월 이내에 받는 게 활용계획서나 관리카드를 받습니다.
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p><b>○ 이혜원 위원 </b> 위원장님, 죄송합니다. 1분만 좀 더 쓰겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 네, 먼저 좀 가셔야 되니까 추가질의까지 그러면 하시는 걸로 하겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 네. 그러면 제가 이 관리카드에 있는 내용으로 말씀을 드릴게요. 23년도에 있었던 거고요. 대부분이 다 그렇습니다, 뭘 찾는 게 아니라. 수행결과에는 그냥 추진완료만 써 있어요, 사업 수행에. 추진경과, 정책연구 결과 후속조치 추진 중, 향후계획 자체결과 보고서 제출, 공문 시행, 수행결과 추진완료. 뭐 어떤 걸 추진을 완료했다는 거예요, 언제? 어디에 반영을 했다는 겁니까? 과제가 선정이 됐으면 그 과제에 대한 부분이 수행돼야 되고 수시에 대한 부분으로 점검을 해야 되고 결과가 나왔으면 결과에 대한 평가와 그 활용상황에 대한 부분까지 점검을 하게 되어 있지 않습니까? 우리 공무원들은 이 조례에 의해서 업무를 수행하시는 거 아닙니까?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 저희가 이제 매년 정기적으로 관리카드로 진행상황을 체크하고 있는데 지금 위원님이 말씀하신 것처럼 그것이 어디에 반영됐는지에 대한 그런 자료까지는 받지 않고 또 평가위원회를 통해서 평가를 안 한 부분은 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그리고 결재라인도 제대로 안 되고 있는 것 같고요. 이게 각 부서에서 실질적으로 위에 평가자가 보고 계신 건지 모르겠습니다. 지금은 다 담당자들만 사인이 돼 있고 과장님들은 하나도 사인이 안 되어 있고요. 그리고 반영 결과에 대한 부분을 분명히 종합평가의견에 평가의견을 제시했는데도 불구하고 평가가 반영된 부분이나 활용상황 점검된 부분이 전혀 없습니다.
</p>
<p style="padding-left:1.2em">  그러니까 만약에 이 매뉴얼이나 양식지를 만드실 거면 이런 과정이 다 활용이 될 수 있는 양식지를 만들어서 체계화를 하시든지 그러면 사후평가까지 다 가능할 거 아닙니까? 근데 여기 내용에는 그냥 수시에 대한 성과까지 보고하는 것만 되어 있습니다, 실적서도 마찬가지고. 그러다 보니까 이후 수행이 안 되는 겁니다. 그리고 평가위원들을 활용해서 평가에 대한 점검을 하게 되어 있음에도 불구하고 평가위원들은 활용을 안 하고 계십니다. 그러니까 제가 말씀드리고 싶은 거는 기본에 충실해서 하는, 충실만 해도 적극행정이 될 것 같다라고 말씀드리는 겁니다.
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 네, 위원님이 지적하신 사항하고 조례에 따른 절차를 준수해서 업무를 수행하도록 하겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 제가 이 사례에 대한 부분을 정책과제의 운영 및 지원에 관한 조례에 관련돼서 말씀을 드려서 그렇지. 기조실장님, 제가 어제도 말씀드린 것처럼 저 조례 보고 있거든요. 조례에 근거해서 진행을 해야 되는데……. 기회전략담당관님 들어가셔도 좋습니다. 근데 조례에 근거해서 업무 수행에 대한 부분들이 제대로 이루어지고 있지 않은 거 너무 많습니다. 필요 없는 거는 진단하셔서 일몰하시고요. 꼭 필요한 부분들에 대한 것들은 조례에 의거해서 업무가 수행될 수 있게만 해도 적극행정이라고 저는 판단이 됩니다. 적극행정을 별도로, 제가 지금 적극행정도 말씀을 드려야 되는데 적극행정에 경기도교육청은 적극행정 면책 제도가 정확하게 돼 있어요. 경기도는 없습니다. 공무원들이 적극적으로 행정을 하려고 해도 면책 제도든 이게 있음에도 반영이 안 돼요. 좀 면밀하게 봐주십시오, 제대로.
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 무슨 말씀인지 알겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 이혜원 부위원장님 수고하셨습니다. 보충질의하실 위원님 거수로 신청해 주시기 바랍니다. 0.1초 빠르셨어요. 네, 이석균 위원님 질의해 주십시오.
</p>
<p><b>○ 이석균 위원 </b> 남양주 이석균 위원입니다. 우리 경기연구원 제가 좀 여쭤보겠는데요. 원장님.
</p>
<p><b>○ 경기연구원장 강성천 </b> 네.
</p>
<p><b>○ 이석균 위원 </b> 최근 3년 경영평가 결과를 보니까 기관도 그렇고 기관장도 그렇고 다 다등급이에요.
</p>
<p><b>○ 경기연구원장 강성천 </b> 그렇습니다.
</p>
<p><b>○ 이석균 위원 </b> 제가, 작년에 행정사무감사 때 계셨었던가요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 지난해에는 제가 없었습니다.
</p>
<p><b>○ 이석균 위원 </b> 없으셨죠? 그때 제가 우리 공공기관담당관님을 통해서 전반적인 출연ㆍ출자기관들에 대해서 경영평가를 집중적으로 다룬 적이 있습니다. 우리 경기연구원의 기관도 그렇고 기관장평가가 이렇게 나온 이유가 뭘까요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 여러 가지 미흡한 부분이 많이 있습니다만 특히 기관평가 부분에 있어서는 경영전략이 상당히 취약한 걸로 나왔고 또 한편으로는 상생 노력이 좀 부족한 걸로 지금 평가가 됐습니다. 그리고 기관장 부분에 있어서는 목표 달성을 위한 노력과 성과 부분이 상당히 미흡한 것으로 평가되었습니다.
</p>
<p><b>○ 이석균 위원 </b> 지금 올해 기관장 평가받으신 거는 원장님 평가입니까, 아니면 전임자 평가입니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 이 부분은 24년도에 대한 평가입니다. 그래서 전임자에 대한 평가……. 
</p>
<p><b>○ 이석균 위원 </b> 전임자 평가죠?
</p>
<p><b>○ 경기연구원장 강성천 </b> 그렇습니다.
</p>
<p><b>○ 이석균 위원 </b> 결국은 쭉 내용들을 살펴보면 내부 만족도라는 이야기가 많이 나와요. 내부 만족도가 혹시 뭔지 아시겠지만 한번 설명해 주시겠습니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 네, 기관의 운영에 대한 내부 구성원들의 평가……. 
</p>
<p><b>○ 이석균 위원 </b> 그렇습니다. 행정라인과 연구라인 혹은 직급 간의 혹은 원장님 포함해서 우리 일반 연구원들과 또 원장님 혹은 부원장님 이런 내부갈등들이 지속적으로 보여요. 해결할 수 있는 방법 생각하신 것 좀 얘기해 주십시오.
</p>
<p><b>○ 경기연구원장 강성천 </b> 네, 말씀 주신 대로 경기연구원 내부 구성이 크게 보면 박사급 연구위원들, 석사급 공무직들, 행정직들, 크게 세 그룹으로 구성이 되어 있습니다. 그러다 보니 운영 시스템 또 여러 가지 보수나 근무와 관련된 규정이 조금 상이한 점이 있어서……. 
</p>
<p><b>○ 이석균 위원 </b> 원장님, 이거 추가질문이어서 시간상의 제약이 있어서 원장님이 앞으로 어떻게 좀 하시겠다 하는 부분을 얘기해 주십시오.
</p>
<p><b>○ 경기연구원장 강성천 </b> 저는 말 그대로 공정한 운영이 될 수 있도록 최선을 다해 노력하겠습니다.
</p>
<p><b>○ 이석균 위원 </b> 관련해서 우리 경기연구원의 조직이나 이런 부분들에 컨설팅을 좀 받아보시라 하는 부분들을 적극 권장해 드렸었고 이유가 조직정비만 그러니까 지금 시대적 조류에 따라서 연구기관 연구 분야 파트라든가 이렇게 그것만 얘기를 말씀드린 게 아니고 바로 이런 내부 만족도도 이 조직의 진단과 혁신을 통해서 좀 해결하시면 좋겠다 하는 부분들을 말씀드렸는데 오시자마자 조직개편은 하셨어요. 근데 조직진단은 받지 않으셨는데 앞으로 어떻게 받으실 계획이 있으십니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 조직진단이 시작이 됐습니다. 외부 기관에 저희가……. 
</p>
<p><b>○ 이석균 위원 </b> 아, 그래요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 네, 시작이 됐고요.
</p>
