<p style="padding-left:1.2em">  경기관광공사, 경기도평생교육진흥원 그리고 경기문화재단이 28년에 들어오는 것으로 예정되어 있습니다. 이 세 군데는 처음 계획이 2019년 11월이에요. 그 계획에서 벌써 10년의 시간이 흐른 건데 사실 28년에도 정확하게 들어갈 수 있는지는 제가 잘 모르겠어요. 어떠한 일이 또 변수가 되어서 이렇게 또 지연될지 알 수가 없어서 준비되어 있는 것을 급조해서 들어가시라는 말씀은 아니지만 마지막 최종 마지노선이 28년이라고 생각하시고 그 안에 지금부터 직원들을 어떻게 이동하실 수 있는 준비를 하실 건지 그리고 재정 확보는 어떻게 하실 건지 전반적인 모든 부분에 대해서 충분히 지금부터 준비가 돼서 가실 수 있게 해 주시고 고양에 들어오는 그날이 반드시 28년은 약속을 지켜주셔야 한다. 그래야 도민들이 10년을 기다리는 것에 답이 될 거기 때문에 그 약속을 반드시 지켜주시고 그때 가시는 거는 전체 이전이기를 반드시, 일부분씩 가지 않고 전체가 가길 바랍니다. 
</p>
<p style="padding-left:1.2em">  공공기관에 대해서 이전 그리고 경기도 공공기관의 복지 그리고 재정 이 모든 부분들에 대해서 기조실에서 좀 더 꼼꼼히 정확하게 잘 살피셨으면 좋겠다는 말씀을 드리고 다시 한번 공공기관과 경기도의 관계에 대해서 경기도의원으로서 중간 역할을 잘 못 한 부분에 대해서 죄송스럽고 심히 유감입니다. 경기도에서 앞으로 그런 일이 다시 일어나지 않기를 간곡히 요청드리면서 제 질의를 마치겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 이경혜 부위원장님 수고하셨습니다. 보충질의하실 위원님 또 거수로 신청해 주십시오. 오창준 위원님 질의해 주십시오.
</p>
<p><b>○ 오창준 위원 </b> 광주 출신 오창준 위원입니다. 오전에는 너무 경기도에만 질의드린 것 같아서 연구원에 질의 좀 드리려고 합니다. 원장님께 질의드리겠습니다. 올해 도 종합감사도 받으시고 그다음에 자체감사도 실시하셨죠?
</p>
<p><b>○ 경기연구원장 강성천 </b> 네.
</p>
<p><b>○ 오창준 위원 </b> 종합감사 시기랑 자체감사 시기가 어떻게 어떻게 됩니까? 
</p>
<p><b>○ 경기연구원장 강성천 </b> 종합감사는 3월에 실시한 것으로 알고 있고요. 자체감사는 7월에 했습니다.
</p>
<p><b>○ 오창준 위원 </b> 7월에. 그러면 자체감사하실 때는 종합감사에서 지적받은 부분을 다시 중복 지적하고 이런 거는 배제하고 감사를 하십니까?
</p>
<p><b>○ 경기연구원감사실장 민철기 </b> 죄송한데 제가 답변드려도 되겠습니까? 
</p>
<p><b>○ 오창준 위원 </b> 네, 위원장님 허락해 주시면.
</p>
<p><b>○ 위원장 조성환 </b> 그렇게 하시죠.
</p>
<p><b>○ 경기연구원감사실장 민철기 </b> 경기연구원 감사실장 민철기입니다. 제가 답변드리는 게 좀 구체적일 것 같아서 신청을 했습니다. 자체감사는 종합감사에서 감사한 것과 중복되지 않도록 감사를 시행했고요. 올해는 종합감사를 아주 깊게 받았기 때문에 종합감사에서 지적된 사항에 대해서 이행상황을 점검하는 데 중점을 두고 감사를 시행했습니다.
</p>
<p><b>○ 오창준 위원 </b> 그러면 지금 중복된 거는 가능하면 배제를 했다고 들었는데 제가 지금 지적사항을 보니 종합감사에서 근무시간 미준수에 따른 경기연구원 인사 복무규정 위반 사안을 지적받으셨고 그런데 자체감사에서는 또 유연근무 관리 소홀, 제가 보기에는 근무 태도는 거의 같은 맥락의 문제사항 같은데 이건 또 중복 지적이 됐어요.
</p>
<p><b>○ 경기연구원감사실장 민철기 </b> 같은 맥락인데요. 종합감사에서 그 부분에 대해서 감사를 안 했기 때문에 저희가 그 부분에 대해서는 조금 더 들여다봤습니다.
</p>
<p><b>○ 오창준 위원 </b> 감사를 안 했다는 게 어떤 거, 이 유연근무는 감사를 안 하고 그냥……. 
</p>
<p><b>○ 경기연구원감사실장 민철기 </b> 종합감사에서는 일정한 복무 전체적인 상황에서 점검을 했고요. 유연근무에 대해서는 그때 깊게 안 봤기 때문에 저희들이 이제 들여다봤습니다.
</p>
<p><b>○ 오창준 위원 </b> 종합검사에서 왜 깊게, 대부분 유연근무를 많이 하시지 않아요, 구성원들께서?
</p>
<p><b>○ 경기연구원감사실장 민철기 </b> 유연근무보다 요즘에는 시간제근무를 선택해서 이렇게 대부분 선호를 하고 있습니다, 직원들께서.
</p>
<p><b>○ 오창준 위원 </b> 유연근무랑 시간제근무 차이가 어떤?
</p>
<p><b>○ 경기연구원감사실장 민철기 </b> 정확하게는 모르겠는데 제가 이해하는 바에 의해서 말씀을 드리면 시간제근무는 한 달에 일정 시간을, 집중 근무시간이 10시에서 3시고요. 그 이외에는 시간을 자기가 탄력적으로 활용을 해서 한 달 기간에 자유롭게 쓰는 게 시간제 선택 근무시간이고요. 유연근무제는 하루 기준으로 해서 7시에 오면 9 to 6처럼 2시간 일찍 가면 2시간 늦게 가고.
</p>
<p><b>○ 오창준 위원 </b> 유연한 범위가 하루냐 주 단위냐 그거에 대한 차이다 그 말씀 주시는 건데……. 
</p>
<p><b>○ 경기연구원감사실장 민철기 </b> 네, 그렇습니다.
</p>
<p><b>○ 오창준 위원 </b> 근데 이게 매번, 제가 알기로 작년도 그렇고 재작년도 그렇고 계속 좀 꾸준하게 지적사항으로 나왔던 것 같은데 근본적인 혹시 원인이 뭐라고 판단하세요?
</p>
<p><b>○ 경기연구원감사실장 민철기 </b> 지금 근본적인 원인을 제가 말씀드리면 종합적으로 이렇게 저희가 관리하는 시스템이 조금 미흡해서요. 지금 그 부분에 대해서 종합감사 이후에 집중적으로 검토를 하고 있습니다. 시스템 개선하는 데는 또 추가적으로 예산이 수반돼서 다른 기관, 잘 되고 있는 기관을 저희들이 찾아가서 벤치마킹을 해서 종합적으로 복무시스템을 효율적으로 운영하는 데 집중을 두고 지금 시행을 하고 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 이게 그러니까 하루 이틀 된 문제가 아닌 것 같아서. 제가 이번에 감사 내역을 보긴 했지만 재작년, 작년 행감 때도 계속 위원님들이 이렇게 한 번씩 언급하셨던 문제로 제가 기억을 해서 이게 계속 지적이 나오고 있는 문제길래 도대체 어떤 게 근본적으로 문제고 해결 방안이 뭔지 좀 궁금해서 말씀을 드렸고요. 이제 잘 운영되고 있는 시스템, 그러니까 제가 보기에는 공공기관 중에 이렇게 막 유연근무제나 이 시간제근무를 잘 활용하는 기관은 잘 없잖아요. 대부분 외부 기업들이나 외국계 기업이나 이런 데서 많이 운영을 하지 국내 공공기관이나 공기업에서는 잘 못 본 것 같긴 하거든요, 이런 사례들을. 그래서 그런 부분도 벤치마킹 잘 하셔 가지고 조금 선도모델이 될 수 있게, 경기연구원이. 어쨌든 다른 28개 공공기관들 중에서 으뜸 가는 공공기관이 될 수 있도록 모범이 되는 사례를 만들어주셨으면 해서 말씀드렸습니다.
</p>
<p><b>○ 경기연구원감사실장 민철기 </b> 네, 그렇게 하겠습니다.
</p>
<p><b>○ 오창준 위원 </b> 네. 그다음에 연구원장님께 다시 한번 좀 질의드릴게요. 이것도 매년 나오는 지적이긴 한데 이직률 관련해서요. 작년에도 제가 이직률이 워낙 높아서 그 부분에 대한 뭔가 근본적인 대책이 필요하다고 말씀을 드렸었고 답변 주신 게 중장기 인력 운영계획을 새로 수립해서 뭐 중기계획도 했고 그 안에 방지를 위한 개선 이런 것들을 뭉뚱그려서 답변을 주셨는데 구체적으로 어떤 개선이 좀 있었는지 여쭤봐도 될까요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 지금 전체적인 통계를 최근 3년간을 보면 전체적인 이직 인원 자체는 줄고 있는 것은 사실입니다. 다만 그럼에도 불구하고 특히 그룹별로 봤을 때 석사 공무직하고 행정직 계층의 이직률이 상대적으로 높습니다. 저는 여러 가지 이유가 있겠습니다만 중요한 부분은 사실은 처우에 대한 불만 요소가 가장 크다고 보여지고요. 특히 저희하고 비슷한 기능을 하고 있는 다른 연구기관하고 비교했을 때 상대적으로 처우 수준이 미흡한 것이 사실입니다. 그래서 그 부분은 저희가 도와 지속적으로 협의를 해서 개선방안을 찾고요. 특히 지금 공무직 석사연구원들의 처우가 상당히 열악한 것이 사실입니다, 특히. 가장 저는 심각하다고 보고 있고 이분들이 조금 더 현재보다 개선될 수 있는 처우를 받을 수 있도록 개선방안을 저희가 내부적으로 만들고 있고요. 그래서 그런 부분을 도와 상의해서 개선할 수 있도록 노력하겠습니다.
</p>
<p><b>○ 오창준 위원 </b> 이게 사실 현실적으로 제일 좋은 거는 뭐 임금을 높이거나 이런 직접적인 방법이 제일 좋을 텐데 그거는 현실적으로 할 수 있는 부분이 아니지 않습니까, 연구원에서, 아무래도? 그러다 보니까 이제 복지…….
</p>
<p><b>○ 위원장 조성환 </b> 정리해 주세요.
</p>
<p><b>○ 오창준 위원 </b> 네. 아, 시간이 다 됐구나.
</p>
<p><b>○ 위원장 조성환 </b> 시간이 넘었습니다.
</p>
<p><b>○ 오창준 위원 </b> 그냥 마무리 발언으로 하겠습니다. 그래서 직접적으로 월급을 올려주는 게 제일 좋겠지만 이제 그런 것들이 현실적으로 좀 어렵다 보니 복리후생, 이게 사실 각 조직마다 이렇게 좀 차별화된 그런 복리후생 구역이 있지만 경기연구원에서도 또 근무환경이나 이런 것들이 다른 공공기관에 비해 좀 차이가 있다 보니 이제 그런 부분들 잘 고려해서 복리후생을 어떤 거를 좀 복제하면 좋을지에 대한 고민을 깊이 해 주셨으면 좋겠습니다.
</p>
<p><b>○ 경기연구원장 강성천 </b> 네, 알겠습니다.
</p>
<p><b>○ 오창준 위원 </b> 질의 마치겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 오창준 위원님 수고하셨습니다. 또 보충질의하실 위원님, 이채명 위원님 질의해 주십시오.
</p>
<p><b>○ 이채명 위원 </b> 고생 많으십니다. 기회전략담당관님께 한번 질의드리겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 기회전략담당관님 발언대에 나오셔서 말씀해 주세요.
</p>
<p><b>○ 이채명 위원 </b> 제가 지난 6월 19일 날 저희 안양상담소에서 기회전략담당관 팀장님이랑 그리고 미래위TF 위원들과 함께 정담회를 가진 적이 있습니다. 혹시 여기 같이 그때 오신 분이 계신지 모르겠습니다. 저희가 작년부터인가요, 미래위원회TF가 조성이 됐습니다. 정책오디션을 거쳐서 25명이 작년에 선정이 됐고요. 올해도 그러면 어떻게 미래위원회TF로 정책 발굴하기 위해서 구성이 됐나요?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 기회전략담당관 김병연입니다. 그때 구성되셨던 분들의 임기를 저희가 24년 1월 20일부터 금년도 11월 20일까지로 1년을 잡았습니다.
</p>
<p><b>○ 이채명 위원 </b> 그러면 아직 기간이 남아 있네요?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 네.
</p>
<p><b>○ 이채명 위원 </b> 그분들께서 제안했던 정책들에 대해서는 지금 어떻게 활용하고 계시나요?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 그분들이 이제 토론그룹들을 운영해서 저희한테 정책 제안을 22건 제출해 주셨습니다.
</p>
<p><b>○ 이채명 위원 </b> 맞습니다.
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 그래서 저희가 그거를 각 부서에다가 실행이 가능한지를 보내봐서 저희가 한 3~4건 정도를 가능한 거로 골라서 저희 부서에서 직접 한 2건 정도를 하고 있고 2건은 타 부서에서 현재 하고 있습니다. 4건 정도가 들어가 있습니다.
</p>
<p><b>○ 이채명 위원 </b> 그러면 4건 정도만 일단은 정책방향으로 가져가는 걸로 이렇게 결정하고 나머지는 어떻게 됐나요?
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 나머지는 부서에서 채택하기 어려운 거기 때문에…….
</p>
<p><b>○ 이채명 위원 </b> 어렵다라고 하면 어떤 부분 때문에 어려운 거죠? 왜냐하면 제가 말씀드리고 싶은 거는 저희 안양의 상담소에 저를 찾아왔습니다, 그 TF 위원들께서. 왜냐하면 안양에 있는 도의원 중에 누군가는 이 제안들이 사장되지 않고 정책으로 가져갔으면 좋겠다라는 뜻으로 저에게 비공개 정책 정담회를 했었는데 그중에서 4건을 저희한테 제안을 했습니다. 제안과제가 뭐냐 하면 자율방범대 연계 약자 돌봄 그리고 글로벌 인재 유치, 청년 유휴공간 연계 등등 해서 4건을 이렇게 가져왔어요. 그래서 제가 그때 어떻게 얘기를 했었냐면 이런 것 등이 사장되지 않기 위해서 제가 경기연구원을 찾아갔습니다. 혹시 연구원장님 계시죠?
</p>
<p><b>○ 경기연구원장 강성천 </b> 네.
</p>
<p><b>○ 이채명 위원 </b> 제가 저번에 부탁을 좀 드렸습니다. 이 부분에 대해서 혹시 도민들의 생활 속의 정책 제안을 실질적으로 제안하기 위해서는 경기연구원에서 기회전략담당관과 함께 정책 연계 프로세스가 있었으면 좋겠다라고 이렇게, 이런 것 등을 제도화했으면 좋겠다라고 제안을 드렸었거든요. 이 부분에 대해서 지금 어떤 방향으로 흘러가고 있는지 간단하게 답변 부탁드리겠습니다.
</p>
<p><b>○ 경기연구원장 강성천 </b> 지난번에 우리 위원님 저희 방문해 주셔서 좋은 제안을 해 주셨고요. 저희가 매년 정책과제 수요조사를 합니다. 그래서 정책 수요조사를 할 때, 도민들 대상으로 정책 수요를 받아서 그거를 저희가 저희 연구과제에 반영하는 프로세스를 좀 더 강화하는 쪽으로 도하고 협의를 하도록 하겠습니다.
</p>
<p><b>○ 이채명 위원 </b> 제가 그때 4건을 가지고 갔었는데 그 건에 대해서는 혹시 정책적으로 고민했다든가 이걸 연구과제로 한번 가져가야 되겠다라고 하는 것 등이 있었나요, 4건 중에서?
</p>
<p><b>○ 경기연구원장 강성천 </b> 저희가 내년도 연구과제에 반영하도록 노력하겠습니다.
</p>
<p><b>○ 이채명 위원 </b> 일단은 왜 이런 말씀을 제가 드리냐면요. 도민들의 이런 생활 속의 정책 제안을 실질적으로 이런 것들을 정책으로 반영하기, 전환하기 위해서는 저는 이게 단순한 공모 제도가 되면 안 된다라고 생각합니다. 그래서 일단 첫 번째, 제안 접수 그리고 부서 검토를 하고요. 경기연구원의 연구과제 연계 그리고 실행부서와의 어떤 협업이 필요하고요. 마지막으로 도정 반영으로 이어지는 이런 정책 연계 프로세스가, 이제는 대충대충 정책 제안하면 이걸 뭐 반영할까 말까 이게 중요한 게 아니라 이걸 제도화해야 된다라고 저는 그때도 말씀드렸고요. 다시 한번 이 자리에서 말씀드리겠습니다. 현재 기회전략담당관실은 이와 같은 어떤 그런 구조적인 프로세스를 마련하고 있는지 그리고 향후에 이렇게 도민 제안형 연구과제 상설 플랫폼을 운영할 계획이 있는지 구체적인 계획을 간단하게 답변해 주시기 바랍니다.
</p>
<p><b>○ 기획조정실기회전략담당관 김병연 </b> 위원님께서 말씀하신 도민들이 주신 소중한 정책 제안들을 저희가 부서에서 채택되지 않았더라도 다시 한번 좀 정책화될 수 있는 그런 부분으로 검토를 해 보겠습니다.
</p>
