<p><b>○ 이채명 위원 </b> 그리고 기회전략담당관님께 다시 한번 부탁드리겠습니다. 작년에, 이제 이분들이 11월 달에 임기가 끝나잖아요. 그럼 일회성이 되면 안 된다고 저는 생각하고요. 올해는 어떤 방식으로 또 미래위원회TF팀을 공모 선정해서 이런 친구들을 어떻게 발굴하고 앞으로 어떻게 갈 것인지에 대해서 간단한 답변 주시기 바랍니다.
