</p>
<p><b>○ 이채명 위원 </b> 이제 4건만 채택되고, 22건 중에서 4건만 채택됐다고 말씀드린 거잖아요. 나머지는 이제 각 부서에다가 사실은 던진 거잖아요. 그러면 추후에라도 그 나머지 던져진 각 부서에서 이런 정책 제안했던 사업들이 어떤 방향으로 가고 있는지까지도 마지막까지 검토하시고요. 피드백 주시고요. 그리고 그분들이 그냥 제안으로만 끝날 게 아니라 내가 제안했던 것들이 정책으로 반영됐을 때 우리 도민들의 삶에 어떻게 적용됐는지까지도 좀 피드백 주시면 고맙겠습니다.
