<p><b>○ 이성호 위원 </b> 여기 이제 11조가 들어가 있으니까 적용 제외된다고 하시는 거잖아요?
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 네, 그렇습니다.
</p>
<p><b>○ 이성호 위원 </b> 근데 그 11조는 어떤 조항인지 아시죠?
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 성과계약 관련 조항입니다, 기관장이.
</p>
<p><b>○ 이성호 위원 </b> 성과계약 관련 조항입니다, 11조는.
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 네, 그렇습니다.
</p>
<p><b>○ 이성호 위원 </b> 근데 경영실적 평가는 28조에 나와 있습니다. 그런데 이제 경영실적 평가와 기관장 성과계약은 같은 제도가 아닙니다. 전혀 다른 제도고 조항도 다르죠. 경기도 출자ㆍ출연 기관 운영 조례에 의하더라도 성과계약서 실적평가는 총괄부서장이 하는 거고 경영실적 평가는 경영평가단이 수행하는 겁니다.
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 네, 그렇습니다.
</p>
<p><b>○ 이성호 위원 </b> 따라서 조례 제7조에 총괄부서장의 성과계약서 실적평가 대상에서 제외된다고 해서 기관장 경영실적 평가대상에서 당연히 제외되는 게 아닙니다. 다른 지자체의 사례를 찾아보세요. 다른 지자체에서는 이거를 제외하지 않는 지자체가 많이 있습니다. 이에 대해 어떻게 생각하십니까?
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 지금 실질적으로 기관장 평가는 성과계약을 근거로 해서 평가를 하고 있습니다. 그래서 지금 저희가 보통 기관장 평가는 책임경영, 성과목표, 이행실적 이렇게 나눠서 하고 있는데…….
</p>
<p><b>○ 이성호 위원 </b> 1분만 더 하겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 네, 추가시간 좀 더 주세요.
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 여기에서 대부분 성과목표, 이행실적은 성과계약서상의 그 목표에 따라서 얼마큼 달성했는지를 평가하는 사항이기 때문에 저희가…….
</p>
<p><b>○ 이성호 위원 </b> 그게 성과계약이 없다고 해서 그 기관장의 경영실적 평가를 할 수 없다는 건 말이 안 되는 거예요. 형식논리에 불과하지 않습니까? 계약서가 안 왔다고 경영, 그 기관장이 어떤 업무 수행을 안 하는 겁니까? 업무 수행하는 걸 왜 평가를 못 합니까? 성과계약서 없어도 당연히 할 수 있죠, 그거를. 그리고 지금 2조3항에 제외 단서조항 1호에 보시면 “지방자치단체가 최대지분을 보유하고 지분의 분산도와 기관 지배가 가능한 경우” 돼 있죠?
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 네, 있습니다.
</p>
<p><b>○ 이성호 위원 </b> 충분히 저는 여기에 해당할 수 있다고 보거든요.
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 여기에 이제 해당할 수 있는데 이거는 저희가 기관별로…….
</p>
<p><b>○ 이성호 위원 </b> 그리고 왜냐하면 이게 지금 경기도주식회사라는 것이 독립해서 자체사업을 하는 곳도 아니고 90%가 위탁사업을 하는 곳 아닙니까?
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 네.
</p>
<p><b>○ 이성호 위원 </b> 그렇기 때문에 당연히 1호에 해당할 수 있다고 보고요. 그래서 기관은 포함되는데 기관장은 경영실적 평가대상 안 된다는 건 완전히 형식논리에 불과해 보입니다. 면밀하게 재검토를 해 주시기 바랍니다.
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 네. 이런 부분은 다시 한번 검토를 해서 이렇게 반영할 수 있으면 반영하도록 노력하겠습니다.
</p>
<p><b>○ 이성호 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 이성호 위원님 수고하셨습니다. 다음 질의하실 위원님, 박상현 위원님 질의해 주십시오.
</p>
<p><b>○ 박상현 위원 </b> 위원장님, 필요시 우리 과장님들, 아니, 담당관님들…….
</p>
<p><b>○ 위원장 조성환 </b> 네, 그렇게 하시죠. 우리 과장님들은 위원님 호출이 있으면 바로바로 발언대로 나와서 말씀해 주시기 바랍니다.
</p>
<p><b>○ 박상현 위원 </b> 경기연구원과 우리 기획조정실 양측에 질의를 좀 하도록 하겠습니다. 작년에 경기연구원에다가 요청했던 사항이 어떤 것이었냐 하면 경기연구원에서 발행하는 그 소중한 정책결과가 경기도정에 어떻게 반영이 되는지에 대해서 협업체계를 마련하고 그 정책을 누가 받아서 활용을 했는지에 대한 주무부서와 그다음에 담당자까지 기재해 달라고 했는데 그 사항이 반영되지 않았어요. 다만 조금 반영이 된 거는 경기연구원 업무보고서 42페이지에 보면 기타 현황에 연구과제 수행실적표에 맨 마지막 정책 반영 및 활용 여부에 대한 것을 기재하기 시작했습니다, 2년 전에. 하지만 이거 가지고는 부족하죠. 왜냐하면 경기연구원이 자체적으로 활용됐다라고 판단하게 된다면 그거는 행정적 기만의 행위로 보기 때문에 실질적으로는 이 정책을 누가 받아서 활용을 했는지에 대한 그 부서와 그 담당자, 담당 공무원을 기재해 달라고 요청했는데 기재가 되어 있지 않습니다. 여기까지는 좋습니다. 하지만 어떤 노력의 결과에 의해서인지 모르겠으나 최근 정책 반영률이 95%라고 저한테 자료 제출했기 때문에 이에 질의를 시작합니다.
</p>
<p style="padding-left:1.2em">  다음 슬라이드 부탁드릴게요.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  기획담당관님, 제가 질문을 드리겠습니다. 지금 경기연구원에서 진행하고 있는 과제가 몇 가지가 있습니다. 지방행정 환경변화에 따른 대응전략, 경기도 민간위탁 관리방안 연구, 경기도 공무직 운영 실태 및 개선방안, 경기도 등록규제 실태 분석 및 규제개선방안 수립 연구가 완료됐다고 떠 있습니다. 저 보고서 본 적 있나요?
</p>
<p><b>○ 기획조정실기획담당관 박현석 </b> 네, 기획담당관 박현석입니다. 제가 저 보고서를 직접적으로 본 적은 없습니다.
</p>
<p><b>○ 박상현 위원 </b> 없고 그러면 이것에 관련돼서 도정 반영 여부에 대해서 논의를 했다거나 아니면 논의했다고 보고를 받은 적 있으십니까?
</p>
<p><b>○ 기획조정실기획담당관 박현석 </b> 제가 현재 확인은 필요한 사항입니다만 두 번째 나와 있는 민간위탁 관리방안 연구에 대한 것이 아마도 저에게 지난번에 이채명 위원님이 말씀하신 그런 조례 개선이나 지침 개정에 반영되지 않았을까 지금 확인을 해 보겠습니다. 그리고 공무직 운영 실태 또한 저희가 매년 두 번 조직진단을 하는데 그런 과정 속에서 아마 녹았을 것으로 생각하는데 이 부분 또한 확인이 필요한 사항입니다.
</p>
<p><b>○ 박상현 위원 </b> 다음 슬라이드, 감사합니다. 예산담당관님, 지금 경기연구원에서 진행하고 있는…….
</p>
<p><b>○ 기획조정실예산담당관 박성환 </b> 예산담당관 박성환입니다.
</p>
<p><b>○ 박상현 위원 </b> 네, 안녕하십니까? 지금 경기연구원에서 진행되는 예산담당관과 유사 그 업무에 관련된 범위가 높다고 판단되는 과제입니다. 자의적으로 판단했습니다. 재정효과 분석 모형, 분권교부세 보전분 일몰에 따른 경기도 대응 그다음에 세수 추계의 전망, 경기도 도비보조금제도 보조율의 효율성 개선방안 연구, 지방공공투자사업의 재정 효율화를 위한 제도 개선방안 연구. 이거 혹시 보고를 받으셨거나 아니면 저 보고서 읽어보셨거나 아니면 요약본을 보셨거나 아니면 경기연구원과 협의했다라고 들으신 적 있으십니까, 혹시? 저게 올해 진행되고 있거나 완료된 보고서들입니다.
</p>
<p><b>○ 기획조정실예산담당관 박성환 </b> 지금 재정효과 분석 모형 관련한 사항하고 분권교부세 관련한 사항의 진행 중인 사항은 보고는 받았습니다.
</p>
<p><b>○ 박상현 위원 </b> 네, 알겠습니다. 거기까지 드리겠습니다. 감사합니다.
</p>
<p style="padding-left:1.2em">  다음 슬라이드요. 공공기관담당관님 부탁드리겠습니다.
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 공공기관담당관 이문환입니다.
</p>
<p><b>○ 박상현 위원 </b> 이거는 올해 초에 완료된 보고서입니다. 경기도 출연기관 설립 타당성검토 개선방안 연구 이하 이 보고서에 대해서 현재 경기연구원과 협업한 적이 혹시 있으십니까?
</p>
<p><b>○ 기획조정실공공기관담당관 이문환 </b> 저 연구는 제가 여기 오기 전에 아마 완료가 된 걸로 알고 있는데요. 타당성 검토에 대해서는 경기연구원하고 몇 차례 협의를 한 적이 있습니다.
</p>
<p><b>○ 박상현 위원 </b> 네, 알겠습니다. 제가 내년에도 이 질문을 똑같이 할 수 있을지 없을지는 잘은 모르겠으나 경기연구원에서 발간하는 소중한 정책보고서가 연간 200건이 넘습니다. 그래서 경기연구원에 관련된 정책과제만 봐도 경기도가 가야 될 방향성을 정확히 알 수가 있거든요. 이 사안들에 대해서 경기도가 모르고 있거나 아니면 경기연구원이 협업하는 데 있어 어떤 협업 절차가 마련되어 있지 않다면 이번 기회를 계기로 최소한 경기연구원과 기획조정실만큼은 유기적으로 협력을 해 주시길 간곡히 부탁드리고.
</p>
<p style="padding-left:1.2em">  두 번째 경기연구원에 부탁드리고 싶은 건 뭐냐 하면 좀 수많은 보고서가 묻힐 수 있습니다. 사회가 너무 빠르게 변하고 있다는 것은 여기 계신 분들이 잘 아실 것이기 때문에 이 부분에 대해서 그 정책이 시의적절성하게 반영이 되기 위해서는 항상 연구 착수보고서, 중간보고서, 결과보고서 할 때 참석을 못 하는 걸 뻔히 알고 있지만 경기도청 담당 공무원이 최소한의 연락이라도 하고 문서와 공문서를 남겨놔서 이러한 감사 때 대비를 해서 최소한 우리 경기연구원은 연구 협업 체계를 마련했고 그다음에 관련된 사항을 도와 밀접하게 협의하고 있다라고 하는 자료를 꼭 남겨 두고 경기도 도청 공무원들은 가급적이면 이런 보고회 때 30분, 1시간 시간을 내서 꼭 진행상황을 점검해 주셨으면 좋겠습니다. 경기연구원에 관련된 인건비라든지 직원 처우에 관련된 것 추후 후속 질문을 하겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 박상현 위원님 수고하셨습니다. 
</p>
<p style="padding-left:1.2em">  지금 자리에 계신 위원님들 보충질의를 다 하셨는데요. 그러면은 추가질의를 신청받도록 하겠습니다. 추가질의하실 위원님. 이석균 위원님, 추가질의 시간은 5분입니다.
</p>
<p><b>○ 이석균 위원 </b> 네. 원장님, 계속해서 아까 경기 RE100 플랫폼 구축에 임차 관련해서 하는데 이거는 조금 원장님과는 나중에 좀 얘기를 하고 이거 담당하시는 부서가 어디입니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 우리 기후환경연구실입니다.
</p>
<p><b>○ 이석균 위원 </b> 혹시 실장님 나오셨습니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 지금 밖에서 대기하고 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 그러면 답변이 될지 모르겠지만 지금 이게 다 임차예요.
</p>
<p><b>○ 경기연구원장 강성천 </b> 네.
</p>
<p><b>○ 이석균 위원 </b> 그래서 제가 그 안에 내용들이 지금 컴퓨터하고 전자칠판 이런 거 임대하시는 거더라고요. 맞습니까?
</p>
<p><b>○ 경기연구원장 강성천 </b> 고성능 컴퓨터하고 그리고 고성능 서버, 메모리 장치입니다. 그게 대부분 금액을 많이 차지하고 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 기본적으로 한 1년 반 정도 되고 어떤 거는 6개월 정도가 되는데 1년 반 사용을 하시는데 지금 9,000, 거의 1억 가까이 되는 돈……. 
</p>
<p><b>○ 경기연구원장 강성천 </b> 그렇습니다.
</p>
<p><b>○ 이석균 위원 </b> 전산 장비도 3,000만 원 이렇게 되는데 지금 이 가격이면 사도 되지 않을까요?
</p>
<p><b>○ 경기연구원장 강성천 </b> 이게 고성능 워크스테이션입니다. 그래서 17대를 임차했다고 합니다. 그래서 말씀하신 대로 이 전체 금액이면 많은 대수는 아닙니다만 일부 PC를 살 수 있는 그런 금액은 맞습니다. 다만 아까 제가 설명드렸던 대로……. 
</p>
<p><b>○ 이석균 위원 </b> 이거를 지금 임차를 하고 나중에 또 반납하게 되면 그 자료는 또 어떻게 처리가,  남겨질 거며 이걸 해야 되는데 이게 지금 항목이 어떤 걸로, 비목이 어떤 걸로 돼 있죠?
</p>
<p><b>○ 경기연구원장 강성천 </b> 위원님, 양해해 주시면 지금 담당 실장이 와 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 네, 들어오세요.
</p>
<p><b>○ 경기연구원장 강성천 </b> 위원장님, 답변을 좀……. 
</p>
<p><b>○ 위원장 조성환 </b> 네, 그렇게 하시죠. 말씀하십시오.
</p>
<p><b>○ 이석균 위원 </b> 제 질문의 요지는 이거를 임차하는 게 아니라 자산취득비로 그렇게 받으셔서 저걸 하시는 게 어떠냐 하는 거죠.
</p>
<p><b>○ 경기연구원기후환경에너지연구실장 김한수 </b> 두 가지 이유가 있는데요. 첫 번째 이제 공기관 위탁사업으로 하다 보니까 사실은 예산 수립할 때 자산취득을 거의 하지 않고 경비성으로 받아서 저희가 제공을 하고 있습니다. 그래서 대부분의 공기관 위탁사업 같은 경우는 자산을 취득하지 않는 방식으로 진행된 부분이 있고요. 
</p>
<p style="padding-left:1.2em">  두 번째, 가장 큰 이유는 이 두 가지 이제 빌린, 그러니까 리스하는 품목이 고성능 PC 17대랑 고성능 1.25페타짜리 나스, 그러니까 저장장치를 사용하고 있습니다. 이것들이 그런데 사실 내구연한이라든지 아니면 시기에 따라서 금방 노후화되는 부분이 있어서 리스가 훨씬 합리적으로 판단하기 때문에 이렇게 진행을 하고 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 지금 금액이 만만치 않아요.
</p>
<p><b>○ 경기연구원기후환경에너지연구실장 김한수 </b> 네, 그렇습니다.
</p>
<p><b>○ 이석균 위원 </b> 이거 이면계약 같은 거 있나요? 예를 들자면 몇 개월, 그러니까 이게 1년 6개월 사용을 하게 되면 그다음에 나머지 내구연한에 잔액 지불하면 연구원이 가지고 보유를 한다든지 아니면 전액 반납입니까?
</p>
<p><b>○ 경기연구원기후환경에너지연구실장 김한수 </b> 네, 전액 반납입니다.
</p>
<p><b>○ 이석균 위원 </b> 그럼 1년 6개월마다 이렇게 가야 된다고요? 경기연구원에 우리 기획담당관님, 기획전략담당관실에서 하시는 거죠?
</p>
<p><b>○ 기획조정실장 허승범 </b> 이석균 위원님, 기조실장입니다. 아마 해당 사업은 기후환경에너지국에서 담당하고 있어서 위탁사무는……. 
</p>
<p><b>○ 이석균 위원 </b> 그럼 경기연구원 출연운영비나 이런 거는 아니고?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네, 위탁사무……. 
</p>
<p><b>○ 이석균 위원 </b> 위탁사업으로 하는 겁니까?
</p>
<p><b>○ 기획조정실장 허승범 </b> 그런 걸로 알고……. 
</p>
<p><b>○ 이석균 위원 </b> 그러면 그쪽에서 받아서 임차하는 걸로 위탁사업 받아서 하는 거고요?
</p>
<p><b>○ 기획조정실장 허승범 </b> 네. 
</p>
<p><b>○ 경기연구원기후환경에너지연구실장 김한수 </b> 네, 그렇게 진행이 되고 기후국에서 위탁사업으로 진행하고 있는 겁니다.
</p>
<p><b>○ 이석균 위원 </b> 사실은 이거보다 작년에 계약했던 서류들이 있어서 좀 봤는데 작년에도 거의 전산용품 임차는 한 8,900만 원에 컴퓨터 몇 대더라, 데스크탑 2대 하고 A세트, B세트 이렇게 돼 있는데 A세트는 그냥 데이터 처리하는 거고 B세트에는 이렇게 영상 처리하는 이런 부분들 이것도 16개월씩 그렇게 하더라고요. 지금 이 정도면 사도 되지 않나요, 제가 보기에는? 
</p>
<p><b>○ 경기연구원기후환경에너지연구실장 김한수 </b> 네, 위원님 다시 한번 말씀드리면 이게 위탁사업으로 받아서 하는 거라서요. 경비성으로 저희가 처리를 하는 거기 때문에 예산에 자산취득을 사실은 잘 하지는 않습니다. 그리고 자산취득을 하게 되면 위탁사업이 끝나고 나면 반납을 해야 되는데 저희가 자산취득했던 컴퓨터를 다시 경기도에 반납할 수는 없는 상황이고……. 
</p>
<p><b>○ 이석균 위원 </b> 아니, 보유를 계속하실 수도 있잖아요, 계속 사용이 되는 방법.
</p>
<p><b>○ 경기연구원기후환경에너지연구실장 김한수 </b> 그러니까 이게 위탁사업은 공기관 위탁  사업 기간이 끝나고……. 
</p>
<p><b>○ 이석균 위원 </b> 저도 공무원을 했기 때문에 무슨 말씀인지는 알고 있어요. 그런데 이 부분들이 계속 지금 말씀하신 그런 구조에 의해서 가느니보다는 제가 그래서 이면계약이나 부가 계약이나 이런 거 말씀을 드렸잖아요. 이게 1년 반 동안 사용하고 아무리 세상이 빨리 지난다고 그래도 이게 그냥 사용이 안 되는 건 아니잖아요.
</p>
<p><b>○ 경기연구원기후환경에너지연구실장 김한수 </b> 네, 그렇습니다. 그런데 저희가 이 사무가 끝나면 그 컴퓨터를 쓸 일이 없기 때문에 반납을 하거나 아니면……. 
</p>
<p><b>○ 이석균 위원 </b> 계속사업들 아니고 1년 반 단기사업 계약해서 하는데.
</p>
<p><b>○ 경기연구원기후환경에너지연구실장 김한수 </b> 네, 단기사업을 받아서 하고 있는 겁니다. 
</p>
<p><b>○ 이석균 위원 </b> 하여튼 본 위원이 말씀드리는 거는 이게 작은 돈도 아니고 이번에도 2억이나 이렇게 되는 돈들이, 세금들이 지금 말씀하신 그런 구조적인 부분들 때문에 계속 들어가야 되고 이거 끝나면 또 다른 사업 맡으면 또 다른 사업도 임차하셔야 되는 거잖아요.
</p>
<p><b>○ 경기연구원기후환경에너지연구실장 김한수 </b> 네, 다른 사업이 있으면 임차를 하게 되는데요.
</p>
<p><b>○ 이석균 위원 </b> 연구원이니까 있으셔야죠. 일이 끊기시면 안 되는 거잖아요.
</p>
<p><b>○ 경기연구원기후환경에너지연구실장 김한수 </b> 네, 알겠습니다. 
</p>
<p><b>○ 이석균 위원 </b> 하여튼 나중에 이것도 저하고 한번 좀 얘기를 해 보셔요. 알겠습니다. 수고하셨습니다. 이상 질문 마치겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 이석균 위원님 수고하셨습니다. 추가질의하실 위원님 혹시 계십니까? 오늘 질의를 많이들 해 주셨는데요. 오전에 이어서 오후까지 기조실 또 경기연구원 이렇게 질의 답변 계속 진행을 하고 있습니다. 혹시 추가질의는 끝났으나 서면질의하실 위원님 계시면 거수 신청해 주십시오. 없으시죠? 
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원님이 안 계시므로 기획조정실과 경기연구원 소관 사항에 대한 질의 답변을 종결하겠습니다. 
</p>
<p style="padding-left:1.2em">  오늘 여러 위원님께서 지적해 주신 사항은 도민의 의견을 대변하는 것인 만큼 허승범 기획조정실장과 강성천 경기연구원장을 비롯한 관계자분들께서는 도정에 적극 반영해 주시기 바랍니다. 또한 오늘 감사 중에 위원님들께서 개선이나 시정을 요구한 사항들도 조속히 조치될 수 있도록 노력해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  위원님 여러분! 고생 많으셨습니다. 그리고 위원님들의 자료 요구와 질의에 성의를 다해 답변해 주신 허승범 기획조정실장과 강성천 경기연구원장을 비롯한 관계자분들께도 감사드립니다. 
</p>
<p style="padding-left:1.2em">  오는 11월 14일 금요일에는 기획조정실과 경기연구원을 포함한 기획재정위원회 소관 실국 업무 전반에 관한 종합감사가 실시될 예정이니 위원님들께서는 참고해 주시기 바랍니다. 이상으로 금일 기획조정실과 경기연구원 소관 행정사무감사 종료를 선언합니다.
</p>
<p class=''ar''>(15시49분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원(11명)
</b></p>
<p class=''aMan''>김정호박상현박진영양우식오창준이경혜이석균이성호이채명이혜원</p>
<p class=''aMan''>조성환</p>
<p><b>○ 출석전문위원
</b></p>
<p class=''em15''>   수석전문위원 이태헌
</p>
<p><b>○ 피감사기관참석자
</b></p>
<p class=''em05''>ㆍ기획조정실</p>
<p class=''em15''>실장 허승범정책기획관 정종국</p>
<p class=''em15''>기획담당관 박현석기회전략담당관 김병연</p>
<p class=''em15''>예산담당관 박성환공공기관담당관 이문환</p>
<p class=''em15''>인구정책담당관 정경임법무담당관 박민제</p>
<p class=''em15''>행정심판담당관 심성보</p>
<p class=''em05''>ㆍ경기연구원</p>
<p class=''em15''>원장 강성천부원장 박경철</p>
<p class=''em15''>연구기획실장 정대영인구사회연구실장 유정균</p>
<p class=''em15''>북부발전연구실장 남지현미래전략연구실장 최준규</p>
<p class=''em15''>감사실장 민철기행정지원실장 박인숙</p>
<p class=''em15''>공공투자관리센터 소장 류시균</p>
<p><b>○ 기록공무원
</b></p>
<p class=''em15''>김수진</p>
