insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2024.11.18. 월요일] 기획재정위원회 전 소관부서(기획조정실, 감사위원회, 도민권익위원회, 경기연구원) — 기획재정위원회 2024년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제11대 경기도의회 기획재정위원회</b> · 2024년도 행정사무감사(2024. 11. 08. ~ 2024. 11. 21.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=14894" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2024년도 행정사무감사
</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관: 기획재정위원회 전 소관부서(기획조정실, 감사위원회, 도민권익위원회, 경기연구원)
</p>
<p><hr /></p>
<p>일  시: 2024년 11월 18일(월)
</p>
<p>장  소: 기획재정위원회 회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시17분 감사개시)
</p>
<p><b>○ 위원장 조성환 </b> 의석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제49조 및 동법 시행령 제41조, 경기도의회 행정사무감사 및 조사에 관한 조례에 따라 기획조정실, 감사위원회, 도민권익위원회, 경기연구원과 경기주택도시공사 등 8개 기관의 소관 사항에 대하여 종합감사를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  감사위원 여러분 그리고 관계공직자 여러분! 안녕하십니까? 기획재정위원회 위원장 조성환입니다. 지난 11일부터 기획조정실을 시작으로 우리 위원회 소관 기관에 대한 행정사무감사 및 현지확인을 15일에 마쳤습니다. 여러 불편을 감수하시면서 감사에 적극 임해 주신 우리 위원님들의 노고에 감사드리고 행정사무감사에 성실히 협조해 주신 수감기관 공직자분들께도 격려의 말씀을 전합니다. 
</p>
<p style="padding-left:1.2em">  오늘 실시하는 종합감사는 지난주에 실시했던 소관 실국별 감사내용을 다시 한번 종합적으로 점검ㆍ검토하고 정책적 개선방안을 모색하는 데 그 취지가 있습니다. 감사위원님들께서는 이 점 양지하여 주시고 수감기관에서도 적극 협조하여 주시기 바랍니다. 특별히 오늘은 공공기관의 기관장분들께서도 출석을 해 주셨는데요. 저희가 공공기관담당관실을 감사하면서 경기도의 도정과 우리 공공기관들의 사업 방향이 일치할 필요가 있고 그다음에 여러 가지 재정적인, 예산적인 부분이나 소관 업무에 대한 감사 부분에 있어서 같이 의논할 필요가 있다라고 판단이 되어서 우리 위원님들과 협의한 끝에 이렇게 출석을 하게 됐습니다. 바쁜 일정에 참석해 주셔서 감사의 말씀을 드립니다. 
</p>
<p style="padding-left:1.2em">  오늘 이 자리에는 우리 위원회의 행정사무감사 활동을 모니터링하기 위해서 수원에서 오신 조미현 님께서 방청하고 계십니다. 또한 언론인이신 전국매일신문 한영민 기자님, 일간경기 김인찬 기자님, 아시아타임즈 임성민 기자님, 천지일보 이성애 기자님께서 취재 중이십니다. 기획재정위원회를 대표하여 감사의 말씀을 드립니다. 
</p>
<p style="padding-left:1.2em">  질의에 앞서 새로 출석하신 분들에 대한 증인선서가 있겠습니다. 지난 11월 14일 우리 위원회 제2차 회의에서 좀 더 심도 있고 내실 있는 감사를 위한 추가 증인  출석요구 의결이 있었습니다. 금일 새롭게 출석요구받은 증인은 경기주택도시공사 사장을 포함한 공공기관장 및 관계자 총 11명입니다. 그중에서 경기의료원 원장, 경기복지재단 대표이사는 해당 상임위 일정 관계로 불출석 사유서를 제출하였음을 알려드립니다. 
</p>
<p style="padding-left:1.2em">  오늘 행정사무감사 증인으로 새로 출석하신 김세용 경기주택도시공사 사장과 각 기관장께서는 증인의 자격으로 답변에 앞서 선서를 하셔야 합니다. 선서를 하는 이유는 경기도의회가 2024년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위 증언을 한 때에는 지방자치법 제49조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있으며 정당한 사유 없이 선서 또는 증언을 거부한 때에는 동법 규정 및 동 조례 제31조에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 아울러 형사소송법 제148조 근친자의 형사책임과 증언거부 또는 제149조 업무상 비밀과 증언거부에 해당하는 때에는 선서와 증언 그리고 서류 제출을 거부할 수 있음을 함께 알려드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인출석 여부를 확인하겠습니다. 피감사기관의 증인들께서는 모두 자리에서 일어서 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  김세용 경기주택도시공사 사장 나오셨습니까? 
</p>
<p><b>○ 증인 김세용 </b> 네. 
</p>
<p><b>○ 위원장 조성환 </b> 조원용 경기관광공사 사장 나오셨습니까? 
</p>
<p><b>○ 증인 조원용 </b> 네. 
</p>
<p><b>○ 위원장 조성환 </b> 유인택 경기문화재단 대표이사 나오셨습니까? 
</p>
<p><b>○ 증인 유인택 </b> 네. 
</p>
<p><b>○ 위원장 조성환 </b> 최문환 한국도자재단 대표이사 나오셨습니까? 
</p>
<p><b>○ 증인 최문환 </b> 네. 
</p>
<p><b>○ 위원장 조성환 </b> 이민주 경기도수원월드컵경기장관리재단 사무총장 나오셨습니까? 
</p>
<p><b>○ 증인 이민주 </b> 네. 
</p>
<p><b>○ 위원장 조성환 </b> 서춘기 경기아트센터 사장 나오셨습니까? 
</p>
<p><b>○ 증인 서춘기 </b> 네. 
</p>
<p><b>○ 위원장 조성환 </b> 한지양 경기아트센터 감사실장 나오셨습니까? 
</p>
<p><b>○ 증인 한지양 </b> 네. 
</p>
<p><b>○ 위원장 조성환 </b> 김민철 경기도시장상권진흥원장 나오셨습니까? 
</p>
<p><b>○ 증인 김민철 </b> 네. 
</p>
<p><b>○ 위원장 조성환 </b> 유훈 경기도사회적경제원장 나오셨습니까? 
</p>
<p><b>○ 증인 유훈 </b> 네. 
</p>
<p><b>○ 위원장 조성환 </b> 다음은 선서의 요령에 대해서 설명드리겠습니다. 선서는 증인들을 대표해서 김세용 경기주택도시공사 사장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 그 자리에서 오른손을 들어주시면 되겠습니다. 그러면 증인들께서는 선서를 해 주시기 바랍니다. 
</p>
<p><b>○ 증인 김세용 </b> 선서! 본인은 경기도의회가 지방자치법 제49조, 같은 법 시행령 제41조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2024년도 행정사무감사를 실시함에 있어 증인으로서 성실하게 감사를 받을 것이며 또한 증언을 함에 있어서는 지방자치법 시행령 제46조제6항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라서 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2024년 11월 18일 경기주택도시공사 사장 김세용. 
</p>
<p><b>○ 위원장 조성환 </b> 모두 자리에 앉아 주시기 바랍니다. 이상으로 증인선서를 마치겠습니다. 
</p>
<p style="padding-left:1.2em">  기존 증인분들이 기관별 감사에서 하셨던 선서의 효력은 오늘 종합행정사무감사에도 유지되므로 진실하고 책임 있는 답변을 해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  이상으로 증인선서 절차를 마치고 질의 답변에 들어가겠습니다. 간부소개 및 업무보고는 각 피감 기관별 감사에서 이미 마쳤으므로 생략하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  질의 답변에 앞서 위원님들께서는 이미 각 기관에 대해서 1차 감사를 마쳤으므로 오늘 감사에서는 기관별 감사에서 다뤘던 중복된 질의는 자제하여 주시고 주요 쟁점이 되었던 사항을 중심으로 질의해 주시기를 당부드립니다. 질의 답변은 앞서 진행했던 방식과 마찬가지로 본질의는 10분 이내로 하고 보충질의는 5분 이내의 일문일답 형식으로 진행하겠습니다. 추가질의 및 서면질의는 별도 신청을 받아서 진행하겠으니 위원님들의 많은 협조 부탁드립니다. 질의하실 위원님께서는 답변을 듣고자 하는 증인을 지정한 후 질의하여 주시기 바라며 질의를 받은 증인은 발언대로 나와 소속과 직ㆍ성명을 밝히고 답변을 해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그러면 질의에 앞서 자료요청을 받도록 하겠습니다. 자료요청하실 위원님께서는 거수로 신청해 주시기 바랍니다. 양우식 위원님. 
</p>
<p><b>○ 양우식 위원 </b> 안녕하세요? 양우식 위원입니다. 자료요구 두 가지 좀 부탁드리겠습니다. 한지양 증인님, 감사실장님 나와 계세요? 
</p>
<p><b>○ 증인 한지양 </b> 네. 
</p>
<p><b>○ 양우식 위원 </b> 어느 분이시죠? 잠깐 일어나 보세요. 위원장님, 자료요구하는 건데 우리 실장님이 저한테 개인적으로 무슨, 제가 처음 뵙는데 연락을 주셨어요. 이렇게 장문의 편지를 주셨는데 이거 관련해서 이걸 좀 증빙할 수 있는 자료들, 증명할 수 있는 자료를 좀 주십시오. 심각한 상황인 것 같은데 이게 보면 내부 간에 갈등, 잘못된 인사, 조직 내 파벌, 저조한 실적, 불합리한 계약관행, 건강하지 못한 논의구조 등등 이런 상황이면 이 아트센터 없애야 되는 상황입니다, 지금. 이거 관련돼서 감사실장님이시니까, 관련 감사했던 자료가 다 있으실 거니까 이거에 관련된 자료 전부 다 위원님한테 제출 좀 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  그리고 두 번째 자료는 감사위원회에 부탁 좀 드릴게요. 이런 사례가 있는지 모르겠어요. 저는 좀 충격적이어서 그런데 경기도의회에 임기제공무원이 낙제점을 받고 퇴직한 지 두 달 만에 1등으로 다시 임기제에 재취업한 상황이 발생했어요, 지금. 이거에 관련돼서 제가 감사위원회에 여쭤볼 테니까 임기제공무원 채용 관련된 규정, 인사위원회 운영에 관련된 규정, 경기도에 있는 아니면 지방공무원 임용령부터 시작해서 전체적인 경기도의회와 경기도청이 보유하고 있는 내부 규정, 지침, 규칙, 모든 인사에 관한, 인사위원회 운영에 관한 규정들 전부 다 확보해서 제출해 주시고 제가 질의할 테니까 그 답변 좀 부탁드리겠습니다. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 알겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 양우식 위원님 수고하셨습니다. 이채명 위원님. 
</p>
<p><b>○ 이채명 위원 </b> 사실 오늘 우리 종합감사 전까지 자료를 요청드렸는데 아직 자료가 오지 않은 것도 좀 많이 있고요. 추가적으로 평화협력국에 관련된 내용이긴 하지만 기조실장님께서도 어느 정도는 알고 있으셔야 될 것 같아서 자료요청을 좀 제가 드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  2023년과 2024년 DMZ 오픈 페스티벌과 관련된 공문, 평화협력국과 그리고 대행기관 간에 주고 받았던 공문 일체 제출해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그리고 두 번째입니다. 평화협력국에서 말하고 있는 체험관 운영과 관련된 인력과 시설 범위와 그리고 또 경기관광공사가 청소년수련시설로 허가도 받고 그리고 지속적으로 점검받을 때 제출한 인력과 그리고 시설 범위 비교표를 함께 제출해 주시기 바랍니다. 제출하실 때 성명ㆍ소속 그리고 직위 등 양쪽이 비교되어 구분되는 그런, 구분해서 중복되는 것은 없는지를 별도로 한번 확인해서 제대로 제출해 주시기 바랍니다. 이상입니다. 
</p>
<p><b>○ 위원장 조성환 </b> 이채명 위원님 수고하셨습니다. 다음은 이혜원 위원님 자료요청해 주십시오. 
</p>
<p><b>○ 이혜원 위원 </b> 이혜원 위원입니다. 먼저 공공기관 담당관에 순세계잉여금 과잉 문제 관련해서 질의할 예정입니다. 공공기관 결산보고서가 조금 미흡해서 제출 현황 및 환수 현황 관련해서 제출해 주시고요. 
</p>
<p style="padding-left:1.2em">  다음은 경기도시장상권진흥원 관련해서 인사특혜 및 각종 비위 문제에 대해서 질의 할 예정인데 제출하신 내용을 살펴보다가 추가 보완 자료가 있어서 요청드립니다. 
</p>
<p style="padding-left:1.2em">  2019년~2024년 현재 이사회 임원 프로필 그리고 제출하실 때 이름 전체 공개해서 개별 제출해 주시고요. 이사회 전ㆍ현직 임원 중에 정당활동 경력이 있을 시 반드시 적시해 주시기 바랍니다. 두 번째 자료는 대외협력관 선발을 위한 평가기준 또 당시 1차 및 2차 지원자 및 지원자의 채점표 그리고 대외협력관이 제출한 경력기술서, 직무수행계획서, 당시 심사한 심사위원회 위원 명단 및 주요 경력 제출해 주십시오. 세 번째, 대외협력관 신설 이후 현재까지 업무성과 내역이랑 출장내역 상세 그리고 법인카드 사용내역까지 해서 사용 일시, 목적, 사용 장소 및 사용지 주소까지 모두 표기해서 제출해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  마지막 한 가지입니다. 지금 감사위원회에서 경기아트센터 감사한 내용에 대해서 비공개 자료까지 관련해서 보고해 주셨는데 내용에서 조금 제가 보완하고 당사자들 소명에 대한 부분들을 좀 확인해야 될 필요성이 있어서 몇 가지 더 제출 요구합니다. 
</p>
<p style="padding-left:1.2em">  아트센터 정관 및 내부 규정 일체 제출해 주시고요. 그리고 인사 관련해서 서류심사 진행된 위원회 서류심사 기준하고 근거 그리고 서류심사위원 명단 그리고 심사위원들의 채점표까지 제출해 주시고요. 세 번째는 개방형 임기제의 이사회 안건 중에 안건 내용하고 그 내용에 대한 감사실에서 요구한 공문 제출해 주시고요. 세 번째, 직책수당 제도에 관련해서 전ㆍ현 해서 변경 비교한 비교표까지 정리해서 제출해 주십시오. 비교표 없으시면 그냥 전후로 해서 제출해 주시면 됩니다. 그리고 다섯 번째는 헬프라인 접수했었던 그 내용에 대한 부분들은 있는데 전 직원에게 보낸 메일이 없습니다. 그게 제출 가능하면 보낸 메일까지 제출해 주시고요. 그리고 5년간 한문연에 관련된 출장자 명단과 입사 연차 그리고 당시 보직이 있으면 제출해 주시고. 그리고 10월 이후에 작년 2023년 행정감사가 진행됐었습니다, 문화체육관광위원회에서. 거기 이후 감사에서 지적한 내용이 있었는데 10월 이후 감사실장에 대한 결재내역과 그 전의 결재자랑 결재 일시까지 기재해서 그 조치한 내용들에 대한 보고를 좀 해 주시고요. 그리고 연봉제 심의위원회 명단하고 인사위원회 이력서 제출해 주시기 바랍니다. 이상입니다. 
</p>
<p><b>○ 위원장 조성환 </b> 이혜원 위원님 수고하셨습니다. 또 자료요청하실 위원님 계십니까? 박상현 위원님. 
</p>
<p><b>○ 박상현 위원 </b> 부천 오쇠리 출신 박상현입니다. 지난 월요일 날 우리 기조실과 함께 행정감사를 할 때 그때 제가 받았던 자료가 분명히 있다고 말씀하셨는데 자료가 없다고 표시해 놓은 거 있었잖아요? 그 추가 자료 부탁드렸는데 아직 안 왔어요. 
</p>
<p style="padding-left:1.2em">  경기도 앱에 관련된 운영사명, 그 운영사가 제공하는 서비스명 그다음에 운영 유지보수 비용 그다음에 하루 1일 이용자 수 그다음에 도민 만족도 그다음에 도민에 관련된 불만사항 그다음에 예산이 어떻게 바뀌고 있는지 예산조정 현황 그다음에 계획에 있는지에 대한 개선 계획안 그다음에 데이터 관리계획 수립 여부에 대해서 제가 자료요구했는데 아직 안 왔거든요. 이거 한번 체크해 주십시오. 일주일 지났습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 박상현 위원님 수고하셨습니다. 요청한 자료가 일주일이나 지났는데 아직 안 온 거는 전달상에 문제가 있는 건가요, 아니면……. 빨리 확인하셔서, 이석하셔도 좋으니까 해당 부서장은 확인을 좀 해서 빠르게 제출될 수 있도록 조치해 주시고요. 다음은 이경혜 위원님 자료요청해 주십시오. 
</p>
<p><b>○ 이경혜 위원 </b> 고양 이경혜입니다. 기획담당관실에 부탁드립니다. 제가 자료요청해서, 기획재정위원회 소관 부서 위원회의 회의 운영에 관한 자료를 요청해서 받았습니다. 자료는 받았는데 제가 요청한 자료는 30만 원 이상의 회의를 한 것에 대한 위원회의 회의록과 시간을 달라고 했는데 시간 없이 30만 원 이상 지급된 회의에 대한 명단만 왔거든요. 제가 궁금한 건 30만 원 이상을 받을 만큼의 시간을 쓰셨는지에 대한 시간이 필요한 거예요. 시간을 넣은 자료를 다시 요청드리겠습니다. 출력 안 하셔도 됩니다. 파일로 주세요. 이상입니다. 
</p>
<p><b>○ 위원장 조성환 </b> 이경혜 위원님 수고하셨습니다. 자료요구하실 위원님 더 계십니까? 박진영 위원님. 
</p>
<p><b>○ 박진영 위원 </b> 제가 회의 중에 요구한 자료가 전달이 잘못됐는지 확인하려고요. 제가 기록해 놓은 거에 따르면 감사위원회에 갑질신고 현황 및 자료 제출 달라고 그랬는데 자료가 안 와 있는 것 같은데요. 이것 좀 검토해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그동안 경기아트센터 관련돼서 경기도 감사위원회 전체에 제보됐던 내용들, 제가 말씀드렸죠. 구두, 문서 그리고 컴퓨터를 통해서 제출, 그러니까 인터넷을 통해서 제출된 모든 자료들 일체 갑질 현황 달라고 그랬는데 자료가 상당한 기간이 지난 것 같은데 안 오는데 안 주시려고 그러시는 건가요? 확인 부탁드리겠습니다. 오늘 내로 꼭, 오늘 내로가 아니라 제가 보충질의하기 전에 꼭 부탁드리겠습니다. 이상입니다. 
</p>
<p><b>○ 위원장 조성환 </b> 박진영 위원님 수고하셨습니다. 자료 제출 요구하실 위원님 더 안 계십니까? 
</p>
<p style="padding-left:1.2em">  그러면 위원님들께서 요구하신 자료는 성실하게 좀 제출을 해 주십시오. 부실하게 제출이 되면 재차 요구가 되거든요. 그러면 시간만 많이 지나고 결국엔 또 여러 가지적으로 비효율적인 부분들이 발생되니까 요구하신 부분 정확하게 파악이 안 되면 위원님들께 개별적으로라도 가서 물어보시고 정확한 자료를 제출해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 질의 답변을 시작하도록 하겠습니다. 사전에 협의된 순서에 의해서 질의를 시작하겠습니다. 먼저 이석균 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이석균 위원 </b> 남양주 이석균입니다. 기획조정실장님, 우리 공공기관 관련해서 우리 경기도의 공공기관이 몇 군데가 있죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 지금 28군데 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 공공기관들이 경영평가를 받게 되죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇습니다.
</p>
<p><b>○ 이석균 위원 </b> 우리 경기도에서는 몇 군데를 평가합니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 지금 저희가 18군데 경영평가하고 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 나머지는 어디서 받고 있습니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 나머지는, 테크노파크 같은 경우에는 산자부 쪽에서 받고 있고요. 그다음에 공기업 같은 경우는 행안부 쪽에서 받고 이렇게 좀…….
</p>
<p><b>○ 이석균 위원 </b> 공기업평가원에서 받는 곳은 네 곳이죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 공기업. 그렇습니다.
</p>
<p><b>○ 이석균 위원 </b> 나머지는 중앙부서의 소관 부서별로 받고 있는 걸로 알고 있는데 지방공기업평가원에서 평가받은 우리 경기도 공공기관의 등급은 어떻게 됩니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 지금 다등급…….
</p>
<p style="padding-left:2.4em">    (기획조정실장, 관계공무원에게 확인 중)
</p>
<p><b>○ 이석균 위원 </b> 우리 경기주택도시공사, 경기관광공사, 경기평택항만공사, 경기교통공사 이렇게 네 곳 맞습니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 맞습니다. 
</p>
<p><b>○ 이석균 위원 </b> 올해 4곳 다 다등급 받은 거 맞습니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇습니다. 다등급.
</p>
<p><b>○ 이석균 위원 </b> 우리 공기업평가원에서는 등급이 어떻게 나눠집니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 점수를 가ㆍ나ㆍ다마다 다 90점에서 85점.
</p>
<p><b>○ 이석균 위원 </b> 가ㆍ나ㆍ다ㆍ라ㆍ마 다섯 등급으로 나눠지게 되는 거죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 다섯 등급이고요. 
</p>
<p><b>○ 이석균 위원 </b> 그러니까 우리 경기도의 공공기관은 4군데 모두 한 중간 정도만 가는 거네요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 이석균 위원 </b> 이 4곳이 혹시 최우수 등급 받은 적이 있습니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 제 기억에는 가등급 받은, 제 기억에는 없습니다. 
</p>
<p><b>○ 이석균 위원 </b> 없나요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 이석균 위원 </b> 나등급은 작년에 경기주택도시공사가 나등급 받았고 경기교통공사는 라등급을 받았는데 맞습니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 이석균 위원 </b> 우리 28개 기관 중에 공기업평가원에서 받는 이 4곳이 글쎄요, 이게 나쁘다고, 실적이 나쁜 등급이라고 얘기하기도 그렇고 좋은 등급이라고도 얘기하기는 좀 어려운데 이게 왜 이렇게 될까요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 지금 행안부 평가기준에 따라서 했었을 때 저희들 실적이나 평가지표에 대한 저희 실적이 그 점수에 해당되기 때문에 이런 등급을 받았다고 생각합니다.
</p>
<p><b>○ 이석균 위원 </b> 점수에 해당되니까 받기는 하는데 도민들이 바라보는 시각의 수준은 우리 경기도가 대한민국에서 가장 큰 광역지방자치단체고 경기도에 소속되어 있는 공공기관들이 좀 더 도민들을 위해서, 나아가서는 대한민국을 위해서 좀 더 노력을 해서 좋은 등급을 받고 또 이게 우리 경기도의 이미지와 개별 공공기관의 이미지와 연결이 되어서 선순환, 좋은 이미지를 가지고 가고 기업에도 내실 있게 가기를 원하는 게 도민들의 바람이고 시각입니다. 그런데 지금 계속 나등급, 다등급. 계속 다등급으로 유지하는 곳도 있어요. 이런 공공기관에 대해서 우리 기획조정실에서 지도라든지 감독이라든지 어떻게 하고 있습니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 위원님, 저희 공공기관담당관실에서 제도 관련된 공통된 부분에 대해서는 같이 논의를 하는데요, 개별적인 사안과 관련해서는 각 기관마다 주무부서가 있습니다. 주무부서에서 지도감독은 총괄적으로 하게 돼 있고요. 저희는 그 주무부서에서 제도 관련돼서 협의가 필요한 사항에서는 같이 논의하는 형태로 지금 이루어지고 있다는 말씀드립니다.
</p>
<p><b>○ 이석균 위원 </b> 지금 실장님의 대답으로 따지면 공공기관담당관의 직제가 필요하지 않은 것 같은데요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 저희가 제도 총괄이라는 측면에서는 그 필요성은 있다고 생각합니다.
</p>
<p><b>○ 이석균 위원 </b> 지금 소관 부서하고 같이 논의는 하고 있습니까? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 소관 부서랑 같이 논의하고 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 어떤 논의를 하고 있습니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 예를 들면 공공기관에서 정원이 더 필요하거나 아니면 그런 부분 관련해서…….
</p>
<p><b>○ 이석균 위원 </b> 정원만 하시는 건가요? 아니면 경영평가 안에 세부 항목들이 있잖아요. 조직이라든지 경영상태라든지 그다음에 ESG라든지 이런 부분들도 논의를 합니까? 아니면 정원이나 인원에 대해서만 논의를 합니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 제가 지금 보고받은 건 정원이나 이렇게 큰 부분 관련돼서 보고를 받아서 알고 있고요. 지금 위원님 말씀하신 그런 개별사항들은 우리 과 단위 선에서는 얘기가 있었을 거라고 생각하는데 제가 직접 듣지는 못해서요.
</p>
<p><b>○ 이석균 위원 </b> 그러면 우리 공공기관담당관이 김도형 과장님 맞으시죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이석균 위원 </b> 오늘 나오셨나요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 아까 위원장님께서 자료 관련해서 나가서 바로 대응이 필요하면 하라고 그래서.
</p>
<p><b>○ 이석균 위원 </b> 그러면 공공기관 공기업평가원에서 하는 거는 다등급 4군데 받았는데 우리 경기도에서 자체적으로도 하고 있죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 출자ㆍ출연기관에 대해서는 저희가 하고 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 몇 군데 하고 있습니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 저희가 아까 말씀드렸듯이 18군데 하고 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 등급이 어느 정도 나오나요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 저희가 등급이 나가…….
</p>
<p><b>○ 이석균 위원 </b> 7군데.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 7군데 있고요. 나머지…….
</p>
<p><b>○ 이석균 위원 </b> 다가 11군데죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 그렇습니다, 네.
</p>
<p><b>○ 이석균 위원 </b> 우리 지금 계속 경기도에서 공기업 평가를 하고 있죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇습니다.
</p>
<p><b>○ 이석균 위원 </b> 가등급 나온 적 있나요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 최근에 몇 년 동안에는, 가등급은 제가 최근 3년 동안에는 없는 걸로 알고 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 표출자료 좀 준비를 해 주시고요. 가등급이 없어서 안 나오는 건가요, 아니면 평가기준에 따라서 안 나오는 건가요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 위원님, 아까 말씀드린 대로 저희가 점수를 부여해서 그 점수에 따라서 등급을 부여하고 있기 때문에요. 그 해당되는 지표를 합산했을 때 해당되는 점수가 나오지 않음에 따라서…….
</p>
<p><b>○ 이석균 위원 </b> 제가 제일 처음 행정사무감사 첫째 날에 공기업평가원과 우리 경기도 평가기준이 다르다는 거 말씀을 드린 거 기억하시나요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 위원님 지적 주셔서 그거에 대해서 지금 개선방안을 검토 중에 있다는 말씀드립니다.
</p>
<p><b>○ 이석균 위원 </b> (전문위원실 직원을 향하여) 표출자료 좀 보여주시겠어요?
</p>
<p><b>○ 위원장 조성환 </b> 위원님, 지금 기술적인 문제로 표출자료가 시간이 좀 걸릴 것 같으니까 이 부분은 다시 질의를 하도록, 이 시간만큼은 이후에 다시 하도록 이렇게 하겠습니다.
</p>
<p><b>○ 이석균 위원 </b> 네. 기술적 저거로……. 표출자료를 보면서 이야기를 해야 되는데 지금 되지가 않으니 제가 추가질의 시간대에 다시 한번 평가기준에 대한 구조적인 모순에 대해서 말씀을 좀 드릴게요. 
</p>
<p style="padding-left:1.2em">  사실은 우리 경기도에서 가등급이 안 나오는 게 아니에요. 공기업 평가기준에 따라서 하게 되면 가등급이 나와요. 그런데 지금 우리 기준을 약간 모호하게 잡아서 가등급이 안 나오는 거예요. 제가 나중에 또 말씀드리겠지만 다등급이나 라등급도 마찬가지예요. 원래는 라등급, 마등급임에도 불구하고 우리 기준에 따라서, 모호한 기준에 따라서 전부 다등급이에요. 그러면 이런 평가기준을 가지고 앞으로 우리 경기도 공공기관이 뼈를 깎는 각성의 노력이 가능하지 않을 것 같아요. 그냥 나등급이나 다등급을 받아서 무난하게 가는 쪽으로 계속될 것 같아요. 거기에서 파생되는 문제들이 경영이라든지 운영이라든지 또 국가에서 얘기하는 ESG지표라든지 이런 부분들이 다 반영되는 것 같아요. 
</p>
<p style="padding-left:2.4em">    (「표출자료 나왔습니다.」하는 전문위원실 직원 있음)
</p>
<p style="padding-left:1.2em">  아, 표출자료 나왔어요? 위원장님!
</p>
<p><b>○ 위원장 조성환 </b> 네, 한 2분 정도 더 연장해서…….
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p><b>○ 이석균 위원 </b> 네. 경영평가 등급 부여기준을 한번 볼게요. 지방공기업에서는 가등급이 90점 이상인데 우리는 95점 이상이었어요. 우리 90점 이상 되는 곳이 몇 군데죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 지난번에 점수 했었을 때…….
</p>
<p style="padding-left:2.4em">    (기획조정실장, 자료 확인 중)
</p>
<p><b>○ 이석균 위원 </b> 2군데입니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 이석균 위원 </b> 경기도경제과학진흥원, 경기도일자리재단 2군데가 가등급인데도 불구하고 나등급으로, 저기 95점 이상으로 높여놨어요. 그러다 보니까 나등급으로 되죠. 또 다른 거를 말씀드리면 라등급이 75점 이상이면 우리는 라등급, 80점 이상이면 다등급인데 경기도는 75점 미만 65점 이상이에요. 이 결과가 어떻게 되냐 하면, 다음 장 표를 한번 보여주시겠어요? 
</p>
<p style="padding-left:1.2em">  경기도시장상권진흥원 한번 예를 들어보겠습니다. 지금 경기도 기준으로는 22년부터 24년까지 다, 라, 다 이렇게 받았는데 공기업평가원 기준으로 하게 되면 라, 마, 라예요. 더군다나 제일 밑에 보시면 우리 경기도는 경영평가 시에 가점을 3점에서부터 7점을 부여해요. 이 3점에서 7점을 부여하는 가점을 제외하게 되면 라, 마, 마 이렇게 변하게 됩니다. 
</p>
<p style="padding-left:1.2em">  한번 저기 보시겠어요? 다른 곳도 마찬가지입니다. 점수가 좋은 곳은 가등급을 받게 되면 영광으로 알아야 됨에도 불구하고 다음 연도에 지속가능, 그러니까 동일한 등급에 대해서 자신감이 없어서 그러는 건지 회피를 하려는 건지는 모르겠어요. 그런데 기준이 경기도만 그렇게 만들어놨어요. 그래서 가등급임에도 불구하고 나등급으로 유지하도록 만들어놨어요. 외면적으로 보기에는 경영이 그런대로 잘되고 있다, 떨어지지 않았다 이렇게 보여지는 수가 있어요. 
</p>
<p style="padding-left:1.2em">  더 심각한 문제는 라등급, 다등급. 다등급 받은 것 중에서도, 지방공기업평가 경기복지재단 한번 볼까요? 우리 경기도는 라, 다, 다. 그러니까 24년 기준으로 다등급을 받았어요. 24년도 다등급을 받았는데 공기업평가원 기준으로는 23년은 라등급이에요, 24년은 다등급이지만. 가점을 제외하게 되면 23년도는 마등급이에요, 공기업평가원 기준으로. 제가 이 얘기를 왜 하는지 아시겠어요? 이 경영평가 하는 목적은 이 경영평가를 통해서 환류를 시켜서 좀 더 경영과 조직 운영에 또 사업과 이런 부분에 긍정적인 피드백을 주고 더 노력을 해서 도민 눈높이에 맞는 경영평가를 달성하라는 우리의 주문이기도 합니다. 그런데 기준이 저렇게 되니 이 기준들 때문에 상당히 도민들의 시야가 흐려져요. 
</p>
<p style="padding-left:1.2em">  제가 마지막 질문만 하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  (전문위원실 직원을 향하여) 다시 앞장 좀 보여주시겠어요? 
</p>
<p style="padding-left:1.2em">  지방공기업 평가기준에 부합하는 우리 평가 수치를 다시 바꾸실 용의가 있습니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 위원님, 지난번에도 말씀 주셔서요. 저도 와서 이제 업무 파악을 하면서 이 부분 관련해서는 좀 같이 하는 것이 맞겠다는 그런 생각을 갖고 있었습니다. 그런데 위원님 지적 주셔서 저희가 이거는 개선하는 방향으로 해서 진행하고 있다는 말씀드립니다.
</p>
<p><b>○ 이석균 위원 </b> 나중에 별도로 보고해 주시고.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇게 하겠습니다.
</p>
<p><b>○ 이석균 위원 </b> 이 부분은 도민들을 위해서라도 반드시 기준을 맞춰주시기를 바랍니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇게 하도록 하겠습니다.
</p>
<p><b>○ 이석균 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 이석균 위원님 수고 많으셨습니다. 
</p>
<p style="padding-left:1.2em">  실장님, 아마 이 부분과 관련해서는 우리 기관장님들도 많은 의견이 있을 것 같아요. 그래서 의견 수렴하실 때 각 기관의 의견들도 좀 참고하셔서 가장 합리적인 안으로 그렇게 좀 마련을 해 주시길 부탁드리겠습니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 위원장님, 그렇게 하겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 다음은 박진영 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 박진영 위원 </b> 안녕하십니까? 화성 출신 박진영 위원입니다. 기조실장님, 지난번 초창기 행감 때 저기 말씀드렸잖아요, 기금 통폐합에 관련된 거. 이거 어느 정도 자료가 나왔나요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 그 부분 관련해서 어제도 예산과장이랑 같이 논의를 했다는 점 말씀드립니다.
</p>
<p><b>○ 박진영 위원 </b> 방향성은 좀 나왔을까요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 방향은 사실은 기금이 개별 기금 조례가 있지 않습니까? 그리고 상임위마다 또 기금에 대한 강한 입장들이 있어서 여러 가지 어려움이 예상은 됩니다만 위원님께서 말씀하신 전체 총괄적인 측면에서의 그 지적사항에 대해서는 저희가 기조실에서도 좀 무겁게 받아들여서 전체적인 그 부분에 대해서는 통합적으로 한번 점검하는 계획을 가져야 되지 않나라고 어제 예산과장이랑 같이 얘기를 했습니다.
</p>
<p><b>○ 박진영 위원 </b> 저는 그 사이에 지금 자료 좀 보다가 봤는데 통합재정기금 관련돼서 조례 개정할 때 그때 용역을 한 적이 있었던 것 같은데 맞나요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 기록상 2019년인가 용역 한 번 한 걸로 알고 있습니다.
</p>
<p><b>○ 박진영 위원 </b> 그러면 이번에도 용역을 추진을 해서 기금 통폐합 어떻게 하실 건지에 대해서 먼저 연구를 해 보신 다음에 진행하시는 건 좀 어떠세요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 저희가 그 부분은 저희 내부적보다는 그런 전문성 있는 기관의 도움을 받는 것이 현실적으로 조금 도움이 될 거라고 생각합니다.
</p>
<p><b>○ 박진영 위원 </b> 네, 알겠습니다. 아, 그리고 하나만 더 질문드리겠습니다. 실장님, 지금 자료가 파악되지는 않겠지만 요새 외환 환율이 계속 오르고 있고 전 세계적으로 경기 불안한데 경기도에서 혹시 달러나 아니면 유로나 이런 외환으로 된 거래들이 있을까요? 경기도 내 산하기관들에?
</p>
<p><b>○ 기획조정실장 이희준 </b> 위원님, 제가 알기로 그건 따로, 저희가 부채 같은 거를 할 때에 그런 문제가 발생할 것 같은데 그 부분은 제가 지금 정확히 인지하지 못하기 때문에요, 파악해서 말씀드리도록 하겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 네. 이 부분 한번 파악해 보시는 게 나을 것 같아요. 저희 쪽 미래 협력국, 미래위 쪽 위원님이랑 얘기하다가 보니까 그쪽에 달러로 된 계약이 좀 있는 것 같다 그러더라고요. 그럼 다른 데도 있을 수도 있고. 그런데 아마 법률상으로는 경기도가 헤징을 할 수 없게 돼 있는 것 같은데 이제는 경기도가 달러나 이 외환 관련된 계약들이 있으면 그 부분에 대해서 좀 헤징을 하는 필요가 있을 것 같아서 그 부분을 검토해 보려고 하는 거거든요. 그리고 이자율도 한번 같이 검토해 봐주세요. 지금 변동으로 돼 있는 이자율들 고정 이자율로 바꿔야 될 필요가 있는 것들도 한번 검토해 보시는 게 나을 것 같아요, 이자율이 어떻게 될지 모르니까.
</p>
<p><b>○ 기획조정실장 이희준 </b> 지금 위원님 말씀하신 거 관련해서 미래나 협약 관련해서 일부 있을 때, 일반적인 사항이라고 생각되지는 않고요. 내용 파악해서 위원님 보고드리도록 하겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 네. 전체적으로 환율이랑 이자율에 대한 부분들은 3~4년 정도 장기적으로 바라보고 어떻게 대응할지 경기도 및 산하기관들 다 한번 좀 검토해 봐 주시기 바라겠습니다. 급한 건 아니고 한번 이런 생각을 하실 때가 된 것 같아서 말씀드려봅니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 알겠습니다. 공공기관까지 포함해서 달러나 유료화 계약사항 파악해서 보고드리도록 하겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 기조실은 질문 다 드렸고요. 
</p>
<p style="padding-left:1.2em">  (전문위원실 직원을 향하여) 저 자료 컴퓨터에 띄어주시겠어요?
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  감사위원장님!
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 박진영 위원 </b> 저희가 화요일 날 감사했죠? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 박진영 위원 </b> 화요일 날 감사하면서 의향을 제대로 전달드리지 못한 건지, 제가 많이 모자란가 봐요. 저는 분명히 제가 기억하기로 그때 사실로는, 여기 보시죠. 경기아트센터 감사실장의 직장 내 괴롭힘 사건 제보내역, 건수까지 파악해서 달라 그랬는데……. 제가 웬만하면 여기서 요구답변서를 이렇게 막 여는 일은 없는데. 제가 진짜 많이 모자란 질문을 드렸던 것 같네요. 이게 다예요? 건수 안 주셨어요? 파악 안 하신 거죠? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 아니, 잠깐…….
</p>
<p><b>○ 박진영 위원 </b> 아니, 답변자료가 이렇잖아요. 제가 지난 화요일 날 요청드린 자료는 분명히 말씀드리기로 경기도 감사실에 경기아트센터 갑질 관련된 사건자료들, 저기 접수된 것들 다 파악하시고 건수 파악해 달라고 그랬는데 자료는 이게 다예요. 아니, 건수가 파악이 안 되신 거세요? 
</p>
<p style="padding-left:2.4em">    (관계공무원, 감사위원장에게 개별설명)
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 바로 파악해서 말씀을 드리겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 지난주 화요일에 제가 드렸던 자료라고요. 이 종합감사 끝나면 끝나는 거죠? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 아닙니다. 
</p>
<p><b>○ 박진영 위원 </b> 하실 필요 없겠네요? 그래서 그러신 거 아니신가요? 일단은 의도적으로 감사행위 자체를 지연시키는 것 같은데?
</p>
<p><b>○ 감사위원장 안상섭 </b> 그렇지는 않고요. 저희가 다시 파악해서 잘…….
</p>
<p><b>○ 박진영 위원 </b> 또 말씀드릴게요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 아마 실무자가 잘못 이해한 것 같습니다. 다시 제출…….
</p>
<p><b>○ 박진영 위원 </b> 아니에요. 잘못 이해하신 거 아니에요. 제가 북부에 왔을 때 직접 찾아오셨고 저 정확하게 전달드렸습니다. 
</p>
<p style="padding-left:1.2em">  두 번째로 경기아트센터 종합감사 결과 및 변경 서류 일체인데, 변경 결재서류 일체라고 말씀드렸는데. 이것도 열어볼까요? 결재서류에 안 나와 있습니다. 결재 없이 연기하신 거예요, 아니면 자료가 없으신 거세요? 아니, 지금 자료를 주기가 싫으신 거세요? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 아마 그 제일 마지막에……. 
</p>
<p><b>○ 박진영 위원 </b> 결재서류라고 제가 분명히 말씀드렸는데 결재서류가 없어요. 이거 열어볼까요? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 제일 마지막에 그……. 
</p>
<p><b>○ 박진영 위원 </b> 제일 마지막에 결재서류가 있을까요? 공문인데요. 공문 처음에도 들어왔던 자료고 제가 이거 공문 봤어요, 처음에도. 제가 내부적으로 결재서류 달라고 그랬어요. 연장 결정하시면 내부적으로 감사기간 연장에 대한 결재하셨을 거 아니에요. 결재서류 달라고 그랬는데. 제가 진짜 말을 잘 못 하나 봐요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 파악해서……. 
</p>
<p><b>○ 박진영 위원 </b> 아니면 전달에 오해가 있나 봐요. 상당한 시간이 지나서 일단 이거는 추가적으로 말씀드리겠습니다. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 
</p>
<p><b>○ 박진영 위원 </b> 서춘기 사장님한테 질문드리겠습니다. 사장님, 2023년, 24년 동안에 병가……. 
</p>
<p><b>○ 증인 서춘기 </b> 안녕하십니까? 
</p>
<p><b>○ 박진영 위원 </b> 죄송합니다. 제가 지금 시간을 계속 너무 많이 써서. 2023년, 24년 동안에 경기아트센터에서 병가휴직하신 분들 계신가요? 
</p>
<p><b>○ 증인 서춘기 </b> 병가 말씀하시는……. 
</p>
<p><b>○ 박진영 위원 </b> 휴직하신 분들. 
</p>
<p><b>○ 증인 서춘기 </b> 병가 말씀하시는 겁니까? 
</p>
<p><b>○ 박진영 위원 </b> 네, 병가휴직하신 분들. 
</p>
<p><b>○ 증인 서춘기 </b> 병가가 제가 명수는 기억 못 하지만 있습니다. 
</p>
<p><b>○ 박진영 위원 </b> 그중에 심리적인 사유로, 정서적인 사유로 병가휴직하신 분 계신가요? 
</p>
<p><b>○ 증인 서춘기 </b> 제 기억에는 없습니다. 
</p>
<p><b>○ 박진영 위원 </b> 확인해서 부탁드리겠습니다. 심리적인 사유로, 병가휴직 사유서 다 갖다 주세요. 그중에 심리적인 사유로 병가휴직하신 분 있는 걸로 알고 있는데. 
</p>
<p><b>○ 증인 서춘기 </b> 네, 제가 확인해서 제출하도록 하겠습니다. 
</p>
<p><b>○ 박진영 위원 </b> 그리고 최근 동안에 경기아트센터 감사실에서 직원분들 굉장히 많이 바뀌셨죠? 
</p>
<p><b>○ 증인 서춘기 </b> 네, 그렇습니다. 
</p>
<p><b>○ 박진영 위원 </b> 인사이동 변경내역 다 주세요. 
</p>
<p><b>○ 증인 서춘기 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 박진영 위원 </b> 감사실에 여쭤보겠습니다. 감사위원장님, 이젠 사건, 이 내용들 충분히 파악하셨을 거로 보고 여쭤보겠습니다. 
</p>
<p style="padding-left:1.2em">  제가 제기했던 의문 중의 하나가 헬프라인 이 부분. 헬프라인에 접수되고 실제로 며칠 후에, 아까 존경하는 이혜원 위원님이 자료요청하셨는데 며칠 후에 그 메일이 전체 직원한테 갔다고 그랬는데 이거에 대해서 어떻게 생각하세요? 그 당시에 서춘기 사장님 답변 안 하셨고요, 23년도에 여쭤보실 때. 이 헬프라인을 보시고 그 내용과 관련해서 이메일 답변한 거라는 건지에 대해서 조사하신 건가요? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 그 당시에 헬프라인에 대해서는 조사를……. 
</p>
<p><b>○ 박진영 위원 </b> 저희가 쟁점으로 삼는 건 다른 조사 말고요, 그 헬프라인을 가지고, 감사실에서 헬프라인이라는 익명 제보시스템에서 받은 정보를 가지고 그 정보를 활용하여 며칠 후에 전체 직원에게 본인에 대한 해명의 메일을 보내신 것 같은데 그 부분에 대해서 조사하셨냐고요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 아, 비밀유지의무 말씀하신, 그 부분 말씀하시는 겁니까? 
</p>
<p><b>○ 박진영 위원 </b> 네. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 그 부분에 대해서는 조사를 했고요. 다만 이제……. 
</p>
<p><b>○ 박진영 위원 </b> 사실관계만 말씀 주세요. 그렇다고 판단하시는지 아니신지. 그 외에 징계사항들에 대한 법률적 검토는 그때 얘기해 주신 것 같고요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 내부에서 비밀이냐 기밀이냐와 관련된 부분에 대해서 검토를 했고 기밀ㆍ비밀 사안이 아니었고 헬프라인……. 네, 기밀ㆍ비밀이 아니었고 그렇게 해서……. 
</p>
<p><b>○ 박진영 위원 </b> 감사위원장님! 헬프라인에 들어온 사항들을 감사실만 볼 수 있게 되어 있다라고 그때 분명히, 문체위 종감하실 때 분명히 감사실만 볼 수 있게 되어 있다고 감사실장님이 당시 답변을 주셨는데 그 상황이 비밀이 아니에요? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 비밀 그러니까……. 
</p>
<p><b>○ 박진영 위원 </b> 헬프라인이 비밀이 아니에요? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 헬프라인에 있는 내용들, 익명으로 오기 때문에 개인정보랄지 기밀이나 비밀내용이 없어서 저희는 그렇게 비밀……. 정책에 대한 감사실이 답변을 내고 있어서……. 
</p>
<p><b>○ 박진영 위원 </b> 위원장님! 하나만 여쭤볼게요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 
</p>
<p><b>○ 박진영 위원 </b> 경기도 감사실에 헬프라인으로 제보를 하면 그 사항들이 비밀사항이 아닌가요? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 그건 비밀사항입니다. 
</p>
<p><b>○ 박진영 위원 </b> 그럼 경기아트센터 헬프라인에 제보를 하면 그 사항이 비밀이 아닌가요? 어불성설이잖아요. 헬프라인에 익명의 제보 라인으로 말하는 건 그 사항이 비밀사항이고 민감하고 제보하시는 분을 보호하기 위해서 일부러 익명까지 하는 건데 그게 비밀이 아니라고요? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 지금 헬프라인의 내용 자체에 대해서 비밀사항이거나 개인의 정보라거나 이런 것이 아니었다라고 판단을 했던 것 같습니다. 그래서 그 발송 내용이 비밀과 기밀이 아니다라는 말씀을 드리는 겁니다. 
</p>
<p><b>○ 박진영 위원 </b> 위원장님! 
</p>
<p style="padding-left:1.2em">  (위원장석을 향하여) 정리 좀. 
</p>
<p><b>○ 위원장 조성환 </b> 위원장님! 일단 답변 중지해 주시고. 박진영 위원님, 말씀하시죠. 
</p>
<p><b>○ 박진영 위원 </b> 위원장님! 헬프라인에 제보된 내용이 감사실장님에 대해서 제보된 내용이고요. 그 내용을 감사실장님이 보셨고요, 저희가 추정하는 바로는. 물론 이 사실이 개인에 대해서 오해를 할 수도 있겠지만, 그래서 조심스럽게 말을 안 했는데요. 그러고 나서 며칠 뒤에 그 내용에 대해서 전체 직원에게 이메일이 뿌려져서 답변 이메일이 뿌려졌습니다. 
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p style="padding-left:1.2em">  하나 더 여쭤볼게요. 
</p>
<p style="padding-left:1.2em">  위원장님, 지나간 시간 때문에 좀 더 해야 될 것 같습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 네, 하나만 더 질의하세요. 
</p>
<p><b>○ 박진영 위원 </b> 작년 행정감사 때 제가 노무사 고용에 대해서 얘기한 적이 있었습니다. 내용은 확인해 보시면 될 것 같은데요. 제가 제기했던 내용은 감사실장님하고 관계가 있어 보이는 노무법인이 고용되었고 그 노무법인이 감사실장님에 대해서 제보한 내용에 대해서 연락이 왔고 그리고 그분에게 이런저런 노무와 관련된 상담을 하신 걸로 알고 있는데, 해당 당사자분이 제보를 주셔 가지고. 근데 제가 이거 그전에 요청드리기를 노무법인 고용계약서 다 갖다 달라고 그랬더니 그때 없었고요. 근데 올해 되게 공교롭게 종감하신 내용을 보면 하나는 헬프라인 관련돼서 담당직원이 실수로 답변을 한 걸로 생각해서, 감사실장님이 전체 메일 보내신 거 답변을 한 걸로 생각해서 종결처리하는 게 늦었다라고 해서 시정조치 받았고요. 또 하나는 방금 말씀드린 노무법인 관련해서, 노무사 고용 관련해서 담당직원이 사장님께 결재 없이 노무사를 고용하여 진행한 것에 대해서 시정조치 받았어요. 되게 우연이지 않나요? 
</p>
<p style="padding-left:1.2em">  그리고 제가 앞에 다시 말씀드리지만 갑질에 대한 것들에서는 일체의 결과가 나오지 않았습니다. 지난번 문체위에서 그렇게 많이 논의되었었고 실제로 존경하는 황대호 위원님이 조사하신 내용에 따르면 42%가 갑질……. 
</p>
<p style="padding-left:1.2em">  위원장님! 잠깐 정회 요청하겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 지금 해당 질의에 대한 답변이 미흡한 부분이 많아서 정회 요청이 들어왔습니다. 
</p>
<p><b>○ 박진영 위원 </b> 위원장님! 해당 질의에 대한 정회 요청이 아니라요, 죄송하지만 한지양 실장님께서 지금 감사태도가 부적절한 것 같아서 정회 요청드리겠습니다. 확인 부탁드리겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 이 앞자리에서는 안 보이는데, 부위원장님들 잠시……. 저희가 행정사무감사 동안에 불성실한 감사태도 때문에 질책도 많이 하고 그렇게 해 드렸음에도 불구하고 지금 좀 그런 부분들이 발생하는 것 같습니다. 일단 위원님들과 논의를 위해서 잠시 감사를 중지하고자 합니다. 이의 없으십니까? 
