<p><b>○ 증인 한지양 </b> 박진영 위원님하고 제가 눈이 마주쳤습니다. 제가 받아 적다가, 말씀하시는 내용을 자세히 들으려고 눈이 마주쳤는데 불쾌하셨던 것 같습니다. 
