<p><b>○ 이혜원 위원 </b> 양평군 출신 이혜원 위원입니다. 먼저 경기아트센터 한지양 감사실장님의 수감태도 때문에 반복적으로 이런 정회 사태가 이루어지는 것에 대해서 심히 유감을 표명합니다. 질의하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  감사위원장님 답변해 주십시오. 먼저 행정감사 기간 중에 있었던 행감 결과를 제가 보고 그 후속 조치 확인과 제 의견, 대안에 대한 제시를 하기 위함이니까요. 제가 질문하는 내용을 들으시고 의견을 물어볼 때 답변을 좀 간략하게 해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  먼저 경기도 평화협력국은 경기도 남북교류협력에 관한 조례에 따라서 법인ㆍ민간단체에게 남북교류협력사업을 위탁하고 있습니다. 내용을 잘 모르시기 때문에 제가 간략하게 요약해서 말씀드리는 겁니다. 이에 따라서 2018년도부터 2024년 올해까지 연속 5회에 걸쳐서 약 3억 원의 보조금을 지급받은 단체가 있습니다. 우리민족서로돕기운동입니다. 그런데 본 위원이 확인한 결과 해당 단체의 사무총장이 올해 5월부터 남북교류협력위원회 위원으로 임명이 돼서 활동을 하고 있습니다. 이 부분은 먼저 임명한 자의 소속이 같다라는 답변을 들었습니다. 동 조례 제17조는 위원의 제척ㆍ기피ㆍ회피를 명시하고 있고 본 위원은 평화협력국이 5년 동안 그리고 현재진행형으로 보조금을 지급하고 있는 단체의 실무총괄인 사무총장을 보조금을 심의하는 위원회 위원으로 임명한 것 자체가 문제라고 보고 있습니다. 감사위원회 위원장님 의견은 어떻습니까? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 저도 명확한 법 조례나 조문들을 잘 숙지하지 못하고 있어서 일단 그렇게 의문을 갖고……. 
</p>
<p><b>○ 이혜원 위원 </b> 제가 지금 다 설명드렸잖아요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 의문을 갖고 있는 점에 대해서는 저도 공감을 하는 부분이 있습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 더욱이 해당 인물 임명 이후에 24년 7월 12일과 10월 24일 남북교류협력위원회 2023년 기금운용 성과보고를 실시했고 25년 운영계획 및 사업계획을 보고받았습니다. 이 사람이 2023년 운영 성과분석보고에 만약에 참석을 했다면 본인 소속 단체도 23년 보조금을 지급받았기 때문에 보조금 지급 내용의 적절성에 대해서 셀프 심사를 했다는 것으로 판단이 되는데 이 부분을 제가 협력국에 자료요구를 했는데 아직 자료가 오지 않아서 그 내용에 대한 부분을 확인을 하고요. 10월 24일 회의에 참석을 했다면 정보를 미리 습득한 것으로 2025년 보조금 신청에 해당 단체는 신청서를 내면 안 된다고 생각을 하거든요. 그리고 명백히 조례 위반인 것으로 보이는데 감사위원회 위원장님 의견은 어떻습니까? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 앞서 말씀드렸지만 그런 의문은 충분히 공감이 갑니다. 그런데 제가 조문이나 법률을 찾아보지 못해서 확정적인 답변드리기는 좀 죄송하고요. 
</p>
<p><b>○ 이혜원 위원 </b> 두 번째입니다. 남북교류협력기금으로부터 비영리단체를 지원할 때 비영리민간단체 지원법 제2조에 자격을 가진 단체에 한해서 지원을 하도록 되어 있습니다. 이것도 추후에 법 조항을 좀 확인해 보시고요. 그런데 지난 행정사무감사에서 경기도가 특정 정당 소속으로 구성된 단체인 경기청년연대에 4년간 약 1억 원에 가까운 보조금을 지급한 것으로 드러났습니다. 해당 단체의 대표는 매년 바뀌었는데 대표들 모두가 보조금을 지급받는 기간 중에 민중당 후보로서 지방선거에 출마해서 사실상 특정 정당 후보를 지지하는 것을 넘어서 단체가 곧 민중당임이 드러났습니다. 특히 보조금 지급받은 기간 동안 대표가 모두 민중당 후보로서 선거에 출마를 했고요. 교육감 선거에서 경기청년연대의 이름으로 진보 후보 지지 캠페인을 실시했습니다. 국가보안법 폐지 및 이석기 석방 시위 실시를 했고 국민의힘ㆍ민주당 등에 대한 반대시위도 실시를 했습니다. 무기 증강 및 국방예산 감축 시위를 했고요. 미국 내정간섭 중단 성명 발표를 실시했습니다. 본 위원이 봤을 때는 명백히 법 위반인 사항이라고 생각하고 지급했던 보조금이 민중당의 당 활동에 사용되지 않았는지 조사가 필요해 보입니다. 감사위원회 의견은 어떻습니까? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 말씀하신 바와 같이 보조금 지급 여부에 대해서 의문을 가질 수 있는 충분한 지적인 것 같습니다. 한번 살펴보도록 하겠습니다. 
</p>
