</p>
<p><b>○ 이혜원 위원 </b> 대안 제시하겠습니다. 기조실장님 그리고 감사위원장님! 이러한 사안에 대해서 엄중한 대응이 필요하다라고 답변을 해 주셨고 일정 부분 공감이 된다라고 말씀하셨기 때문에 경기도지방보조금 지원 계획상 정치중립의 의무를 좀 추가했으면 좋겠다는 의견을 드리고 또 감사위원회 남북교류협력기금에 대한 특정감사를 즉시 실시할 것을 요청드립니다. 답변 주십시오. 
