<p><b>○ 이혜원 위원 </b> 한 가지 더 질의드리도록 하겠습니다. 제가 오후 추가질의 때 경기아트센터 관련해서 질의를 할 텐데 제가 23년도 문화체육관광위원회 소속에 있을 때 경기아트센터 행정감사를 진행했고 감사 중에 감사실장에 대한 감사요구를 했습니다. 감사에 대한 부분들 접수됐습니까? 접수된 거 있으세요? 23년 행정사무감사 때 경기아트센터 감사실에 대한 감사요구를 했어요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 
</p>
<p><b>○ 이혜원 위원 </b> 그에 대한 접수가 있었습니까, 감사위원회에? 
