<p><b>○ 감사위원장 안상섭 </b> 그때 행정사무감사 있고 일부들은 처리가 됐고 2024년 2월 25일 아마 행정사무감사에 문제가 있어서 들어간 걸로 알고 있고요. 
</p>
<p><b>○ 이혜원 위원 </b> 전반적인 내용들 다시 파악해서 제출해 주시고 아까 박진영 위원이 얘기하셨던 내용들에 대한 부분들도 지금 일맥상통하는 내용이거든요. 전반적인 내용에 대한 부분들 확인하시고 이메일이 됐든 구두가 됐든 쪽지가 됐든 감사위원회 제보가 들어간 내용들 현황 파악하셔서 제출해 주시고 행정사무감사 조치 결과에 대한 세부내용, 그 질의를 하고 답변을 요구했던 위원이 저인데 저한테는 어떠한 피드백이 없었습니다. 결과보고서에 제출하셨는지 모르겠지만 그 내용 별도로 제출해 주십시오. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 답변드릴까요? 
</p>
<p><b>○ 이혜원 위원 </b> 네. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 현황들이나 감사에 활용되었던, 저번에도 위원님께 말씀드렸지만 그 결과는 저희들이 다 보여드립니다. 그런데 최종……. 
</p>
<p><b>○ 이혜원 위원 </b> 감사위원장님, 제가 그 내용도 확인했고요. 그 비공개 자료도 확인했습니다. 그랬는데도 불구하고 내용이 없었다라고 지적을 하는 거고요. 그거에 대한 내용 아까 제가 자료요구 다시 했잖아요? 보완을 하기 위해서 자료요구를 한 겁니다. 내용 다시 한번 검토해 보시고 다시 답변해 주십시오. 지금 종합감사이기 때문에 제가 세부내용에 대한 부분은 별도로 얘기를 해야 될 것 같습니다. 자료 검토하셔서 다시 제출해 주시고 다시 답변 주십시오. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 알겠습니다. 살펴보겠습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 기획조정실 공공기관담당관님! 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 공공기관담당관 김도형입니다. 
</p>
<p><b>○ 이혜원 위원 </b> 공공기관 순세계잉여금에 관련해서 좀 질의드릴게요. 계속적으로 먼저도 제가, 우연찮게 또 담당관님께서 문화체육관광위원회에 계실 때 질문했던 부분이라 내용을 알고 계실 것 같습니다. 공공기관들 28개 기관이잖아요? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 28개 기관에 제가 먼저도, 전년도도 순세계잉여금을 보니까 계속 증가를 하고 있었거든요. 그런데 현재도 계속 증가 중입니다. 집행률은 49.2% 정도 낮고 그리고 예산 대비 순세계잉여금에 대한 부분들은 높은 데는 29%가 넘어요. 계속적으로 증가되는 이유에 대해서 잠깐 답변을 좀 해 주십시오.
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 그렇지 않아도 제가 여기 7월 23일 자로 왔을 때 24일 날 업무보고 시에 위원님께서 그 순세계잉여금 관련된 부분을 많이 언급해 주셔서요. 저희가 나름 합리적 운영을 위해서 예산 편성 주요 안내사항 같은 걸 만들어서 그동안 세 차례에 걸쳐서 공공기관과 집행부 주무부서까지 교육을 시켰는데요. 계속해서 이 부분에 대해서는 기본적으로 순세계잉여금이 많이 남는 것은 제가 현재까지 파악한 바로는 집행률에 우선 문제가 있습니다. 그래서 그 집행률 높일 수 있고 그다음에 예산 편성 시부터 그 부분을 전부 다 가져갈 수 있도록 검토해서…….
</p>
<p style="padding-left:2.4em">    (타임 벨 울림) 
</p>
<p><b>○ 이혜원 위원 </b> 시간이 끝나서 이후에 제가 보충질의할 때 이 표를 제시하면서 현황 체크를 할 테니까요. 답변 준비해 주시기 바랍니다. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 알겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 이혜원 위원님 수고하셨습니다. 다음은 이경혜 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이경혜 위원 </b> 고양 이경혜입니다. 먼저 굉장히 우려스러워서 기조실장님께 먼저 여쭙겠습니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 기획조정실장입니다.
</p>
<p><b>○ 이경혜 위원 </b> 어제 초코파이가 든 대북전단 때문에 굉장히 김여정 위원이 화가 많이 난 걸로 알고 있는데 어떻게, 들으셨죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 대북전단 내용은 들었는데요. 그 초코파이 내용까지는 제가 정확히 인지하지 못했습니다.
</p>
<p><b>○ 이경혜 위원 </b> 제가 짧게 잠깐 읽어드릴게요. “김정은 북한 국무위원장의 여동생 김여정 노동당 부부장이 대북전단이 날아왔다고 주장하며 대가를 치를 것이라고 겁박했다. 김 부부장은 17일 조선중앙통신을 통해 발표한 담화에서 전날 국경 부근과 중심 지역에까지 한국 쓰레기들이 들이민 각종 정치 선동 삐라와 물건짝들이 떨어졌다고 주장하며 거듭되는 경고를 무시하고 또다시 반공화국 정치모략선동물들을 살포하는 도발을 감행한 한국의 치사스럽고 저열한 행위를 강력히 규탄한다.”라고 했어요. 그래서 경기도에서 파주, 김포, 연천 등 11개 시군을 위험구역으로 지정했거든요. 그래서 안보관광 중단됐고요. 이 부분 아직 잘 모르고 계시나요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 알고 있습니다. 
</p>
<p><b>○ 이경혜 위원 </b> 알고 계시죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 이경혜 위원 </b> 저희 이 부분에 대한 대책을 어떻게 갖고 계신지에 대해서 제가, 내일 평화협력국이 있지만 그것과 별개로 경기도의 입장에서 기획을 하고 있는, 기획과 정책을 담당하는 실장님께 아주 짧게 한번 여쭤보고 싶습니다. 이 지역에 계신 도민들을 위해서 어떤 안보대책을 갖고 계신지 한번 잠깐 말씀 주십시오.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 말씀드리겠습니다. 관련해서 저희 안전실이, 위험구역설정은 안전실에서 하고 있거든요. 그래서 안전실과 평화협력국이 그 지역주민들에게 피해가 가지 않도록 그런 동향이나 이런 것들이 있을 때면 전면적으로 현장에 나가서 필요한 부분을 대응하고 있다고 제가 지금 파악하고 있습니다. 
</p>
<p><b>○ 이경혜 위원 </b> 도민들이 불안한 하루하루를 보내시는 부분들에 대해서 좀 더 세심하게 살피시고 각별하게 주의를 살펴서 이 위험한 곳에 계시는 분들에 대한 걱정과 우려를 좀 잘 챙겨주시길 부탁을 드립니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 이경혜 위원 </b> 저도 이제 질의를 좀 해 보도록 하겠습니다. 감사위원회 위원장님께서는, 앉아 계셔도 되고요. 제가 질의를 하는 것에 대해서 잘 듣고 메모하셨다가 제 마지막 질문에 답변을 해 주시면 됩니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 알겠습니다. 
</p>
<p><b>○ 이경혜 위원 </b> 먼저 DMZ 관련해서 제가 증인출석을 요구했는데요. 경기문화재단의 유인택 대표님 잠시 앞으로 나와주시겠습니까?
</p>
<p><b>○ 증인 유인택 </b> 네, 경기문화재단 대표 유인택입니다.
</p>
<p><b>○ 이경혜 위원 </b> 거짓이 없이 말씀 주실 거라고 믿습니다.
</p>
<p><b>○ 증인 유인택 </b> 네.
</p>
<p><b>○ 이경혜 위원 </b> 제가 듣기로 DMZ조직위원회 위원으로 계셨던 걸로 알고 있습니다. 맞습니까?
</p>
<p><b>○ 증인 유인택 </b> 네, 맞습니다.
</p>
<p><b>○ 이경혜 위원 </b> 그런데 지금 현재는 어떠십니까? 해촉되셨죠?
</p>
<p><b>○ 증인 유인택 </b> 네, 어떻든 조직위원이 아닙니다.
</p>
<p><b>○ 이경혜 위원 </b> 임기를 다 마치시고 조직위원이 아니신 겁니까, 아니면 임기를 하던 중에 그냥 끝나신 겁니까?
</p>
<p><b>○ 증인 유인택 </b> 작년 1월 달에 취임해서 한 2월경? 1~2월 사이에 토론과 뭐가 있었는데 딱 한 번 조직위원회 열리고 나서 그다음에 어느 순간 저는 부르지를 않아서 나중에 알았습니다.
</p>
<p><b>○ 이경혜 위원 </b> 언제 해촉된 걸로 들으셨습니까?
</p>
<p><b>○ 증인 유인택 </b> 그것조차 들은 바 없습니다.
</p>
<p><b>○ 이경혜 위원 </b> 없습니까? 그러면 왜 해촉됐는지는 아직도 잘 모르고 계십니까? 잘 모르시나요?
</p>
<p><b>○ 증인 유인택 </b> 아마 제가 회의 때 제 상식, 그러니까 축제, 페스티벌의 일반적 대한민국에서 벌어지는 거기에서 조금 벗어난다 싶어서 문제 제기 내지는 의견을 제시했는데 그것이, 아마 그런 사유가 아닐까 싶습니다.
</p>
<p><b>○ 이경혜 위원 </b> 미루어 짐작하지만 그렇지 않을까라고 생각이 같이 들 수 있습니다. 저도 유인택 대표님께서 문화에 대한 굉장한 해박한 지식을 갖고 계신 전문가인 걸로 알고 있고 그래서 현재 경기문화재단의 대표를 하고 계신 걸로 압니다. 그런 걸로 봤을 때 DMZ에 페스티벌을 연, Let’s DMZ라고 해야 될까요, 오픈 페스티벌이라고 해야 될까요? 이 조직위에는 충분히 필요한 부분의 위원으로 계셨어야 옳았다라고 생각을 하는데 위원회에서 잠시 머물다 나오신 것에 대해서 아쉽게 생각합니다. 이 부분에 대해서 혹시 다른 하실 말씀이 있으신가요?
</p>
<p><b>○ 증인 유인택 </b> 저희 경기문화재단 일을 감당하기에도 하도 정신이 없어서, 그거는 또 실무를 경기관광공사가 일원화됐기 때문에 더 이상 드릴 말씀은 없습니다.
</p>
<p><b>○ 이경혜 위원 </b> 네, 알겠습니다. 잘 들었습니다.
</p>
<p><b>○ 증인 유인택 </b> 네, 감사합니다.
</p>
<p><b>○ 이경혜 위원 </b> 자리로 가셔도 좋습니다. 
</p>
<p style="padding-left:1.2em">  제가 왜 이 말씀을 드렸는지는 저희가 지난주 감사에서 말씀드려서 알 거예요. DMZ조직위원회에서 경기문화재단의 유인택 대표님뿐만 아니라 다른 두 분이 더 이유도 모르는 채로, 언제 해촉됐는지도 모르는 채로 해촉이 되었습니다. 조직위원회의 임기가 어떻게 되는지, 해촉에 대한 규정과 절차는 어떻게 되는지 이 부분에 대해서 이후에 감사위원회에서는 다시 정리를 해서 감사에 들어가 주시기를 부탁드립니다.
</p>
<p style="padding-left:1.2em">  두 번째, 감사위원장님께서 계속 들어주셔야 될 것 같은데요. 다음은 경기도연구원입니다. 잠깐 앞으로 나와 주시겠어요? 
</p>
<p style="padding-left:1.2em">  자료 표출 부탁드립니다.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  자료 보이실까요? 
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 이경혜 위원 </b> 제가 지난주에 경기도의 28개 공공기관 그리고 기획재정위원회의 소관 부서 모두 해서 위원회별 회의와 회의 시간 그리고 회의록, 거기에 따른 수당에 대해서 자료를 요청했었습니다. 해서 30만 원 이상의 위원회 수당을 지급한 건에 대해서 자료를 요청했는데 제가 오늘 지금 보여드리는 건 제일 먼저 자료를 주셨기 때문에 표출이 된 것이고 다른 공공기관이나 다른 소관 부서가 아무 문제가 없어서 이 경기연구원만 띄운 것은 아니라는 것을 다시 한번 주지시키면서 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  2시간 이내의 지급 수당이 얼마가 되죠? 회의비가 얼마가 지급되죠?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 통상 저희가 회의비 기준단가를 설정하면 그 기준단가에 의해서 2시간 이내는 적용을 하고 2시간이 지나면 할증을 해서 지급하고 있습니다.
</p>
<p><b>○ 이경혜 위원 </b> 2시간 이전에 얼마 받죠?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 2시간 이전에 저희가 이게…….
</p>
<p><b>○ 이경혜 위원 </b> 20만 원입니다. 시간이 많지 않아서. 2시간을 초과해야 30만 원의 수당이 지급됩니다.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 할증하게 돼 있습니다.
</p>
<p><b>○ 이경혜 위원 </b> 그런데 저 자료 보시면 몇 시간 있는지 시간 보이십니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 1시간 한 걸로 돼 있습니다.
</p>
<p><b>○ 이경혜 위원 </b> 1시간 했는데 지급 얼마 하셨습니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 30만 원씩 지급한 걸로 되어 있습니다.
</p>
<p><b>○ 이경혜 위원 </b> 표출 또 다른 자료 또 있죠? 여기 보시면 몇 시간 하셨습니까? 역시 1시간입니다. 
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네. 1시간 정도.
</p>
<p><b>○ 이경혜 위원 </b> 수당 지급 얼마 하셨습니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 30만 원입니다.
</p>
<p><b>○ 이경혜 위원 </b> 이 부분에 대해서 분명히 문제 있다라는 거 인정하십니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네. 확인해 보겠습니다.
</p>
<p><b>○ 이경혜 위원 </b> 네, 들어가십시오. 
</p>
<p style="padding-left:1.2em">  제가 지금 이 부분에 대해서 지난주에 말씀드렸어요. 자료를 지난주 금요일까지 달라고 요청했는데 금요일 날까지 이 각각 공공기관과 소관 부서에서 자료를 주는데, 시간이 그렇게 오래 걸릴 일이 아니거든요. 저한테 자료 오늘 아침에 주신 곳들도 너무너무 많아요. 그럼 저보고 언제 보고 이 시간에 질의하라는 건지 잘 모르겠어요. 그럼에도 불구하고 제가 지금 28개 공공기관들 계속 살펴보고 있거든요. 파일로 보고 있는데 28개 공공기관 모두가 문제입니다. 지금 경기연구원 거는 제일 먼저 온 것 때문에 열심히 일을 제출하시고도 먼저 혼이 나신 거고 전체 공공기관이 다 똑같습니다. 소관 부서도 마찬가지입니다. 자료를 제가 일일이 다 보여드리지는 않지만, 이런 일이 있습니다. “2시간 이내에서 회의를 하면 30만 원을 받을 수 없으니 우리 조금만 버티고 10분만 기다립시다. 그럼 30만 원 받을 수 있어요.”라고 하는 회의도 있었어요. 그리고 제가 이 자료를 보면 지금 옴부즈만에서는 굉장히 자료를 잘 만들어서 주셨어요. 
</p>
<p style="padding-left:1.2em">  위원장님, 혹시 보충질의 같이 해도 될까요? 
</p>
<p><b>○ 위원장 조성환 </b> 네, 그렇게 하시죠.
</p>
<p><b>○ 이경혜 위원 </b> 옴부즈만 같은 경우는 자료를 이렇게 지급명세서 전에 누가 자료를, 어떤 회의를 했는지 얼마 지급했는지 써 있습니다. 그리고 회의한 분들의 서명이 다 들어가 있어요. 그리고 지급한 회의의 시간이랑 속기사의 기록까지 다 들어가 있습니다. 이렇게 자료를 만드는 데가 있는가 하면 소관 부서에서 달라고 했는데도 자료에 시간이 안 나와요. 지급된 것에 대한 시간을 알려달라고 한 이유가 뭐겠어요? 30만 원 이상을 적정하게 지급했는지를 알고 싶은데 그 시간을 안 준다는 것은 그 시간만큼을 안 하고 지급해서라고 저는 미루어 짐작해도 되겠습니까? 어떻게 기조실장님께 전체적으로, 실장님께 여쭙겠습니다. 그렇게 생각해도 될까요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 그건 자료를 아직 안 낸 부서마다…….
</p>
<p><b>○ 이경혜 위원 </b> (자료를 들어 보이며) 자료는 이제 다 왔습니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 이제 다 왔어요? 네. 
</p>
<p><b>○ 이경혜 위원 </b> 네, 자료는 다 왔고요. 모두가 이런 회의록조차 안 주셨고 ○○○ 몇 명 왔다라고 했는데요. 이 옴부즈만 자료가 그나마 충실하게 왔고 그런데도 불구하고 여기에 자료를 보면 이렇게 있습니다. 아주 잘한 사례로는 20만 원씩 8명을 지급합니다. 시간이 10시 2분에 시작해서 12시 4분, 2분 초과했는데 이거 20만 원 지급으로 정리했어요. 그런데 그 옴부즈만에서도 그다음엔 어떤 일을 하냐면, 30만 원 초과수당을 지급한 건입니다. 13시 57분에 시작해서 16시 3분에 끝납니다. 그러면 정확하게 2시간 조금 넘어요. 그런데 지급을 30만 원 합니다. 16시, 3분 지난 거죠? 그런데 엄밀히 따지면 3분 안 지난 거예요. 2시에 시작하기로 한 회의를 57분에 시작하고 16시 3분에 끝내고 30만 원을 지급합니다. 이게 실태입니다. 이게 옴부즈만 거를 그나마도 조금 본인들이 어떻게 회의를 했는지, 몇 시간을 했는지까지 내준 자료가 이런 거고요. 나머지 공공기관들 제가 자료를 나중에 살펴보시기를 감사위원장님께 부탁드리는 겁니다. 
</p>
<p style="padding-left:1.2em">  왜냐하면 45만 원, 70만 원이 넘는 회의비들도 있어요. 그중에 제가 깜짝 놀란 것 중의 하나는 어떤 게 있냐면 기획예산담당과에서는 주민참여위원회 회의를 합니다. 주민참여위원회 회의를 하면, 이 부분에 대해서는 제가 진짜 잘 이해를 못 해서 여쭙고 싶은 건데 주민참여위원회에서 회의를 하면 한 번에, 잠시만요. 자료를 좀 펼치겠습니다. 2024년 7월 23일 날 165명이 회의합니다. 그리고 24년 7월 22일 날 172명이 회의를 합니다. 이 2개 회의는 제가 제출해 달라고 한 30만 원 이상 초과 지급된 회의의 명단입니다. 이거 2개 합쳐서 1억 1,100만 원의 회의비가 이틀간 나갑니다. 그런데 이분들 그러면 172명, 165명 합치면 300분이 넘게, 한 340명 정도 될 것 같거든요. 이분들 회의를 그 시간만큼 했는지에 대해서 좀 궁금하고요. 
</p>
<p style="padding-left:1.2em">  그리고 그전에도 마찬가지예요. 22년도에도 마찬가지로 8,160만 원이 며칠 상간에 나가는데 이분들의 회의 시간도 나와 있지 않고 출석자들 명단만 나와 있거든요. 이렇게 되어 있는 회의록을 계속 제가 봐야 하는 이유는 잘 모르겠지만 제가 드리고 싶은 말씀은 그겁니다. 어느 누구도, 어느 부서도, 어느 공공기관도 이 회의의 규칙을 지키지 않는다. 왜일까요? 실장님께 먼저 여쭙겠습니다. 왜 회의규칙을 안 지키고 수당을 다 무조건 어떻게 하든 30만 원 이상으로 주려고 할까요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 말씀드리겠습니다. 저희가 그 수당은 그 규정에 맞게 2시간 이내인 게 20만 원이고 그다음에 2시간 이상이 추가로 줄 수 있는 규정으로 돼 있는데 그거는 규정에 맞게 지급하는 게 맞다고 보고요.
</p>
<p><b>○ 이경혜 위원 </b> 네. 거기까지 하겠습니다. 규정에 맞게 지급하는 것이 맞습니다. 1시간도 30만 원, 2시간도 30만 원, 3시간도 30만 원 그리고 4시간, 5시간이 넘어가면 60만 원, 70만 원이 넘는 것까지도 지급이 됩니다. 거기에 서면으로 질의를 따로 해서 추가로 15만 원 이상씩이 또 같이 합쳐져서 출석, 참석한 수당과 서면수당이 합쳐져서 나가기도 합니다. 
</p>
<p style="padding-left:1.2em">  전체를 감사위원장님께 요청합니다. 공공기관 그리고 전체 경기도 모든 부서의 위원회별 회의의 회의록을 확인하시고 2시간 이내에 30만 원 지급된 부분들에 대해서 정확히 정리하셔서 이 부분을 어떻게 조치할 건지 결과를, 내년 초까지는 해야 되겠죠? 워낙 많으니까. 다 정리해서 어떻게 징계하실 건지 어떻게 앞으로 처리해 가실 건지에 대해서 답을 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  이상은 추가질문에서 말씀드리도록 하겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 위원장님, 답변해 주세요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 방금 말씀해 주신 부분들에 대해서는 경기도뿐만이 아니라 공공기관 앞에서 지적해 준 것처럼 도덕적 해이에 대한 문제점이 아마 있어 보이는 듯합니다. 그래서 종합적으로 좀 고민을 해서 특정감사에 담아낼 수 있도록 그렇게 노력해 보겠습니다. 그리고 앞서 DMZ조직위원회 위원 해촉 문제와 관련해서도 이 부분도 한번 들여다보면서 특정감사가 가능한지 여부도 살펴보도록 하겠습니다.
</p>
<p><b>○ 이경혜 위원 </b> 네. 감사해 주십시오. 거기 세 분이나 이유도 없이, 무슨 사유로 어떻게 됐는지, 언제인지도 모르고 정리된 부분에 대해서 반드시 감사가 필요하다고 생각합니다. 이상입니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 살펴보겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 이경혜 위원님 수고하셨습니다. 다음은 오창준 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 오창준 위원 </b> 광주 출신 오창준 위원입니다. 장진수 도민권익위원장님께 좀 질의 드리겠습니다. 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네.
</p>
<p><b>○ 오창준 위원 </b> 저번 감사 때 저희가 위원회에서 요구했던 위원들 잔여 임기 보장 관련해서 질의를 드리려고 하는데요. 지금 현재 도민권익위원회의 근거 조례인 도민권익위원회의 설치 및 운영에 관한 조례에 보면 목적에 지방자치법 제129조 그다음에 공공감사에 관한 법률 제5조 그다음 부패방지 및 국민권익위원회의 설치와 운영에 관한 법률 8조 및 32조에 따라서 설치한다고 되어 있습니다. 그런데 그중에 공공감사에 관한 법률을 살펴보면 이 합의제 감사기구의 경우에는 위원장 1명을 포함한 3명 이상, 7명 이하의 위원으로 구성한다고 되어 있어서 아마 동 조례, 도민권익위원회의 설치 조례에도 위원의 구성은 7명으로 되어 있는 걸로 제가 알고 있습니다. 근데 맨 아래로 내려보면 특례사항으로 현재 이미 기임용된 위원들에 대해서는 임기 보장을 해 준다고 되어 있는데 이 경우에는 제가 판단하기에는 공공감사에 관한 법률과 또 이제 국민권익위원회의 설치 운영에 관한 법률에서 충돌이 있다고 보여지는데 어느 법안이 더 우세한 겁니까?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 도민권익위원회 임기를 기존 옴부즈만 임기를 그대로…….
</p>
<p><b>○ 오창준 위원 </b> 네, 연장하는 건에 대해 드리는 겁니다.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 글쎄요, 저는 조례에 따라서…….
</p>
<p><b>○ 오창준 위원 </b> 위원장님이 구성하신 게 아니라, 그럼 기조실장님께 질의드리겠습니다, 같은 내용으로. 기조실장님이 보실 때는 뭐가 더 우선을 해야 되는 겁니까, 이게? 7명 이내로 하는 걸 우선해야 되는 건지 아니면 기존 임용된 위원들의 임기를 보장해 주는 게 맞는 건지. 법률적 해석 받아보셨습니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 아니요. 그거 관련해서는 제가 지금 위원님 말씀하신 내용을 근거로 해서 말씀을 드리겠습니다. 별도로 상위 법령에 규정이 따로 되어 있지 않다면 그 조례에서 그런 부칙이나 경과규정을 둘 수는 있다고 생각합니다. 하지만 상위 법령에서 일정 부분 룰을, 규정을 두고 있다면 조례에서 그거와 좀 달리해서 정하기는 어렵지 않나 이렇게 생각합니다.
</p>
<p><b>○ 오창준 위원 </b> 제 말씀도 그 말입니다. 7명으로 인원을 정해 놔서 조례도 7명으로 하는데 지금 위촉해 놓은 분들이 10명이 넘다 보니까 10명에 대해서 해촉을 못 한다 그래서 그냥 유지를 했는데 그러면 이 경우에는 조례를 만드는 걸 좀 딜레이시키든지 해야 되는 게 맞지 않습니까? 상충되는 경우에는. 누가 답변 주실 분이, 법무에서 해 주시든지. 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 그간의 많은 논의가 있었을 것으로 알고 있고 제가 그간의 과정을 소상히 알지는 못합니다만 법령상 상충되는 부분은 없는 걸로 알고 있고 저는 조례에 규정된 대로 잔여 임기를 그대로 적용해서 업무를 하겠다라는 데 많은 생각을 하고 있어서 그간의 과정들에 대해서는 소상히 알지 못하는 점 송구스럽게 생각합니다. 
</p>
<p><b>○ 오창준 위원 </b> 그럼 다시 질의드리겠습니다. 그럼 현재 10명의 옴부즈만 중에 세 분 같은 경우에는 24년 12월 31일이 임기 만료입니다. 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네. 
</p>
<p><b>○ 오창준 위원 </b> 이분들 연임 가능하다고, 본인 의사에 따라서 연임 가능하시죠? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 그렇습니다. 
</p>
<p><b>○ 오창준 위원 </b> 이것도 그러면은 그냥 4년, 몇 년 연임이죠? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 2023년 1월 1일에 위촉되신 분들의 경우에는 당시에 옴부즈만 조례가 2년에 1회 연임을 규정하고 있었는데 그 이후에 옴부즈만 조례가 개정돼서 4년으로 바뀌었고요. 그리고 상위법에서 4년을 규정하고 있기 때문에 이분들이 희망하는 한 연임하는 것으로……. 
</p>
<p><b>○ 오창준 위원 </b> 연임하면 임기 몇 년으로 책정됩니까? 잔여 임기 2년만 연장됩니까, 아니면 4년……. 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 잔여 임기 2년만 연장됩니다. 
</p>
<p><b>○ 오창준 위원 </b> 그러면 이분들도 그냥 신청하시면 도민권익위원회에서는 다 오케이 하시는 걸로 그렇게 알고 있으면 되겠습니까? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 그렇게 저희가 검토를 하고 있습니다. 
</p>
<p><b>○ 오창준 위원 </b> 일단 알겠습니다. 다음으로 갑질조사와 관련해서 프로세스 주신 것 중에 조사계획 수립 및 조사과정에서 도민참여옴부즈만이라고 적혀 있는데 여기 도민참여옴부즈만이 아직 유지되고 있는 겁니까, 이 명칭이? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 도민참여옴부즈만은 새로이 신설되는 제도입니다. 옴부즈만이 일반 옴부즈만이 있는가 하면 전문 옴부즈만을 둘 수 있습니다. 전문 옴부즈만으로 이해를 해 주시면 되겠습니다. 위촉은 아직 하지 못하고 있습니다. 
</p>
<p><b>○ 오창준 위원 </b> 위촉을 하지 못하고 있다. 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네. 저희가 추천과 공모절차를 거쳐서 빠르면 연내에 추진해서 내년 초에 일단 50명을 위촉할 계획으로 업무를 추진 중에 있습니다. 
</p>
<p><b>○ 오창준 위원 </b> 그러면 다시 질의드리겠습니다. 현재 갑질신고로 인한 처리현황에 4건 진행 중이신데 이 건에 대한 조사는 누가 하고 있습니까? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 옴부즈만이 위촉되기 전까지는 도민감사관으로 위촉되신 분 중에서 협조를 받아서 노무사님들을 섭외해서 업무를 진행하고 있습니다. 저희가 노무사가 없기 때문에. 
</p>
<p><b>○ 오창준 위원 </b> 도민참여옴부즈만 구성은 몇 명으로 하십니까, 만약에 구성하면? 인원제한이 있습니까? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 최대 100명으로. 
</p>
<p><b>○ 오창준 위원 </b> 분야별로? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 분야별……. 
</p>
<p><b>○ 오창준 위원 </b> 도민감사관이랑 똑같이 운영하신다는 얘기네요, 분야별로 받는다는 게? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 그렇습니다. 인력풀로 좀 생각해 주셔도 될 것 같고요. 
</p>
<p><b>○ 오창준 위원 </b> 아니, 그러니까 인력풀인데 도민감사관 같은 경우에는 애초에 분야별로 나눠서 전문가들을 모집하고 있습니다. 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 저희도 분야별로 나눠서 전문가로 구성하고 있습니다. 
</p>
<p><b>○ 오창준 위원 </b> 그러면 도민감사관과 도민참여옴부즈만의 어떤 역할적인 차이가 저는 뭔지 좀 궁금한데 설명해 줄 수 있습니까? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 도민감사관에 대해서는 도민의, 감사위원회에서 전문 자문이나 여러 활동들을 하는 걸로 알고 있고요. 저희는 도민의 눈을, 도민을 대신해서, 도민을 대리해서 도정을 감시할 수 있는 차원에서 도민참여옴부즈만을 두고 있습니다. 
</p>
<p><b>○ 오창준 위원 </b> 감사위원장님께 질의드리겠습니다. 방금 도민권익위원장님께서 말씀하셨는데 제가 생각할 때 도민감사관과 도민참여옴부즈만의 경우에는 역할이 굉장히 겹친다고 생각이 드는데 감사위원장님께서는 어떻게 보고 계신지 좀 말씀해 주시겠습니까? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 아마 저도 자세히는 모르나 이런 데에 대한 고민들이 있으셨던 걸로, 위원님들 그때 조례 만드는 과정에서. 그래서 그 조례에 그러한 고민들이 잘 녹아져 있다고 생각을 하고 있습니다. 제가 거기에 대해서는 많이 고민을 못 했습니다. 죄송합니다. 
</p>
<p><b>○ 오창준 위원 </b> 답변을 받기가 좀 어려운 것 같네요. 제가 이 부분은 그러면 따로 조례 심의 다시 개정 얘기하면서 말씀드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  사실 제가 이 질의를 드린 이유는 저번 주 질의 때 제가 말씀드렸듯이 갑질조사 개시 같은 경우에는 내부 건……. 이건 기조실장님께 답변 듣겠습니다. 갑질조사 같은 경우에는 기존에 감사위원회에서 했었고 제가 17개, 그러니까 경기도 제외한 16개 시도와 또 한 150개 정도의 감사관실이나 또는 감사위원회가 있는 기초지자체 전부를 확인해 본 결과 이 내부조사 같은 경우에는 모두 다 감사위원회에서 진행을 하고 있는데 저희 경기도만 유일하게 또 도민권익위원회에서 진행을 하고 있습니다. 그런데 아무리 생각해도 이 내부적인 부분에 대한 갑질 사건을 처리하는 데 있어서 외부조직은 아니지만 외부위원으로 구성된 도민권익위원회에서 이걸 실질적으로 조사하고 신고센터를 운영하는 것 자체가 조금 어떻게 보면 부적절하다는 생각이 들어서 제가 좀 질의를 드리는데 실장님께서는 어떻게 보시는지? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 지금 감사관실이 지난번에 조례 개정돼서 감사위원회랑 도민권익이랑 구분되는 과정 속에서 지금 위원님이 말씀하신 대로 조금 다른 시도랑 달리 특이하고 합리적이지 않은 부분이 있다면 그 부분들은 해당 부서랑 협의해서 일부 조정될 필요가 있다고 봅니다. 
</p>
<p><b>○ 오창준 위원 </b> 답변하신 대로 이번에 아마 제출하신 것 중에 경기도 행정기구 조례 있는 걸로 아는데 그 조례를 개편하는 과정에서 좀 참고 부탁드리겠습니다. 바로 좀 빠른 시일 내에 협의하셔 가지고 반영해 주셨으면 좋겠습니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇게 하도록 하겠습니다. 
</p>
<p><b>○ 오창준 위원 </b> 일단 이것으로 본질의 마치도록 하겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 오창준 위원님 수고하셨습니다. 다음은 박상현 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 박상현 위원 </b> 부천 오쇠리 출신 박상현입니다. (전문위원실 직원을 향하여) 화면에 띄울 수 있을까요? 
</p>
<p><b>○ 위원장 조성환 </b> 자료 표출이 잘 안 되는 것 같은데 이거 준비되는 동안 그러면 박상현 위원님 괜찮으시면 다른 위원님 먼저 하고 준비를 시키도록 하겠습니다. 
</p>
<p><b>○ 박상현 위원 </b> 네, 알겠습니다. 다른 위원님 먼저 부탁드리겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 그러면 정승현 위원님 질의 부탁드리겠습니다. 
</p>
<p><b>○ 정승현 위원 </b> 정승현입니다. 공공기관담당관님. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 공공기관담당관 김도형입니다. 
</p>
<p><b>○ 정승현 위원 </b> 물론 기조실장께서도 같이 들으셔야 되겠지만 오늘 뒤에 지금 각 공공기관 기관장님들 다 오셨잖아요? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 여기 왜 오셨다고 생각하세요? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 저는 그동안 공공기관에서 공공기관 자체적인 역할이라든가 이런 것에 대한 위원님들의 관심과 기대치에 조금 부족한 부분이 있었다고 판단이 돼서 오시게 했다고 생각합니다. 
</p>
<p><b>○ 정승현 위원 </b> 그 책임이 단순히 공공기관장들한테만 있는 거예요, 아니면……. 어디에 있다고 보세요? 
