<p><b>○ 기획조정실공공기관담당관 김도형 </b> 그건 공공기관 자체적 문제뿐만 아니라 저희도 같이 소통이라든가 이런 거에 문제가 있다고 판단합니다. 
</p>
<p><b>○ 정승현 위원 </b> 저는 개인적으로 오늘 공공기관장들 부른 부분에 대해서 나름 제 의견을 말씀드렸어요. 그럼에도 불구하고 어쨌든 다수 위원들께서 이렇게 부를 수밖에 없는 부분에 대해서는 공공기관담당관실에서 큰 책임을 느끼셔야 된다는 거예요. 그렇지 않겠어요? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정승현 위원 </b> 기조실장님! 지금 공공기관담당관의 역할이 뭐라고 생각하세요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 공공기관담당관실 같은 경우에는 공공기관 전체에 대한 제도 개선이나 운영 관련해서 총괄적인 역할을 하고 있습니다. 
</p>
<p><b>○ 정승현 위원 </b> 그렇죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 근데 결국은 그런 부분들이 지금 기대치에 미치지 못한 부분들, 그렇다고 인식이 됐기 때문에 오늘 뒤에 지금 공공기관장들 다 부른 것 아니에요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇게 생각하고 있습니다. 
</p>
<p><b>○ 정승현 위원 </b> 결론부터 말씀을 드리면 다시는 이런 일이 없도록 공공기관담당관실에서는 업무에 철저를 기해 주셨으면 좋겠어요. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 최선을 다하겠습니다. 
