<p><b>○ 정승현 위원 </b> 공공기관담당관님, 언제 오셨죠? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 금년 7월 23일부터 왔습니다. 
</p>
<p><b>○ 정승현 위원 </b> 지금 오신 지 얼마 안 됐기 때문에 전체적인 업무파악이 다 되셨을지 모르겠습니다마는 지금 공공기관담당관실에 정책팀이 있고 지원팀이 있고 평가팀 3개 팀이 있는 거죠? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정승현 위원 </b> 지금 공공기관별로 각 담당 부서에서 관리, 정책이나 지원업무는 따로 다 하고 있는 거죠? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 주무부서에서 담당하고 있습니다. 
</p>
<p><b>○ 정승현 위원 </b> 주무부서에서 다 하고 있는 거죠? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 그럼 실질적으로 지금 공공기관담당관실에서는 가장 주요한 팀이 지금 평가팀이라고 할 수 있고 그 평가결과에 따라서 오늘 이렇게 자리가 될 수밖에 없는 상황이라고 보여져요. 지금 평가팀 직원 몇 명 있죠? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 평가팀 5명입니다. 
</p>
<p><b>○ 정승현 위원 </b> 5명이요? 지난번에 3명인데 2명 늘어났네요. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 지난번에……. 
</p>
<p><b>○ 정승현 위원 </b> 제가 왜 인원을 여쭤봤냐면 그때 당시에 제가 말씀을 드릴 때 3명 가지고는 절대적으로 27개가 되는 공공기관 업무를 다 관장하고 평가하는 데 있어서 합리적인 결과가 나올 수 없다. 그렇게 해서 제가, 실장님 기억나세요? 평가팀 인원 늘리라고 했던 거. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 이 과장 오기 전에 그 말씀하시고 일부 내부적으로 조정을 좀……. 
</p>
<p><b>○ 정승현 위원 </b> 담당관님께서도 앞서 답변에서 그렇게 인식하셨던 것처럼 어쨌든 담당관실에서 27개, 28개 기관에 대한 총체적인 책임과 역할, 지도감독 업무를 책임지고 있다고 한다면 인력 구성부터 제대로 갖춰야 된다는 거예요. 한정된, 제한된 인력 가지고 이 많은 기관들을 관리감독하기에는 분명히 문제가 있고 그로 인한 제대로 된 평가가 이루어질 수 없다라는 것들이에요. 그 부분에 대해서 더욱더 만전을 기해 주시기 바라면서 지금 공공기관 27개인가요? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 28개입니다. 
</p>
<p><b>○ 정승현 위원 </b> 28개죠. 그중에 우리 경기도 예산, 그러니까 사업 예산만 지금 편성되는 곳이 몇 개 기관이고, 인건비까지. 인건비 포함되지 않는 기관이 몇 곳이에요? 우리 경기도 예산 중. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 인건비가 포함되지 않는 곳은 3개가 제외돼서 25개 기관에 인건비가 지원되는 것으로 알고 있고요. 
</p>
<p><b>○ 정승현 위원 </b> 3개 기관에는 인건비 지원이 아니라 자체예산 가지고 운영하고요. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정승현 위원 </b> 지금 우리 경기도 각 공공기관 전체 인구, 그러니까 정원에 대해서 지금 우리 도가 관리를 하고 있는 거죠? 총정원 관리에 포함시켜서 지금 관리하고 있는 거죠? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 공공기관 총정원 관리하고 있습니다. 
</p>
<p><b>○ 정승현 위원 </b> 지금 현 정부 들면서 공무원 정원 동결 방침에 따라서 우리 도 공무원 정원 하나도 늘리지 못하고 있는데 이 방침에 공공기관도 해당이 되는 건가요? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 저희들이 공공기관 정원 증가를 공무원 정원 증가율에 따라서 그동안 해 왔었는데 그렇게 해서는 저희들이 공공기관이 담당하고 있는 업무를 감당할 수가 없어서 2023년도서부터 7월 이후에 그것 때문에 변경을 해서 공공기관만 정원의 2%, 공공기관 총정원의 2% 정도는 늘릴 수 있도록 내부적 방침을, 공공기관 정원 운영 계획을 바꿨습니다. 
</p>
<p><b>○ 정승현 위원 </b> 각 기관마다 업무적 성격에 따라서, 특성에 따라서 다를 수도 있겠지만 지금 정원 문제로 굉장히 어려움을 겪고 있는 기관들이 있는 거죠? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 맞습니다. 
</p>
<p><b>○ 정승현 위원 </b> 그리고 공공기관 정원에 관한 부분은 도지사의 권한이잖아요? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 맞습니다. 
</p>
<p><b>○ 정승현 위원 </b> 정부가 공무원 정원 동결시켰다고 해서 공공기관까지 해당되는 건 아니잖아요? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 저희들이 자체 운영 규정을 만들다 보니까, 네. 
</p>
<p><b>○ 정승현 위원 </b> 자체 지침을 통해서 도지사 권한으로 정원 관리를 하고 있는 거죠? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 그렇습니다. 
</p>
<p><b>○ 정승현 위원 </b> 제가 이것까지 강제하지는 않겠어요. 지금 다른 시도 보니까 공공기관 정원에 대해서 광역시도에서 지침을 통해서 정원 관리를 하고 있는 시도는 없는 걸로 보여요. 경기도만 유일하고. 그럼에도 불구하고 그 취지에 대해서는 제가 충분히 공감을 하기 때문에 그 지침의 잘잘못에 대해서는 얘기하지 않겠어요. 그러나 아까 제가 평가팀이나 지원팀, 정책팀 얘기했지만 각 기관별 특성 또 현실을 반영한 그런 정원 정책은 충분히 인정이 돼야 된다라는 부분에 대해서는 제가 좀 제안을 드리겠습니다. 무슨 얘기인지 아시겠어요? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 그리고 다시 한번 말씀드리지만 하여튼 앞으로는 공공기관장들이 이 자리에 나오지 않도록 담당관실에서 철저한 관리감독해 주셨으면 좋겠고. 기조실장님! 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 공공기관담당관께 저는 충분한 권한을 좀 주셨으면 좋겠어요. 뒤에 지금 기관장들 앉아 계시지만 공공기관담당관실에서 업무지침이나 여러 가지 제안을 했었을 때 얼마만큼 받아들일 수 있느냐 없느냐에 대한 문제의식도 갖고 있습니다마는 충분히 그런 것들을 받아들일 수 있도록 공공기관담당관에 저는 충분한 그런 권한도 주어졌으면 좋겠어요. 그러고 나서 책임도 물어야 된다고 저는 생각하거든요. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇게 하도록 하겠습니다. 
</p>
<p><b>○ 정승현 위원 </b> 수고하셨습니다. 인구정책담당관님. 기조실장님께서 답변하실래요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 기조실장 이희준입니다. 
</p>
<p><b>○ 정승현 위원 </b> 제가 통계청 자료를 보니까, 지금 우리 경기도에서 굉장히 많은 인구 정책들을 시행하고 있는 거죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 24년만 해도 16개 사업에 1,783억 예산을 소위 말하는 저출산 대응을 위한 청년세대 및 신혼부부 등 각 세대별 지원사업으로 시행을 했어요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 22년부터 3년간 하면 약 한 3,200억 정도를 쏟아부었는데 그럼에도 불구하고 지금 통계청 인구 동향조사를 보면 경기도 관내에서 화성과 양주 외에는 지금 출산율이 계속해서 낮아지고 있어요. 이렇게 막대한 예산, 출산정책 내지는 인구감소 대응정책이라고 해서 지금 많은 예산들을 쏟아붓고 있는데 화성과 양주 외에 나머지 29개 시군은 계속해서 출산율이 낮아지고 있다는 것들이죠. 이에 대해서 어떻게 생각하세요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 전반적으로 화성과 양주는 청년들 유입인구가 그래도 꽤 있는 편입니다. 그러다 보니까 출산율이 어느 정도 유지되고 있는데 나머지 지역들은 고령화 현상과 물려서 전반적으로 줄어들고 있는 상황입니다. 
</p>
<p><b>○ 정승현 위원 </b> 제가 늘 말씀드리지만 인구감소 요인은 그리고 저출산 요인은……. 
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p style="padding-left:1.2em">  조금만 더 하겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 네. 
</p>
<p><b>○ 정승현 위원 </b> 너무 명약관화하다고 생각합니다. 그 원인은 누구나 공감하듯이 딱 정해져 있다고 생각합니다. 그래서 정책 역시도 이에 맞는 현실성 있는 정책들이 반영돼야 된다. 그런 측면에서 저는 그렇지 못한 결과가 이 화성, 양주 외에는 저출산이 계속 지속되고 있다 저는 그렇게 보이고 있거든요. 굳이 말씀드리지 않겠지만 저출산이나 인구 감소 요인이 무엇인지에 대해서 제대로 된 진단을 다시 한번 해 주시고 그 진단에 따라서 출산정책들을 계속해서 펴나갔으면 좋겠다라는 말씀을 드리겠습니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 더욱 유념해서 업무 추진하도록 하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 우리가 굉장히 많은 예산들을 쏟아붓고 있는데 전체적인 인구는 경기도가 늘어나고 있지만 결국 이거는 총 인구수 증가에 대해서는 지금 효과를 보고 있지 못하는 거잖아요. 지자체 자체 인구는 증가하고 있지만 그러나 이런 것들이 여기에 안주해서는 안 된다는 거죠. 기본적인 맥락은 우리가 출산율을 높이기 위한 정책들이지 다른 지자체에서 우리 경기도로 전입하고 전출 안 가게 만드는 그게 인구정책은 아니라는 것들이죠. 그렇죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그래서 기본적으로 이 출산율을 높일 수 있는 그런 정책들을 심도 있는 고민을 통해서 그래서 현실성 있는 그리고 이런 정책들로 인해서 실제로 출산율이 좀 높아질 수 있는 그런 경기도만의 정책들을 저는 좀 다시 한번 고민했으면 좋겠습니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇게 하도록 하겠습니다. 
</p>
<p><b>○ 정승현 위원 </b> 경기도가 이런 정책들을 내놨었을 때 결국 대한민국 정책이 되는 것이에요. 그래서 경기도가 하면 저는 대한민국이 한다 그런 기조로 하여튼 경기도에서 획기적인 그런 어떤 방안들을 내놓으셨으면 좋겠습니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 작년에 저희도 난임부부 그 시술 관련해서는 저희가 소득 제한 기준을 없애는 그런 정책을 펴서 중앙에서도 호응을 받았는데요. 저희 그런 정책들을 더욱더 많이 만들어내도록 하겠습니다. 그렇게 하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 일부 학자들 평에 의하면 굉장히 우리 경기도뿐만 아니라 정부 자체가 인구정책에 대해서 획일적인 그런 정책들을 펴고 있다라는 것들이죠, 실질적인 현실성 있는 정책들이 아니라. 그래서 저는 개인적으로 좀 이 지역 특성에 맞는, 도시 특성에 맞는, 각기 다 다르잖아요. 도농복합도시가 있고 청년들이 주로 많은 인구가 있고 노령인구가 많은 도시가 있고 그렇잖아요. 그러면 그 도시 특성에 맞는 인구정책도 가져가셔야 된다, 저는 그렇게 보고 있습니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 그 부분까지는 저희가 아직 이렇게 뭐, 그런데 시군과 조금 더 논의를 해 가면서 위원님 말씀하신 건 보완할 수 있도록 하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 그리고 마지막으로 한 가지만 더 제안드리면 우리가 지금 각종 기금을 운용하고 있잖아요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 거기에 지금 초고령사회를 대비한 그런 기금이 있나요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 고령사회 대비 기금은 별도로 따로 있지는 않습니다.
</p>
<p><b>○ 정승현 위원 </b> 없죠, 지금?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 제가 광주광역시를 보니까 지금 초고령사회를 대비한 기금을 하나 조성했더라고요. 저는 이거는 정말 필요하다고 봅니다. 그래서 이 부분도 좀 내부적으로 검토하셔서 초고령사회에 진입이 됐었을 때 이 예산을 효율적으로 활용할 수 있는 그런 부분들을 사전에 준비해야 되지 않겠느냐. 그런 측면에서 이 기금 설치 부분에 대한 고민들을 검토해 달라는 제안을 드리면서 제 말씀 마치겠습니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 아까 박진영 위원님께서 기금 관련해서 여러 가지 종합적으로 한번 볼 필요가 있다고 말씀 주셔서 저희도 그 부분에 대해서는 적극 저희도 검토하겠다고 말씀드렸는데 아울러서 같이 검토하도록 하겠습니다. 
</p>
<p><b>○ 정승현 위원 </b> 물론 기금의 통폐합 과정도 충분히 필요합니다. 지금 우리가 기금 운용에 대한 저평가를 받는 이유 중의 하나도 여러 가지 그런 부분들이 있기 때문에 통폐합과 관련해서 초고령사회 진입을 앞두고 있는 이 시기에 이와 관련된 기금을 새로 설치하는 부분들도 한번 고민해 보시라는 거예요.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 같이 검토하게 하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 정승현 위원님 수고하셨습니다. 오전 질의 마지막 순서로 우리 박상현 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 박상현 위원 </b> 부천 오쇠리 출신 박상현입니다. 지난주에 자료요구 사항에 대해서 약간 혼동이 좀 있어서 저희 쪽에서 공식적으로 자료요구를 한 적이 없었음을 미리 말씀을 드리고 그거에 대해서 먼저 양해의 말씀을 좀 부탁드리겠습니다. 그래서 자료를 제가 혼자서 급하게 만들어서 여기에서 보시는 표출자료가 조금 보기가 어려운 점을 미리 양해 부탁드리겠습니다. 기조실장님!
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 기조실장 이희준입니다.
</p>
<p><b>○ 박상현 위원 </b> 기조실이 현재 경기도 행정기구와 관련된 조례에 의해서 도정의 기획, 조정, 조직의 관리에 관련된 업무를 법적으로 수행해야 한다는 점에서는 동의하시죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇습니다.
</p>
<p><b>○ 박상현 위원 </b> 그다음에 기조실은 도정의 비전과 혁신전략을 제시하고 그다음에 성과평가를 총괄하여 도정의 일관성과 효율성을 또 추진하는 데에 대해서 법적으로 제시된, 명시된 거는 확인하셨죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 알고 있습니다.
</p>
<p><b>○ 박상현 위원 </b> 그럼 제가 오늘 또 얘기하고 싶은 것은 이 사항입니다. 지금 이 표출자료를 보려고 하는데 기조실에서 실질적으로 이런 다양한, 도민들을 위한 공공서비스가 다양화되어 있는데 저희가 정책 목적으로 바로 도민들에게 요청하는 사업이 있는, 지원하는 사업이 있는 반면에 도민들의 참여가 또 절실히 필요한 사업 또한 있습니다. 
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  이 표출자료를 한번 보시면 기조실에서 이것을 관리하지 않으면 어떻게 되는지에 대해서 잠시 한번 살펴보겠습니다. 첫 번째, 이거 몇 가지입니다. 150개 중에서 제가 시간상 몇 개만 추스린 거예요. 교통정보과에서 경기교통정보에 관련된 서비스를 2010년도부터 하는데 2024년에 올해 예산 유지비용이 한 1,000만 원 들었는데 사실상 다운로드 횟수가 24년도에 한 3,000건 정도입니다. 누적된 거 그러니까 계속 사용한, 올해 한 해만요. 
</p>
<p style="padding-left:1.2em">  그다음 페이지요. 또 교통정보과에서 경기버스정보에 대해서 2024년에 4,100만 원에 관련된 운영비가 들어가는데 이 경기버스정보에 관련된 서비스는 24년도에 약 8만 8,000명 정도가 다운로드됐고요. 
</p>
<p style="padding-left:1.2em">  그다음에요. 평생교육과 경기도 지식(GSEEK)이라고 하는 서비스가 있습니다. 이거는 2024년도 1년 운영비가 1,500만 원입니다. 관련된 데이터 수집자료도 굉장히 다양한데요. 이거는 2024년도에 8만 7,000명이 사용을 했고요.
</p>
<p style="padding-left:1.2em">  그다음에요. AI프런티어사업에서 똑D를 관리하고 있는데 이거는 1년간 운영비용만 약 10억 정도입니다. 그런데 24년도에 사용자 다운로드가 한 9만 3,000명 정도 됐고. 
</p>
<p style="padding-left:1.2em">  그다음에요. 경기옛길이라고 하는 서비스가 있는데 2024년도에 약 2,000만 원 정도의 운영비가 나갔습니다. 사용자는 약 2,000명 정도가 나왔고요. 
</p>
<p style="padding-left:1.2em">  그다음에요. 도자재단에서 박물관서비스를 보게 되면 2024년도 약 1,000만 원 정도의 운영비가 발생됐고 사용자는 2024년도 기준의 약 580명 정도고요.
</p>
<p style="padding-left:1.2em">  그다음. 그다음에요. 경기도 편의시설에 관련된 서비스입니다. 이거는 운영ㆍ유지ㆍ홍보비 포함해서 약 5,000만 원, 24년도에 약 1,900명 정도, 약 2,000명 정도가 사용하셨습니다.
</p>
<p style="padding-left:1.2em">  그다음에요. 안심톡, 경기안심톡이 있는데 2024년도에 운영비가 4억 4,000만 원인데 24년도 기준 다운로드 횟수가 1만 3,000명 정도입니다.
</p>
<p style="padding-left:1.2em">  그다음에요. 사이버도서관도 운영비가 약 300만 원 정도에 사용자는 다운로드가 2만 7,000건 정도가 있었고요.
</p>
<p style="padding-left:1.2em">  그다음에요. 이거는 유심히 봐야 될 것 같은데 워라밸링크라고 하는 곳에서 일단은 운영비만 2억 2,000 정도입니다, 1년에. 앱은 폐지가 됐고요. 
</p>
<p style="padding-left:1.2em">  제가 이거를 시간을 들여서 일단 기조실장님께 표출자료를 꼭 보여드리고 싶었던 건 뭐냐 하면 운영비용이라든지 다운로드 횟수라든지 1회 사용자 평균 수라든지 그다음에 경기도민들에게 제공되는 서비스에 따라서, 다양한 변수에 의해서 분명히 이게 유지비용이나 운영비가 결정될 거라고 보는 거고 저희가 이 위탁기관의 업무에 관련된 양을 아마 조사해 보면 이 금액이 적정하다라고 저희는 믿고 있습니다. 그런데 이것을 평가할 방법이 절대 없어요. 모든 실국에서 지원하고 있는 이 앱에 관련된 정책의 효능성이라든지 또 이 앱이 가지고 가게 되는 운영비용이라든지 그다음에 이것들에 관련돼서 도민들이 얼마큼 많은 분들이 혜택을 받느냐에 대한 이슈들이, 다양한 요소들이 있는데 이것에 대해서 지금 몇 년째 자료를 보고 있는데 이게 알 수가 없다는 거죠, 어떤 기준에 의해서 예산이 책정이 되고 그 예산이 집행이 되고. 
</p>
<p style="padding-left:1.2em">  이게 아마 예산 총괄 부서에서는 이 사업이 각 실국이 원하니까 집행이 됐다라고 믿고 일단 예산을 내리는 건 확실한데 실질적으로 이게 정말로 도민들을 위해서 필요한 사업이라고 한다면 사용자가 적으면 홍보비를 늘려야 되는 거고 이런 식으로 뭔가 전략적으로 기조실에서 전체적으로 업무를 좀 봐줘야 되는데 지난주 월요일 날 기조실장님은 아직까지 명쾌한 해답을 주시지는 않으셨어요, 사실상. 검토해 보겠다. 하지만 이 자료를 보게 되면 기조실장님의 생각이 다를 거라고 생각이 돼서 급하게나마 자료를 일단 정리를 조금 해 봤습니다. 그래서 아마 자료가 추가로 올 건데요. 그 자료를 보시게 되면 훨씬 더 명확하게 우리 기획조정실에서, 이거 운영하라는 게 아니라 전체적으로 이게 도정의 방향에 맞고 그다음에 중복되는 게 있으면 조정이 돼야 되고 그다음에 과도하게 운영비가 많이 발생되는 것이 있으면 이게 왜 발생되는지 확인을 해 보고 그다음에 이것에 대한 정책적 추진이나 평가에 관련된 근거를 마련하고 이런 것도 저는 기조실에서 반드시 필요한 사항이라고 생각해서 좀 시간을 들여서 이 사항에 대해서 얘기를 했고요. 자료가 오는 즉시 다시 한번 검토를 해 보고 다시 추가 질문에 대해서 얘기를 하겠습니다. 실장님!
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 박상현 위원 </b> 두 번째입니다. 이거는 기조실에 관련돼서 업무 중에 어떻게 보면 조직에 관련된, 조정에 관련된 겁니다. 키워드는 장애인표준사업장입니다. 갑자기 장애인표준사업장 갖고 와서 좀 놀라실 거라고 생각이 드는데요. 장애인표준사업장은 일반적으로 장애인들을 10명 이상 고용을 해서 장애인표준사업장이라고 지정받는 것입니다. 근데 일반적인 회사입니다. 일반적인 회사이나 국가에 관련된 정책적 목적을 실현시키기 위해서 예를 들어서 장애인에 관련된 고용을 늘린다거나 그다음에 장애인에 관련된 고용을 늘리게 되면 그다음에 그것에 대해서 국가적으로 혜택을 주기 때문에 나름대로는 장애인과 함께 더불어 살기 위해서 일반 기업이 장애인을 많이 고용하는 기업을 보통 장애인표준사업장이라고 얘기를 하는데요. 현재 이 장애인표준사업장이 소위 말해서 경제노동위원회 산하의 기업을 위한 지원과로 되어 있는 건 아니고 보통 일반 장애인자립과라고 배정이 돼 있어 보건복지로 되어 있습니다. 어떻게 보면 복지 쪽으로 일단은 배정이 돼 있는 거거든요. 이것에 대해서 그렇게 장애인자립과에 소속된 이유와 배경이 혹시 있을까요? 어떤 법적 근거가 있기 때문에 아마 그쪽으로 된 걸까요? 아니면 장애인이라고 하는 그 단어가 있기 때문에 장애인자립과로 배정한 걸까요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 말씀드리겠습니다. 위원님, 저희가 일반적으로 업무가 무 자르듯이 딱 되는 경우에는 그렇게 딱 결정이 되는데 지금 말씀하신 대로 기업이자 장애인 이렇게 관련돼서 중복돼 있는 경우에는 통상 저희들이 중앙부처에서 어디에서 그 업무를 하느냐에 따라서 다루고 있는데 장애인자립표준장 업무는 지금 보건복지부에서 하다 보니까…….
</p>
<p><b>○ 박상현 위원 </b> 아, 아닙니다. 지금 현재 장애인표준사업장은 고용노동부 산하에 있습니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 노동부, 네. 아, 그 부분은 고용노동부……. 그 부분은 다시 확인해 보겠습니다.
</p>
<p><b>○ 박상현 위원 </b> 네, 확인해 주시고. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇게 하겠습니다.
</p>
