<p style="padding-left:1.2em">  식사 맛있게 하셨습니까? 날씨가 갑자기 추워졌습니다. 건강에 유의하셔야 될 것 같고요. 오후 첫 순서로 이성호 위원님 본질의해 주시겠습니다.
