<p><b>○ 기획조정실장 이희준 </b> 네, 기조실장 이희준입니다.
</p>
<p><b>○ 이성호 위원 </b> 요구자료 두 번째 책자 320페이지에 좀 보시면. 의문이 나는 사항이 좀 있어서 여쭤보려고 하는데요. 예비비 집행내역을 보시면, 24년 거를 보시면 2번에 보셔도 판결원금과 이자 지급. 4번, 5번, 6번 다. 아, 5번, 6번 같은 경우에도 “판결원금 이자 지급” 이렇게 돼 있거든요. 9번하고 13번도 그렇고 17번도 마찬가지인데. 이게 합치면 한 38억 원 정도가 됩니다. 그런데 제가 알기로는 본예산에 판결금이나 이런 걸 지급할 수 있는 계정이 있는 걸로 알고 있는데 본예산에 잡히지 않고 이런, 여기 예비비로 집행하는 이유는 어떤 건지 좀 궁금합니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 잘 아시다시피 판결이라는 게 언제 날지가 사실 굉장히 유동적이지 않습니까? 그래서 저희가 소송비용 해서 변호사 비용이랑 그다음에 인지대 이런 것들은 어느 정도 예측이 되기 때문에 그 소송비용 관련해서 예산을 잡는데요. 이런 판결금과 관련해서는 사실 이렇게 확정적으로 예측되지 않는 경우에는 거의 잘 잡지를 못합니다. 왜냐하면 판결 시기가, 그래서 부득이하게 예비비로 지급하는 경우가 있다는 경우를 말씀드립니다. 
</p>
<p><b>○ 이성호 위원 </b> 만약 그런 이유라고 그러면 향후에는 좀 면밀하게 검토가 필요할 것 같거든요. 판결 같은 경우에도 소송 진행상황 같은 거를 잘 보시다 보면 언제 정도에 판결이 날지 판결선고 같은 것도 예측이 충분히 가능하고, 왜냐하면 1년 내에 하는 거기 때문에. 예산은 1년 동안 잡는 거니까 1월에서 12월 그중에는 판결이 날 거 정도는 예측이 충분히 가능한 사건들이 많거든요. 그런 예측이 지금 많이 안 된 것 같아요. 이런 부분에 대해서는 조금 면밀한 검토를 향후에는 좀 해 주시면 좋을 것 같습니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 이거는 부서랑 협의해서요, 조금 더. 그리고 하나 조금 더 추가적인 어려움을 말씀드리면 토지보상금 같은 경우에 저희가 어느 정도 예측하고 해서 하면 되는데 소송 같은 경우에는 사실 저희가 대응할 때 또 진다는 걸 전제로 해서 예산을 편성하는 것도 조금 어려움이 있고 그래서 저희가 부득이 예비비로 편성하는 측면도 있다는 말씀드리고요. 저희가 예측 가능한 부분에 대해서는 시기나 그다음에 손해보상금 이런 것들은, 토지보상금 이런 것들은 어느 정도 가능하지 않습니까? 그런 부분들은 최대한 부서랑 협의해서 반영될 수 있도록 그렇게 하겠습니다.
</p>
<p><b>○ 이성호 위원 </b> 그리고 전에 감사 때 말씀을 드렸었는데 법무담당관이 예측을 해야 될 부분 중에 이런 부분이 다 들어가는 거거든요. 항소나 상고 여부에 관한 판단도 제대로 지금 안 되고 있는 상황이라 오히려 이런 판결 같은 것도 예측, 판결 시기조차도 예측을 못 한다는 거는, 웬만한 소송은 다 1년 내에 판결이 납니다. 그런데 이걸 예측을 못 해서 38억이 예비비로 나갔다는 거는 조금 문제가 있어 보이거든요. 그래서 추후에는 하여튼 이거는 좀 잘 면밀한 검토를 부탁드리겠습니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 저희가 부서랑 협의해서 반영할 수 있는 부분은 반영하도록 그렇게 하겠습니다.
</p>
<p><b>○ 이성호 위원 </b> 그리고 15번, 16번 보시면 오물풍선 살포로 발생한 피해 지원이라든지 호우 피해시설 복구비 지원. 2023년, 321페이지에 12번 보시면 우박 경기동북부 지역 피해 재해복구비 이런 내용들 있지 않습니까? 
