<p><b>○ 이성호 위원 </b> 그리고 또 재난관리기금이 있고 재해구호기금이 있는데 이 기금이 굉장히 잔액이 많은 걸로 알고 있거든요. 그런데 이 기금을 쓰지 않고 재해ㆍ재난, 예비비로 먼저 집행을 하는 어떤 사유라든지 기준이 있나요, 그게?
</p>
<p><b>○ 기획조정실장 이희준 </b> 그 부분은 제가 좀 말씀드리겠습니다. 재해ㆍ재난 관련해서요. 우리 시군이나 이쪽에서 재해 관련된 하천이나 도로 같은 데 비용들은 우선적으로 말씀하신 그 기금에서 지출이 됩니다. 다만 기금 부서에서 민간한테 나가는 돈은 그 기금에서 일정 부분 제한이 있다고 합니다. 그래서 여기 있는 부분들은 민간한테 나가는 경우로 이해하시면 될 것 같습니다. 그래서 거기는 기금상의, 사용상의 제한 때문에 저희가 예비비로 지출하고 있다는 말씀드립니다. 
</p>
<p><b>○ 이성호 위원 </b> 여기 있는 재해 관련 내용은 다 민간이라고 보면 되는 거고. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 대부분 그렇습니다. 
