<p><b>○ 이성호 위원 </b> 네, 알겠습니다. 그리고 법무담당관님께 질의하겠습니다. 안 계시면 실장님께 좀 말씀드릴게요. 
</p>
<p style="padding-left:1.2em">  그때 소송심의위원회라든지 어떤 그런 절차 관련해서 개선방안을 자료요청드렸는데 내용이 너무 좀 간단하게 와서 그래서……. 잠시만요. 
</p>
<p style="padding-left:2.4em">    (이성호 위원, 자료 확인 중)
</p>
<p style="padding-left:1.2em">  그때 제가 말씀드린 내용이 굉장히 많은데 한 네 줄 정도로 대책을 보내주셨더라고요. 그래서 지금 자료를 다시 받기는 좀 어려울 것 같고 추후에 진행경과에 관해서 그때그때 보고를 해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그리고 제가 몇 가지를 다시 좀 필요한 사항 건의를 하고자 하는데요. 첫 번째로 소송심의위원회의 성격상 조례규칙심의회가 소송심의위원회를 대행하는 규정을 개정하거나 폐지할 것이 필요할 것 같고 그다음에 소송심의위원회에서 실국장 외에 법률전문가를 포함시킬 것. 또 중요 소송의 상소 여부, 여기서 상소는 항소나 상고 여부입니다. 그 여부를 소송심의위원회에서 결정할 것 그리고 대법원의 상고심 결과가 심리불속행기각이 나올 경우에 상고심을 대리한 변호사나 법무법인에 대한 어떤 페널티라든지 어떤 제재부과 방안이 있어야 될 것 같고 또 승소 가능성이 높다고, 어떤 중요한 소송인데도 승소 가능성이 높다고 자문을 했는데 패소한 경우에 그 후에 후속 조치가, 그 자문변호사 내지 법무법인에 대해서 수임 또는 자문의 일정 기간 제한이라든지 어떤 페널티 마련이라든지 이런 후속 조치가 필요한 것으로 보여서 이런 부분에 대해서 본 위원이 건의하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음으로 경기연구원의 경우에 유사한 내용의 대법원 판결이 존재하는 상황에서 그런 대법원 판결의 판시 내용에 반하는 어떤 연구가 진행되지 않도록 추후에 각별한 주의를 해 주시기 바랍니다. 이상입니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 위원님 말씀하신 부분 감안해서 저희가 후속 조치 준비토록 하겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 이성호 위원님 수고 많으셨습니다. 이렇게 본질의를 다 마쳤습니다. 이제 보충질의를 할 텐데요. 아마 보충질의에는 우리 공공기관장님들에 대한 질의가 있을 예정입니다. 우리 기관장님들의 바쁘신 일정을 참고해서 저희 질의가 다 끝나면 끝나는 기관은 먼저 이석하시도록 위원장이 말씀을 드릴 테니까 질의 후에 이석하시면 되겠습니다. 
</p>
<p style="padding-left:1.2em">  저희가 오늘 공공기관장님들 이렇게 한자리에 모신 이유 중의 하나는 사실은 도민의 삶에 영향을 주는 사업들을 가장 많이 하는 기관들이 우리 공공기관입니다. 그리고 도정 운영의 큰 축이기도 하고. 이러한 기관들에 대해서 저희가 한번 점검하고 또 혁신이 필요한 부분도 있고 또 기관장님들의 애로사항도 있다고 판단이 되어서 조직, 예산 그다음에 그러한 감사와 관련된 부분에 대해서 저희가 기관장님들과 질의 답변을 통해서 해결 방안을 마련하고자 하는 부분들이 있습니다. 특별히 우리 경기도는 북부특별자치도를 추진하고 있고 공공기관에 대한 북부 이전 계획도 지금 순차적으로 진행되고 있는 상황이어서 개개별 공공기관이 해결하기에는 한계가 있는 사안들이 많이 있습니다. 그래서 이런 자리를 통해서 그러한 부분들에 대한 논의를 의회와 시작을 하고 서로 소통하는 그러한 부분들이 되기를 희망하는 그런 기대감이 있습니다. 
</p>
<p style="padding-left:1.2em">  그러면 보충질의를 시작하도록 하겠습니다. 우리 이경혜 위원님께서 먼저 해 주시기 바랍니다. 
</p>
<p><b>○ 이경혜 위원 </b> 고양 이경혜입니다. 먼저 경기관광공사의 조원용 사장님 잠시 앞으로 나와 주시겠습니까? 
</p>
<p><b>○ 증인 조원용 </b> 경기관광공사 사장 조원용입니다. 
</p>
<p><b>○ 이경혜 위원 </b> 아침부터 고생이 많으십니다. 두 가지를 여쭤볼게요. 제가 지난번 DMZ 오픈 페스티벌 중에 DMZ 콘서트를 가서 보았어요. 1부가 DMZ 평화콘서트였고 2부가 DMZ 피크닉 페스티벌이었죠? 
</p>
<p><b>○ 증인 조원용 </b> 네. 
</p>
<p><b>○ 이경혜 위원 </b> 2부 DMZ 피크닉 페스티벌을 관광공사에서 하셨죠? 
</p>
<p><b>○ 증인 조원용 </b> 네, 했습니다. 
</p>
<p><b>○ 이경혜 위원 </b> 그러면 DMZ 평화콘서트 예산이 혹시 얼마인지 아십니까? 
</p>
<p><b>○ 증인 조원용 </b> 4억 정도 되는 걸로 알고 있습니다. 
</p>
<p><b>○ 이경혜 위원 </b> 그러면 그날 2부에 관광공사 예산은 얼마셨어요? 
</p>
<p><b>○ 증인 조원용 </b> 그거가 3억 이하로 알고 있습니다. 
</p>
<p><b>○ 이경혜 위원 </b> 더 작은 금액이었던 거죠. 제가 듣기로는 금액의 3분의 1 정도라고 들었는데 사장님 말씀 주신 걸로는 조금 더, 많은 차이가 나지는 않았네요. 제가 말씀드린 건 칭찬드리고 싶어서예요. 그날 원래 DMZ 오픈 페스티벌에서 하는 주 1부의 공연보다 2부의 관광공사에서 준비한 피크닉 페스티벌에 어마어마한 인원들이 오셨어요. 앞에 1부에 계셨던 분들 거의 빠져나가고 2부에서, 그 평화누리가 인산인해를 이룬 건 저는 지금까지 평화누리 가서 처음 봤거든요. 밤 10시 반이 넘는 시간까지 너무나 많은 사람들이 감동하고 즐거워하고 가는 모습을 보면서 작은 예산으로도 이렇게 큰 효과를 거둘 수 있게 만들어준 것에 대해서 감동도 했고 그날의 일을 굉장히 잘했다, 칭찬드리고 싶어서 잠시 나오셔서 말씀 주셨으면 좋겠다 했고요. 
</p>
<p style="padding-left:1.2em">  또 하나가 그 많은 사람들을 쓰려면 인원은 얼마 정도 필요할까요? 숫자로 말씀하실 수 없죠. 제가 계속 여쭤보는 이유는 대체인력이나 별도 정원이 더 필요하실 텐데 이 부분에 대해서 요청을 따로 하신 적이 있을지 여쭤보고 싶어서입니다. 
</p>
<p><b>○ 증인 조원용 </b> 인원 요청은 많이 하지만 어쨌든 공사로서 행자부의 어떤 인원 확충에 대한, 늘리지 못하게 돼 있는 것도 있고 공공기관담당관하고도 협의할 때 여러 기관이 있기 때문에 형평성 차원에서 한꺼번에 많이 못 늘린다 이런 얘기도 들었고 그래서……. 
</p>
<p><b>○ 이경혜 위원 </b> 알겠습니다. 거기까지 답변 주시면 감사하겠습니다. 자리로 돌아가셔도 좋습니다. 
</p>
<p style="padding-left:1.2em">  제가 DMZ에 대한 이야기를 내일 다시 할 건데 관광공사에서 DMZ에 대한 위탁사업을 70% 이상 하고 있기 때문에 오늘 제가 한 번 더 여쭤본 거고요. 마지막 질의를 좀 더 하겠습니다. 
</p>
<p style="padding-left:1.2em">  제 자료 혹시 표출 보여주실 수 있나요? 맨 뒤로 가주시면 됩니다. 
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  그 자료 보시면 경기도 초과근무 부정수급 조사결과 및 조치예요. 일일이 다 읽지는 않겠습니다. 21년 21건, 22년 43건, 23년 55건, 24년에 몇 건인지 알 수 없지만 31개 시군에 119건의 부정수급 결과가 있었고 경기도는 21년 4명, 22년 8명, 23년에는 없습니다. 24년은 아직 어떻게 되는지 자료가 없어서 제가 말씀드릴 수 없지만 앞서 말씀드렸던 위원회의 수당 지급에 대한 부분도 규정과 절차를 어긋나게 한 일들이 발생했고 이런 초과근무수당 부정수급자들도 지속적으로 발생하는 부분이 있다면 이것들을 끊임없이 잘 관리하셔야 하는 부분에 대해서 말씀을 드리고 싶어서 제가 한 번 더 조정을 드렸는데요. 기획조정실장님께서는 전반적인 이 수당 지급 체계들, 공무원들의 수당 지급과 위원회 수당 지급들에 대해서 특별히 더 신경을 쓰셔서 절차와 규정을 어기지 않고 제대로 할 수 있도록 도와주시길 부탁드리고. 감사위원장님께서는 제가 아까 말씀드린 것처럼 반드시 위원회의 감사 다 해 주시고 이 결과는 끝나는 대로, 올해 다 못 하시겠지만 끝나는 대로 내년에라도 결과를 저에게 반드시 가져다주시길, 보고 부탁드리겠습니다. 그렇게 해 주실 수 있으시죠, 위원장님? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 알겠습니다. 
</p>
<p><b>○ 이경혜 위원 </b> 마지막으로 한 가지만 더 기획조정실장님께 말씀드릴게요. 도민권익위원회의 옴부즈만에서 잘한 실천 사례가 어떤 것들이 있냐 하면 난임부부들의 지원에 대한 문제를 민원을 받고 이 부분을 도민권익위원회에서 해결해서 21회의 난임 지원 회차에서……. 
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p style="padding-left:1.2em">  조금 더 써도 되나요, 아니면 추가로 할까요? 
</p>
<p><b>○ 위원장 조성환 </b> 1분만 더 주시죠. 
</p>
<p><b>○ 이경혜 위원 </b> 난임 지원을 할 수 있는 회차를 늘려주고 지원을 확대해 주는 그런 좋은 사례가 있었습니다. 제가 여기서 이런 좋은 사례들은 끊임없이 이어져야 돼서 앞서 제가 질의에서도 말씀을 드렸지만 난임부부들을 지원할 수 있는 예산의 지원 확대 요청을 부탁드리고요. 또 하나가 저는 이 부분을 위해서 경기도 공무원 그리고 경기도 의회사무처 그리고 경기도 공공기관들이 똑같이 난임부부들을 위한 휴가 일수 확대를 위한 조례를 만들고자 합니다. 이 부분에 기획조정실장님께서 조례 제안에 함께 참여해 주실 수 있을지만 여쭙겠습니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 위원님, 기본적으로 위원님 말씀하신 부분은 공감하는데요. 저희가 공공기관의 경우에는, 위원님 지난번에도 말씀 주셨지 않습니까? 그래서 그 부분 관련해서는 공공기관 같은 경우에는 근로기준법상 취업규칙이나 이런 거에서 복무 문제를 다루게 돼 있어서 그 부분은 조금 위원님이랑 논의하는 과정에서 저희가 법적인 부분에 같이 상의드리도록 하겠습니다. 
</p>
<p><b>○ 이경혜 위원 </b> 다른 지자체와 똑같이 그 부분이 연계되지 않게끔, 자율적인 도지사의 권한으로 연계되지 않고 할 수 있는 만큼의 안에서 같이 조례를 제정할 수 있도록 함께 노력해 주시길 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  행정감사 받으시느라고 고생 많으셨고요. 앞으로도, 이게 시작입니다. 결과의 끝을 아직은 본 게 아니니까 감사의 결과를 마무리까지 다시 잘 살펴서 저희 위원들에게 보고해 주시길 부탁드립니다. 수고 많으셨습니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇게 하겠습니다. 
</p>
<p><b>○ 이경혜 위원 </b> 고맙습니다. 이상입니다. 
</p>
<p><b>○ 위원장 조성환 </b> 이경혜 위원님 수고하셨습니다. 경기관광공사 조원용 사장님! 이석하시면 되겠습니다. 고생 많으셨습니다. 
</p>
<p style="padding-left:1.2em">  다음은 이석균 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 이석균 위원 </b> 남양주 이석균입니다. 경기도사회적경제원장님 오셨어요? 
</p>
<p><b>○ 증인 유훈 </b> 네, 왔습니다. 
</p>
<p><b>○ 이석균 위원 </b> 앞으로 좀 나와주실까요? 원장님, 우리 경기도사회적경제원이 언제 생겼죠? 
</p>
<p><b>○ 증인 유훈 </b> 제가 근무를 시작한 것은 22년 12월 27일이고요. 실제로 직원을 뽑은 것은 작년 5월 25일이고 실제 경영은 작년 6월 1일부터 시작했다고 보시면 되겠습니다. 
</p>
<p><b>○ 이석균 위원 </b> 실질적으로 경영평가는 처음 받으신 거죠? 
</p>
<p><b>○ 증인 유훈 </b> 네, 처음 받았습니다. 저희가 아시겠지만 경영평가는 1년 치 경영실적에 대한 평가인데 저희는 조금, 6개월 정도 한 것 가지고 평가를 먼저 받았습니다. 
</p>
<p><b>○ 이석균 위원 </b> 점수는 알고 계신지? 
</p>
<p><b>○ 증인 유훈 </b> 알고 있습니다. 많이 좀……. 
</p>
<p><b>○ 이석균 위원 </b> 제가 오늘 원장님께 좀 이야기드리고 싶은 부분은 무얼 잘했거나 잘못했거나 하기보다는 이제 처음으로 본격적인 궤도에 올라가기 위한 준비작업이 됐다면 이제는 본격적으로 경영혁신이라든지 성과라든지 이런 부분들을 내야 될 부분이어서 제가 오늘 좀 뵙자고 얘기를 했습니다. 
</p>
<p style="padding-left:1.2em">  저는 다른 사업이나 내용에 대해서 말씀드리는 것보다는 경영평가 내용을 가지고 좀 한번 공유를 했으면 좋겠습니다. 점수 중에 이게 받기가 좀, 실적을 내기가 어려웠다 하는 부분은 어느 부분일까요? 
</p>
<p><b>○ 증인 유훈 </b> 저희가 작년도 같은 경우에는 조직 안정화와 사업들에 대한 론칭을 하다 보니까 어려운 부분들이 좀 있었습니다. 아무래도 경영혁신이라든가 이런 부분에 여력이 없었다는 말씀을 드리고요. 그다음에 점수에 보시면 좀 낮은 부분들이, 또 예산의 운영이나 이런 부분들도 이미 보완을 했습니다. 그래서 시스템적인 보완이 필요했었어서 이런 보완도 이미 완료한 상태입니다. 
</p>
<p><b>○ 이석균 위원 </b> 제가 경영평가 결과보고서를 쭉 읽어보니까 제일 눈에 띄는 부분이 기관의 비전과 미션을 우선적으로 확립할 필요가 있다 하는 구절이 눈에 보여요. 
</p>
<p><b>○ 증인 유훈 </b> 네, 있습니다. 
</p>
<p><b>○ 이석균 위원 </b> 이런 부분들을 어떻게 향후에 해 나가실 건지, 물론 지금 미션과 비전이 있으실 거예요. 
</p>
<p><b>○ 증인 유훈 </b> 네, 있습니다. 
</p>
<p><b>○ 이석균 위원 </b> 그런데 경영평가하시는 분들 눈에 보기에는 사회적경제원의 위상에 맞도록 업그레이드되었으면 좋겠다 하는 부분인데 혹시 계획 가지고 계셔요? 
</p>
<p><b>○ 증인 유훈 </b> 저희 지적한 사항에 대해서는 중장기 경영전략을 수립하도록 하고 있고요. 그리고 평가단에서 지적한 내용 중에 가장 중요한 부분들이 내재화되어 있는 부분입니다. 그래서 일방적으로 전략을 만드는 것이 아니라 내부 직원들과의 소통 그리고 또 사회적경제에 굉장히 많은 이해관계자들이 있는데 어떤 이해관계자와의 소통을 통해서 만들도록 하겠습니다. 
</p>
<p><b>○ 이석균 위원 </b> 지금 내부 구성원들과의 소통을 이야기해 주셨는데 먼저 고무적인 부분은 여성관리자 비율이 좀 높다고요? 
</p>
<p><b>○ 증인 유훈 </b> 네, 많이 높습니다. 
</p>
<p><b>○ 이석균 위원 </b> 한 22% 정도 되는데요. 
</p>
<p><b>○ 증인 유훈 </b> 저희 보직자 중에 2명이니까요. 저희 보직자가 많지 않습니다. 많지 않은데 2명이나 있고 남녀 비율은 딱 반반입니다. 저희가 50 대 50입니다. 
</p>
<p><b>○ 이석균 위원 </b> 그리고 좀 말씀드리고 싶은 부분들은 소통과 관련해서 직무분석이 되지 않아서 직무기술서를 표준 직무기술서로 쓰고 있다 하는데 이 부분에 대해서는 기관에 맞도록 좀 정립을 해야 될 텐데 이건 언제까지 하실 예정이세요? 
</p>
<p><b>○ 증인 유훈 </b> 그것도 이미 올해 저희가, 저희랑 비교할 수 있는 기관이 광역에 없습니다, 아시다시피. 그래서 우리나라에 최초로 만들어진 기관이다 보니까 벤치마킹이 아니라 올해 저희가 한 사업들의 내용들을 가지고 전체적인 직무를 좀 더 저희가 세부적으로 자체에서 정의를 했고요. 그것들을 규정에 담는 작업을 또한 내년에 진행하도록 하겠습니다. 
</p>
<p><b>○ 이석균 위원 </b> 혹시 자체적으로 조금 어려우시면 우리 경기연구원에서도 기업 컨설팅 이런 부분들을 하고 있어요. 우리 같은 경기도니까……. 
</p>
<p><b>○ 증인 유훈 </b> 네, 자문을 받도록 하겠습니다. 
</p>
<p><b>○ 이석균 위원 </b> 한번 같이 하셔서 처음부터 제대로. 제가 이 부분을 말씀드리는 이유는 제가 경기도 공공기관들을 전부 이렇게 이번 행정사무감사 기간 동안에 경영평가 자료하고 면담도 하고 다 했는데 대부분의 문제가 뭐냐 하면 내부 소통 그다음에 오래된 기관일수록 서로 간에 단절 이런 문제가 경영에까지 문제가 되는 부분들이 있어서 우리 사회적경제원은 지금 시작하는 부분이니까 처음부터 이런 부분들을 잘 숙지하시고 타 기관들의 도움과 조언을 좀 받으셔서 이런 부분들이 처음부터 생기지 않고 내부 소통이 잘 되어서 경영실적과 대외적인 위상으로 연결될 수 있도록 제가 주문을 드리겠습니다. 
</p>
<p><b>○ 증인 유훈 </b> 너무 좋으신 제언 반영해서 저희가 꼭 명심하고 진행하도록 하겠습니다. 
</p>
<p><b>○ 이석균 위원 </b> 감사합니다. 이상입니다. 
