<p><b>○ 이혜원 위원 </b> 앞서 말씀드린 것처럼 순세계잉여금 비율이 10%가 넘는 기관이 22곳 중에 8곳인데 그중에서 가장 비율이 높은 곳이 수원월드컵경기장이에요. 29%가 높습니다. 이 부분이 제가 전년 23년도 행감과 예산에서도 우리 수원월드컵경기장 대표님께 말씀드렸던 것 같은데 이게 또 발생을 했네요, 23년도에도?
</p>
<p><b>○ 증인 이민주 </b> 네, 답변을 드리겠습니다. 저희 재단이 좀 특징이 있는데요, 다른 공공기관에 비해서. 독립채산제를 운영하고 있다는 특징이 하나 있고요. 그다음에 거대 노후시설이라는 특징이 좀 있습니다. 그래서 코로나 이후에 행사 수요가 많아져서 저희가 수입이 대폭 는 측면이 있고요. 그리고 저희 독립채산제이기 때문에 급박한 일이 생겼을 경우에 도의회나 시의회로부터 지원을 받을 수가 없는 형편이기 때문에 어느 정도 여유자금을 좀 확보해야 될 필요가 있고요.
