<p><b>○ 증인 이민주 </b> 네, 100%.
</p>
<p><b>○ 이혜원 위원 </b> 그럼 순세계잉여금이 계속적으로 늘어나는 부분은 어느 정도의 여유자금을 확보하기 위한 부분인 건데 그러면 여유자금은 어느 정도의 제한을 두고 계신 건가요? 이게 한도 없이 계속적으로 이 부분을 해 놓을 수는 없잖아요.
