<p><b>○ 증인 김민철 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 그 지역화폐 관련해서 어떤 측면에서는 지역화폐를 만들고 그걸 활성화하기 위해서 경상원을 설립하지 않았나 할 정도로 지금 지역화폐에 대한 부분이 많은 부분을 차지하고 있고요. 그리고 24년도 경상원 관련해서 출연금을 보니까 이게 매년 출연금에 대한 부분들도 23년도보다는 지금 24년도에 출연금이 330억 2,400만 원 정도 있습니다. 순세계잉여금 관련해서 계속적으로 말씀을 드렸었는데 경상원 같은 경우도 집행률은 70%대예요. 그런데 순세계잉여금은 예산 대비해서 20% 정도 됩니다. 그리고 21년에서 22년 증가율은 3.14%였는데 22년에서 23년 증가율이 47.19%나 돼요. 이거 확인을 못 하셨겠죠, 원장님? 
</p>
<p><b>○ 증인 김민철 </b> 아니, 이런 것 같습니다. 먼저 두 가지 질문해 주셨는데요. 그 지역화폐 관련돼서는 저희 경상원에서는 홈페이지 유지ㆍ관리ㆍ등록 정도만 저희 기관에서 지금 현재 하고 있습니다. 그리고 순세계잉여금 같은 경우는 사실 기관 설립된 지 5년 또 이전하다 보니까 여러 가지 애로사항들이 많이 있고 또 대부분 인건비나 사업비가 조금 이렇게 많이 잉여금으로 남긴 부분이 있습니다. 그래서 올해도 우리 경상원 직원들이 9월 말 기준으로 11명 정도 비어 있다 보니까 그 인건비 예산 그리고 일반 경비 예산 그리고 사업비 예산이 약 한, 사업정리지원금이 한 15억 정도 이렇게 되는 것 같습니다. 그래서 내년부터는 이런 부분…….
