<p><b>○ 이혜원 위원 </b> 경기도 공공기관담당관님, 혹시 우리 공공기관에 제가 알기로는 한 여섯 곳 정도는 있는 것으로 아는데 맞나요? 없는 곳도 있는 것 같은데. 답변 안 하셔도 됩니다. 앉으십시오. 
</p>
<p style="padding-left:1.2em">  그래서 경상원이 22년 조신 원장 취임 직후인 12월에 조직개편을 통해서 없었던 대외협력관 자리를 신설했어요. 근데 이 부분이 거의 2급 상당 전문계약직이고 그리고 연봉이 세전 6,500만 원 정도 수준이라고 파악을 하고 있습니다. 근데 조신 원장 대선 당시 이재명 선대위의 민생정책특보단 단장 직책이 좀 있었던 걸로 파악이 되고 있고 처음에 23년도 3월 7일에 첫 공고를 했는데 적격자가 없었다고 판단을 했다고 하고요. 그리고 두 번째 4월 21일 재공고했을 때 1명이 선발됐습니다. 그런데 그 선발된, 합격한 그 대외협력관이 과거 이재명 민주당 대표 수행한 이재명 대표 측근의 친동생이라고 하는데 혹시 확인되실까요?
</p>
<p><b>○ 증인 김민철 </b> 제가 아직 정확한 확인은 하지 못했습니다. 그런데 들어와서 이제 그런 말씀들을 듣고 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 들으셨습니까? 
</p>
<p><b>○ 증인 김민철 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 제가 확인한 거 좀 말씀드릴게요. 형 김 씨가 이재명 성남지사였던 2014년 수행비서로 활동을 했고 이재명 도지사 시절 의전비서로 활동을 했고 대선캠프에서도 활동을 했고 당대표 취임 이후에 민주당 국장급 당직자로도 채용이 됐다라고 합니다. 그래서 그 형 김 씨는 이재명 재판의 핵심인 고(故) 성남 개발공사 김문기 처장을 몰랐다는 허위사실 공표 혐의 재판 관련해서 2015년 호주 뉴질랜드 출장도 함께 동행했다고 하는데 문제는 이재명 최측근의 친동생이 없던 직위를 신설했는데 거기에 채용이 돼서 특혜 채용의 의혹을 받고 있습니다. 그래서 그런 부분들이 지속적으로 얘기가 나오고 있고 23년도 경노위 행감에서도 이 부분이 지적됐습니다. 그런데 거기에 어떤 명확한 답변을 듣지를 못했어요. 그래서 제가 요구하겠습니다. 어차피 원장님도 지금 다 파악을 못 하셨을 테니까 실제 당시 채용 당사자들의 채점기준이나 채점표 그리고 공모 당시의 서류 이런 부분들을 종합적으로 살펴볼 필요가 있다. 이제 종지부를 찍어야 될 것 같으니까요. 그 자료를 세부적으로 제출을 하셔서 내용 파악할 수 있도록 해 주시면 좋겠습니다. 
</p>
<p><b>○ 증인 김민철 </b> 네, 알겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그리고 또 하나, 보통 1년마다 직원들의 업무평가를 하게 되거든요. 근데 대외협력관의 경우 업무평가 기준이 어떻게 되는지 그리고 대외협력관의 지난 1년 업무평가에 대한 상세 내용을 혹시 들으신 적이 있나요? 업무평가가 어떻다. 
</p>
<p><b>○ 증인 김민철 </b> 세부적으로는 아직 듣지 못했습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 그러면 대외협력관 취임 이후에 현재까지 성과에 대한 부분이나, 저는 이분을 본 적이 없어서. 여기 지금 경상원 홈페이지 보면 대외협력관에 대한 업무가 경기도, 경기도의회, 유관기관, 언론 대응 및 대외협력 이렇게 돼 있습니다. 그래서 경기도의회에도 같이 협력해야 되는 부분들이 있거든요. 그런데 저는 이분 얼굴을 본 적이 없어요. 어떤 형태로 우리와 소통을 하시는지 잘 모르겠는데 그 업무가 주요업무이신 것 같은데 그런 부분들이 세세히 나타나지 않아서 그런 부분들에 대한 걸 확인을 해야 될 것 같습니다. 
</p>
<p style="padding-left:1.2em">  여러 가지가 있는데 시간이 좀 지나서 제가 추가질의 다시 하도록 하겠습니다. 이상입니다. 
</p>
<p><b>○ 증인 김민철 </b> 네, 알겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 이혜원 위원님 수고하셨습니다. 김민철 원장님은 이석하셔도 좋습니다. 
</p>
<p style="padding-left:1.2em">  그리고 추가적인 부분은 서면으로 질의해 주시고 서면으로 답변을 부탁드릴게요. 이석하셔도 좋습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 위원장님, 저는 질문하고 답변을 받아야 되는데……. 
</p>
<p><b>○ 위원장 조성환 </b> 시간이 지금 다 됐습니다. 위원님 지금 시간을 충분히……. 
</p>
<p><b>○ 이혜원 위원 </b> 추가질의까지 있지 않습니까? 
</p>
<p><b>○ 위원장 조성환 </b> 보충질의까지만 공공기관장님들은 아까 하기로 제가 설명을 드렸기 때문에 그래서 지금 이어서 발언을 하시도록 한 번 더 기회를 드린 거거든요. 
</p>
<p><b>○ 이혜원 위원 </b> 의사진행발언 요청하겠습니다. 위원장님, 추가질의는 위원의 고유권한이고 추가질의에 대한 부분은 몇 건이 있어도 추가질의할 수 있는 겁니다.  
</p>
<p><b>○ 위원장 조성환 </b> 추가질의하셔도 좋은데 공공기관장들에 대해서는 보충질의 시간에 저희가 마무리를 하기로 했고 그리고 한 번……. 
</p>
<p><b>○ 이혜원 위원 </b> 저는 그 부분에 대해서 협의한 적이 없습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 아니, 아니요. 아까 그렇게 얘기했습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 보충질의에 대한 부분만 협의를 했고요. 
</p>
<p><b>○ 위원장 조성환 </b> 그렇게 했습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 추가질의에 대한 부분은 협의를 하지 않았습니다. 그 부분은 별도로 그럼 정회를 신청하고요. 정회 후에 다시 한번 확인해 주시고 진행해 주셨으면 좋겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 네, 그거는 그렇게 하시면 되겠고요. 원장님은 이석하십시오. 
</p>
<p style="padding-left:1.2em">  지금 정회 요청이 들어왔는데 이채명 위원님이 본질의를 못 하셨어요. 
</p>
<p><b>○ 이채명 위원 </b> 본질의 아예 못 했습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 그래서 본질의까지 하고. 
</p>
<p><b>○ 이채명 위원 </b> 계속 보충질의, 추가질의할 때까지 기다렸습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 네, 그래서 본질의를 하시고 그리고 정회하고 협의하도록 하겠습니다. 이채명 위원님 질의해 주십시오. 
</p>
<p><b>○ 이채명 위원 </b> 그동안 행감을 위해서 수고하신 우리 기조실장님 이하 모든 공직자분들 너무 고생 많으셨다는 말씀드리면서 지금부터 질의 들어가겠습니다. 
</p>
<p style="padding-left:1.2em">  기조실장님께 먼저 질의드리겠습니다. 실장님! 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 기획조정실장 이희준입니다. 
</p>
<p><b>○ 이채명 위원 </b> 집행부가 예산을 편성하는 데 우리 경기도 예산 편성 지침을 준수하지 않아도 문제가 없다고 생각하시는지요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 예산 편성 지침을 준수하는 것이 맞습니다. 
</p>
<p><b>○ 이채명 위원 </b> 그렇죠. 그럼 만약에 위반했다면 어떤 조치가 이루어지시죠? 짧게 답변해 주세요. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 위반했다면 저희가 예산 편성 과정에서 드러난다면 조정을 하고요. 통상 그렇게 하고 있습니다. 
</p>
<p><b>○ 이채명 위원 </b> 알겠습니다. 예산을 수립할 때 근거가 되는 것이 조례이죠? 그렇죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이채명 위원 </b> 경기도 조례를 위반해서 예산을 편성했다면 이것 또한 어떻게 되는 거죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 그것도 예산 편성 과정에서 드러나게 된다면 조정을 하게 됩니다. 
</p>
<p><b>○ 이채명 위원 </b> 또 세 번째, 집행부가 각종 위원회를 설치할 때 그리고 이 위원회 운영을 위한 수당 및 그리고 여비 등을 지급할 때 역시 기준이 되는 조례가 저는 있다고 알고 있습니다. 맞죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 있습니다. 
</p>
<p><b>○ 이채명 위원 </b> 이 조례에 따라서 설치되지 않은 위원회는 당연히 수당 등의 지급이 집행부 예산으로 편성되거나 집행될 수 없는 것이 맞죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 위원님, 아까 말씀하신 그 조례……. 
</p>
<p><b>○ 이채명 위원 </b> 제가 말씀드린 것은 평화협력국에서 만들어 놓은 DMZ 오픈 페스티벌 조직위원회 운영 규정을 말씀드리는 겁니다. 알고 계시죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 운영 규정, 알고 있습니다. 
</p>
<p><b>○ 이채명 위원 </b> 이게 조례입니까, 아니면 내부 규정 방침 정도로 이해하면 되겠습니까? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 그 부분에 대해서는 제가 정확하게는, 평화협력국 업무 소관이라서요. 제가 그……. 
</p>
<p><b>○ 이채명 위원 </b> 일단은 평화협력국 업무 소관이긴 하지만 이게 사실은 모든 우리 각 부서마다에 공통적으로 저는 적용된다고 보고 있고요. 한번 살펴서 답을 주시기 바랍니다. 또 제가 평화협력국에 질의를 했었지만 답변을 받지 못했던 게 뭐가 있냐면 캠프그리브스 유스호스텔 같은 경우 운영 관련된 예산을 우리 경기도 평화협력국에서 공기관 대행사업으로 추진하면서 관리직 인건비를 반영하지 않고 있어요. 이것을 경기관광공사가 출연금으로 인건비를 지금 반영시켜서 운영하고 있는 것은 제가 2025년 경기도 예산 편성 지침을 위반했다라고 말씀을 드렸고요. 그리고 경기도 조례를 위반했다고 말씀을 드렸습니다. 제가 평화협력국에 말씀드린 이 부분도 한번 검토를 해 보시고요. 
</p>
<p style="padding-left:1.2em">  그럼 감사위원장님께 질의드리겠습니다. 앞서 제가 질의한 내용에 대해서 조례나 예산 편성 지침에 근거하지 않고 이렇게 수년간 지속해서 캠프그리브스 체험관 운영과 관련돼서 문제가 없는지 살펴볼 필요가 있고요. 특히나 명확한 검토를 우리 감사위원회에서 해 봐 주시는 것이 저는 객관적일 수 있다라고 생각이 되는데 이 부분에 간단하게 답을 주시고요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 
</p>
<p><b>○ 이채명 위원 </b> 그리고 DMZ 오픈 페스티벌 조례에 근거하지 않고 진행된 부분이 지금 있습니다. 그거는 조직 내부 규정을 운영하면서 지금 운영을 하고 있는데 이 부분에 대해서도 해당 부서에 맡기지 마시고요. 정상적이지 않게 진행된 점이 없는지를 한번 살펴보시기를 감사위원장님께 제가 요청드리도록 하겠습니다. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 한번 살펴보겠습니다. 다만 검토와 관련해서는 사전 컨설팅이나 이렇게 형식이 있습니다. 그런 절차를 통해서 올라오면 살펴보도록 하겠습니다. 
</p>
<p><b>○ 이채명 위원 </b> 네, 알겠습니다. 그리고 저번에 제가 공용차량 관련해서 경기아트센터 질의드렸을 때 일단 향후 계획에 어떻게 저한테 답변을 주셨냐면 전용차량의 출퇴근 이용에 대한 이해충돌방지법 위반 여부에 대해서는 추가 검토하시겠다고 말씀을 주셨고 그리고 나머지 공용차량 전반에 걸쳐서 공공기관 28개 기관에 대해서 특정감사 추진 검토 이렇게 답변 주셨습니다. 맞습니까? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다. 서면보고드린 바와 같이 여러 가지 관련 규정을 살펴봤더니 위원님이 지적하신 바와 같이 일부 공용차량 운영 규정에 출퇴근이 적시되지 않은 부분도 많이 있고 각 공공기관마다 다 다르고 그래서 이번에 한번 전반적인 공공기관 실태를 파악해 보고요. 특정감사와 관련해서 추진할 수 있도록 해 보겠습니다. 
</p>
<p><b>○ 이채명 위원 </b> 알겠습니다. 그리고 경기아트센터 서춘기 대표님 잠깐 발언대로 나와주시면 고맙겠습니다. 
</p>
<p><b>○ 증인 서춘기 </b> 경기아트센터 사장 서춘기입니다. 
</p>
<p><b>○ 이채명 위원 </b> 경기아트센터에 대해서는 제가 공공기관담당관님과 그동안에 많은 질의 답변 속에서 지적 아닌 지적을 드렸고요. 한 가지 저는 정책적인 면에서 대표님께 질의드려보도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  경기예술방송국이, 제가 참고로 우리 평화협력국의 오픈 페스티벌 관련해서도 영상송출이 DMZ 오픈 페스티벌 영상송출인데 어떤 것은 조회수가 100단위고 어떤 것은 한 10만 정도 단위가 된 게 있었습니다. 경기예술방송국 같은 경우도 보니까요, 2020년 10월 코로나 시절에 예술인 지원사업으로 시작해서 보니까 본격적으로 연간 한 15억 정도 출연금을 받아서 취약계층과 예술인들의 영상제작과 방송국 운영에 지금 사용했었습니다. 
</p>
<p><b>○ 증인 서춘기 </b> 네, 맞습니다. 
