<p style="padding-left:1.2em">  앞서 우리 양우식 위원님께서 자료요구를 했었지만 그 주신 내용 안에 지금 현재 경기아트센터의 모든 사업들이 기존에 수의계약으로 체결된 것들 98%를 지금 현재 감사실장이 가시면서 95%까지 많이 낮췄다라고 하셨는데 어느 정도 선에서 이렇게 모든 사업들이 수의계약이 이루어지고 있는지 그 부분에 대해서 간단하게 언급 좀 해 주시면 좋겠습니다. 
