<p><b>○ 증인 한지양 </b> 저희가 공연장이기 때문에 수의계약을 할 수 있는 재량이 굉장히 큽니다. 그렇다 하더라도 입찰로 할 수 있는 부분이 굉장히 많고 그다음에 제가 실제로 일상감사를 하면서 가격이 고무줄처럼 늘어났다 줄었다 하는 사례를 너무 많이 보았기 때문에 이런 계약을 어느 정도 상식적인 선에서 이루어지게 하려고 정말 많이 노력했습니다. 그런데 이 모든 게 갑질이 되고 그다음에 있으면 불편한 존재로 해서 정말 왕따 아닌 왕따 생활을 2년간 했습니다. 그런데 이것을 고쳐주셔야 될 분들이 도 집행부시고요, 의원님들이세요. 제가 정말 갑질을 해서 그랬다면 저는 당연히, 감사부서장으로서 갑질을 했다면 제가 처벌을 받아야 된다고 생각하는데 그 대신에……. 
</p>
<p><b>○ 이채명 위원 </b> 잠깐만요, 실장님. 제가 묻는 말에 간단하게만 답을 주시고요. 사실은 제가 시간이 얼마 남지 않은 관계로 인해서, 저도 사실은 많은 지금 제보를 받고 있는데요. 저희 도의원들이 직접 방문을 해서라도 양쪽의 얘기를 사실 다 들어봐야 될 것 같다는 생각이 드는데 제보된 사안에 대해서 저희가 면밀하게 조사를 하고 그리고 판단을 해야 될 거다라고 생각합니다. 그래서 이 부분에 대해서는 예를 들어서 모든 명확한 사실관계를 바탕으로 해서 저희가 질의 답변을 해야 되지 않나라는 생각이 들어서 제가 앞서 자료요청한 수의계약 건수라든가 이런 걸 정확한 자료를 저에게 주시면 그 이후에 다시 제가 추가질문하는 걸로 하겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 이채명 위원님 수고하셨습니다. 
</p>
<p style="padding-left:1.2em">  이렇게 해서 우리 보충질의 박상현 위원님 남으셨고 또 지금…….
</p>
<p><b>○ 이석균 위원 </b> 잠깐만요, 위원장님? 
</p>
<p><b>○ 위원장 조성환 </b> 발언이 있으신데…….
</p>
<p><b>○ 이석균 위원 </b> 의사진행발언 좀…….
</p>
<p><b>○ 위원장 조성환 </b> 지금 정회 요청이 들어온 게 있어서 정회를 좀 했으면 하는데.
</p>
<p><b>○ 이석균 위원 </b> 네. 정회를 요청합니다.
</p>
<p><b>○ 위원장 조성환 </b> 네. 정회를 하고 그다음에 정리를 하고 회의를 속개하면 좋겠습니다. 16시 30분까지 감사중지를 선포합니다. 
</p>
<p class=''ar''>(15시54분 감사중지)
</p>
<p class=''ar''>(16시30분 감사계속)
</p>
<p><b>○ 위원장 조성환 </b> 의석을 정돈하여 주시기 바랍니다. 성원이 되었으므로 감사를 속개하겠습니다. 
</p>
<p style="padding-left:1.2em">  박상현 위원님 보충질의해 주시기 바랍니다.
</p>
<p><b>○ 박상현 위원 </b> 부천 오쇠리 출신 박상현입니다. 기조실장님, 아까 확인해 보셨나요, 장애인표준사업장이 중앙부처 어느 소속 소관의 부서인지?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 고용노동부의 장애인노동과 소관이었습니다.
</p>
<p><b>○ 박상현 위원 </b> 그럼 확인하셨죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 박상현 위원 </b> 보건복지부가 아니라 분명히 고용노동부였습니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 확인했습니다. 
</p>
<p><b>○ 박상현 위원 </b> 그것에 대해서 적절한 조치 부탁드리겠습니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 그 해당 부서랑, 관련 부서랑 협의토록 하겠습니다.
</p>
<p><b>○ 박상현 위원 </b> 네. 이어서 질의를 좀 하겠습니다. 기조실장님, 현재 공공기관담당관에서 공공기관을 평가할 때 평가지표가 혹시 몇 개인지 아시나요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 48개 지표입니다.
</p>
<p><b>○ 박상현 위원 </b> 세부지표까지 하면 몇 개인지 혹시 아시나요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 492개입니다.
</p>
<p><b>○ 박상현 위원 </b> 492개의 지표를 가지고 공공기관을 평가하게 됩니다. 그래서 저희가 매번 공공기관에 관련된 시정 요청사항이 있었는데 크게 두 가지였습니다, 제 기억으로는요. 하나는 순세계잉여금, 불용액이 너무 많아서 그 불용액에 대한 조치를 가급적이면 했으면 좋겠다라는 것이 하나 있었고, 두 번째는 장애인 생산품에 관련된 구매 비율이 낮아서 최소한 법적 요건을 조금 준수해 달라고 요청했던 적이 많이 있었습니다. 기억나시죠, 그것도?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 
</p>
<p><b>○ 박상현 위원 </b> 그런데 최근에 제가 공공기관담당관을 통해서 장애인표준사업장 전시회에 관련돼서 참여를 독려해 달라고 하는 요청을 조금 드렸었어요. 그래서 몇 개 기관이, 정말 공공기관담당관을 통해서 몇 개 기관이 참여했는지에 대해서 리스트를 좀 만들어달라고 했는데 총 28개의 기관 중에서 참석한 기관이 12군데입니다. 무슨 말이냐 하면 경기도청 공공기관담당관에서 공공기관에다가 가급적 좋은 취지로 장애인표준사업장 관련된 전시회에 와서 한 번쯤 돌아보고 거기에서 나오는 많은 실제적인 얘기도 듣고 하려고 요청을 드렸는데 실제로 28개 기관에서 12개 기관만이 참석을 했어요. 이거에 대해서 어떻게 생각하세요, 기조실장님?
</p>
<p><b>○ 기획조정실장 이희준 </b> 나름 사정이 있을 수 있겠지만 좀 아쉽게 생각합니다.
</p>
<p><b>○ 박상현 위원 </b> 네, 그렇다고 생각하시죠? 사실 공공기관담당관이 지금 하고 있는 업무를 보면 공공기관에 관련된 운영기본계획에 관련돼서 사전에 협의를 하거나 그다음에 공공기관 평가에 관련된 평가기준을 만들어서 평가를 하거나 그거 이외에 많이 얘기 나오는 정원이라든지 규정을 바꾼다든지 이런 많은 일들을 하고 있는데 실제로 공공기관담당관의 요청사항을 공공기관이 어떻게 보면 좀 막말로 얘기해서는 조금 말을 안 듣는 거잖아요. 요청사항에 대해서 협조가 잘 안 된다고 볼 수 있는 거죠. 기조실장님?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 좀 아쉽게 생각합니다.
</p>
<p><b>○ 박상현 위원 </b> 저도 대단히 아쉽게 생각합니다. 그래서 이것에 대해서 조금만 더 짚고 넘어가겠습니다. 실제로 공공기관 평가지표가 492개라는 것이 조금 많다고 생각되지는 않으신가요, 혹시?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 492개 적지 않은 지표인 것 같습니다.
</p>
<p><b>○ 박상현 위원 </b> 그리고 실제로 경기도청이나 도청에 의한 공공기관담당관의 요청이나 또는 경기도의회에서 행정감사 때 지적된 사항에 대해서 시정ㆍ후속 조치를 분명 하게끔 그런 업무분장이 명확히 되어 있음에도 불구하고 시정하지 않았을 시에 우리 공공기관담당이 할 수 있는 조치는 혹시 무엇이 있을까요? 없으시죠? 그러면 실질적으로 이런 평가를 아무리 많이 한다고 한들 그 평가지표는 유명무실해질 경우가 많겠네요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 나름대로 ESG가 됐든 혁신이 됐든 그런 기준들에 따라 평가를 하는데요. 지금 말씀하신 부분은 저희가 총괄적으로 적용할 수 있는 그런 부분이 필요하다고 생각합니다.
</p>
<p><b>○ 박상현 위원 </b> 일단 그 평가지표에 대해서 어떻게 개선할지는 잘 모르겠으나 최소한 경기도의회에서 시정한 요청사항 그다음에 경기도 공공담당관이 경기도 공공기관에게 협조에 관련된 요청을 했을 시 좀 더 적극적으로 협조할 수 있게끔, 이런 아쉽다라는 표현이 안 나오게끔 할 수 있는 평가지표를 명확히 반영하여서 좀 큰 포션으로, 492개에서 493개로 늘리는 것이 아니라 한번 적절하게 평가지표를 잘 부탁드리고요. 
</p>
<p style="padding-left:2.4em">    (타임 벨 울림) 
</p>
<p style="padding-left:1.2em">  (위원장석을 향하여) 저 1분만 더 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  장애인표준사업장 및 장애인기업에 관련된 우선구매 비율에 대해서 최근에 제가 그 전시회에 가서, 현장에 가서 확인해 봤을 때 최근 경기도교육청에서 빠른 시일 안에 장애인표준사업장과 40여 개의 경기도청 산하 기관이 계약을 했다고 어떻게 보면 아름다운 멘트를 축사에 해 주시더라고요. 경기도교육청의 담당관은 윤향선 주무관이시고 그 주무관 한 분이 신경을 썼느냐 안 썼느냐에 따라서 1년 동안 적체되어 있던 공공기관, 경기도교육청 산하 공공기관인 40여 개 기관이 한꺼번에 그 계약에 참여할 수 있게 되었다고 들었습니다. 이 부분에 대해서는 경기도교육청 윤향선 주무관과 충분히 협의를 거쳐서 어떠한 절차에 의해서 어떻게 그렇게 빠르게 많은 실적을 이뤄낼 수 있었는지 그 절차를 꼭 한 번쯤 확인하셔서 우리 경기도청 산하의 28개 공공기관들도 이런 장애인 물품에 관련된 구매를 좀 적극적으로 할 수 있게끔 조치 부탁드리겠습니다.
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 교육청과 협의해서 그렇게 하도록 하겠습니다.
</p>
<p><b>○ 박상현 위원 </b> 네, 감사합니다.
</p>
<p style="padding-left:2.4em">    (조성환 위원장, 이경혜 부위원장과 사회교대)
</p>
<p><b>○ 부위원장 이경혜 </b> 박상현 위원님, 다 마무리하신 건가요? 
</p>
<p><b>○ 박상현 위원 </b> 네, 마무리했습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 수고하셨습니다. 다음 추가질의하실 위원님? 이혜원 부위원장님 질의하십시오.
</p>
<p><b>○ 이혜원 위원 </b> 이혜원 위원입니다. 공공기관담당관과 감사위원장님이 좀 들어주셨으면 좋겠습니다. 감사위원회에서 경상원 설립이 2019년 9월이었는데 감사가 없다가 9월부터 23년 10월까지 업무에 대한 감사를 실시했고 2024년 2월에 감사보고서가, 결과보고서가 나왔어요. 내용 파악하고 계시죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇게 알고 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 18개 지적이 된 걸로 알고 있는데 자세히 내용을 보면 직장 내 괴롭힘이나 채용 결격사유 미확인으로 인해서 최종 합격처리를 한 건이 있었어요. 이거 몇 년도 정도에 발생한 사건인지 알고 계십니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 이 관련해서는 양해해 주시면 담당 과장을 통해서 답변…….
</p>
<p><b>○ 이혜원 위원 </b> 시간이 많지 않으니까, 지금 추가질의 5분 안에 답변을 들어야 돼서. 해당 건이 몇 년도에 발생한 사건인지 또 해당 건이 감사에서 적발된 경위 그리고 부서장 A의 실제 내부 조치 징계가 어떻게 결론이 났는지. 조치 결과는 하셨는데 이후 조치 후의 조치상황이 어떻게 되는지 현재 상황을 확인해서 제출해 주시고요. 피해자와 가해자의 분리 조치가 잘 되었는지 피해자에 대한 기관의 배려가 어떤 것이 있었는지 정리해서 주시고요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 그중에서 가장 심각했었던 게 비리퇴사 임원이 성과급 부적정 돼서 환수 조치 내리신 거 기억나십니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 아마 기재되어 있으면, 환수 조치 시정이 내려진 걸로 알고 있습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 이분이 계속적으로 경무관 출신이기도 했었고 금품수수 혐의도 있어서 2년 6개월 선고받으셨던 전력도 있고 코나아이 해외법인장 경력을 갖고 있는데 여기 경상원에 채용이 돼서 또 이 지역화폐 관련해서 업무에 대한 부분들을 좀 갖고 있어서 이해충돌에 문제가 있다라는 부분 내용들도 있었고요. 그러고 나서 한 1년 뒤에 2021년 11월에 카페에서 음료 배달을 거부당하고 카페에 행패 부리고 난동을 부려서 영업을 방해한 혐의로 직위해제가 되었습니다. 그렇죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 그랬는데 소상공인을 위해야 되고 소상공인의 발전을 기해야 되는 분이 피해를 끼친 사안이 또 심각한 사안임에도 불구하고 경상원에서 성과급 그때 672만 원 정도를 지급했어요. 그거 환수 조치하라고 시정명령 내리셨는데 지금 환수 조치 확인하셨습니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 위원님, 정확하게 확인해서 아까 앞서 지적하신 부분들과 같이 해서 답변…….
</p>
<p><b>○ 이혜원 위원 </b> 이거 조치 결과보고 안 받으셨어요? 시정 조치하시면 시정에 대한 결과 확인을 하셔야 되는 거잖아요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 확인하셔서 답변 다시 해 주시고요.
