<p><b>○ 감사위원장 안상섭 </b> 앞서 질문하신 부분들과 관련해서 서면으로 답변드리도록 하겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 네. 아까 이사회 관련해서 제가 자료는 봤는데 비공개자료여서 보기만 하고 내용보고만 들었거든요. 그런데 거기 보면 정당인 출신들도 있었고 일부 정치 편향적인 인사들도 있고 한데 이게 이재명 전 지사 때나 김동연 측근 자리 나눠주기식에 대한 자리인 건지 그 이사회에 관련된 부분들 전반적으로 다시 한번 검토해서 제출해 주시기 바랍니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 방금 질의하신 건 경상원 말씀하신…….
</p>
<p><b>○ 이혜원 위원 </b> 네, 경상원. 현재 다 경상원이에요. 
