<p><b>○ 감사위원장 안상섭 </b> 그 지적하신 부분…….
</p>
<p><b>○ 이혜원 위원 </b> 다 이해하셨죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 지적하신 부분 살펴서 보고드리도록 하겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 네. 서춘기 사장님 계십니까? 
</p>
<p><b>○ 증인 서춘기 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 경기아트센터 감사실장님과 같이 답변해 주시고요. 먼저…….
</p>
<p><b>○ 증인 서춘기 </b> 아트센터사장 서춘기입니다.
</p>
<p><b>○ 이혜원 위원 </b> 사장님, 제가 23년도 행정사무감사 때 어떤 지적들을 했는지 혹시 기억이 나십니까? 그때도 사장님이 답변이 제대로 이행이 안 돼서 감사실장한테 답변요구를 했었고요. 그때 제가 속기록을 보니까 지금 개인적인 판단으로 본인은 감사를 시행하고 있다라고 답변을 하셨어요, 감사실장님이. 감사실장님, 기억나세요? 감사실 운영을 어떻게 하냐고 물어봤을 때 내 판단에 의해서 한다라고 답변하셨어요. 속기록에 남아 있습니다.
</p>
<p><b>○ 증인 한지양 </b> 네, 기억납니다.
</p>
<p><b>○ 이혜원 위원 </b> 그래서 제가 이게 규정이나 근거에 의해서 감사에 대한 부분이나 절차를 이행해서 진행을 해야지 개인적인 판단에 의해서 하는 건 맞지 않다라고 말씀을 드렸고 그랬더니 그 내용에 대한 부분들을 의견 달아서 제출해 달라고 했어요. 16건이었어요, 그때 진행하고 있었다는 거. 1년이 지났는데 아무것도 안 주셨어요, 본인이 제출하겠다고 약속하셨는데. 이사회에 승인받아서 제출하겠다고 하셨는데. 사장님, 이거에 대해서 보고받으신 적 있습니까?
</p>
<p><b>○ 증인 서춘기 </b> 죄송하지만 제가 기억이 잘 나지를 않습니다.
</p>
<p><b>○ 이혜원 위원 </b> 기억이 안 나실 이유가 없는데요.
</p>
<p><b>○ 증인 서춘기 </b> 제출 16건은, 위원님 말씀하신 건 제가 기억나고요. 그 제출 여부에 대해서는…….
</p>
<p><b>○ 이혜원 위원 </b> 감사실장이 사장님께 보고한 내용이 있으십니까?
</p>
<p><b>○ 증인 서춘기 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 보고하셨습니까?
</p>
<p><b>○ 증인 서춘기 </b> 네. 16건에 대해서는 제가 보고…….
</p>
<p><b>○ 이혜원 위원 </b> 아니, 16건 말고요. 작년도 행정사무감사 때 그 내용을 보완해서 본인이 개인의 판단으로 가부를 결정한다고 하셨기 때문에 개인 의견을 달아서, 16건에 대해서 절차 무시하고 개인 의견으로 판단해서 하신다 그래서 개인 의견 달아서 제가 제출해 달라고 했고요. 사장님 결재받고 이사회 승인받고 제출해 달라고 했고 답변을 하셨습니다. 근데 아직까지 답변이 없으세요, 제출도 안 됐고.
</p>
<p><b>○ 증인 서춘기 </b> 제가 바로 제출하도록 하겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 감사실장님, 왜 안 하셨습니까? 사장님도 지금 보고받으신 적 없으시다는데. 왜 본인은, 지금 저한테도 문자 주셨잖아요?
</p>
<p><b>○ 증인 한지양 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 억울하다라는 표현이십니다, 모든 내용이. 본인은 다 억울하십니까?
</p>
<p><b>○ 증인 한지양 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 그럼 다 억울한, 소명 근거자료 제출하셨어요? 아까 자료요구했는데, 아침에.
</p>
<p><b>○ 증인 한지양 </b> 제가 감사부서장이기 때문에 감사 관련 법률과 규정에 의해서 아까 우리 위원님이 말씀하신 것처럼 규정과 어떤 감사계획에 근거하지 않고 어떤 자료를 제시하는 것은 규정 위반이라고 생각이 듭니다. 그래서 제가 말씀드리는 것은…….
</p>
<p><b>○ 이혜원 위원 </b> 그러면 실장님, 본인의 잘못은 인정을 하고 본인도 잘못했으니 우리 직원들 잘못도 있는데 이런 부분들에 대해서 어떻게 해결방안을 찾아갈지 그 부분에 대한 해결방안 모색하시는 게 목적이라고 하지 않으셨어요? 근데 1년 동안 바뀐 게 뭡니까? 감사에서는 직원들 감사대상에 대한 부분들에 대해서 제대로 감사위원회에서 소명 안 된 내용들도 많고. 지금 감사위원회에 행정사무조사해야 될 판이에요, 제대로 절차가 이행이 됐는지. 그때 제가 행정사무감사하면서 지역아트센터의 감사실에 대한 감사실 감사를 요구했는데 감사실장에 대한 부분은 거의 없어요, 제보는 있다는데. 왜 이런 걸까요? 그러면 지금 감사위원회도 절차는 진행했는데 내용이 없다 그러고 제보한 거는 있고 감사실장님은 본인 잘못은 없고 다른 사람 잘못이, 다 다른 사람이 잘못했다고 답변을 하시니 그러면 결정적으로 소명을 듣기 위해서는 저희가 행정사무조사를 해야 할 수밖에 없는 거지 않습니까? 절차상으로는 맞죠, 사장님?
</p>
<p><b>○ 증인 서춘기 </b> 저희가 더 확인하겠습니다.
</p>
<p><b>○ 증인 한지양 </b> 제가 답변드려도…….
</p>
<p><b>○ 이혜원 위원 </b> 추가질의하도록 하겠습니다. 답변드린 적이 없습니다, 기회를.
</p>
<p><b>○ 증인 한지양 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 사장님 들어가셔도 좋습니다. 추가질의할 때 다시 요구하겠습니다. 이상입니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 이혜원 부위원장님 수고하셨습니다. 다음 추가질의하실 위원님 계십니까? 박진영 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 박진영 위원 </b> 이경혜 위원장님, 추가질의는 시간제한이 없는 거죠?
</p>
<p><b>○ 부위원장 이경혜 </b> 일단은 추가질의는 다 원하시면 계속해 드리기는 할 건데 시간은 5분을 먼저 사용하시고 이후에 또 추가로 하거나 그렇게 진행하겠습니다. 다른 위원님들과 고르게 하겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 네, 간결하게 최대한 하겠습니다. 서춘기 사장님, 잠시만 나와주시겠습니까?
</p>
<p><b>○ 증인 서춘기 </b> 경기아트센터 사장 서춘기입니다.
</p>
<p><b>○ 박진영 위원 </b> 제가 다른 상임위로 상임위가 바뀐 이후로 여기 와서 자꾸 아트센터에 대해서 이런저런 얘기를 하는 게 좀 저 자신도 되게 자괴감이 들긴 합니다. 근데 작년에 문화체육관광위원회에서는 저를 비롯한 모든 위원님들이 충분히 내용을 설명하셨고, 본인들이 제보받은 내용을 설명하셨고 그게 올바르고 공정하게 처리되어서 반영되어 있을 거라고 생각했습니다, 올해 종합감사 결과를 보기 전까지요. 
</p>
<p style="padding-left:1.2em">  올해 감사실에서 이례적으로 원래는 3년만 하도록 되어 있는 게 2년 만에 종합감사를 아트센터에 했습니다. 작년에 행감을 했던 위원으로서는 당연히 작년에 여러 위원님들이 여러 가지 제보받은 내용들을 공개적으로 제시했으니까 그 부분에 대한 감사가 주로 이루어질 거라고 생각했는데 올해 종합감사 결과를 보면 그 부분에 대한 내용은 하나도 있지 않습니다. 사장님, 어떻게 생각하십니까?
</p>
<p><b>○ 증인 서춘기 </b> 감사는 경기도 감사실에서 한 걸로 제가 알고 있습니다. 그 부분에 대해서 제가 관여할 수 있는 입장이 아니기 때문에 제가 뭐라고 말씀드릴 수는 없지만 아마 위원님들이 요청하시는 감사 부분에서 일정 미흡한 부분도 있다고 생각을 합니다.
</p>
<p><b>○ 박진영 위원 </b> 알겠습니다. 사장님, 저번 주 화요일 날 문화체육관광위원회에서 행감 받으셨죠?
</p>
<p><b>○ 증인 서춘기 </b> 네, 그렇습니다.
</p>
<p><b>○ 박진영 위원 </b> 지금 아직 행감자료가 정리가 안 돼서, 서면으로. 근데 제가 존경하는 황대호 위원님이 유튜브에 특별하게 올려놓으신 내용을 봤는데. 사장님, 지금 경기아트센터에서 감사실 직원이 세 분이 바뀌셨고 그분의 한 분은 ------로 치료를 받고 계신다는데 이거 사실인가요? 사실인지 아닌지만 대답 부탁드리겠습니다. 
</p>
<p><b>○ 증인 서춘기 </b> ……. 
</p>
<p><b>○ 박진영 위원 </b> 이때 화요일 날 질문은 한지양 실장님께서는 잘 모르겠다고 대답하셨는데 이 정도 사안이면 사장님으로서 지금까지는 충분히 파악을 하셨을 거라고 보고 있습니다. 사실인지 아닌지만 말씀 주십시오. 감사실 직원이 3명이 바뀌었고 그중에 한 분은 ------로 지금 치료를 받고 계신다는데 맞는지 아닌지만 말씀 주십시오. 
</p>
<p><b>○ 증인 서춘기 </b> 제가 공식적으로 보고받은 바는 없는데 제 개인적으로 들은 바는 있습니다. 
</p>
<p><b>○ 박진영 위원 </b> 사장님, 제가 경기아트센터 질병휴직 현황을 달라고 했는데요. 제가 제보받은 바로는 지금 감사실 직원 한 분이 원래 ------로 질병휴직을 하시려고 했는데 사장님이 면담하시고 연가를 내라고 하셨다는데 그 말 맞나요? 맞는지 아닌지만 대답해 주십시오. 증인선서하셨습니다. 
</p>
<p><b>○ 증인 서춘기 </b> 제가 연가를 쓰라고 했다고 이런 말씀하시는 겁니까? 
</p>
<p><b>○ 박진영 위원 </b> 한 분이 ------로 휴직을 신청하셨는데 사장님하고 면담을 하고 휴직이 아닌 연가로 바꿨다는데 제가 혹시 오해하고 있을 수 있으니까 그` 사실이 있었는지 없었는지만 얘기해 주십시오. 사장님, 면담하셨습니까? 
</p>
<p><b>○ 증인 서춘기 </b> 제가 면담한 거는 휴직이 아니었고요, 사표였습니다. 저한테……. 
</p>
<p><b>○ 박진영 위원 </b> 그 직원은 지금 사직 안 하셨죠? 
</p>
<p><b>○ 증인 서춘기 </b> 네. 
</p>
<p><b>○ 박진영 위원 </b> 지금 휴가 상태시죠? 지금 상태가 어떠세요? 
</p>
<p><b>○ 증인 서춘기 </b> 휴가상태는 아니고요, 근무를 지금 하고 있습니다. 
</p>
<p><b>○ 박진영 위원 </b> 어떤 이유로 사직을 하셨는지 여쭤봐도 될까요? 직원 성함은 말하지 않았으니까. 
