<p><b>○ 증인 서춘기 </b> 네, 사직을 생각했다라고 저한테 면담이 왔었는데. 
</p>
<p><b>○ 박진영 위원 </b> 어떤 이유일까요? 
</p>
<p><b>○ 증인 서춘기 </b> 업무적으로도 그렇고 자기 개인의 향후 진로를 위해서, 저한테는 향후 진로를 위해서 사표를 쓰겠다라고 한 겁니다. 
</p>
<p><b>○ 박진영 위원 </b> 알겠습니다. 아까 존경하는 이혜원 위원님께서 행정조사를 말씀해 주셨는데 이런 사항들을 정확하게 확인하려면 행정조사가 필요할 것 같다라는 생각이 아주 들고 있습니다. 지금 상황들을 정확하게 파악하기 위해서는 아트센터에서 관련됐던 직원분들 면담을 좀 해야 될 것 같고요. 저희 기획재정위원회는 아트센터를 관할하는 상임위원회는 아니지만 지금 종합감사를 올해 경기도 감사실에서 아트센터를 하셨는데 그 내용이 상당히 불충분하다고 보기 때문에 종합감사를 했던 내용과 함께 행정조사를 해야 되지 않을까라는 생각을 조금 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  제가 길게 써야 된다는 부분도 하나씩 이제 짚고 넘어가겠습니다. 제 거 화면 열어주세요. 
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p style="padding-left:1.2em">  3분 내에 끝내겠습니다. 
</p>
<p><b>○ 부위원장 이경혜 </b> 마이크를 조금만 띄워서 쓰시면 좋겠습니다. 
</p>
<p><b>○ 박진영 위원 </b> 네. 3분 내에 끝내겠습니다. 제 거 화면 좀 열어주세요. 
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  이거 작년도 행정사무감사 내용입니다, 문체위의. 존경하는 황대호 위원님이 보수제도 개악이라는 헬프라인 제도에 대해서 언급하셨어요. 그리고 이제 연관된 내용은 그러고 나서 3일 후에 메일이 전체 직원에게 뿌려졌다는 내용입니다. 그 메일 내용 아까 존경하는 이혜원 위원님께서 달라고 하셔 가지고 지금 와 있는데 제목이 보수제도 개악에 대해서입니다. 연관성 그때 없다고 하셨죠? 사장님. 
</p>
<p><b>○ 증인 서춘기 </b> 네? 
</p>
<p><b>○ 박진영 위원 </b> 그때 이 헬프라인에 보고된 내용하고 이 메일하고는 연관성이 없다고 하셨죠? 
</p>
<p><b>○ 증인 서춘기 </b> 연관성이 없는 게 아니고 그전에 이미 논의됐던 사항이라고 제가 말씀을 드렸습니다. 
</p>
<p><b>○ 박진영 위원 </b> 저희가 그때 여쭤봤던 거는 감사실장님이 이 메일을 보고 이 메일에 대한 답변을, 이 헬프라인을 보고 이 헬프라인에 대한 답변으로 이 메일을 쓰신 게 아니냐라는 생각을 여쭤봤었습니다. 이 메일이 12월 달에 왔고요. 이거 아트센터 23년 9월 27일 자 공지사항입니다. 감사위원장님, 자세히 봐주시기 바랍니다. 경기아트센터는 공익신고자 보호 및 지원을 위하여 운영 지침을 제정하여 운영하고 있습니다. 참고하여 주시기 바랍니다. 또한 경기아트센터는 헬프라인을 운영하고 있습니다. 익명신고와 제보를 받고 있으며 제보 내용의 기밀성과 익명성을 보장하기 위해라고 하고 있습니다. 감사위원장님! 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 
</p>
<p><b>○ 박진영 위원 </b> 아직도 생각이 바뀌지 않으셨죠? 헬프라인에 대한 내용과 비밀유지에 대한 사항과 관계가 없다라는 거에 대해서요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 헬프라인은 익명으로 제보를 하는 거고 그 내용은……. 
</p>
<p><b>○ 박진영 위원 </b> 그러니까 만약에 어떤 분이 헬프라인에 익명으로 제보를 했어요. 그러고 그 헬프라인을 담당하시는 분이 그 내용과 관련해서, 그 내용을 활용하여 외부적으로 메일을 쓰거나 하신 게 비밀유지 엄수 조항이랑 관련이 없다고 생각하시는 거죠, 아직도? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 비밀과 기밀에 대해서, 저 헬프라인을 감사실장이 확인했습니다. 그것까지는 저희들이 확인을 했고요. 그다음에 발표문을 봤습니다. 발표문을 보고 내부에 있는 저희 변호사 두 분께서 기밀인지 비밀인지 이와 관련된 논의들을 내부에서 했다고 합니다. 그런데 헬프라인이 익명으로 제보가 들어옵니다. 이를 확인한 감사실장도 아마 저분이 누군지를 모를 겁니다. 그래서 아마……. 
</p>
<p><b>○ 박진영 위원 </b> 근데 감사실장님이 그 헬프라인에 대한 내용을 확인하시고 이거를 전체 직원에게, 며칠 뒤에 전체 직원에게 변명하는 내용을 보내셨다면 이거는 본인이 업무로서 취득한 내용에 대해서 비밀을 지켜야 함에도 불구하고 공개적으로 이 비밀을 활용한 게 아닌가라는 생각이 들어서입니다. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 충분히 말씀을 이해합니다. 저희도 그것 때문에 내부에서 변호사 두 분들과 여러 가지로 논의를 했고 개인정보가 없고 정책적인 사항들에 대해서 발표문을, 발표하셨기 때문에……. 
</p>
<p><b>○ 박진영 위원 </b> 논의하신 내용 다 주시고요. 합리적으로 말씀드리겠습니다. 
</p>
<p style="padding-left:1.2em">  위원장님, 죄송한데 답변이 길어졌습니다. 조금만 더 쓰겠습니다. 길어질 것 같아서……. 
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 1분 안에 정리 부탁드립니다. 
</p>
<p><b>○ 박진영 위원 </b> 1분 안에? 2분만. 
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 그러시죠. 
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 제가 답변을 정리해야 될 입장이라서 더 이상 말씀 안 드리겠습니다. 합리적으로 말씀드리겠습니다. 익명제보시스템이라는 거는 익명을 보장하고 그 내용에 대한 익명성도 보장해서 명백하게 편하게 제보를 하고 그 내용들이 개선되게 하기 위한 건데 익명제보시스템을 접속할 수 있는 분에 대해서 익명의 제보가 오고 그 익명의 제보가 온 거를 익명의 피제보자가 그 내용을 가지고 전체 직원에게 메일을 쓴다면 익명제보시스템이 의미가 있을까요? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 충분히……. 
</p>
<p><b>○ 박진영 위원 </b> 위원장님이 지금 말씀하시는 내용에 따라서 경기도 전체의 익명제보시스템에 대해서 저는 의문을 제기할 겁니다. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 일단 한번 그 내용을……. 위원님, 발표문으로 되어 있는 내용문을 한번 봐주십시오. 그 내용문을 보고 아마 여기서도 내부에서 많은 고민이 있었던 것 같습니다. 
</p>
<p><b>○ 박진영 위원 </b> 내부에서 논의하신 내용 주시고요. 그리고 짧게 해야 되니까 말씀드리겠습니다. 이 내용 확인해 보시면 알겠지만 제가 지난 행감 때 어떤 노무법인께서, 사측으로 고용된 어떤 노무사님께서 감사실장님에 대해서 제보한 내용에 대해서 사측 이야기를 하시고 내용에 대해 조사를 받아야 된다라고 얘기하셨다는데 그 당시에 제가 이거 계약된 거냐 안 된 거냐고 물어봤습니다. 근데 공교롭게도 신기합니다. 경기아트센터에서 종합감사하신 내용 보면 이 당시 결재 관계에 대한 문제가 있어서 이분이 결국에는 훈계 처분을 받으셨습니다. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 맞습니다. 
</p>
<p><b>○ 박진영 위원 </b> 내용의 본질은 경기아트센터하고 정식 고용계약을 맺지 않은 상태에서 특정 개인에 대해서, 신고가 들어온 내용이 그 특정 개인, 어떤 노무사에게 전달이 됐고요. 개인정보가 유출됐고요. 그 노무사가 그분께 이런저런 얘기를 해서 그분이 하도 어이가 없어 가지고 제보한 내용입니다. 이거 그냥 단순히 결재사항을 안 했다라는 내용이 아닌 것 같은데요. 개인정보 보호에 대한 위반 그리고 감사절차, 처리절차에 대한 문제도 있는 것 같고요. 이런 부분 처리절차조차 제대로 감사위원회에서 명확하게 처리해 주시지 못한다면 이 부분도 상당히 저는 행정조사를 해야 되는 합리적인 사항이라고 보고 있습니다. 이상입니다. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 위원님, 잠깐 말씀드려도 될까요? 
</p>
<p><b>○ 박진영 위원 </b> 제가 시간이 없어서요. 죄송합니다. 
</p>
<p><b>○ 부위원장 이경혜 </b> 박진영 위원님 수고하셨습니다. 감사위원장님, 잠시 후 다시 또 다른 위원님 질문받고 이어서 답변드릴 수 있는 시간 있으면 드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  다음 추가질의 있으신 위원님 계십니까? 이채명 위원님 먼저 하겠습니다. 이채명 위원님 질의하십시오. 아트센터 사장님은 들어가셔도 좋습니다. 
</p>
<p><b>○ 이채명 위원 </b> 안양 출신 이채명 위원입니다. 기조실장님께 질의드리겠습니다. 처음 저희 기조실 행감할 때 제가 질의드렸던 부분인데요. 이거는 기획담당관과도 관련돼 있습니다. 저희 경기도의 비전과 목표, 방향을 제시하기 위한 우리 기획담당관이 먼저 이거는 선제적으로 좀 알아야 됐으면 좋겠다라고 생각이 들어서 제가 올해 통합수도사업을 저희 경기도에서 먼저 주도해야 된다라고 제안을 드리면서 자료요청을 했던 게 있습니다. 혹시 실장님, 들어보셨죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 이채명 위원 </b> 그 내용에 대해서 혹시 행안부가 발표한 2023년도 사업연도 지방공기업 결산 및 경영분석 보고서 혹시 5년 치 자료도 한번 확인하셨나요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 분석보고서 개별 내용까지는 제가……. 
</p>
<p><b>○ 이채명 위원 </b> 구체적으로 확인을 안 하셨죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 
</p>
<p><b>○ 이채명 위원 </b> 사실은 상수도 같은 경우는 지난 5년간 적자액이 한 6,700억, 6,900억 정도가 되고요. 그리고 하수도 같은 경우는 경기도 88곳 중에서 우리 도내 22개 하수도가 지난 5년간 적자가 약 1조 9,400억 정도가 됩니다. 그래서 우리 경기도 내 시군 적자의 골칫덩어리로 상하수도를 사실 손에 꼽을 수 있을 정도라고 해도 과언이 아닐 정도라서 혹시 지난 9월에 수도법 개정안, 일부개정안 혹시 보셨나요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 봤습니다. 
</p>
<p><b>○ 이채명 위원 </b> 주요 핵심이 뭐라고 보십니까? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 수도사업에 대한 통합 계획을 수립할 수 있도록 근거를 마련한 겁니다. 
</p>
<p><b>○ 이채명 위원 </b> 맞습니다. 우리 도지사가 직접 수도사업 통합을 단행하거나 또 복수의 시장ㆍ군수가 통합계획 수립 요청하는 경우 등에 대해서는 통합수도 사업을 할 수 있는 게 이번 일부개정법률안의 핵심입니다. 제가 국회 환경노동위원회의 검토보고서를 확인했습니다. 인구 30만 이하 소규모 지자체 124곳이 지금 현재 자립경영이 굉장히 어려운 상태라고 합니다. 우리가 요금 현실화라고 하는 그런 어떤 명목하에 주민들에게 이런 부담을 가중시키는 것은 사실 실질적인 대책이 저는 될 수 없다라는 생각이 들면서 오늘 계기로 우리 경기도가 통합수도 사업을 실현하며 규모의 경제를 실현하고 가족용 요금 하향 안정화로 우리 주민들의 복리증진 향상을 실현해 주실 것을 요청드리면서요. 이번 행감 때 제가 제안한 통합수도 사업 추진 요구를 이번 행정사무감사 결과보고서에 처리요구 사항으로 넣어서 우리 경기도가 국내 도 지역 중에서 가장 먼저 앞서 나갈 수 있게끔 행정력을 저희 경기도의회 차원에서 함께 견인해 나가도록 하겠습니다. 혹시 우리 실장님, 제가 제안한 내용에 대해서 그동안에 실장님, 고민하셨을 것 같습니다. 간단하게 답변 주시기 바랍니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 위원님 말씀하시는 것 중에서 지난번에 말씀을 주셨기 때문에 저도 좀 고민을 했고요. 그다음에 도가 할 수 있는 경우가 있고 둘 이상의 시장ㆍ군수가 또 요청할 수 있는 경우가 있지 않습니까? 그래서 기본적으로 상하수도 업무는 저희가 기구 정원 조례상에 보면 수자원본부 소관입니다. 그래서 수자원본부랑 좀 얘기를 나눴고요. 그래서 거기서 검토를 좀 해 달라고 저희가 요청을 한 사항이고요. 그다음에 저희 차원에서 직접 할 수 있는 것들은 행안부에서 공기업 경영평가를 할 때 그런 부분들이 지표로 반영될 수 있는 부분 저희가 적극 건의하도록 하겠습니다. 
</p>
<p><b>○ 이채명 위원 </b> 지금 현재 다른 광역시에서는 먼저 추진하려고 많이 노력 중이더라고요. 저희 경기도가 1,410만 가장 큰 규모의 인구수를 자랑하고 있잖아요. 먼저 선도적으로 시행해 주실 것을 당부드리면서 저희가 또 한 가지, 그동안에 경기아트센터 등등 저희 공공기관에 관련해서 공용차량 문제점을 제가 많이 지적했습니다. 그중에서 내부 규정이 사실 다 상이한 건 알고 계시죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 이채명 위원 </b> 그 부분에 대해서 향후에 어떻게 정비를 할 것인지 그것도 간단하게 실장님 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 지금 내부 규정이 있는 경우랑 그다음에 권익위 판단에 따르면 사회상규상 두 가지가 있는데요. 그래도 그 기준이 있는 경우가 보다 분명하기 때문에 그건 저희가 가급적 기준을 마련할 수 있도록 공공기관을 유도해 나가겠다는 말씀을 드립니다. 
</p>
<p><b>○ 이채명 위원 </b> 네, 알겠습니다. 이상입니다. 
</p>
<p><b>○ 부위원장 이경혜 </b> 이채명 위원님 수고하셨습니다. 이석균 위원님 추가질의 있으신 건가요? 
</p>
<p><b>○ 이석균 위원 </b> 네. 
</p>
<p><b>○ 부위원장 이경혜 </b> 잠시만 기다려 주시겠어요. 지금 시간이 5시라서 회의한 지 좀 경과돼서 그럴까요? 집행부가 굉장히 힘들고 피곤해하시는 모습들이세요. 그럼에도 불구하고 저희 아직 행감 안 끝났거든요. 조금 더 경청해 주는 자세를 유지해 주시기를 좀 부탁드립니다. 저희 여기서 있으면 다 보여요. 그래서 어떤 분이 어떤 불만의 표정으로 계신지가 다 보이는데 불만이 있을 수도 있고 여러 가지 하고 싶은 말씀 많으실 수도 있지만 그래도 위원이 행감에 질의를 하고 있는 그 순간들은 경청을 해 주시는 자세가 서로 간에 예의가 아닐까 싶습니다. 그래서 예의를 지켜주시길 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  계속해서 질의 이어가겠습니다. 이석균 위원님 질의하여 주십시오. 
</p>
<p><b>○ 이석균 위원 </b> 남양주의 이석균입니다. 오전에 이희준 실장님께 말씀드렸던 우리 공공기관의 경영평가 이 부분은 다시 한번 기준과 이거를 논의해 보겠다라고 말씀을 주셨는데 연이어 우리 공공기관담당관이신 김도형 과장님께 좀 질의를 드리려고 하다가 그때 자료를 가지러 나가셨던가 봐요. 우리 공공기관담당관께 질의를 좀 드리겠습니다. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 공공기관담당관 김도형입니다. 
</p>
<p><b>○ 이석균 위원 </b> 네, 과장님. 과장님도 어떻게 보면 큰 범주의 월급을 받는 샐러리맨이라고 생각하실 수 있나요? 큰 범주에. 뭐 공공성을 띠고 있는 공무원이시기도 하지만. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이석균 위원 </b> 언제 월급 받을 때가 제일 좋으십니까? 성과급 받을 때가 제일 좋지 않을까요? 자료 한번 좀 띄워주시겠어요. 
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  오전에 우리 경기도 경영평가와 지방공기업의 경영평가에 상이되는 기준에 대해서 말씀을 드렸고 우리 실장님께서 아까 드린 말씀처럼 다시 한번 이거를 논의해서 수정을 하겠다라고 얘기를 하셨는데 우리 많은 공직자분들 혹은 공공기관에 근무하시는 분들도 아마 성과급이 어떻게 보면 좀 기다려지는 부분일 것 같습니다. 그런데 표를 한번 보시죠. 표가 좀 짧게 나오기는 했지만. 
</p>
<p style="padding-left:1.2em">  우리가 90점 이상이면 공기업에서는 가급으로 분류가 되는데 우리 경기도는 나급으로, 95점 미만까지는 나급으로 그렇게 되죠. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 맞습니다. 
</p>
<p><b>○ 이석균 위원 </b> 우리가 나급을 받게 되면 정확한 점수에 따라서, 우리 출연출자기관 경영평가 결과에 따른 성과급 지급률에 따라서 세부적으로 또 나눠지는데 우리 경기도경제과학진흥원 한번 볼까요. 총점이 92.70점을 받아서 등급이 나급, 지방공기업으로 치면 가급이죠. 그런데 지방공기업에서는 가급으로 치면 180%~200%의 성과급을 가지고 가게 되는데 경기도 경영평가에서는 나급 92.7점이니까 아마 92.6 이상 95 미만의 직원 성과급 같은 경우에는 한 140% 정도로 받을 것 같습니다. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 맞습니다. 
</p>
<p><b>○ 이석균 위원 </b> 이거 보면 우리 공공기관의 직원이라고 그러면 뭔가 감회가 새로울 것 같은데요. 우리가 기준이 달라지면 180~200%를 받을 수가 있는데 지금 경기도 경영평가 기준에 따라서 이렇게 받게 되면 140%를 받게 됩니다. 아무리 지금, 제일 잘한 기관이 되겠죠. 그래서 상당히 회의가 느껴지고 경영평가에 대해서 좀 더 잘 받을 걸 이런 얘기도 나올 것 같고 또 나아가서는 기관장들의 의지가 좀 더 강하면 성과급을 더 받을 수 있지 않을까 하는 그런 생각들도 들 수 있을 것 같아요. 어떻게 생각하십니까? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 위원님 말씀에 동의합니다. 
</p>
<p><b>○ 이석균 위원 </b> 그리고 보니까 우리 경기도 경영평가에서는 가점제도가 있어요. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 있습니다. 
</p>
<p><b>○ 이석균 위원 </b> 아시죠? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네. 
</p>
<p><b>○ 이석균 위원 </b> 혹시 아시는 대로 한번 얘기해 주시겠어요? 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 장애인 관련된 것도 있고 RE100 관련된 것도 있고요. 
</p>
<p><b>○ 이석균 위원 </b> 혹시 점수도 몇 점인지 아시면 좀 상세하게 얘기해 주시겠어요. 
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 제가 지금 갑자기, 외우지는 않고 있었기 때문에. 혁신 우수사례 관련된 게 3점 있고요. 장애인 의무고용률 초과달성이 0.5점, RE100이 1점, 공약 등 핵심사업 관련된 1점 또 권고사항 이행이 0.5점 가점이 있고요. 감점은 저희 조직이나 정원 관리 지침 준수하지 못했을 때 장애인 의무고용 관련 0.5점, 공시 위반했을 때 0.1점, 기관장 성과계약 체결 지연 등에 0.4점 등이 있습니다. 
</p>
<p><b>○ 이석균 위원 </b> 아주 정확하게 기억하고 계시는데요. 우리 가점이 6점, 감점이 2점, 감점을 안 받더라도 최대 받을 수 있는 가점이 6점인데 지금 표출자료에 나와 있는 거를 보게 되면 가점이 경기도시장상권진흥원이 1.96점으로 가장 적게 받았고요, 경기도 청소년수련원이 4.51점으로 가장 높게 받았습니다. 그런데 가점을 총점에서 제외를 해 보니까 두 번째 칸에 있는 점수가 나옵니다. 이 점수를 그러니까 가점을 주지 않고 성과급으로 환산을 해 봤더니 가장 점수가 높은 경기도경제과학진흥원이 115% 정도 돼요. 그럼 성과급으로 따지면, 180~200%에 따지면 거의 절반에서 조금 더 많은 수준으로 이렇게 되고 있는데 저는 이 가점이라는 부분들이 인센티브를 주기 위한 혹은 성과 등급을 낮은 데를 약간 높게, 높은 데를 약간 낮게 평준화시키는 그런 무게추 작용을 한다라고 봐요. 따라서 본 위원이 말을 맺겠습니다. 오전에 이희준 실장님께 정말 경영 공공기관이, 기관장이 제대로 생각을 가지고 제대로 하고 또 평가가 제대로 되고 실적이 제대로 되어야 올바른 경영 실적과 성과급이, 인센티브가 돌아간다고 생각합니다. 그래서 이 경영평가 기준과 인센티브 그리고 가점ㆍ감점 항목 이런 부분들에 대해서 종합적으로 다시 한번 판단을 해야 되겠다고 생각하는데 이희준 실장님, 어떻게 생각하십니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 위원님 말씀에 공감합니다. 
</p>
<p><b>○ 이석균 위원 </b> 이게 그냥이 아니라 1년 동안 뼈 빠지게 근무한 우리 공공기관 직원들의 희비가 여기에 엇갈려져 있는데 우리는 수년 동안 해 온 것처럼 그냥 무난하게 넘어가고 무난하게, 그러면 거기에 대해서 책임지는 사람은 무난하게 가는데 거기에 피해를 받는 우리 공공직원들은 피눈물을 흘릴 수밖에 없지 않겠습니까? 이 부분을 오늘 약속하신 대로 내년부터는 평가기준과 등급기준에 대해서 전체적인 고려를 하시고 수정을 해 주시기를 부탁드립니다. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 위원님, 그렇게 하도록 하겠습니다. 
</p>
<p><b>○ 이석균 위원 </b> (위원장석을 향하여) 그리고 한마디만 더 해도 되죠? 
</p>
<p style="padding-left:1.2em">  김도형 과장님, 우리 공공기관 평가담당관이라는 이런 직책과 조직이 본 위원이 보기에는 지금까지는 그냥 중간의 소통 역할 정도가 되었던 것 같아요. 그런데 공공기관이라 함은 우리 경기도가 필요로 해서 도민들을 대신해서 우리가 만든 기관이고 그 운영은 도비로 이루어지는 거 맞습니까?
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 맞습니다. 
</p>
<p><b>○ 이석균 위원 </b> 그러면 그 공공기관이 잘하느냐 못하느냐 하는 부분들은 감사위원회에서 하는 부분들도 있고 자체감사도 있고 또 여러 가지가 있을 수는 있지만 우리 공공기관담당관의 역할이 다시 정립되었으면 좋겠습니다. 우리 경기도의회에서도 상임위별로 공공기관에 관한 한은 소관 상임위가 모든 것을 한다라는 생각을 가지고 있는데, 물론 그게 맞을 수 있습니다, 사업에 대해서. 우리 공공기관 고유목적사업들과 우리 경기도에서 필요로 하는 정책사업들을 하는 거를 소관 상임위원회에서 하는 거는 맞습니다. 그런데 경영평가에 대해서는 소관 상임위가 아니라 공공기관담당관에서 쥐고 가야 된다는데 어떻게 생각하시는지요?
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 네, 위원님 말씀에 전적으로 공감합니다. 
</p>
<p><b>○ 이석균 위원 </b> 그렇다면 공공기관이 경영평가를 제대로 받고 잘 받기 위해서는 공공기관담당관에서 관심도 가지고 어떨 때는 싫은 소리도 하시고 어떤 때는 또 공적으로는 공문도 보내시고 또 그쪽에 소명도 받으시고 하는 적극적인 부분들이 공공기관담당관이 하셔야 될 일인 것 같은데 그것도 동의해 주시는 겁니까?
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 최선을 다하겠습니다. 
</p>
<p><b>○ 이석균 위원 </b> 지금 최선을 다하신다고 얘기를 하셨는데 앞으로는 공공기관의 경영평가라는 것이 오전에도 말씀드렸다시피 우리 경기도의 얼굴이 될 수도 있고 경기도의 사업이 될 수 있고 도민의 행복 향유에 가장 최측근에 있는 기관들이 어쩌면 공공기관일 수 있을 것 같습니다. 그런데 이 공공기관이 그냥 “나 아니야, 다 아니야. 라만 안 받으면 돼.”, “가 받으면 내년이 걱정되니까 가라도 나 정도로 낮춰줘.” 이러한 안이한 생각으로 가다가는 도민도 불행해지고 세금은 세금대로 쓰고 여러 가지 의사소통이 안 될 것 같아요. 그런데 이거를 해결하고 중간에 풀어주시는 곳이 공공기관담당관이신 것 같아요. 그래서 앞으로도 더 적극적으로 경영평가에 대해서는 우리 기획재정위원회 소관 사항이고 기획재정위원회와 기획조정실 특히 공공기관담당관께서 이 부분들은 쫙 잡고 가시는 게 맞을 것 같습니다. 어떻게 생각하십니까?
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 위원님 생각에 전적으로 공감하고요. 위원님들 기대치가 높으시지만 그래도 거기에 맞출 수 있도록 열심히 노력하겠습니다.
</p>
<p><b>○ 이석균 위원 </b> 그렇게 노력해 주시면 우리 기획재정위원회 위원들은 공공기관담당원과 기획조정실에 발맞추어서 함께 공공기관이 거듭날 수 있도록 그렇게 하는 데 일조하도록 하겠습니다.
</p>
<p><b>○ 기획조정실공공기관담당관 김도형 </b> 감사합니다. 
</p>
<p><b>○ 이석균 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 이석균 위원님 수고하셨습니다. 다음 또 추가질의하실 위원님 계십니까? 마지막인 것 같습니다. 이혜원 부위원장님, 마지막으로 추가질의하여 주십시오.
</p>
<p><b>○ 이혜원 위원 </b> 추가질의하겠습니다. 경기아트센터 이어서 하겠습니다. 감사위원장님이 답변해 주시면 될 것 같습니다. 감사위원장님, 종합감사 내용하고 특정감사 내용 제가 자료요구를 최초에 해서 받았잖아요? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 내용을 보니까 2개 내용이 좀 다른데 유사한 건들이 좀 있습니다, 인사위원회 관련해서. 인사위원회 관련해서 내부 인사규정도 보셨죠? 경기아트센터.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그런 걸로 알고 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 위원회 명단, 참석 명단, 회의록 이런 거 다 보셨어요, 감사할 때? 왜 물어보냐면 지금 여기에서 내용 조치사항에 대한 부분은 인사규정 위반 해서 재적위원 임의 제외에 관련된 내용이 있어요. 그리고 특정감사 내용에서도 단원에 대한 인사 절차에 관련된 내용이 있어요. 그런데 저희가 행정사무감사 작년에도 하고 계속적으로 제보가 간 걸로 알고 있는데 제보받으실 때 공식으로 접수된 제보 건에 대한 부분만 감사를 하시나요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 그렇지는 않고 이거 아마 종합감사를 할 때는 일단 기본 제보사항들이 있고 또 감사에 들어가면 잘 아시겠지만 공개적으로 많이 감사 제보를 하고 있습니다. 그런 것들을 다 모아서 제가 알기로는 종합감사 2023년 53개 정도…….
</p>
<p style="padding-left:2.4em">    (자료를 들어 보이며) 
</p>
<p><b>○ 이혜원 위원 </b> 그런데 제가 알기로는 이렇게 공개 감사와 관련돼서 안내문을 통해서, 여기 나와 있는 자료를 통해서 이렇게 제보를 하신 분들도 있고 한데 저희한테 주신 자료 내용에는 그런 내용이 없고요. 그리고 일단은 제출하신 자료 내용만 보더라도, 인사위원회 규정과 인사위원회 명단, 참석 명단 이런 것만 봐도 뭐가 잘못됐는지 내용을 파악할 수 있는데 그런 내용이 전혀 없어요. 
</p>
<p style="padding-left:1.2em">  하나 볼까요? 경기아트 인사위원회에 제가 아까 자료요구해서 왔는데 인사위원회의 당연직에 우리 내부 인사위원회는 3명 있습니다. 경영기획실장, 사무처장, 예술정책과장 이렇게. 그리고 인사위원회 내부규정에도 인사위원회 제7조에 인사위원장은 경영기획실장이 되고 당연직 위원은 사무처장과 경기도 소관 부서 과장이 되며 그리고 나머지는 외부 인사에 관련된 사항이고 그것은 사장이 위촉하는 걸로 되어 있습니다. 그런데 제가 이 예술감독 채용 관련돼서 서류 제출 요구해서 받았는데요. 경기도극단 예술감독 채용, 경기도무용극단 예술감독 채용, 경기시나위오케스트라 예술감독 채용에 왜 내부에 한 사람밖에 없죠? 한○○ 감사실장으로 되어 있는데. 감사실장이 인사위원인가요? 제가 지금 말씀드린 내용에는 감사실장이 인사위원으로 위촉된 바가 없거든요. 그런데 왜 여기에는 감사실장이 인사위원으로 들어가서 예술감독 채용하는 데 관여를 하셨죠? 채점표를 받아보니까 제척ㆍ회피된 부분도 전혀 없고. 이름을 다 가려서 누구와 채점을 하셨는지는 모르겠는데 명단에는 들어와 있습니다. 그런데 제가 이 부분을 말씀드리는 건 감사위원회에서 감사를 할 때 이런 전반적인 내용들을 보고 판단을 하시면 제보된 내용하고 연관을 시킬 수도 있는 거고 인사위원회 자료만 제대로 보셔도 무엇을 지적해야 되는 상황이고 개선해야 될 상황인지를 확인하시는 게 감사위원들 몫 아닌가요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 맞습니다. 기초적인 거는 제보를 받지만……. 
</p>
<p><b>○ 이혜원 위원 </b> 기초적인 거잖아요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 내용상에 나오는 것도 지적을 해야 되는 게 맞습니다.
</p>
<p><b>○ 이혜원 위원 </b> 근데 왜 여기 조치사항에는 통보 내용밖에 없는데요? 업무 관련자 신분상 조치에 관련된 부분이고 이것도 임의 제외, 재적위원 임의 제외에 관련된 내용만 들어가 있어요. 주요사항이라서 그런가요? 이거 별도의 사안이 또 있으신가요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 아마 제가 알기로는 아까 인사위원과 그다음에 심사위원은 좀 다른 것 같기도 하고요.
</p>
<p><b>○ 이혜원 위원 </b> 제가 이 질문을 하고 이걸 굳이 지적을 한 이유는 지금 감사위원회의 감사활동하는 부분들에 대해서 행정사무감사를 하는 와중에 계속 경기아트센터에 대한 부분들이 나옵니다. 그래서 결국에는 경기아트센터 사장님과 감사실장을 증인 채택해서 그 관련된 부분을 확인하고 있는 상황인데 예전에 2023년 행정사무감사에서 지적된 내용에 대한 부분들도 감사가 전혀 안 됐고 자료 제출조차도 안 됐고 그리고 여기서 진행되고 있는 내용, 저는 왜 이 같은 부분을, 지금까지도 행정사무감사에서 이 반복되는 내용을 또 하고 있을까 의문이 들더라고요. 도대체 왜 그럴까, 감사위원회도 있는데. 또 경기아트센터에 감사실도 있는데, 굳이? 이게 경기아트센터에 많은 제보가 있습니다. 내부에서도 있을 수 있고 외부에서도 있을 수 있는데 누구도 억울하지 않게 감사 좀 제대로 해 주시면 안 되겠습니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 말씀드려도 되겠습니까?
</p>
<p><b>○ 이혜원 위원 </b> 해 주십시오.
</p>
<p><b>○ 감사위원장 안상섭 </b> 일단 그와 관련해서는 그때 당시 행정사무감사에서도 한 16개를 아트센터에 아마 시정 조치 요구를 하신 걸로 알고 있고요. 저희도 이 자료들을 한 53건 정도, 감사 전, 감사 후 이렇게 해서 53건 제보를 받아서…….
</p>
<p><b>○ 이혜원 위원 </b> 전반적인 부분을 말씀드리는 게 아니라 지금 1건을 제대로 감사를 하셔도 제대로 된 내용들이 나오는데 감사가 절차대로 잘 진행이 됐는지, 이거를 또 행정사무감사에서 또 감사를 해야 되는 상황이 답답하다는 말씀을 드리는 겁니다. 그래서 아니, 먼저도 제가 도민권익위의 갑질현황에 대한 부분들 자료 받아봤더니 있더라고요. 그런 부분은 왜 안 하십니까? 그리고 공개적으로 나온 내용들이 한두 건입니까? 언론보도 내용들도 많고. 이 내부에서 진행되는 일들이 무궁무진한데 그 부분에 대해서 감사 진행조차도 안 되고 있고 현황 파악도, 현황 파악은 하셨겠죠. 진행이 안 되고 있고 제대로 절차와 결과가 안 나오니까, 조치가 안 되니까, 조치사항을 해 놓고도 그 확인조차도 또 안 되니까. 조치 뭐 “시정만 하세요.” 이렇게 하면 시정이 됩니까? 시정된 게 확인이 돼야죠. 개선된 게 확인이 됐어야 시정되는 거 아닙니까? 그런 부분들에 대해서, 그러니까 위원님들이 계속 행정사무조사가 필요하다는 얘기를 하는 겁니다. 조사특위가 필요하다. 답변하실 필요 없습니다, 위원장님. 수고하셨습니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 죄송합니다. 하여간 최선을 다하겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 네, 수고하셨습니다. 이상입니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 이혜원 부위원장님 수고하셨습니다. 박진영 위원님 추가질의 있으신 건가요?
</p>
<p><b>○ 박진영 위원 </b> 네, 짧게요. 
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 먼저 하십시오.
</p>
<p><b>○ 박진영 위원 </b> 죄송합니다. 질의가 길지 않아서요. 감사위원장님, 저한테 주신 자료 보니까 감사실장의 직장 내 괴롭힘 사건 제보현황이 있는데, 여기 총 2건으로 주셨는데 1건은 9월 14일 날 그리고 11월 18일 날 경기도 헬프라인 시스템으로 제보되어 있습니다. 맞죠?  
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 
</p>
<p><b>○ 박진영 위원 </b> 이 부분 현 시스템에 제보되어서 처리된 내역 그리고 답변된 내역들 부탁드리겠습니다. 그리고 또 1건은 2월 15일 날 아트센터 종합감사 공개감사 청구, 이메일로 접수된 것 같네요? 감사실장 직장 내 괴롭힘 사건 처리절차에 대한 문제 제기. 이것도 처리절차 주시고요. 그리고 위원장님, 분명히 첫 감사 때 제가 말씀드렸죠? 증인선서하셨고 말씀하신 내용에 대해서 책임지셔야 된다고.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 
</p>
<p><b>○ 박진영 위원 </b> 2건입니다. 저한테 주신 내용이 2건이에요, 1건이라고 보고하셨는데.
</p>
<p><b>○ 감사위원장 안상섭 </b> 그 1건이 갑질 행위와 관련된 직접적 제보이고요. 다른 1건은 그 감사 절차를 잘못 이행했다라는…….
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 하나만 더 여쭤보겠습니다. 위원장님, 경기도 감사실로 헬프라인이나 등등등등으로 특정 기관에 대해서 갑질에 대한 제보가 1년에 몇 건이나 오죠? 특정 기관 하나당 평균이요. 파악 필요하시면 파악하실 필요가 있으실 것 같고요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 제가 지금 알고 있지는 못해서.
</p>
<p><b>○ 박진영 위원 </b> 제 생각으로는 1년에 경기도의 공공기관에 대해서 갑질에 대한 제보가 0건인 데도 많을 거라고 생각합니다. 특정 기관에 대해서 1건이 추가 제보가 계속 들어왔어요, 23년 9월 14일 날. 11월 18일 날. 이거 되게 굉장히 이례적인 상황이라고 생각하는데 이럼에도 불구하고 직장 내 갑질에 대한 부분들은 처음에 하실 때 파악 안 됐다라고, 상태 파악이 안 된 부분으로 많이 말씀 주셨던 것 같은데 맞나요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 지금 그래서 다시 살펴보았습니다. 다시 살펴보았고 그 갑질에 대한 제보가 있었고 변호사 의뢰해서 처리가 완료됐고요. 그다음 1건이 이걸 잘못했다라고 다시 제보를 했더라고요. 그래서 직접적인 갑질 제보 1건하고 그 갑질 제보 처리, 변호사를 선임해서 외부 조사기관에 맡겼다라는 게 잘못됐다 이 처리 건으로 또 1건을 받은 겁니다.
</p>
<p><b>○ 박진영 위원 </b> 제가 이 말씀을 드리는 거는 갑질 신고에 대해서 경기도감사위원회가 처리하는 방식이 상당히 미흡하지 않나라는 의구심이 들어서 이 말씀드립니다. 이상입니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 박진영 위원님 수고하셨습니다. 더 추가질의하실 위원님 없으십니까? 그러면 저도 추가질의 하나만 하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  아트센터 서춘기 사장님, 잠시 앞으로 나와 주십시오.
</p>
<p><b>○ 증인 서춘기 </b> 경기아트센터 사장 서춘기입니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 저희 기획재정위원회는 공공기관의 내부의 일들을 살피는 기관은 아닙니다. 알고 계시죠?
</p>
<p><b>○ 증인 서춘기 </b> 네, 알고 있습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 그럼에도 불구하고 오늘 기획재정위원회의 행정감사에 굉장히 많은 시간을 아트센터에 할애가 되어서 지금 행감을 하고 있습니다. 이 이유에 대해서 사장님께서 제일 많이 알고 계실 거라고 생각하는데 지금 아트센터가 이렇게 행정감사를 문화체육관광위원회가 아닌 기획재정위원회에서 길게 받고 계신 이유에 대해서 짧게 어떻게 생각하시는지 답변을 부탁드립니다.
</p>
<p><b>○ 증인 서춘기 </b> 대단히 송구스럽게 생각을 합니다. 그리고 우리 기관의 모든 직원들은 사실 나름의 열심히 일을 하고 있다고 생각을 합니다. 그리고 저희 기관은 한 480여 명의 직원이 있습니다. 예술가들의 집단이다 보니 제 개인적인 생각으로는 48개의 예술세계가 존재하고 있습니다. 많은 소리가 날 수밖에 없는 구조이고 이 구조가 조금은 더 잘 다스려졌다면 오늘과 같은 이런 현상은 일어나지 않았으리라고 생각을 합니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 거기까지 답 듣겠습니다. 제가 이렇게 여쭤본 이유는, 지금 사장님께서 말씀하신 대로라면 경기도 전체 공무원들이 몇 명 정도일 거라고 생각하십니까?
</p>
<p><b>○ 증인 서춘기 </b> 제가 판단할 때 한 3만 명 될 거라고 생각합니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 그러면 경기도에 3만 명의 직원이 일하고 있으면 3만 명의 소리를 지금 우리는 듣고 있어야 될 거라고 생각하십니까?
</p>
<p><b>○ 증인 서춘기 </b> 아닙니다. 그래서 저희…….
</p>
<p><b>○ 부위원장 이경혜 </b> 그러면 아트센터만 유난히 열심히 일해서 지금 이렇게 큰 소리가 난다라고 생각하시는 겁니까? 모두가 다 똑같이 경기도청, 경기도의회, 경기도교육청 다 모든 공무원들이 함께 일하고 다 열심히 최선을 다해 자기 자리에서 일하고 있습니다. 
</p>
<p><b>○ 증인 서춘기 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 부위원장 이경혜 </b> 그럼에도 불구하고 각자의 자리에서 열심히 최선을 다하는 일 이외에 이 정도의 민원이나 제보와 감사의 문제를 가지고 있지는 않습니다. 아트센터는 정말 반성하셔야 된다고 생각을 하고요. 
</p>
<p><b>○ 증인 서춘기 </b> 네, 많이 반성하겠습니다. 
</p>
<p><b>○ 부위원장 이경혜 </b> 들어가셔도 좋습니다. 
</p>
<p><b>○ 증인 서춘기 </b> 감사합니다. 
</p>
<p><b>○ 부위원장 이경혜 </b> 그리고 한지양 감사실장님, 정말 억울하다고 말씀하시는데요. 억울하신 분의 표정으로는, 제가 이게 인권 유린, 인권 침해라고 생각지는 마십시오. 원래 표정이 그러신지 모르겠지만 끊임없이 위원들이 행감에 질의를 하고 있는 중에도 웃거나 턱을 괴거나 머리를 흔들면서 그 부분에 대한 여러 가지 태도를 갖고 계신 걸로는 저희가 볼 때는, 정말 억울함도 갖고 있을 수 있죠. 그럼에도 불구하고 이 행감이, 위원들을 바라보고 있는 한지양 감사실장님의 태도가 정말 그게 억울해서일까라는 생각을 자꾸 갖게 하거든요. 그래서 저는 이 부분에 대해서도 진정성 있게 받아들여 주셨으면 좋겠다라는 제안을 한번 드려 봅니다. 제가 무리한 요구를 드린 걸까요? 답변하기 어렵습니까? 
</p>
<p><b>○ 증인 한지양 </b> ……. 
</p>
<p><b>○ 부위원장 이경혜 </b> 지금도 똑같은 모습을 하시네요. 알겠습니다. 저희 기획재정위원회 위원들이 드리는 말씀들이 그 정도로 대답하기도 우스운 건지 잘 모르겠습니다. 저는 박진영 위원님께서 아까 말씀을 하셨고 이혜원 부위원장님께서도 말씀을 하셨어요. 행정조사에 대해서 말씀을 하셔서 저희가 어떻게 해야 될지 고민을 하고 있는 중인데 저희 검토를 하겠지만……. 잠시만요, 제가 지금 추가질의 중이어서요. 
</p>
<p><b>○ 이석균 위원 </b> 의사진행발언을 좀 하려고 합니다. 
</p>
<p><b>○ 부위원장 이경혜 </b> 제 추가질의 끝나고 하시면 좋지 않을까 싶은데요. 
</p>
<p><b>○ 이석균 위원 </b> 아니, 지금 질의를 하고 말씀을 하는데 대답이 없는 경우는 이거는 무슨 일입니까? 
</p>
<p><b>○ 부위원장 이경혜 </b> 그래서 제가 마무리하고 나면 이석균 위원님 다시 말씀해 주시면 좋겠습니다. 
</p>
<p style="padding-left:1.2em">  그래서 정말 저희가 행감의 태도를 첫날부터 끊임없이 말씀을 드렸어요. 모든 집행부의 직원분들이 다 이러신 건 아니에요. 특정 몇 분 때문에 저희가 끊임없이 이 이야기를 해야 되는 것들도 집행부에 대단히 송구스럽게 생각을 하고요. 오늘 추가질의를 이렇게 끊임없이 해야 되는 이유도 아트센터의 문제인데 감사실장님 억울한 부분 있을 수 있습니다. 그러면 감사위원회에 저희 다 같이 해서 행정조사하는 것도 저도 제안드려 봅니다. 함께 어떤 부분이 문제인지 어떻게 풀어야 되는지 감사위원회에서 다 같이 한번 다시 행정조사할 수 있도록 저희가 조치하는 논의를 좀 해 보는 것까지 제안을 드리면서 제 추가질의는 마치겠습니다. 
</p>
<p style="padding-left:1.2em">  이제 윤석균 위원님 의사진행발언하십시오. 
</p>
<p><b>○ 이석균 위원 </b> 네, 의사진행발언하겠습니다. 시간이 오래된 거 맞아요. 그다음에 많은 질문과 대답이 오간 것은 맞습니다. 저도 웬만하면 오늘 일이 많음에도 불구하고 우리 상임위원회의 심각성으로 제가 자리를 안 떠나려고 해요. 그런데 우리 증인으로 나오신 분들이, 다는 아니죠. 그런데 질문을 하는데 대답을 안 하는 이런 경우는 도대체가 어디에 있는지, 이게 가능한 이야기인지 제가 좀 묻고 싶고요. 
</p>
<p style="padding-left:1.2em">  위원장님, 정회를 해서 적절한 조치를 논의했으면 좋겠습니다. 이게 행정사무감사입니까? 
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 알겠습니다. 그러면 이석균 위원님의 정회 요청이 들어와서 잠시 정회를 할까 합니다. 위원님들 동의하십니까? 
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 잠시 정회를 하도록 하겠습니다. 행감 중지하겠습니다. 
</p>
<p class=''ar''>(17시34분 감사중지)
</p>
<p class=''ar''>(17시41분 감사계속)
</p>
<p><b>○ 위원장 조성환 </b> 좌석을 정돈해 주시기 바랍니다. 성원이 되었으므로 감사를 속개하겠습니다. 
</p>
<p style="padding-left:1.2em">  앞서 우리 존경하는 위원님들께서 여러 질의를 해 주셨는데 답변과 관련된 태도에 대한 문제 제기가 있으셨던 것 같습니다. 감사실장님! 마이크 켜시고. 
</p>
<p><b>○ 증인 한지양 </b> 경기아트센터 감사실장 한지양입니다. 
</p>
<p><b>○ 위원장 조성환 </b> 우리 한지양 실장님께 많은 질의가 있었는데 답변하기 곤란한 사항이 좀 있으셨나요? 
</p>
<p><b>○ 증인 한지양 </b> 사실 억장이 막혀서 말이 안 나왔습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 오전에 우리 양우식 위원님께서 자료요청한 거 억울하신 부분들 서면으로 자료요청해 달라고 하셨는데 계속 감사받느라 작성을 못 하셨죠? 
</p>
<p><b>○ 증인 한지양 </b> 그렇기도 하고 그 사안은 정말 많은 양의 자료, 방대합니다. 그래서 여러 위원님께서 말씀하셨지만 저의 갑질이 제목이 되든 아니면 제가 위원님들께 보낸 편지가 주제가 되든 그 부분에 대해서 위원님들이 직접 나오셔서 저희 아트센터를 살펴봐 주시기를 바랍니다. 
</p>
<p><b>○ 위원장 조성환 </b> 네, 알겠습니다. 우리 공직자는, 저희 선출직을 비롯한 공직자는 도민들을 대표해서 일하기도 하고 또 도민들을 위해서 일하기도 하기 때문에 때로는 억울한 일이 있을 수 있어요. 억울함을 가질 수가 있어요. 그러나 의회에서 그러한 부분에 대한 표현방식은 조금 절제돼야 되고 그다음에 일단은 순응적인 태도를 가져야 합니다. 위원님들의 질의가 개별 위원님들의 질의가 아니고 선출직으로 선출된 도민들의 대표성을 갖고 질의를 하시는 것이기 때문에 억울함이 있다 하더라도 성실하고 충실하게 답변을 해 주신 이후에 그다음에 다른 절차들, 소통을 가져야 될 필요가 있거든요. 이 부분에 대해서는 동감하시죠? 
</p>
<p><b>○ 증인 한지양 </b> 네. 
</p>
<p><b>○ 위원장 조성환 </b> 그래서 질의를 하셨을 때 답변을 하지 않거나 그렇게 다른 태도로 있으시면 오해를 살 수 있습니다. 이 부분에 대한 부분 양지하시겠습니까? 
</p>
<p><b>○ 증인 한지양 </b> 네. 
</p>
<p><b>○ 위원장 조성환 </b> 그렇다고 하면 지금 위원님들이 요청하신 행정사무조사를 비롯해서 또 감사실장님이 해당 기관의 현장방문을 통해서 그러한 부분들을 살펴봐 주기를 원하시기 때문에 저희가 그런 부분들을 좀 면밀하게 보고 또 실장님의 의견도 충분히 듣고 직원들의 의견도 듣고 서로 이 부분에서 좀 과도한 부분이 있는지 없는지를 면밀히 살펴서 그런 조치들이 이루어지도록 할 테니까. 우리 서춘기 사장님! 동의하시죠? 나오셔서 답변해 주십시오. 이러한 방법에 대해서 다른 의견 있으십니까? 
</p>
<p><b>○ 증인 서춘기 </b> 저는 위원장님 말씀에 충분히 동의를 합니다. 그렇지만 저희 기관은 지금도 끊임없이 일을 해야 되는 기관입니다. 연말이 다가오고 있고. 그래서 위원장님께서 헤아려 주신다면 경기도와 저희가 자정적인 노력을 한번 해 보도록 하겠습니다. 2023년도, 2024년도 연속적으로 저희가 두 번에 걸쳐 감사를 받았습니다. 그러고 나서 지금 딱 6개월이 지났는데요. 6개월 동안에 저희가 많은 일이 일어났다고는 생각하지 않습니다. 혹시 감사에 미비된 점이 있다 할 수는 있어도. 그래서 그러한 부분에 대해서는 위원장님께서 양해해 주시고 위원님들께서 양해해 주신다면 저희 기관과 경기도가 적극적으로 협의해서 어떤 새로운 방향에 대한 모색을 하였으면 합니다. 이렇게 양해해 주셨으면 고맙겠습니다, 위원장님. 
</p>
<p><b>○ 위원장 조성환 </b> 기획조정실장님! 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 기획조정실장 이희준입니다. 
</p>
<p><b>○ 위원장 조성환 </b> 사장님이 이런 의견을 주셨는데 기조실장님 입장은 어떠하신가요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 이 부분은 지금 사장님 입장에서 기관 전체를 좀 고려해서 하신 말씀이신데요. 이 부분은 저희가 위원님들 판단하시면 그 부분 종합해서, 저희가 그 이행 여부는 위원님들이 종합적으로 판단해서 결정하시면 그에 따라서 후속적으로 해야 될 사항이라고 생각합니다. 
</p>
<p><b>○ 위원장 조성환 </b> 그런 필요성은 느끼시는 거죠? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 오늘 말씀 중에 위원님들이 부족함을 느끼신 분들이 많이 있는 것처럼 보이기 때문에 또 감사실장님께서도 충분히 조금 더 하시고 싶은 얘기도 있고 그런데 또 사장님께서는 기관 전체를 생각하시는 부분에서 이런 말씀을 주신 걸로 이해해서요. 그건 위원님들이 종합적으로 해서 판단하실 일이라고 생각합니다. 
</p>
<p><b>○ 위원장 조성환 </b> 네, 알겠습니다. 사장님 자리로 돌아가셔도 좋습니다. 
</p>
<p><b>○ 이채명 위원 </b> 의사진행발언하겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 이채명 위원님. 
</p>
<p><b>○ 이채명 위원 </b> 제가 사실은 경기아트센터의 사업과 관련해서 지금 수의계약이 98%였는데 95%로 많이 완화시켰다라고 말씀을 들었기 때문에 앞서 제가 자료요구를 했었습니다, 아까. 그런데 아직 자료를 받지 못했기 때문에 자료도 좀……. 지금 행감은 거의, 종합감사는 오늘 끝나는 거잖아요. 그래서 아까 실장님께서도 말씀 주셨지만 도의원이 직접 와서 한번 정밀하게 조사를 해 달라고 하셨는데 그 부분이 어떤 부분인지 간단하게 혹시 들을 수 있나요? 왜냐하면 저는 지금 아직 자료를 받아보지 못했기 때문에 추가적으로 제가 질의를 하지 못했습니다. 
</p>
<p style="padding-left:1.2em">  왜냐하면 아까도 경기예술방송국 같은 경우도 40억의 예산을 3년인가 투입시켰는데 보셨다시피, 아시다시피 조회수가 정말 현저히 떨어졌습니다. 한 건당 거의 20회 정도밖에 되지 않았거든요. 이런 부분에 대해서 투입 대비 효율이 굉장히 많이 떨어지는 이 부분에 대해서도 사실은 정책적인 감사도 저는 필요하다라는 생각이 들기 때문에 이 부분도 고려해서 저희가 어떤 방향으로 이 부분을 조사, 특별하게 좀 더 직접적으로 구체적으로 조사를 해야 되는지도 조금 방향 제시를 해 주셨으면 고맙겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 네, 박진영 위원님. 
</p>
<p><b>○ 박진영 위원 </b> 제가 행정조사에 대해서 언급한 건 엄밀히 말하면 경기아트센터는 문화체육관광위원회 쪽에 소속된 기관이고요. 제가 이쪽에서 행정조사를 하고자 하는 것은 그동안 많은 갑질신고가 있었는데 경기도 감사위원회에서 그 갑질신고에 대해서 정확하게 조사했는지 그리고 갑질이 실제로 있었는지. 저희는 감사와 관련된 업무하는 데를 감사하는 위원회이기 때문에 그런 부분에 대해서 저는 행정조사를 하고자 했던 거였었습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 네, 잘 알겠습니다. 소관 부서가 있고 또 소관 상임위원회가 있기 때문에 해당 상임위원회와 논의하고 또 양당 간 대표단하고 논의해서 이런 문제를 잘 매듭지을 수 있도록 협의하겠습니다. 협의해서 차후 일정을 잡을 테니까 그렇게 참고하시고 적극적인 협조를 부탁드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  그러면 더 이상 질의하실 위원님이 안 계시므로 질의 종결을 선포합니다. 
</p>
<p style="padding-left:1.2em">  이상으로 금일 예정되었던 기획조정실, 감사위원회, 도민권익위원회, 경기연구원과 경기주택도시공사 등 공공기관 소관 사항에 관한 종합감사를 모두 마치겠습니다. 내일은 균형발전기획실, 평화협력국, 감사위원회, 공공기관담당관과 경기평택항만공사를 포함한 2개 공공기관 등의 소관 사항에 관한 종합감사가 실시될 예정입니다. 
</p>
<p style="padding-left:1.2em">  이상으로 감사 종료를 선포합니다. 
</p>
<p class=''ar''>(17시50분 감사종료)
</p>
<p>(----,---- 부분은 경기도의회 회의규칙 제62조제1항에 따라 게재하지 아니하기로 한 부분임)
</p>
<p><hr /></p>
