insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2024.11.12. 화요일] 감사위원회, 도민권익위원회, 경기연구원 — 기획재정위원회 2024년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제11대 경기도의회 기획재정위원회</b> · 2024년도 행정사무감사(2024. 11. 08. ~ 2024. 11. 21.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=14879" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2024년도 행정사무감사
</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관: 감사위원회, 도민권익위원회, 경기연구원
</p>
<p><hr /></p>
<p>일  시: 2024년 11월 12일(화)
</p>
<p>장  소: 기획재정위원회 회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시17분 감사개시)
</p>
<p><b>○ 위원장 조성환 </b> 의석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제49조 및 동법 시행령 제41조, 경기도의회 행정사무감사 및 조사에 관한 조례에 따라 감사위원회 및 도민권익위원회 소관에 대한 2024년도 행정사무감사를 시작하겠습니다.
</p>
<p style="padding-left:1.2em">  감사위원 여러분 그리고 공직자 여러분! 안녕하십니까? 기획재정위원회 위원장 조성환입니다. 어제에 이어 계속해서 행정사무감사를 위해 수고해 주시는 위원님들께 감사드립니다. 공정하고 투명한 감사 운영으로 청렴한 경기도를 만들기 위해서 애쓰시는 안상섭 감사위원장, 장진수 도민권익위원장을 비롯한 관계공직자 여러분께도 감사의 말씀드립니다.
</p>
<p style="padding-left:1.2em">  그러면 오늘은 위원회 감사일정에 따라 감사위원회와 도민권익위원회 소관에 대한 2024년도 행정사무감사를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  오늘 이 자리에는 우리 위원회의 행정사무감사 활동을 모니터링하기 위해서 수원에서 조미현 님께서 수고해 주시고 특히 경상북도의회 정진오 서기관님께서 수고해 주십니다. 환영합니다. 또한 언론인이신 스카이데일리 강재규 기자님께서 취재 중이십니다. 기획재정위원회를 대표해서 감사 말씀드립니다.
</p>
<p style="padding-left:1.2em">  공직자 여러분께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 집행기관의 행정사무 전반에 관한 실태를 파악하여 잘못된 점을 시정ㆍ개선하고 나아가 2025년도 예산안 심사에 반영함은 물론 도민의 삶의 질 향상에 기여하는 것이 그 목적인 만큼 매우 중요한 의미가 있습니다. 따라서 감사에 임하는 집행기관 공직자분들께서도 본 위원회가 이번 행정사무감사를 통해 얻고자 하는 소기의 목적이 달성될 수 있도록 감사에 충실히 임해 주시기를 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 증인선서가 있겠습니다. 감사를 받는 안상섭 감사위원장과 각 부서장 및 장진수 도민권익위원장은 증인의 자격으로 소관 업무보고와 질의 답변에 앞서 선서를 하셔야 합니다. 선서를 하는 이유는 경기도의회가 2024년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위함입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제49조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조 규정에 의하여 고발될 수 있으며 정당한 사유 없이 선서 또는 증언을 거부한 때에는 동법 규정 및 동 조례 제31조에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 아울러 형사소송법 제148조 근친자의 형사책임과 증언거부 또는 제149조 업무상 비밀과 증언거부에 해당하는 때는 선서와 증언 그리고 서류 제출을 거부할 수 있음을 함께 알려드립니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석 여부를 확인하겠습니다. 피감사기관의 증인들께서는 모두 자리에서 일어나 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  안상섭 감사위원장 나오셨습니까? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 장진수 도민권익위원장 나오셨습니까?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 김상팔 감사총괄과장 나오셨습니까? 
</p>
<p><b>○ 감사위원회감사총괄과장 김상팔 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 이선범 감사1과장 나오셨습니까?
</p>
<p><b>○ 감사위원회감사1과장 이선범 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 성현숙 감사2과장 나오셨습니까? 
</p>
<p><b>○ 감사위원회감사2과장 성현숙 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 유용철 계약심사과장 나오셨습니까?
</p>
<p><b>○ 감사위원회계약심사과장 유용철 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 다음은 선서의 요령에 대해 설명드리겠습니다. 선서는 증인들을 대표해서 안상섭 감사위원장께서 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손을 들어주시면 되겠습니다. 그러면 증인들께서는 선서를 해 주시기 바랍니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 선서! 본인은 경기도의회가 지방자치법 제49조, 같은 법 시행령 제41조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2024년도 행정사무감사를 실시함에 있어 증인으로서 성실하게 감사를 받을 것이며 또한 증언을 함에 있어서는 지방자치법 시행령 제46조제6항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로를 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2024년 11월 12일 경기도 감사위원회 위원장 안상섭.
</p>
<p><b>○ 위원장 조성환 </b> 모두 자리에 앉아 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  이상으로 증인선서를 마치고 간부소개와 업무보고를 받도록 하겠습니다. 안상섭 감사위원장 나오셔서 간부소개와 업무보고를 해 주시기 바랍니다. 일단 간부소개 먼저 해 주시죠.
</p>
<p><b>○ 감사위원장 안상섭 </b> 안녕하십니까? 경기도 감사위원장 안상섭입니다. 감사위원회 출범과 운영에 아낌없이 지원과 협조를 해 주신 기획재정위원회 조성환 위원장님과 여러 위원님들 모시고 2024년 감사위원회 주요업무에 대하여 보고드리게 됨을 매우 뜻깊게 생각합니다.
</p>
<p style="padding-left:1.2em">  먼저 업무보고에 앞서서 감사위원회 간부공무원을 소개해 드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  김상팔 감사총괄과장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이선범 감사1과장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  성현숙 감사2과장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  유용철 계약심사과장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  효율적인 업무보고를 위해서 배부해 드린 책자를 중심으로 일반현황과 주요기능, 주요성과와 핵심업무 추진상황, 그밖의 주요업무 추진상황 순으로 말씀드리겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 3쪽과 4쪽 일반현황입니다. 감사위원회 기구는 현재 4과 19팀이며 인력은 현재 정원 103명에 현원 114명입니다. 올해 세출예산 규모는 총 22억 8,600만 원으로 주로 사무공간 임차료 등을 위한 사무관리비, 여비 등 경상적 경비입니다. 주요기능은 위원님들께서 양해해 주시면 유인물로 갈음하고자 합니다.
</p>
<p style="padding-left:1.2em">  다음 7쪽입니다. 2024년도 주요성과를 보고드리겠습니다. 먼저 감사위원회 출범입니다. 출범 이후 도의회 추천 2명을 포함한 감사위원 6명을 위촉하였고 광역지자체 최초로 경기도 감사 규칙에 인권 존중의 감사를 제1원칙으로 명시하는 등 감사운영규정도 마련하였습니다. 감사위원과 전 직원이 참여하는 청렴서약식 및 도민권익위원회, 도민감사관 등이 함께 “도민의 눈으로, 도민의 손으로, 도정을 살피다.”라는 통합 비전 선포식을 개최하였습니다. 위원회 1호 안건으로는 광역지자체 중 가장 넓은 적극행정 면책 범위를 담은 경기도 감사위원회 적극행정 면책 규정을 의결하였고 감사권익보호관 제도를 적극행정을 지원하기 위해 확대 아울러 개편하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 8쪽입니다. 금년도 계획된 종합감사와 특정감사를 차질 없이 수행 중에 있습니다. 특히 생활밀착형 특정감사를 통해 도민의 안전을 강화하였습니다. 5월에는 장마철 침수 대비로 지하차도와 배수시설을 점검하여 고장 난 지하차도 펌프에 대한 조치 등을 요구하였고 7월에는 아리셀 화재 후 대형화재 리스크를 선제적으로 예방하기 위해 소방재난본부와 합동으로 안전ㆍ화재 취약 사업장에 대한 긴급 특정감사를 실시하였습니다. 9월에는 임산부 전용 주차구역 관리실태를 점검하여 지적사항에 대한 조치를 요구하였고 도청 감독 부서에도 안전한 설치기준을 마련하도록 제도 개선을 통보하였습니다. 청렴하고 공정한 공직문화 조성을 위해 청렴실천 선언식과 청렴이음 페스타를 개최하였으며 청렴 교육 4시간 의무 이수제를 도입해서 2026년 1월 1일 이후부터는 승진임용 시부터 적용할 예정입니다. 공익제보 활성화를 위해 전국 최초 공익제보 안심전화번호 서비스를 도입하고 공익제보자에 대한 보상금과 포상금 7,686만 3,000원을 지급하였습니다. 공직자 8,066명에 대한 재산 등록, 재산 공개, 재산 심사를 추진하여 깨끗한 공직사회를 구현하고 계약 심사를 통해 1,930건의 사업 중 379억 원을 조정하여 재정건전성 향상을 도모하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 핵심업무 추진상황을 보고드리겠습니다. 13쪽입니다. 도민 중심의 새로운 감사 운영체계 확립입니다. 도민으로부터 신뢰받는 감사행정 구현을 위해 경기도 감사 규칙 등 자치법규를 제정하였고 감사위원회 구성 후 네 차례 회의를 개최하여 위원회 자체 규정과 감사 결과 등을 심의 의결하였습니다. 앞으로 도민 중심의 감사 정책을 차질 없이 추진해 나가도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  14쪽입니다. 감사 혁신을 위한 감사정보시스템 구축입니다. AI, 디지털 전환 등에 선제적으로 대응하기 위한 데이터감사팀을 광역지자체에 최초로 설치하였으며 핵심 사업으로 감사정보시스템 구축을 추진하고 있습니다. 감사정보시스템은 각 기관에서 운영 중인 행정정보시스템과 연계하여 수감기관의 감사자료 제출 부담을 완화하고 감사업무 전산화로 업무 효율성을 제고하는 등 궁극적으로 도민 중심, 수요자 중심의 신뢰받는 감사시스템을 구현하는 것을 목표로 하고 있습니다. 기획재정위원회에서 지난 추경에 예산을 반영해 주셔서 용역사업을 선정하였고 지난주 착수보고회에는 조성환 위원장님, 박상현 위원님, 이석균 위원님 그리고 또 외부에서 행정안전부 감사관 등 여러 전문가들을 모시고 추진 방향, 추진 일정 등을 심도 있게 논의하였습니다. 바쁘신 의정활동 가운데도 특별히 시간을 내어서 많은 조언을 해 주신 것에 대해 이 자리를 빌려 다시 한번 감사의 말씀을 드립니다. 참고로 감사원 디지털감사국과 행정안전부 감사관실에서도 지방자치단체 최초로 감사시스템을 도입하는 데 큰 관심을 보이고 있으며 적극적인 자문과 지원을 약속한 바 있습니다. 향후에는 시군, IT전문가 등과 협의체를 구성하고 용역이 진행되는 과정에서도 위원님들께 보고드리면서 성공적으로 시스템이 구축될 수 있도록 만전을 기하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음 17쪽입니다. 적극행정 지원을 통한 일하는 공직문화 조성입니다. 9월 말 현재 총 91건의 사전 컨설팅 감사를 통해 현장 공무원의 적극행정을 지원하였고 도민 홍보를 실시하였으며 역량강화를 위한 자체 워크숍도 2회 개최하였습니다. 올해 2월에는 2023년 운영실적 평가 결과에 따라 대통령 기관표창을 수상하기도 하였습니다. 또한 적극행정을 지원하기 위한 감사권익보호관의 운영 근거를 경기도 감사위원회 감사사무 처리 규정에 명시하였습니다. 앞으로 감사권익보호관이 독립적인 위치에서 수감자의 적극행정에 관한 소명을 지원하도록 운영할 계획입니다. 일하는 공직자를 보호하기 위해 적극행정 면책 범위를 광역 최대 수준으로 확대하되 다만 감사를 느슨하게 하거나 감사를 면제받기 위한 제도로 활용되지 않도록 제도 취지에 걸맞게 운영하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  18쪽입니다. 감사 내실화를 통한 청렴하고 공정한 직무수행 지원입니다. 종합감사는 총 9개소에 대해 실시하였는데 이 중 7개소는 조치가 완료되었고 하남시와 남양주시는 후속조치를 진행 중에 있습니다. 또한 침수 대비, 임산부 보호, 화재 예방 등 도민 안전을 위한 감사, 로컬푸드 직매장 지원사업 등 도정 모니터링을 통한 감사 등 총 9회에 걸쳐 특정감사와 광주시 주택부지 조성 허가 관련 주민감사청구 등 총 19회의 감사를 추진하였습니다. 현재 성남시 종합감사, 건설폐기물 처리기준 관리실태 및 빅데이터 활용 특정감사 2건, 연천군 산업폐기물 매립장 관련 주민감사청구 등 총 4건의 감사를 추진 중에 있습니다. 
</p>
<p style="padding-left:1.2em">  다음 21쪽입니다. 공공기관 자체감사 체계 확립을 통한 책임경영 지원입니다. 올해 2년 차를 맞이한 공공기관 감사협의체는 정기회의와 소그룹 모임을 각각 두 차례 실시하였고 경기도 공공기관 일상감사 운영지침, 공공기관 감사업무 매뉴얼을 제작ㆍ배부하는 등 공공기관 자체감사 체계 확립을 지원하였습니다. 공공기관의 감사역량을 강화하기 위해 감사 담당자 실무교육을 실시하였으며 경기아트센터 등 공공기관에 대한 종합감사 3회, 특정감사 2회를 실시하였습니다. 앞으로도 공공기관 자체감사기구와 소통 협력을 지속하고 공공기관 제보 사건에 대한 맞춤형 조사를 통해 부패이슈를 책임 있게 관리해 나가도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  22쪽입니다. 도민과 함께하는 감사 추진입니다. 8월 26일 대한민국 미래를 밝히는 청렴 약속을 슬로건으로 청렴사회민관협의회와 함께 청렴이음 페스타를 개최하였습니다. 또한 도민감사관이 참여하는 총 11건의 종합감사 및 특정감사를 실시하였으며 10월 8일에는 성과보고회를 열어 우수사례를 발표하고 참여실적이 우수한 도민감사관 및 또 시군의 시민감사관 총 8명에게 도지사 표창을 수여하였습니다. 한편 내실 있는 계약심사제도 운영을 위해 7월 20일부터 제5기 원가분석자문단 85명을 구성하여 운영하고 있습니다
</p>
<p style="padding-left:1.2em">  다음 주요업무 추진현황에 대해 말씀드리겠습니다. 25쪽입니다. 올해는 국민권익위원회 종합 청렴도 평가에서 2등급 이상 달성을 목표로 다양한 정책, 청렴 시책을 시행하였습니다. 앞으로도 부패 취약 분야를 중점 개선하기 위해 청렴ㆍ반부패 시책을 전략적으로 추진하겠습니다. 
</p>
<p style="padding-left:1.2em">  26쪽입니다. 도민 눈높이에 맞는 엄정한 공직기강 확립을 위해 이슈와 중점 분야를 중심으로 맞춤형 공직기강 조사를 강화하였습니다. 공직비위를 사전에 예방하기 위한 감찰활동과 공직비위 조사 과정의 공정성과 전문성도 높이기 위한 다양한 노력을 기울이고 있습니다. 일하는 공직사회 조성을 위한 소극행정 특별조사와 고질적 비위행위에 대한 집중 점검도 소홀함이 없이 추진토록 하겠습니다.
</p>
<p style="padding-left:1.2em">  27쪽과 28쪽입니다. 계약 심사는 자치단체에서 발주하는 공사, 용품, 물품 등의 입찰ㆍ계약을 위한 기초금액과 설계변경 증감액의 적정성을 심사하는 제도입니다. 적정원가 심사를 통해 사업의 품질과 안전을 확보하고 원가분석자문단을 통해 전문성과 신뢰성을 높이고 있습니다. 또한 이행 실태점검 등 사후관리를 통해 계약심사제도의 이행력을 확보하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 29쪽입니다. 위원님들께서 양해해 주신다면 2022년 행정사무감사 처리 결과는 배부해 드린 유인물로 갈음하고자 합니다. 
</p>
<p style="padding-left:1.2em">  감사위원회 출범을 감사 혁신의 새로운 출발점으로 삼아 도민이 직접 체감할 수 있는 의미 있는 변화를 이끌기 위해 노력하겠습니다. 또한 오늘 업무보고를 통해 위원님들께서 주시는 조언들을 감사위원회에 반영하기 위해 최선을 다하고 주요 추진사항에 대해서 적극적으로 소통하겠습니다.
</p>
<p style="padding-left:1.2em">  이상으로 감사위원회 소관 주요 업무보고를 마치겠습니다. 감사합니다.
</p>
<p><hr /></p>
<p>업무보고서(감사위원회)
</p>
<p><hr /></p>
<p><b>○ 위원장 조성환 </b> 안상섭 감사위원장 수고하셨습니다. 이어서 장진수 도민권익위원장 나오셔서 업무보고해 주시기 바랍니다.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 안녕하십니까? 도민권익위원장 장진수입니다. 존경하는 조성환 기획재정위원회 위원장님과 여러 위원님들을 모시고 2024년 행정사무감사 도민권익위원회 소관 업무보고를 드리게 됨을 매우 뜻깊게 생각합니다. 
</p>
<p style="padding-left:1.2em">  배부해 드린 유인물을 중심으로 업무보고를 드리겠습니다. 보고드릴 순서는 일반현황, 2024년도 주요업무 추진현황, 2022년도 행정사무감사 지적사항 처리 결과 순입니다. 
</p>
<p style="padding-left:1.2em">  먼저 3쪽 일반현황입니다. 도민권익위원회 기구는 1위원회 5팀이며 인력은 정원 30명에 현원은 공무직 포함 32명입니다. 
</p>
<p style="padding-left:1.2em">  다음은 4쪽입니다. 금년도 세출예산 규모는 총 3억 5,300만 원으로 주로 사무관리비와 공공운영비 등 경상적 경비가 되겠습니다. 
</p>
<p style="padding-left:1.2em">  이어서 주요기능은 위원님들께서 양해해 주신다면 유인물로 갈음하고자 합니다.
</p>
<p style="padding-left:1.2em">  다음은 5쪽 비전 및 전략 목표입니다. 도민권익위원회 비전은 도민이 만족하는 권익 보호로 변화의 경기 구현이며 이를 실천하기 위한 전략 목표를 소통ㆍ현장 중심의 도민권익 보호, 도민 참여 확대로 신뢰받는 도정 그리고 갑질 근절로 상호 존중의 공직문화 확산으로 설정하여 추진하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 2024년도 주요업무 추진현황입니다. 먼저 11쪽 도민권익 보호 중심의 도민권익위원회 운영입니다. 도민권익위원회는 위원님들의 관심과 지원으로 지난 9월 2일 독립된 합의제 행정기관으로 출범하였습니다. 위원회는 위원장 포함 7명으로 구성되어 있으나 현재 기존 옴부즈만의 임기 보장 규정에 따라 현재 11명으로 위원회를 운영하고 있습니다. 도민권익위의 주요기능은 도민의 권익 보호와 권리 구제를 위한 정책 발굴과 고충민원을 처리하고 있으며 도민 참여 기반의 공공사업 감시ㆍ평가, 도민감사청구제도 등을 도입하여 이에 관한 사항을 심의 의결하고 있습니다. 지난 10월 8일에 비전 선포식과 1차 정례회의를 개최하였으며 향후 도민 권익보호기관으로서 도민권익위원회의 성공적 운영을 위해 노력해 나가겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 12쪽 도민에 의한 행정감시, 도민감사청구입니다. 도민감사청구는 도민참여의 일환으로 도 관할 사무처리가 위법ㆍ부당하다고 판단될 경우 도민이 감사를 청구할 수 있는 제도입니다. 감사가 청구되면 도민권익위원회의 심의를 통해 실시 여부를 결정하고 실시 결정일로부터 60일 이내에 감사를 종료하고 결과를 통보하도록 하고 있습니다. 11월 중 도민권익위원회 심의를 거쳐 운영계획을 수립한 후 도민감사청구를 실시할 예정으로 제도 안내 등 홍보에 만전을 기하여 도민감사청구 활성화에 노력하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 13쪽 도정의 공정성 강화를 위한 공공사업 감시ㆍ평가입니다. 도민 참여에 의한 도정의 감시ㆍ평가 활동으로 도에서 추진하는 공사, 용역, 물품구매, 보조사업 전반을 도민참여옴부즈만이 감시ㆍ참관하는 제도입니다. 파급효과 등을 고려하여 도민 관심사업과 도 정책사업을 선정하여 계약이행 과정을 감시하는 중점감시와 계약상대자 선정 과정에 참관하는 참관활동을 추진하고 있습니다. 11월 말부터 공공사업 감시ㆍ평가를 시범운영하고 감시ㆍ참관 활동과 갑질 상담ㆍ조사 등 분야별 자문 역할을 수행하는 도민참여옴부즈만은 공개모집과 추천을 받아 위촉할 예정입니다.
</p>
<p style="padding-left:1.2em">  다음은 14쪽 갑질 근절을 위한 전문적ㆍ체계적 신고ㆍ처리 운영입니다. 도민권익위원회에 갑질 및 직장 내 괴롭힘에 대한 전담조직인 갑질피해 신고ㆍ지원센터를 설치해 갑질 신고 접수ㆍ상담 및 조사, 피해자 보호 등의 업무처리를 일원화하였습니다. 갑질 여부와 피해자 보호조치를 결정하는 갑질 행위 전담 심의위원회를 운영하여 전문적ㆍ체계적인 신고ㆍ처리가 이루어지도록 하겠습니다. 2차 피해 방지 등 피해자 권익보호에 더 집중하고 갑질 인식 개선 교육 등을 통해 구성원이 상호 존중받는 조직문화의 확산을 위해 노력하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 15쪽 고충민원 처리로 도민권익 보호 및 확대입니다. 도민권익위원회는 고충민원 조사ㆍ처리 전담기관으로 도에 접수된 고충민원과 중앙부처에서 이첩된 고충민원 등 2024년도에 총 3,653건을 접수하여 처리하였습니다. 향후 고충민원 조사ㆍ처리에 전문가 참여로 제도개선 필요사항을 적극 발굴하고 적극적인 고충민원 조사ㆍ처리로 도민의 권익구제 및 신뢰성을 제고해 나가겠습니다.
</p>
<p style="padding-left:1.2em">  마지막으로 19쪽 2022년도 행정사무감사 지적사항 처리결과입니다. 2022년도 행정사무감사 시 위원님들께서 지적해 주신 사항들은 조치 완료하였습니다. 주요내용은 위원님들께서 양해하여 주신다면 유인물로 갈음하고자 합니다.
</p>
<p style="padding-left:1.2em">  도민권익위원회의 성공적 운영을 위해 조성환 위원장님을 비롯한 여러 위원님들의 아낌없는 관심과 지원을 부탁드리며 저를 비롯한 도민권익위원회 전 직원이 도민의 눈높이에서 도민의 고충을 처리하고 도민의 권익보호와 권리구제에 최선의 노력을 다하겠습니다.
</p>
<p style="padding-left:1.2em">  이상으로 도민권익위원회 소관 주요 업무보고를 마치겠습니다. 감사합니다.
</p>
<p><hr /></p>
<p>업무보고서(도민권익위원회)
</p>
<p><hr /></p>
<p><b>○ 위원장 조성환 </b> 장진수 도민권익위원장님 수고하셨습니다.
</p>
<p style="padding-left:1.2em">  다음은 질의 답변 순서입니다. 어제와 마찬가지로 본질의 10분 이내로 하고 보충질의는 5분 이내로 하겠습니다. 일문일답 형식으로 진행하고요. 우리 집행기관 간부분들 답변 주실 때에는 짧고 명료하게 답변해 주시면 되겠습니다. 추가질의는 별도 신청을 받아서 진행할 예정입니다. 또 구체적이고 실무적인 내용은 우리 소관 부서장께서 답변하셔도 좋습니다. 다만 사전에 위원장께 동의를 구하고 발언대로 나와 소속과 직ㆍ성명을 밝히고 답변을 해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 질의에 앞서서 자료 요청을 받도록 하겠습니다. 자료 요청하실 위원님들 많으신데요, 일단 박진영 위원님.
</p>
<p><b>○ 박진영 위원 </b> 경기도 감사위원회에 자료 요청드립니다. 2024년 경기아트센터 종합감사계획 변경 통보 기간 연장 관련해서요, 이 연장 관련된 결재서류 문서 일체 좀 부탁드리겠습니다. 그리고 지금 감사위원회에 지속적으로 여러 가지 자료를 요청드렸는데 다른 위원님의 의견을 들어봐도 공공감사에 관한 법률 제20조제5항에 따라서 주실 수 없는 자료가 상당한 것 같은데 저희 행정사무감사에 대해서 저희가 정보제공을 요청하는 게 지방자치법이랑 지방자치법 시행령에 보장되어 있는데 이 법률 간의 상충관계에 대한 법령 해석서 또는 법률 검토의견서 있으시면 부탁드리겠습니다. 그리고 추가적으로 내부적으로 자료의 성격, 생산 주체, 내용 분류에 따라서 공개대상 범위에 대해서 지침을 정해 놓은 거나 법률 검토하신 거 있으시면 부탁드리겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 다음은 이석균 위원님.
</p>
<p><b>○ 이석균 위원 </b> 우리 도민권익위원회에 출연ㆍ출자ㆍ보좌기관 등 공공기관 감시ㆍ평가 실적이 있으면 제출해 주시되 여기 출범한 지 얼마가 안 된 부분들이 있어서 출범한 이후의 자료와 하기 이전의 이런 공공기관에 대한 감시ㆍ평가 자료 있으면 제출을 해 주시고요.
</p>
<p style="padding-left:1.2em">  우리 감사위원회는 22년, 23년 종합 청렴도 평가 결과를 지표별로 요약해서 자료를 주시는데 요약된 표로 된 거 그것만 주지 마시고 뒤쪽에 청렴도 분석해 있는 그 내용 중에 요약된 게 있어요. 그것까지 해서 22년, 23년 제출해 주시고 그다음에 8개 위원회 심의회, 협의회 회의 개최현황을 회의별로 정리를 해 주시되 위원회명, 기능, 회의 방식, 회의 차수, 회의 내용 양식으로 제출해 주시기 바랍니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 다음은 이채명 위원님 자료 요구해 주시기 바랍니다.
</p>
<p><b>○ 이채명 위원 </b> 자료 요청드리겠습니다. 어제 제가 기획재정위원회 공공기관담당관에 자료 요청했던 내용들인데요. 아직까지 사실은 자료가 오지를 않고 있어서 구체적으로 자료를 오늘 저희가 도민권익위원회 그리고 감사위원회에다가 질의할 내용과 겹쳐 있기 때문에 다시 한번 재차 자료 요구를 드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  공공기관의 과도한 시간외근무 상황인데요. 특히나 경기문화재단, 경기아트센터, 경기도사회서비스원 그리고 킨텍스 관련해서 주시고요. 그리고 최근 공공기관 3년간, 앞서 제가 말씀드린 4개 기관이죠. 3년간 차량 운행일지를 자료로 주시기 바랍니다. 또 그리고 지금 공공기관에 주 52시간 초과근무한 곳이 102시간, 특히 경기아트센터 같은 경우는 129시간을 초과근무를 했습니다. 근데 경기문화재단은 제가 직접 행정사무감사 전에 방문을 했는데 감시단속적근로자다라고 얘기를 하시더라고요. 그래서 예외조항이 있긴 하지만 그래도 혹시나 이거는 감사위원회에서 점검하고 검토했는지를 알아보기 위해서 그러면 나머지 아트센터라든가 사회서비스원, 킨텍스 같은 경우도 감시단속적근로자인지 확인 여부까지 해서 부탁을 드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  또 한 가지입니다. 지금 자료 8페이지에 보면 내실 있는 종합감사로 기관운영의 건전성과 투명성을 개선하기 위해서, 작년이죠. 올해인가 공공기관의 감사를 시행했다라고 했습니다. 그중에서 아트센터가 기관 감사를 받은 것으로 알고 있는데요. 관련된 감사 내용과 그리고 결과조치 관련해서 자료로 제출해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그리고 감사위원장님께 다시 한번 더 말씀드리는데 혹시 올해 경기아트센터 기관 감사의 주요내용은 어떤 사안인지, 감사가 완료된 것으로 알고 있는데요. 이것을 요약해서 서면으로 답변해 주시기 바랍니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 또 자료 요청하실 위원님, 이성호 위원님.
</p>
<p><b>○ 이성호 위원 </b> 용인 출신 이성호 위원입니다. 감사위원회 행정사무감사 요구자료 255페이지에 사업보조금의 목적 외 사용 및 관리 부실 2023년 지적사항 관련해서 현재 추진 중으로 되어 있는데 구체적인 현재 추진 내용하고, 구체적인 채권추심을 위해서 지금 현재 추진하고 있는 내용을 제출해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그리고 257페이지 맨 밑에 경제실 자금 관리ㆍ운영 위ㆍ수탁계약 업무 소홀 관련해서 처분요구서 제출해 주시고요.
</p>
<p style="padding-left:1.2em">  그리고 329페이지에 외부강의 상세내역이 있는데 이 강의료가 적정한지 판단하려면 어떤 직위에 있고 이런 내용이 있어야 되는데 전혀 그런 게 없거든요. 그 강사가 어떤 자격으로 하는 건지 그런 내용하고 원래 성명도 다 제출을 해야 되는 내용입니다. 개인정보로 거부할 수 없는 내용이기 때문에 최소한 어떤 직위에 근거해서 이게 강의를 하고 있는 건지 그런 내용을 제출해 주시기 바랍니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 다음은 양우식 위원님 자료 요구해 주시기 바랍니다.
</p>
<p><b>○ 양우식 위원 </b> 양우식 위원입니다. 자료 요구하겠습니다. 한 2주 전에 언론상에 공개되었던 경기도 공무원 뇌물사건 거기에 연루된 경기도의원 관련된 문제 지금 어떻게 진행되고 있고 내용이 어떻게 됐었던 건지 사건 발생 이후부터 인지하고 있었던 내용에 대해서 어디 어느 곳에 보고를 했고 어디 어디 공유가 되었는지 등등 세부적으로 날짜별로 정리해서 제출해 주시고요.
</p>
<p style="padding-left:1.2em">  두 번째 자료 요구는 저희 의회 의사담당관실에서 허위 공문서 작성 공무원 관련해서 감사위원회에다가 감사 요청 자료를 보낸 걸로 알고 있습니다. 그 내용이 어떻게 되었고 의회에서 보낸 공문들하고 지금 현재 조치사항들까지 세부적으로 작성해서 보고 바랍니다. 제출해 주십시오. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 다음은 이경혜 위원님 자료 요구해 주십시오.
</p>
<p><b>○ 이경혜 위원 </b> 이경혜입니다. 저는 감사위원회에 부탁드리겠습니다. 감사정보시스템 정보화 전략 관련해서 지난번에 추진하는 자료를 요청 좀 드리려고 하는데요. 데이터 작성하는 거 관련해서, 정보시스템 관련해서 프로그램 개발비용하고 유지비용에 대한 예산 책정 그리고 업체 선정 방식에 대한 계획안을 자료로 제출해 주시기 부탁드립니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 이경혜 위원님 수고하셨습니다. 계속해서 자료 요청하실 위원님. 박상현 위원님 요청해 주십시오.
</p>
<p><b>○ 박상현 위원 </b> 감사위원회는 한 가지 자료를 부탁드리겠습니다. 감사정보시스템 구축을 위한 스마트 감사 TF 구성 및 운영에 관련된 자료 1건 부탁드리고요.
</p>
<p style="padding-left:1.2em">  도민권익위원회 부탁드리겠습니다. 민원이 발생해서 도민권익위에서 민원을 처리할 때 관련된 절차와 물론 불가능한 건 알겠지만 평균적으로 소요되는 시간을 살짝만 기재를 해서 주시면 좋을 것 같습니다. 평균입니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 수고하셨습니다. 다음은 이혜원 위원님 자료 요구해 주십시오.
</p>
<p><b>○ 이혜원 위원 </b> 이혜원 위원입니다. 먼저 도민권익위원회 갑질 근절을 위한 신고ㆍ처리현황을 제출해 주시는데요. 23년도, 24년도 현재까지에 대한 현황을 제출해 주시되 14페이지 갑질 신고 접수 및 처리 프로세스 지금 여기는 6단계를 넣으셨습니다. 신고 접수, 조사 및 피해자 보호, 갑질 전담심의위원회 심의ㆍ의결, 결과 통보, 처분 요구, 징계 등 처분. 여기에 두 단계를 더 더하겠습니다. 사후관리와 재발 여부와 방지대책까지 8단계로 해서 지금 신고ㆍ처리현황에 대한 부분들을 자료 정리해서 제출해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  두 번째입니다. 감사위원회에 자료 요구하겠습니다. 감사가 이번에도 공공기관 감사하는 데 오해를 하셨다고 하셨습니다. 거기에 경기아트센터 관련해서 자료 요구한 내용이 있었는데 지금 2건이, 제가 자료 요구한 내용 중에 2건이 미제출이 됐습니다. 그 이유를 써놓으신 거 보니까……. (전문위원실 직원을 향하여) 이거 혹시 표출 가능합니까? 경기아트센터 종합감사 조사 추진현황 관련된 표출자료 띄워주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  여기 내용 보시면 저한테 제출하지 못한 이유를 “공공감사에 관한 법률 제20조제5항 및 지방자치단체에 대한 행정감사규정 제11조제5항에 해당되어 미제출함을 양해바란다.” 이렇게 하셨어요, 2건을 다.
</p>
<p style="padding-left:1.2em">  제가 다시 한번 자료 요구 좀 하겠습니다. 이게 뭐 때문에 자료 요구를 못 하시는지 모르겠어요. 이 공공감사에 관한 법률과 지방자치단체에 대한 행정감사규정은 자료를 감사 목적 외의 용도로 사용해서는 안 된다고 명시되어 있습니다. 본 위원이 자료 제출을 요구한 것은 명백히 감사 목적을 위해서 요구한 겁니다. 만약에 개인정보나 이런 부분들이 들어가 있고 수집 동의가 안 되어 있다고 하면 저 혼자 볼게요. 그리고 다른 부분에 사용하지 않겠습니다. 감사 목적에만 쓰겠습니다. 현황 파악하는 데만 쓸 테니까요, 제출해 주시고.
</p>
<p style="padding-left:1.2em">  두 번째 반박 논리입니다. 지방자치법 제49조 행정사무 감사권 및 조사권은 행정사무감사를 위해 자료 제출 요구할 수 있다고 되어 있습니다. 그리고 경기도의회 행정사무감사 및 조사에 관한 조례 제12조에 근거하여 경기아트센터의 행정사무감사를 위한 자료 요구임을 밝힙니다.
</p>
<p style="padding-left:1.2em">  그렇기 때문에 제가 기요구자료 중에 미제출한 감사 과정에서의 분석 근거자료와 종합감사 결과보고서, 비공개 처리되지 않은 원본 보고서를 개별 제출할 것을 다시 한번 요구드립니다.
</p>
<p style="padding-left:1.2em">  그리고 지금 기획조정실 실장님 계시죠? 지금 46건을 어제 위원님들이 자료 요구하셨는데 미제출됐습니다. 지금 어제부터 계속적으로, 어제 하루 종일 감사 행태나 태도에 대해서 저희가 계속 지적을 했습니다. 어떤, 감사받으시는데 질문에 대답도 못 하시고 자료를 찾아서 주는 부분들도 신속하게 이루어지지 않고 자료 요구를 했으나 자료가 오지 않아서 저희가 질문하는 데도 계속 방해를 받고 있고. 이것은 감사를 못 하게 하시려고 작전들을 짜신 건지 좀 의심스럽습니다.
</p>
<p style="padding-left:1.2em">  위원장님, 자료가 다 제출되지 않은 상태에서 감사를 시행하는 것은 실효성이 좀 미흡하다고 봅니다. 정회 요청합니다.
</p>
<p><b>○ 위원장 조성환 </b> 지금 정회 요청이 들어왔는데요. 자료 추가 요청, 이채명 위원님 먼저 하시죠.
</p>
<p><b>○ 이채명 위원 </b> 감사위원회 관련해서 추가적으로 더 하나, 2023년과 2024년 전체 우리 경기도 공공기관의 자체감사를 실시해서 징계조치나 결과에 대해서 취합해서 자료로 제출해 주시기 바랍니다. 그리고 혹시나 경기아트센터 감사 내용과 감사 결과에 대해서도 이거는 따로 저한테 별도로 보고해 주시기 바랍니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 기획조정실장님 나오셨죠?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 기획조정실장 이희준입니다.
</p>
<p><b>○ 위원장 조성환 </b> 어제 자료 요청을 한 것 중에 제출이 안 돼 있다고 지금 말씀을 하시는데 이거 보고받으셨습니까?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 오늘 아침에도 과장들 회의했고요. 위원님들 지금 요구하신 것 중에, 저희가 체크해 보니까 위원님들 요구하신 것 중에 한 10건 정도가 지금 현재 미제출이 돼 있는데 그중에 대부분이 공공기관담당관을 통해 공공기관에서 받아야 되는 자료들입니다. 그래서 지금 현재 공공기관에 계속 저희가 촉구하고 있고요. 저희가 그 부분을 받아서 제출을 해야 되는 상황이다 보니까 조금 지체되고 있다는 말씀드리고요. 최대한 지금 독려 중에 있다는 말씀드립니다.
</p>
<p><b>○ 위원장 조성환 </b> 어제 제가 말씀드렸는데 제출이 안 되면 위원님들께 설명을 드리라고 했었고. 지금 이 요구자료 목차를 보니까 옴부즈만의 역할 정리 자료 요구가 돼 있는데 미제출됐어요. 이거 시간 걸리는 겁니까? 이거 담당관이 바로 작성을 해야 되는 그런 내용 아닌가요? 그리고 3년간 보조금 미집행 세부 내역, 이런 건 다 갖고 있는 자료잖아요. 그리고 임원추천위원회 명단, 3년간. 이런 게 작성하는 데 하루 이상 걸려야 되는 그런 자료인가요? 3년간 차량운행일지 이런 것들. 감사위원장님.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 감사하실 때 피감기관이 자료를 제출하지 않으면 어떡하십니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 일단 한계가 있는 자체사무 같은 경우에는 협의를 통해서 또 아니면 위법사항이나 이런 것들이 보여질 때 하고 만약에 어떤 감사 진행하는 과정에서 그런 자료 협조 요청을 하지 않을 때는 지속적으로 서류 제출 요구를 하게 됩니다.
</p>
<p><b>○ 위원장 조성환 </b> 여태까지 그렇게 해 오셨어요? 지속적으로 자료 좀 내라, 내라, 내라 이렇게 감사합니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 사실상 저희 감사하는 기능과 역할에 따라서 감사자료를 요청하면…….
</p>
<p><b>○ 위원장 조성환 </b> 피감기관이 적극적으로 자료를 제출하죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 자료 제출 잘 해 주고 있습니다.
</p>
<p><b>○ 위원장 조성환 </b> 그 감독기관을 무시하지 않는 이상은 성실하게 최선을 다해서 신속하게 자료를 제출하지 않습니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다. 법률적으로 크게 문제가 없으면 다 적극적으로 감사에 협조를 해 주고 있습니다, 감사 자료 제출 요구에.
</p>
<p><b>○ 위원장 조성환 </b> 이석균 위원님 의사진행발언 하시겠습니까?
</p>
<p><b>○ 이석균 위원 </b> 네, 의사진행발언 좀 하겠습니다. 
</p>
<p><b>○ 위원장 조성환 </b> 네.
</p>
<p><b>○ 이석균 위원 </b> 우리가 지금 우리의 고유권한이고 도민으로부터 부여받은 거에 의해서 행정사무감사를 하는데 좀 전에 증인들로부터 들은 이야기가 심히 우려와 행정사무감사를 진행시키지 못하도록 하는 부분에 대해서 유감을 표하는데, 자료 요청을 했는데 그 공공기관에서 자료 요청에 대해서 딜레이, 그러니까 연기를 한다든가 반응이 없다든가 하는 부분들이 있다는 얘기에 대해서 심각한 유감을 표명하고요. 우리 위원장님께서 지금 현재 기준으로 우리가 위원회에서 공공기관에 요청한 자료를 아직까지 주지 않은 것에 대해서 종합감사에 증인으로 출석시킬 것을 강력히 요청합니다.
</p>
<p><b>○ 위원장 조성환 </b> 이석균 위원님 의사진행발언 해 주셨습니다. 정승현 위원님 의사진행발언 해 주시죠.
</p>
<p><b>○ 정승현 위원 </b> 기조실장님. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 기조실장입니다.
</p>
<p><b>○ 정승현 위원 </b> 지금 감사자료 제출하지 않는 부분에 있어서 이게 제출하기 곤란해서 제출하지 않는 부분이 있는가요, 아니면 시간상 자료 작성하는 데 어려움이 있어서 제출하지 않는 부분인가요?
</p>
<p><b>○ 기획조정실장 이희준 </b> 시간상 자료 작성과 그 자료를 받는 부분에서의 문제입니다.
</p>
<p><b>○ 정승현 위원 </b> 곤란해서 제출하지 않는 부분은 없는가요? 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네. 저희가 오늘 따로 과장들 회의할 때에도 곤란의 부분보다는 저희가 공공기관한테 요청을 통해서 받아야 되는 상황이지 않습니까? 그래서 그런 부분에서 조금 시간이 걸린다고 보고받았습니다.
</p>
<p><b>○ 정승현 위원 </b> 지금 미제출 자료목록 보니까 다 기존의 공공기관에 정리돼 있는 것들이에요. 그런데 이게 지금 시간상 이유로 제출하지 않는다라는 것은 공공기관 직무형태가 그만큼 해태해 있다는 거예요. 담당관실에서 그리고 의회에서 자료 요구를 하면 지금 새로 작성할 게 없어요, 제가 봤을 때. 그만큼 27개 공공기관이 지금 직무에 그만큼…….
</p>
<p><b>○ 위원장 조성환 </b> 위원님, 알겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 단호하게 얘기하세요. 단호하게 얘기하셔서……. 
</p>
<p><b>○ 기획조정실장 이희준 </b> 네, 그렇게 하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 이거 만약에 오늘 중으로 제출하지 않으면 공공기관 담당관 다 들어오도록 하세요.
</p>
<p><b>○ 위원장 조성환 </b> 위원님, 마이크 정리해 주시고, 의사진행발언은 위원장에게 해 주시고요. 증인들이나 참고인에게는 질의 시간에 질의해 주시면 되겠습니다. 박진영 위원님.
</p>
<p><b>○ 박진영 위원 </b> 추가자료 요청이 있어서. 저거 화면 좀 띄워주시겠어요.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  제가 지금 보다가 확인해서 자료 요청이 좀 늦었는데 아트센터 종합감사 결과보고 공개형입니다. 공개해도 되는 거라서 공개한 겁니다. 이거 이 사건 관련돼서 좀 자세한 내용을 알아야 될 것 같아서 이것도 자료 요청드립니다. 어차피 지금 결국에 공공감사에 관한 법률 때문에 못 주신다고 얘기하실 수 있겠지만 제가 이거 요청하는 이유는 지난번에 문화체육관광위에서 종합감사 행감 할 때 관련됐던 내용이 있던 것 같아서 혹시 그거랑 연관이 있는지 연관성을 좀 확인하려고 그러는 거거든요. 이 자료 꼭 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 여담으로 말씀드리는데 저희한테 감사실 자료 못 주신다고 얘기하시는데 지방자치법 시행령에 따르면 저희들 특별한 규정이 없는 경우에는 협조하셔야 되고요. 그리고 저희들도 감사나 조사, 감사 또는 조사는 개인의 사생활을 침해하거나 계속 중인 재판이나 수사 중인 사건의 소추에 관여할 목적으로 행사돼서는 안 된다라고 돼 있죠. 저희도 이런 거 관계되지 않으면 자료 받아야 되는 거고요. 추가적으로 저희한테도 지방의원과 사무보조자는 감사 또는 조사를 통해 알게 된 비밀을 정당한 사유 없이 누설해서는 안 된다라고 돼 있습니다. 저희도 의무 부과되어 있습니다. 분명히 주지해 주시기 바랍니다. 이상입니다.
</p>
<p><b>○ 위원장 조성환 </b> 의사진행발언 하실 위원님 또 계신가요? 이혜원 위원님. 아, 일단 자료 요구는 아까 끝났고요. 의사진행발언 하실 위원님 손 들어주세요. 
</p>
<p><b>○ 이혜원 위원 </b> 위원장님.
</p>
<p><b>○ 위원장 조성환 </b> 네, 이혜원 위원님.
</p>
<p><b>○ 이혜원 위원 </b> 제가 분명히 의사진행발언 자료 요구하면서 했는데 지금 계속적으로 이어지고 있는데 같은 형태인 것 같습니다, 위원님들 말씀하시는 부분들도 그렇고. 지금 현재 공공기관 자료 요구했는데 계속 자료 제출에 대한 행태도 계속적으로 반복되는 부분들 말씀드린 거고 피감기관에 대한 태도 부분들도 계속 말씀드렸습니다. 제출하고 미제출된 부분들에 대해서 자료 요구를 했음에도 불구하고 미제출된 부분과 자료 제출된 부분에 대한 근거가 명확하지도 않습니다. 도대체 기준이 뭔데 어떤 거는 제출하고 어떤 건 제출하지 않고. 이런 형태 위원장님, 자료 제출되지 않고 미제출된 부분도 명확한 근거 없이 이렇게 하는 부분들에 대해서는 이 행정감사 진행하면 안 됩니다. 자료 제출 때까지 정회 요청드립니다.
</p>
<p><b>○ 위원장 조성환 </b> 정회 의견이 들어왔고요. 다른 위원님들, 관련돼서 정회 관련해 주실 말씀…….
</p>
<p style="padding-left:2.4em">    (「재청합니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  재청 동의 들어왔습니다. 
</p>
<p style="padding-left:1.2em">  감사위원장님.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 우리 업무보고 내용을 들어보니까 일하는 공직문화 조성하는 것도 감사위원회의 역할입니다. 그렇죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다.
</p>
<p><b>○ 위원장 조성환 </b> 지금 공직기강이 해이해졌다고밖에 저희는 볼 수가 없어요. 위원님들이 업무보고를 받으시면서 자료 요구하는 것들이 이렇게 많은 것도 사실은 이상한 거고 1차, 2차, 3차에 걸쳐서 행정사무감사 자료들을 요청했으나 자료가 부실하게 제출되고 미제출되니까 또 이렇게 당일 날 자료 요구를 하는 이런 시스템이 지금 계속 반복되고 있습니다. 감사정보시스템 구축하시죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다.
</p>
<p><b>○ 위원장 조성환 </b> 이런 문제 개선한다고 하시는 거죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다.
</p>
<p><b>○ 위원장 조성환 </b> 피감기관의 태도가 이런 태도일 때 감사를 하는 감사위원회 입장에서는 어떤 심정이실 것 같아요? 감사 제대로 진행할 수 있겠습니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 자료 요청해 주신 부분들 정리해서 준비해서 제출할 수 있도록 하겠습니다.
</p>
<p><b>○ 위원장 조성환 </b> 감사위원회는 자료 제출을 지금 받으셨기 때문에 성실하게 제출하실 거라고 믿는데. 기조실장님?
</p>
<p><b>○ 기획조정실장 이희준 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 어제 제출된 자료 요구가 지금 안 됐고요. 제가 오늘 말씀드렸지만 어제 수감 태도도 엉망이었어요. 점심 먹고 와서 하품을 하지 않나. 네? 바로바로 지적 안 했습니다. 그런데 이런 모습을 보면서 의회에 대한 집행부 집행기관의 생각이 어떤지를 저는 판단이 안 섭니다. 
</p>
<p style="padding-left:1.2em">  아무튼 정회 요청 들어왔고 자료 제출 안 됐습니다. 자료가 제출돼서 정상적인 감사가 진행될 때까지 감사를 중지하겠습니다. 이의 있으십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  감사중지를 선포합니다.
</p>
<p class=''ar''>(11시06분 감사중지)
</p>
<p class=''ar''>(14시09분 감사계속)
</p>
<p><b>○ 부위원장 이경혜 </b> 의석을 정돈하여 주시기 바랍니다. 성원이 되었으므로 감사를 속개하겠습니다.
</p>
<p style="padding-left:1.2em">  안녕하십니까? 이경혜 위원장입니다. 오전에 감사위원회와 도민권익위원회의 증인선서, 업무보고, 자료 요구까지 절차를 마치고 감사중지를 하였습니다. 이와 관련하여 위원님들과 사전 협의한 대로 경기연구원까지 포함하여 행정사무감사를 일괄 진행하고자 합니다. 다만 일괄 진행에 앞서 경기연구원에 대한 감사개시 선언, 감사 취지 설명, 증인선서, 간부소개 및 업무보고, 자료 요구 절차를 마쳐야 하므로 이에 대해 위원님들의 양해를 구하고자 합니다. 본 위원장이 설명드린 부분에 대해 위원님들께서는 이의 없으십니까?
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그럼 위원님들께서 동의해 주셨으므로 경기연구원에 대한 감사개시 선언 등의 사전 절차를 마치고 진행하겠습니다. 
</p>
<p style="padding-left:1.2em">  감사개시를 선언하겠습니다. 그럼 지금부터 지방자치법 제49조 및 동법 시행령 제41조, 경기도의회 행정사무감사 및 조사에 관한 조례에 따라 경기연구원 소관에 대한 2024년도 행정사무감사를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  감사 취지에 대해 설명드리기에 앞서 경기도 싱크탱크로서 경기도의 경쟁력 강화와 정책 개발을 위해 애써주시는 박충훈 경기연구원 원장 직무대행을 비롯한 관계자분들께 감사드립니다. 경기연구원 관계자분들께서도 잘 아시는 바와 같이 지방의회 행정사무감사는 집행기관의 행정사무감사 전반에 관한 실태를 파악하여 잘못된 점을 시정ㆍ개선하고 나아가 2025년도 예산안 심사에 반영함은 물론 도민의 삶의 질 향상에 기여하는 것이 그 목적인 만큼 매우 중요한 의미가 있습니다. 따라서 감사에 임하는 경기연구원 관계자분들께서도 본 위원회가 이번 행정사무감사를 통해 얻고자 하는 소기의 목적이 달성될 수 있도록 감사에 충실히 임해 주시길 당부드립니다.
</p>
<p style="padding-left:1.2em">  그러면 증인선서가 있겠습니다. 감사를 받는 박충훈 경기연구원 원장 직무대행과 각 본부장, 실장 등은 증인의 자격으로 소관 업무보고와 질의 답변에 앞서 선서를 하셔야 합니다. 선서를 하는 이유는 경기도의회가 2024년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김 없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법 제49조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조 규정에 의하여 고발될 수 있으며 정당한 사유 없이 선서 또는 증언을 거부한 때에는 동법 규정 및 동 조례 제31조에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 아울러서 형사소송법 제148조 근친자의 형사책임과 증언거부 또는 149조 업무상 비밀과 증언거부에 해당하는 때에는 선서와 증언 그리고 제출 서류를 거부할 수 있음을 함께 알려드립니다. 참고로 경기연구원장은 현재 공석이어서 박충훈 경기연구원 부원장이 원장의 직무를 대행함을 알려드립니다. 또한 공석인 공공투자관리센터 소장을 대신해서 박정환 총괄기획부장이 증인으로 출석하였음을 알려드립니다.
</p>
<p style="padding-left:1.2em">  그럼 먼저 증인 출석 여부를 확인하겠습니다. 피감사기관의 증인들께서는 모두 자리에서 일어서 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  박충훈 경기연구원 원장 직무대행 나오셨습니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 부위원장 이경혜 </b> 김점산 기획조정본부장 나오셨습니까? 
</p>
<p><b>○ 경기연구원기획조정본부장 김점산 </b> 네.
</p>
<p><b>○ 부위원장 이경혜 </b> 유영성 북부자치연구본부장 나오셨습니까?
</p>
<p><b>○ 경기연구원북부자치연구본부장 유영성 </b> 네.
</p>
<p><b>○ 부위원장 이경혜 </b> 김을식 미래전략연구본부장 나오셨습니까? 
</p>
<p><b>○ 경기연구원미래전략연구본부장 김을식 </b> 네.
</p>
<p><b>○ 부위원장 이경혜 </b> 민철기 감사실장 나오셨습니까?
</p>
<p><b>○ 경기연구원감사실장 민철기 </b> 네.
</p>
<p><b>○ 부위원장 이경혜 </b> 공공투자관리센터 소장의 직무를 대신하는 박정환 총괄기획부장 나오셨습니까?
</p>
<p><b>○ 경기연구원경기도공공투자관리센터소장직무대행 박정환 </b> 네.
</p>
<p><b>○ 부위원장 이경혜 </b> 다음은 선서의 요령에 대해 설명을 드리겠습니다. 선서는 증인들을 대표해서 박충훈 경기연구원 원장 직무대행께서 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손을 들어주시면 되겠습니다. 그러면 증인들께서는 선서를 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 선서! 본인은 경기도의회가 지방자치법 제49조, 같은 법 시행령 제41조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2024년도 행정사무감사를 실시함에 있어 증인으로서 성실하게 감사를 받을 것이며 또한 증언을 함에 있어서는 지방자치법 시행령 제46조제6항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2024년 11월 12일 경기연구원장 직무대행 박충훈.
</p>
<p><b>○ 부위원장 이경혜 </b> 모두 자리에 앉아 주십시오.
</p>
<p style="padding-left:1.2em">  이상으로 증인선서를 마치고 간부소개와 업무보고를 받도록 하겠습니다. 박충훈 경기연구원 원장 직무대행 나오셔서 간부소개와 업무보고를 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 먼저 저희 경기연구원 발전을 위해 관심을 가지시고 항상 염려해 주시고 성원해 주시는 이경혜 위원장님을 비롯한 기획재정위원회 위원님들께 깊이 감사드립니다. 원장 직무대행 박충훈입니다. 
</p>
<p style="padding-left:1.2em">  오늘 기획재정위원회 위원님들을 모시고 2024년도 경기연구원 제379회 정례회 업무보고를 드리게 되어 뜻깊게 생각합니다. 연구원의 발전을 위하여 기획재정위원회 위원님들의 많은 관심과 성원을 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  보고에 앞서 연구원의 주요간부를 소개해 드리겠습니다.
</p>
<p style="padding-left:1.2em">  박정환 경기도공공투자관리센터 소장 직무대행입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김점산 기획조정본부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  유영성 북부자치연구본부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김을식 미래전략본부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  민철기 감사실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 연구원의 주요업무를 보고드리겠습니다. 보고드리는 순서는 일반현황, 미션ㆍ비전ㆍ핵심 가치 및 경영 목표 그리고 2024년 주요사업 추진현황과 2024년 하반기 주요 업무보고의 조치 결과, 마지막으로 기타현황 순으로 말씀드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  1쪽 일반현황입니다. 경기연구원은 1995년에 개원하여 경기도의 정책 개발 기능을 수행하고 있습니다. 현재 연구원 조직은 본원이 1부원장, 3본부, 8센터, 7실, 7부로 구성되어 있고 부설기관인 경기도공공투자관리센터가 3부로 구성되어 있습니다. 경기연구원의 인력은 정규직 정원 187명에 현원 167명, 공무직 63명에 현원 57명이며 비정규직인 기간제 근로자 41명 등 총 167명이 근무하고 있습니다. 조직도는 자료를 참고하여 주시기 바랍니다. 설립현황에 대해서 말씀드렸고요.
</p>
<p style="padding-left:1.2em">  2쪽 예산현황에 대해서 보고드리겠습니다. 올해 총예산 규모는 297억 원으로 일반회계 267억 원, 공공투자관리센터 특별회계 30억 원입니다. 일반회계 수입ㆍ지출 내역을 보다 세부적으로 말씀드리겠습니다. 수입 항목은 일반회계 237억 중 경기도 출연금이 165억 원으로 일반회계 예산의 69.7%를 차지하고 있습니다. 지출 항목으로는 인건비가 124억 원으로 일반회계 예산의 52.2%를 차지하고 있으며 연구사업비는 59억 원으로 24.7%를 차지하고 있습니다. 
</p>
<p style="padding-left:1.2em">  3쪽입니다. 경기연구원의 미션은 정책 연구 및 개발을 통해 경기도민의 삶의 질 향상과 경기도정 발전에 기여하는 것입니다. 연구원의 경영 목표 및 핵심 가치, 전략과제 등은 3페이지에 있는 자료로 갈음하겠습니다.
</p>
<p style="padding-left:1.2em">  4페이지입니다. 주요사업 추진현황에 대해서 보고드리겠습니다. 먼저 연구과제사업 추진현황입니다. 연구원은 경기도 및 경기도의회, 31개 시군의 정책 수요에 기반하여 총 171개의 연구과제를 수행 중에 있으며 연말까지 정책 수요에 대응하여 추가적인 연구과제의 발굴 및 착수를 지속적으로 추진할 예정입니다. 2024년 연구과제의 운영현황은 표를 참고해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  5쪽입니다. 부서별 추진현황을 간략하게 보고드리겠습니다. 자치행정연구실은 전반적인 행ㆍ재정 분야의 연구 및 재난안전 관련된 연구를 담당하고 있습니다. 주요 연구과제로는 삶의 기회 확대를 위한 초광역 행정서비스 대응체계의 연구, 신규 사회재난 대비 미래 전망과 대응방안 등 39건의 연구과제를 수행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 7쪽 공간주거연구실입니다. 공간주거연구실은 도시계획, 도시재생 및 지역균형발전 등의 연구를 담당하고 있습니다. 대표적인 연구로는 뉴 컴팩트시티를 위한 경기도 역세권의 입체복합화 방안, 전세피해 예방 및 지원을 위한 방안 연구 등 13건의 연구를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  8쪽입니다. 모빌리티연구실은 교통 및 물류에 관한 연구를 종합적으로 담당하고 있습니다. 모빌리티연구실은 수도권 통합 대중교통 요금 지원방안 연구, 경기도 철도 지하화 사업 개발 전략 수립 등 22건의 연구를 추진 중에 있습니다.
</p>
<p style="padding-left:1.2em">  10쪽 기후환경연구실은 탄소중립, 생태, 대기 및 자원순환 등의 연구를 수행하고 있으며 연구실 산하에 경기도 RE100플랫폼 구축을 위한 기후환경정보센터와 RE100플랫폼사업추진단을 두고 있습니다. 기후환경연구실은 11쪽에서 보시는 바와 같이 경기도 개발사업 탄소중립 가이드라인 연구, 경기도 기후격차 실태조사 연구 등 25건의 연구를 수행하고 있으며 2025년 6월까지 경기도 RE100플랫폼 구축사업을 위탁받아 운영하고 있습니다.
</p>
<p style="padding-left:1.2em">  12쪽입니다. ESG정책연구센터는 ESG 관련 동향에 대한 분석 및 공공 부문 ESG 확산을 위한 연구사업 및 포럼 등을 운영하고 있습니다.
</p>
<p style="padding-left:1.2em">  13쪽 북부자치본부 추진현황입니다. 먼저 북부자치연구본부는 글로벌지역연구실, 균형발전지원센터, 경기북부특별자치도연구센터로 구성되어 있으며 균형발전, 북부특별자치도 등 북부 관련 주요현안에 대한 연구를 전담하고 있습니다. 북부자치연구본부에서는 경기북부 신산업벨트 조성방안 연구, 경기북부특별자치도 시군별 비전ㆍ발전 전략 연구 수립 등 15건의 연구를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  15쪽 미래전략연구본부의 사업계획에 대해서 보고드리겠습니다. 먼저 미래전략연구본부는 경제사회실과 인구영향평가센터, 전략연구센터, AI혁신정책센터로 구성되어 있으며 경제, 사회, 관광, 인구 등 상당히 넓은 영역의 연구주제를 담당하고 있습니다.
</p>
<p style="padding-left:1.2em">  16쪽에서 18쪽입니다. 경제사회연구실과 인구영향평가센터, AI혁신정책센터에서는 경기도 기후테크 산업 육성전략 연구, 2023년 경기도 인구인지예산 및 인구영향평가, 사람과 사회 가치 증대를 위한 AI 정책 방향과 과제 등 49건의 과제를 수행하고 있습니다. 이외에도 전략연구센터는 연구과제보다는 민선8기 경기도의 주요현안에 대한 이슈분석 등을 통하여 단기적 현안 대응에 집중하여 즉시적 정책지원을 목표로 운영되고 있습니다.
</p>
<p style="padding-left:1.2em">  19쪽 마지막으로 정책연구 이외에 이슈분석에 대해 보고드리도록 하겠습니다. 이슈분석은 15개의 핵심 연구분야를 중심으로 정책을 발굴하는 Policy Initiative와 경기도 주요현안에 대한 즉시적 대응을 목적으로 하고 있는 이슈브리프로 구성되어 있습니다. 현재 10월 말 기준 Policy Initiative는 12건, 이슈브리프는 162건이 완료되었습니다. 올해 발간된 Policy Initiative의 현황은 19쪽에 제시하였습니다.
</p>
<p style="padding-left:1.2em">  20쪽입니다. 연구부대사업 추진현황에 대해서 보고드리겠습니다. 연구부대사업은 대외협력교류 강화와 도민 맞춤형 콘텐츠 제공으로 요약할 수 있습니다. 먼저 경기연구원은 도내 15개 공공기관과의 MOU 추진을 통하여 G+정책플랫폼을 구축하고 협력사업을 추진하고 있습니다. 2024년에는 G+정책플랫폼의 공동의제를 인구로 설정하고 공동연구 및 공동세미나 등을 추진하였습니다. G+정책플랫폼의 주요 협력사업은 21쪽 표를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  22쪽에서 24쪽까지는 정책세미나 현황입니다. 연구원은 수도권 초광역 협력포럼 등 도정 주요현안 지원을 위한 정책세미나를 29회 추진하였습니다.
</p>
<p style="padding-left:1.2em">  24쪽입니다. 또한 경기연구원은 핵심 연구분야 관련 전문성 강화를 위하여 외부 전문가와 결합하여 연구회를 운영하고 있습니다. 올해는 AI혁신정책, 외국인주민 등 8개 분야의 연구회에서 총 28회의 회의를 진행하였습니다.
</p>
<p style="padding-left:1.2em">  25쪽, 26쪽입니다. 경기연구원은 산동사회과학원과의 연구교류를 지속하고 있으며 이외에도 중국종합개발연구원, 핀란드 헬싱키대학과의 새로운 국제 네트워크를 구축하였습니다.
</p>
<p style="padding-left:1.2em">  27쪽입니다. 또한 국내 차원에서는 다양한 협력사업 및 MOU 체결 등을 통해 경기연구원의 네트워크 역량을 강화하였습니다.
</p>
<p style="padding-left:1.2em">  28쪽입니다. 경기도의회와의 협력사업 추진에 대해서 말씀드리겠습니다. 경기의정포럼에서는 한국사회 미래전망, 문화도시 등 주요현안에 대한 정책 토론의 장을 확대하였고 또한 경기도의회, 집행기관, 시민단체, 전문가 네트워크를 활용한 지역현안 토론회를 지원했습니다. 지역현안 토론회는 현재까지 2건을 지원하였고 향후 2건이 더 예정되어 있어서 위원님들의 많은 참여를 통해서 보다 확대된 운영을 추진하려고 계획하고 있습니다.
</p>
<p style="padding-left:1.2em">  29쪽, 30쪽입니다. 경기연구원은 약 40회에 이르는 지식기부 활동, 학술지 발간 등을 통해 연구원의 사회적 책임을 다하고자 노력하였습니다.
</p>
<p style="padding-left:1.2em">  31쪽입니다. 뉴미디어 시대의 사용자 요구를 반영하여 연구원 차원에서의 연구성과 확산을 위하여 카카오톡 채널을 신설하였습니다. 연구원은 경기도민에게 좀 더 친근하게 다가가기 위하여 유튜브 영상 제작 등을 적극적으로 추진하고 있습니다. 그 결과 2023년 약 1만 8,935명이던 구독자 수가 2024년 10월 기준으로 약 2만 6,932명으로 큰 폭으로 성장하였습니다. 또한 도민과의 적극적인 소통을 위해 상시제안제도 등도 지속적으로 운영하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음 32쪽에서 34쪽 연구지원사업의 추진현황입니다. 경기연구원은 연구지원사업 차원에서 연구업무의 효율성 제고를 위하여 AI를 적극 도입하여 활용하고자 하였으며 이외에도 ESG 경영실천을 위한 노력도 지속적으로 기울이고 있습니다. 또한 좀 더 다양한 방식의 소통을 위하여 연구 확산을 위한 기획출판 사업도 지속적으로 추진하고 있습니다. 그리고 또 노후장비 교체 및 서버 도입을 통해서 업무의 보안성과 효율성을 제고하고 공간정보 구축 그리고 현안 이슈 등의 정책 홍보를 지원하고 있습니다.
</p>
<p style="padding-left:1.2em">  35쪽 연구기반사업의 추진상황에 대해서 보고드리겠습니다. 경기연구원은 15개 핵심 연구분야를 중심으로 경기도정에 대한 기여를 강화하고 정책제안 기능을 높이기 위해서 정책연구 및 Policy Initiative 등의 추진과정에 대해서 그 프로세스를 개선하는 작업을 하였습니다. 또한 연구성과의 지속적 향상을 위하여 성과 및 역량평가를 중심으로 한 평가제도의 개편과 보상체계 개편도 적극 추진하였습니다.
</p>
<p style="padding-left:1.2em">  다음으로 경기도 공공투자관리센터에 대해서 보고드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  36쪽입니다. 공공투자관리센터는 투자사업 및 재정사업에 대한 심사 및 평가를 중심으로 관련 네트워크 사업 등을 수행하고 있습니다. 경기도 공공투자관리센터는 10월 말 현재 투자심사 사전검토 및 관련 지원업무를 총 235건 수행하였습니다.
</p>
<p style="padding-left:1.2em">  37쪽입니다. 센터는 재정사업평가를 통하여 경기도가 추진하는 재정사업 총 867건을 평가하여 구조조정 및 정책 개선방안을 제시하였습니다. 민간투자사업에 대한 조사 및 지원도 동시에 수행하고 있습니다. 그리고 공공투자관리센터의 업무역량 향상을 위하여 매년 해당 주제를 선정하여서 정책 및 지침연구를 추진하고 있는데 올해는 총 7건을 수행하였습니다.
</p>
<p style="padding-left:1.2em">  38쪽입니다. 경기도 공공투자관리센터에서는 올해부터 수행사업에 대한 만족도 조사를 수행하고 있으며 전국지방공공투자관리센터 협의회 등 대내외 네트워크 확대 그리고 정보교류를 강화하여 추진하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 39쪽, 40쪽입니다. 올해 7월 연구원 업무보고 시 주요 조치결과에 대한 내용입니다. 제출 자료로는 이혜원 위원님이 요구하신 연구원 각 센터의 기능, 현황 등 정리자료 건에 대해서는 대면보고를 드릴 예정이며 이외 조치사항으로 박상현 위원님이 요구하신 업무보고 자료에 대한 과제별 정책 반영내역 실적 표기 건에 대해서는 이번 업무보고 자료에 반영하였습니다. 그리고 또한 이혜원 위원님이 말씀하신 인구영향평가센터 등 관련 정보 및 도민 접근성 개선 필요 건에 대해서는 별도로 대면보고를 드릴 예정입니다.
</p>
<p style="padding-left:1.2em">  41페이지부터 59페이지까지는 2023년, 2024년 연구과제의 수행실적이며 마지막으로 60쪽부터 63쪽은 부서장 명단을 첨부하였습니다.
</p>
<p style="padding-left:1.2em">  이상으로 연구원 제379회 정례회 업무보고를 모두 마치도록 하겠습니다. 경기연구원은 올해 2024년 다짐했던 업무보고 내용을 바탕으로 해서 보다 성장하는 계기가 되도록 하겠습니다. 그 과정에서 많은 위원님들의 관심과 조언을 부탁드립니다. 경청해 주셔서 감사합니다.
</p>
<p><hr /></p>
<p>업무보고서(경기연구원)
</p>
<p><hr /></p>
<p><b>○ 부위원장 이경혜 </b> 박충훈 경기연구원 원장 직무대행 수고하셨습니다.
</p>
<p style="padding-left:1.2em">  그럼 지금부터 감사위원회, 도민권익위원회, 경기연구원에 대한 일괄 질의 답변을 시작하겠습니다. 질의 답변은 계속해서 본질의는 10분 이내로 하고 보충질의는 5분 이내로 일문일답 형식으로 진행하겠으며 추가질의는 별도 신청을 받아 진행하겠으니 위원님들의 많은 협조 부탁드립니다. 또한 위원님들의 질의사항 중 구체적이고 실무적인 내용에 대해서는 소관 부서장께서 답변하셔도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대로 나와 소속과 직ㆍ성명을 밝히고 답변해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  질의에 앞서 자료 요청하실 위원님께서는 거수로 신청해 주시기 바랍니다. 양우식 위원님.
</p>
<p><b>○ 양우식 위원 </b> 양우식 위원입니다. 감사위원회 추가 자료 좀 요청드릴게요. 위원장님, 혹시 직원분들한테 제가 이게 너무 양이 많고 이것저것 위원님들 요구서가 많아서 그냥 사무실 통해서 자료 요구를 했는데 구두발언한 거 아니면 자료 제출하지 말라고 지시하셨어요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 전혀…….
</p>
<p><b>○ 양우식 위원 </b> 저희가 요구했는데 감사위원회에서 구두발언한 것 외에는 제출하지 않는다고 그랬다는데요, 직원분이.
</p>
