<p><b>○ 이혜원 위원 </b> 위원님들, 자료 제출한 거 만족하십니까, 내용? 저는 기조실에서 자료 왔는데 솔직히 만족하지 않습니다. 본인들이 자료 제출을 하기 위해서 시간 내에 2시까지 내라고 했더니 2시에 맞추기 위해서 자료 제출을, 위원님들 내용도 다 봤는데 이게 내용이 부실한 자료를 제출하면 뭐 합니까? 행감을 하기 위해서 내용을 파악하고 그거에 대한 개선점을 우리가 찾아내고자 지금 행정사무감사를 하는 건데 내용 파악도 할 수 없는 자료를 제출하셔서, 소비지원금이라고 하면 그게 무슨 내용인지 아십니까? 경기연구원장님, 내용만 보시면 아시겠어요? 그게 무슨 사업입니까? 여쭤보는 거예요, 자료가 그렇게 와서. 그게 지역화폐 관련돼서 인센티브 준 500억 사업이라는 거 아시겠습니까, 그렇게만 내용 보시면?
