<p><b>○ 부위원장 이경혜 </b> 정리하겠습니다. 의사진행발언 하시고 이채명 위원님 자료 요청하시고 그다음에 이석균 위원님 그다음 말씀 진행하도록 하겠습니다. 이혜원 부위원장님 말씀하십시오. 
