<p style="padding-left:1.2em">  자료 제출 요구 더 추가로 하실 위원님 계십니까? 안 계십니까? 위원님들께서 요구하신 자료는 신속히 작성해서 모든 위원님들께 배부해 주십시오. 
</p>
<p style="padding-left:1.2em">  정회를 했던 이유들을 잘 알고 계시죠? 지금까지 자료 요청에 대해서 그리고 행정사무감사를 받는 그 태도에 대해서 저희 위원님들께서 지속적으로 문제 제기를 하셨기 때문에 지금쯤은 모든 집행부에 계신 분들께서 여러 가지로 긴장하셨을 거라고 생각을 하고요. 좀 더 집중해 주시고 충분히 답변하실 수 있는 일들을 잘 준비해 주시기를 부탁을 드리면서 그러면 질의 답변을 시작하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  질의하실 위원님께서는 거수로 신청하여 주시기 바랍니다. 없으신가요? 질의 순서, 오창준 위원님, 원래 질의 순서대로 그럼 시작을 할까요? 질의 순서 오전에 약속한 대로 질의 순서대로 질의를 시작하겠습니다. 먼저 오창준 위원님 질의해 주십시오.
