<p><b>○ 오창준 위원 </b> 그리고 경기연구원이 경기도의 대표적인 연구기관이고 어떻게 보면 정책을 세워나가는 그런 부서인데 예산 필요하다고 못 한다고 그러면 저희가 뭐 하러 있습니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 아닙니다. 그런 사항 포함해서 보고드리도록 하겠습니다. 
</p>
<p><b>○ 오창준 위원 </b> 네, 알겠습니다. 
</p>
<p style="padding-left:1.2em">  다음은 도민권익위원장님께 질의드리겠습니다. 나오셨습니까?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 도민권익위원장입니다.
</p>
<p><b>○ 오창준 위원 </b> 작년에 존경하는 저희 박상현 위원님께서 경기도 갑질 행위 근절 및 피해자 지원 조례 발의하셨고, 재작년에 발의하셨구나. 하셨고 그거에 따라서 지금 이 갑질사건 같은 경우에는 감사위원회가 아니고 도민권익에서 담당을 하죠?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 그렇게 하고 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 이거 언제부터 이쪽으로 이관됐습니까, 업무가? 처음부터 도민권익위에서 했습니까?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 도민권익위원회 조례에 따라서 9월 2일 날 도민권익위원회가 설립되면서 그때부터 임무가 이관됐습니다.
</p>
<p><b>○ 오창준 위원 </b> 그러면 그전에 경기도 옴부즈만일 때는 여기 업무를 어디서 담당했습니까?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 옴부즈만위원회일 때는 감사관실에서 그때그때마다 담당자가 달라질 수 있는 여러 부서에서 그때그때 상황에 따라서 진행을 했던 것으로 알고 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 감사관실? 지금 감사위원회고 그 당시 감사관에서 했었죠, 이 업무를?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 그렇습니다.
</p>
<p><b>○ 오창준 위원 </b> 이게 도민권익위원회로 이관된 이유가 뭐죠? 이 조례는 어디 딱 부서 정해지지 않았으니까 원래 감사관실에서 했으면 감사위원회에서 해도 되는데 굳이 도민권익위원회로 이 업무가 이관된 이유가 있습니까? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 조례 취지에 따라서 좀 더 체계적이고 도민 고충 해결과 권익보호를 총괄하는 권익보호전담기구인 저희 도민권익위원회가 체계적으로 일원화돼서 처리하는 게 좋겠다고 판단한 것으로 알고 있습니다.
</p>
<p style="padding-left:2.4em">    (타임 벨 울림) 
</p>
<p><b>○ 오창준 위원 </b> 위원장님, 저 보충질의까지 좀 한 번에 이어서 하겠습니다. 위원장님.
</p>
<p><b>○ 부위원장 이경혜 </b> 네. 
</p>
<p><b>○ 오창준 위원 </b> 보충질의까지 이어서 좀 하겠습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 같이 하시죠. 죄송합니다.
</p>
<p><b>○ 오창준 위원 </b> 근데 이거 갑질사건 처리 프로세스를 보면 조사까지는 도민권익위에서 하시는데 결국 최종적으로 징계 의결 그런 거는 다 감사위원회로 이관하게 돼 있는데 이렇게 되면 하나의 업무를 굳이 2개의 부서에서 나눠서 할 이유가 없지 않습니까? 기존에 원래 갑질 처리는 감사위원회에서 하던 업무인데 굳이 도민권익으로 넘길 만한 이유가 없어 보이는데 어떻게 생각하세요?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 갑질 업무를 체계화하고 일원화하고 또 전문적이고 신속하게 판단할 필요가 있다고 판단하고 저희 도민권익위원회가 그 차원에서 1차적으로 갑질 행위 여부를 판단하고 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 그러니까 갑질 행위 여부에 대해서 감사위원회가 하면 안 되는 이유가 있냐는 말씀입니다. 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네?
</p>
<p><b>○ 오창준 위원 </b> 도민권익위원회가 아니고 감사위원회에서 하면 안 되는 이유가 있냐고 여쭤보는 겁니다.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 일단 저희는 조례의 취지에 따라서 갑질 업무 전담기구로서 최선을 다해서 갑질사건의 신고 처리에 전념을 기하고 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 당연히 이제 업무 맡으셨으면 해야죠. 당연히 제가 그런 의지를 여쭤보는 게 아니라 행정적으로 왜 감사관에서 하면 안 되는 이유가 있는지 그거에 대해서 생각하신 게 있냐고 여쭤보는 거예요. 제가 “열심히 안 하시니까 하지 마세요.” 이런 말씀드리는 게 아니지 않습니까? 이번에 부서 생긴 지 몇 달 됐다고 제가 그런 얘기를 뭐 하러 드리겠어요? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네. 그 부분에 대해서는 많은 논의를 해 주신다면 또, 저희 그전에 그런 논의들을 거쳐서 조례를 만들어 주신 것으로 알고 있고 저희는 조례의 취지에 따라서 엄정한 갑질 신고 처리를 하겠다는 말씀을 드리겠습니다. 
</p>
<p><b>○ 오창준 위원 </b> 네, 알겠습니다. 그러면 감사위원장님께 다시 질의드겠습니다. 제가 방금 아까 도민권익위원장님께 드렸던 질의에 대해서 한번 감사위원장님께서는 어떻게 생각하시는지 말씀 좀 주실래요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 감사위원장 안상섭입니다. 아마 도민권익위원회하고 감사위원회가 분리가 되면서 도민 권익구제 차원에서 갑질 행위 부분과 관련해서는 조례에 담아놓은 절차에 따라서 갑질 행위 조사권한을 도민권익위가 가지고 있는데 그 깊은 취지는, 갑질 행위도 물론 조사권한 또 징계까지 이어질 수 있어서 감사위원회의 권한이라고 볼 여지도 있겠으나 도민 권익구제 차원에서의 어떠한 그런 도민권익위의 기능과 역할들을 고려해서 조례에 그렇게 담아놓지 않았었나 이런 생각이 듭니다.
</p>
<p><b>○ 오창준 위원 </b> 네. 본 위원이 왜 이 질의를 드렸냐면 사실 이 갑질 신고가 저는 처음에는 이해를 민간인들, 도민들 대상으로 공무원 갑질하는 케이스에 대한 조사인 줄 알았어요. 근데 내용을 보니까 서로 공무원 간의 위계질서나 이런 거에 대한 갑질을 좀 전담을 하시는 것 같더라고요. 그런데 이런 경우에는 도민권익을 위한 위원회에서 일할 게 아니라 사실 이 내부감사를 위한 감사위원회실에서 저는 하는 게 맞다고 생각이 들어서 이 말씀을 드리는 거고 한번 깊은 고민을 해 주셨으면 좋겠습니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 충분히 공감이 가는 말씀이고 이해가 되는 부분이 있어서 그런 부분들을 한번 검토해 보겠습니다.
</p>
<p><b>○ 오창준 위원 </b> 네, 알겠습니다. 그다음에 하나 더 여쭤볼 게 공무원 범죄의 경우에 징계 처리 규정이 정해져 있죠? 어떤 범죄에 대해서 어떤 징계를 한다 이런 것에 대한?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다. 양정기준이 있어서 양정기준에 따라서 공무원 징계를 처리하고 있습니다. 
</p>
<p><b>○ 오창준 위원 </b> 근데 제가 이번 요구에서 주신 자료에서 보면 2022년도에 9급 직급에 계신 공무원께서 준강제추행 범죄이력이 있었고 그 처분 결과가 해임이었습니다. 그런데 동년도에 이분은 준이 아니고 그냥 강제추행인데 직급이 3급이셨는데 강등 처분이 나왔습니다. 이런 경우에는 왜 그런지 혹시 설명이 가능하십니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 그 구체적인 내용은 제가 잘 파악은 하지 못하고 있습니다마는…….
</p>
<p><b>○ 오창준 위원 </b> 예를 들어 강제추행이 사실 어떤 경우에 준강제추행보다 훨씬 높은 등급의 범죄, 범죄등급을 매기는 건 아니지만 어쨌든 더 강한 징계가 필요한 부분인 것 같은데 이게 누구는, 3급은 강등으로 끝나고 9급은 해임으로 끝나는 이런 결과는 어떻게 생각하시는지.
</p>
<p><b>○ 감사위원장 안상섭 </b> 맞습니다. 그렇게 형식적으로 보면 형평성에 맞지 않는 양형기준이 되겠다라는 위원님의 말씀에 충분히 공감합니다. 다만 그 이후에 죄질이든 어떤 이후의 상황들을 살펴봐야 되는데 그때 당시 강등이 됐던 건, 양형의 기준에 있어서 징계가 좀 낮았던 건 합의를 하고 또 그게 기소유예 처분이 되어서 실형으로 나가지 않았기 때문에 그러한 것을 고려해서 징계 양정을 정한 것으로 알고 있습니다.
</p>
<p><b>○ 오창준 위원 </b> 그러면 준강제추행 했던 이 9급 공무원께서는 뭐 그런 여지가 없었다 이렇게 받으면 됩니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그런 차이가 있어서 양정에 있어서 차이가 있음을 이해해 주셨으면 고맙겠습니다.
</p>
<p><b>○ 오창준 위원 </b> 저희한테 주실 때 이게 아무래도 개인정보 보호 차원이겠지만 자세한 내용이 없기 때문에 저희가 이런 결과를 보고서는 이런 의문을 가질 수밖에 없고 저희뿐만 아니라 아마 어떤 분들이, 어떤 도민들께서 보셔도 아마 이렇게 오해하실 수밖에 없을 것 같아요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 충분히 이해합니다.
</p>
<p><b>○ 오창준 위원 </b> 이런 부분에 대해선 명확한 근거를 통해서 일괄된 그런 징계결과가 나왔으면 좋겠습니다. 참고해 주셨으면 좋겠습니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 잘 알겠습니다.
</p>
<p><b>○ 오창준 위원 </b> 이것으로 질의 마치도록 하겠습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 오창준 위원님 수고하셨습니다. 다음 질문하실 위원님은 박진영 위원님이십니다. 질의 부탁드립니다.
</p>
<p><b>○ 박진영 위원 </b> 자료 좀 띄워주세요.
</p>
<p style="padding-left:1.2em">  안녕하십니까? 화성 출신 박진영 위원입니다. 감사위원장님 앞으로 나와주시기 바랍니다. 위원장님, 혹시 오해의 소지가 있을까 봐 미리 말씀드리는데 저는 감사위원회 공무원분들 열심히 일하시고 소명에 따라서 일하시는 거 알고 있습니다. 그리고 특정 케이스에 대해서 좀 얘기를 하긴 하겠는데 이거는 감사위원회가 감사를 하는 과정에 있어서 얼마나 공정한지에 대한 부분들을 하기 위한 특정 하나의 케이스라는 걸 말씀드리고요. 양해해 주시면 이제 질의드리겠습니다. 그리고 위원장님, 실제로 감사위원회는 그 어디에도 제재를 받지 않잖아요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다. 독립 합의제 기구로 9월 달에 출범했습니다.
</p>
<p><b>○ 박진영 위원 </b> 그거에 대해서 제재를 할 수 있는 기구는 저희 기획재정위원회밖에 없죠? 공식적으로 제재할 수 있는 기구는.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다. 상급 감사원에서도 또 제재는 받을 수 있다라고 말씀을 드릴 수 있습니다.
</p>
<p><b>○ 박진영 위원 </b> 그런 점 양해해 주셔서 받아들여 주시기 바랍니다. 위원장님, 경기도 감사 규칙에 따르면 종합감사는 3년 주기로 실시한다고 돼 있는데 지금 보면 경기아트센터는 22년에 종합감사를 했는데 24년에 종합감사를 한 번 더 했습니다. 연장 결정 이유에 대해서 제가 자료 요청을 드렸는데 연장 결정 관련된 내부결재 서류가 오질 않았습니다. 연장 결정 이유에 대해서 설명해 주실 수 있나요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 아마 그 자료를…….
</p>
<p><b>○ 박진영 위원 </b> 제가 자료 요구를 드린 거는 위원장님이 지금 취임하신 지 얼마 안 됐고 위원장님이 취임하시기 이전에 있었던 일이기 때문에 위원장님이 혹시 이유를 모르실까 봐 드린 건데 어차피 자료 안 왔고…….
</p>
<p><b>○ 감사위원장 안상섭 </b> 연장 결정 자료는 드린 걸로 제가…….
</p>
<p><b>○ 박진영 위원 </b> 연장 결정 사유에 대한 내부결재 문서를 달라고 했습니다. 연장 결정 관련된 내부결재 문서, 그냥 위원장님 답변해 주세요, 아시면.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 박진영 위원 </b> 왜 연장된 거죠?
</p>
<p style="padding-left:2.4em">    (감사위원장, 자료 확인 중)
</p>
<p style="padding-left:1.2em">  위원장님.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 죄송합니다.
</p>
<p><b>○ 박진영 위원 </b> 통상적으로 종합감사를 하는데 연장되는 일들이 일상적인 일인가요, 아니면 드문 일인가요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 연장은 일단 인원이나 감사의 규모에 따라 한계가 있기 때문에…….
</p>
<p><b>○ 박진영 위원 </b> 짧게 답변해 주세요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 연장은 자주 있습니다.
</p>
<p><b>○ 박진영 위원 </b> 연장은 자주 있으시다고요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 연장 처리는 많이 합니다.
</p>
<p><b>○ 박진영 위원 </b> 연장 결정 관련된 내부결재 문서 꼭 부탁드리겠습니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 알겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 아트센터 종합감사 감사 결과보고서인데요. 여기 보시면 중점사항에 직장 내 괴롭힘, 기타 감사 제보사항 등이라고 되어 있습니다. 위원장님, 경기아트센터와 관련해서 직장 내 괴롭힘, 갑질 등에 관련해서 경기도 감사위원회, 이전에 감사관이죠? 구두, 문서 또는 기타의 사항으로 제보된 사항이 있었는지요? 위원장님, 답변 주시기 전에 확실히 말씀 주세요. 지방자치법에 따르면 “거짓증언을 한 자는 고발할 수 있으며”라고 되어 있습니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 제보가 있었던 것으로 들었고요. 근데 제보에 따라서 그 제보 내용을 감사했던 것으로 그렇게 알고 있습니다.
</p>
<p><b>○ 박진영 위원 </b> 종합감사에 갑질에 관련된 사항들이 중점사항이 맞죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 박진영 위원 </b> 제보된 내역들, 구두로 된 거, 문서로 된 거 그리고 감사위원회에서 처리했던 내용들 모두 부탁드리겠습니다, 자료로.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 박진영 위원 </b> 제보된 사항에 대해서 감사가 어떻게 진행됐어요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 위원님, 죄송합니다. 잘 못 들었습니다.
</p>
<p><b>○ 박진영 위원 </b> 제보된 사항이 있다고 말씀을 주셨는데 제보된 사항에서 감사가 어떻게 진행되었느냐고요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 제보된 내용에 대해서는 제가 구체적으로 아직 파악을 못 했고요. 제보된 바는 있었고 그 제보된 바에 따라 감사를 실시를 했…….
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 지금 이 자리에서 말씀 주시지 못할 거면 또다시 정회해서 위원장님이 해당 사실을 파악하고 명확하게 답변 주실 수 있을 때까지 다시 정회해야 되는데 이거 듣지 못할 거면 제가 굳이 시간을 써 가지고 왜 위원장님께 질문을 드리나요? 갑질 신고 처리 프로세스 지금 도민권익위원회에서 마침 들어온 거 보니까 공무원 갑질에 대한 피해 신고가 접수되면 대면ㆍ비대면 상담하게 돼 있습니다.
</p>
<p style="padding-left:1.2em">  제가 여쭤보고 싶은 건 제보된 사항이 있으면 그 제보된 당사자들과 상담하시거나 제보된 특정 제보자가 있으면 그 특정 제보자에게 제보 사실을 재확인했는지 여쭤보는 겁니다. 시간이 없어서 이거 따로 보고 부탁드리겠습니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 제보사항과 관련된 내용은 처분사항 결과보고서에 담겨 있다고 합니다.
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 제가 말씀드리는 거는 제보된 사항이 있고 제보됐으면 제보자가 있고 피제보자가 있는데 그분들과 관련해서 대면 또는 구두로 사실확인이 있었는지 여쭤보는 거고요. 이거 별도로 보고 부탁드릴게요. 종합감사 때 다시 여쭤볼게요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 한번 살펴보도록 하겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 서면, 구두, 기타 모든 사항 등과 관련돼서 처리된 내용들 모두 다 보고 부탁드리겠습니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 알겠습니다. 검토해 보겠습니다.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 이거 지난해에 문화체육관광위원회에서 존경하는 황대호 위원님이 행정감사 때 하신 내용들에 대한 일부 기사 발췌인데요. 존경하는 황대호 위원님이 본인이 자체적으로 설문조사를 한 결과 직장 내 갑질 및 인권의 여부를 묻는 설문에서 경기아트센터의 43%가 “네.”라고 대답했고 이 중에 특정 간부직원의 막말 등으로 인권침해를 받고 있다고 기재했는데 이 내용 아시나요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 죄송합니다. 그 보도내용을 접하지는 못했습니다.
</p>
<p><b>○ 박진영 위원 </b> 다음 내용으로 넘어가겠습니다. 그 당시 감사했던 내용 중의 일부인데요. 설명드리면 경기아트센터 헬프라인 익명신고시스템입니다. 이거 관련해서 2023년 12월 8일 제보된 내용과 관련해서 연관성이 있어 보이는 전체 메일이 2023년 12월 11일 감사실장에게, 직원 전체에게 송부되고 이와 관련해서 공공감사에 관한 법률상의 비밀유지 의무 위반 소지가 있음을 지적하신 내용이고요. 오른쪽 페이지에 보시면 여기 이 내용은 실제로 황대호 위원님께 제보 주신 분이 했던 메일 중의 일부인데 그 당시 감사실장님 그리고 서춘기 대표님께서는 이거는 그 익명제보 헬프라인 내용과 관계가 없다 하셨는데 이 메일의 내용으로 봐서는 상당한 연관성이 있어 보이는데 어떻게 생각하세요?
</p>
<p style="padding-left:1.2em">  요점만 말씀드리면 헬프라인에 제보된 사항이 있었고요. 감사실장님이 3일 후에 그와 관련된 전체 메일을 보내셨어요. 그리고 황대호 위원님이 제보받은 사항으로 그 메일의 일부 내용들에 대해서 언급하셨는데 아무리 봐도 연관성이 있어 보입니다. 내용 확인해 주세요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 박진영 위원 </b> 그리고 제가 되게 신기한 사항을 발견했어요. 지금 경기도 종합감사 내용 중의 일부인데요. 아무리 봐도 이 건과 관련 있어 보입니다. “별별별별 해서 뭐뭐에 제보된 건에 대해 가팀은 처리절차에 따라 처리결과를 입력하지 않고 제보 내용 등을 당사자인 A가 같은 달 19시 50분에 임직원 몇 명에게 해명 이메일을 발송한 것을 별도 답변한 것으로 처리하고 시스템에는 처리결과를 입력하거나 종결에 따른 서면통지를 하지 않음” 해 가지고 시정명령 받았죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그런 걸로 알고 있습니다.
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 굉장히 상황이 이상해요. 실제로 지난해 문체위 행정감사에서 모든 제보받은 내용들이 다 드러났고 상당히 합리적인 의심이 가는 부분이 있는데 실제로 경기도가 2년 만에 갑자기 종합감사를 나가서 처리된 내용 중에 그 당시 언급된 내용이 직원의 잘못으로 시정명령 처리됐어요. 어떻게 생각하시나요?
</p>
<p style="padding-left:1.2em">  그 당시 황대호 위원님께서 제기했던 의문은 이게 감사실장님이, 법 정확하게 말씀드릴게요. 공공감사에 관한 법률상 비밀유지 의무 위반인지에 대해서 지적하셨어요. 이 부분에 대해서 감사하셨어요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 이 부분은 그때 당시에 공공기관 감사에 관한 법률 2조 및 3조에 따른 공공기관 적용 범위 대상이 아니다 이렇게 아마 그때 당시에 조사과정에서 판단이 되었던 것 같습니다. 그래서…….
</p>
<p><b>○ 박진영 위원 </b> 네? 다시 말씀 주시죠.
</p>
<p><b>○ 감사위원장 안상섭 </b> 공공감사에 관한 법률 제2조 및 제3조에 따른…….
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 아트센터 내부감사규정에도 해당이 안 되고요. 지금 종합감사의 상당 부분 내용들이 규정을 위반하여 직원들이 한 것에 대해서 상당 부분 많이 시정명령을 받았어요. 지금 아트센터 종합감사 내용을 보시면 상당히 많은 부분들이 내부규정 위반으로 지적됐어요. 근데 경기도아트센터 감사규정들은 적용 안 되고 그냥 단순히 말씀 주신 게 공공감사에 관한 법률상의 비밀유지 위반에 적용이 안 된다고 말씀 주시는 건데 맞나요? 제대로 조사하신 거 맞으세요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 그때는 그렇게 적용 범위 대상이 아닌 것으로 판단을, 아마 조사가 되었던 것 같습니다.
</p>
<p><b>○ 김정호 위원 </b> 안 들립니다. 정확히 좀 말씀해 주십시오.
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 진짜 정말 죄송한데요. 합리적으로 이해가 안 돼요. 이쯤 되면 위원장님, 저는 경기도 감사위원회가 경기아트센터를 감사한 내용 전체에 대해서 의심이 들어요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 저희도 문제가 있어서 22ㆍ23ㆍ24년에 걸쳐서, 3회에 걸쳐서 특정ㆍ종합감사 이렇게 실시한 것으로 알고 있습니다.
</p>
<p><b>○ 박진영 위원 </b> 언제요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 22년도, 23년도, 24년도에 걸쳐서 종합감사 2회, 특정감사 1회 이렇게 실시를 했던 바가 있습니다.
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 신상발언 좀 하도록 하겠습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 네.
</p>
<p><b>○ 박진영 위원 </b> 감사위원장님, 그 사건이 23년 12월에 행정사무감사에 지적이 됐는데 지금 22년도 사건을 얘기하시는 거죠?
</p>
<p style="padding-left:1.2em">  위원장님, 감사위원장님 업무 파악이 정확히 되지 않은 것 같아서 정확한 답변을 들을 수 없어서 감사위원장님이 업무 파악 정확히 해서 정확히 답변 주실 수 있을 때까지 공개적으로 정회를 요청합니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 그러면 정회를 요청하셨습니다. 다른 위원님들께서 정회 요청에 동의하십니까?
</p>
<p style="padding-left:2.4em">    (「동의합니다.」하는 위원 있음)
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 20분 정도 드리면 되겠죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 부위원장 이경혜 </b> 정회를 하기 전에 말씀을 드리겠습니다. 감사위원장님께서 위원장님이 되신 지가 얼마 안 됐기 때문에 그동안의 일들에 대해서는 충분히 숙지가 안 되셨을 수는 있다고 생각을 합니다. 다만 숙지가 안 되셨으면 다른 분들이 계시잖아요. 담당했던 분들에게라도 질문을 해서 이 답을 명쾌하게 주셔야 되는데 “그런 것 같습니다.”로 이 감사를 마무리할 수는 없다는 말씀입니다. 그러면 정회를 할 테니 위원장님께서는 충분히 숙지하시고 정리해서 “같습니다.”가 아니라 정확한 답변을 주실 수 있도록 준비해 오시기 바랍니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 이채명 위원 </b> 위원장님, 잠깐만요. 저 의사진행발언이 아니고요. 앞서서 저도 지금 늦게 자료를 받았는데요.
</p>
<p><b>○ 부위원장 이경혜 </b> 잠시만요. 의사진행발언으로…….
</p>
<p><b>○ 이채명 위원 </b> 네, 의사진행발언 하겠습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 하십시오.
</p>
<p><b>○ 이채명 위원 </b> 사실은 자료를 늦게 받아서 추가적으로 보니까 제가 그동안에 문제 제기했던 내용들이 감사에 지적이 됐고요, 보니까. 지적사항이 됐거든요. 여기에 보면 지금 현재 공직자의 이해충돌 방지법 및 아트센터 공용차량 관리규칙을 위반해서요, 처리결과에 수원지방법원에 이해충돌방지법 위반 사실 통보를 2024년 7월 5일 날 했고요. 그리고 사적 사용 운행거리에 대한 유류비 추산 및 환수 완료를 똑같이 2024년 7월 10일 날 했고요. 그래서 추가적으로…….
</p>
<p><b>○ 부위원장 이경혜 </b> 이채명 위원님, 의사진행발언을 정리만 해 주시고.
</p>
<p><b>○ 이채명 위원 </b> 네. 더 사실은 7월 15일 자로 전 부서 대상 공용차량 이용수칙 공지를 했다고 하니까요, 공용차량 이용수칙 자료를 좀 제가 받아봐야 될 것 같습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 자료 요청하시는 겁니까?
</p>
<p><b>○ 이채명 위원 </b> 의사진행과 함께, 사실 자료 요청도 못 했기 때문에.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 알겠습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 그러면 자료 요청대로 받고 의사진행발언 마무리하셨습니까?
</p>
<p><b>○ 이채명 위원 </b> 마무리하겠습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 알겠습니다.
</p>
<p><b>○ 이채명 위원 </b> 왜냐하면 자료가 진즉 왔었으면 제가 아까 자료 요구할 때 추가적으로 더 자료 요청을 했었을 텐데 자료가 지금 왔기 때문에 자료 요구를 못 하잖아요. 그래서 제가 의사진행발언과 함께 자료 요구를 했습니다. 이상입니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 알겠습니다. 김정호 위원님, 따로 하실 말씀 있으신 건가요?
</p>
<p><b>○ 김정호 위원 </b> 없습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 알겠습니다. 그러면 지금 자료가 늦게 온 이유로 위원님들께서 계속 자료를 보지 못한 채로 행감을 하실 수도 없고 주시는 답변이 정확하지 않아서 저희는 지금 계속해서 회의를 할 수는 없을 것 같습니다.
</p>
<p style="padding-left:1.2em">  정회를 요청하셨습니다. 동의하십니까?
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 감사를 중지하는 데 이의 없으시다는 말씀으로 알겠습니다. 그러면 16시 30분까지 감사중지를 선포합니다.
</p>
<p class=''ar''>(16시07분 감사중지)
</p>
<p class=''ar''>(16시32분 감사계속)
</p>
<p><b>○ 부위원장 이경혜 </b> 의석을 정돈해 주시기 바랍니다. 성원이 되었으므로 감사를 속개하겠습니다.
</p>
<p style="padding-left:1.2em">  박진영 위원님 아까 마지막 발언을 다 못 하셔서 먼저 시간을 드리고 감사위원장님 앞에 나오셔서 답변 주신 다음에 다음 위원님 질의를 하도록 하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 위원장님, 저 의사진행발언 좀 하겠습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 정승현 위원님 말씀하십시오.
</p>
<p><b>○ 정승현 위원 </b> 위원장님, 앞서 감사위원장님 답변을 쭉 들었는데요. 우리가 지금 답변을 누구한테 듣는 것도 중요하지만 오늘 행정사무감사에서 정확한 사실을 아는 게 더 저는 중요하다라고 보여지거든요. 물론 감사위원장께서 내용들을 충분히 숙지하시고 답변을 해 오셨으면 좋았을 텐데 그렇지 못한 부분에 대해서는 굉장히 아쉬움이 있습니다.
</p>
<p style="padding-left:1.2em">  그래서 제가 말씀드리고자 하는 것은 말씀드린 것처럼 정확한 사실을 아는 게 중요하기 때문에 미처 지금 감사위원장님께서 내용들에 대해서 정확히 숙지 못한 부분에 대해서는 현장에서 감사반장으로 나갔던 분이나 아니면 팀장이 됐든 정확한 내용을 알고 있는 직원으로 하여금 답변을 듣는 것도 나쁘지 않다 저는 그렇게 보여지거든요. 그렇지 않으면 오늘 회의가 원만하게, 원활하게 진행되기가 어려울 것 같습니다. 그렇기 때문에 답변 가능한 부분은 직원들이 답변할 수 있도록 그렇게 해서 회의 진행했으면 좋겠습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 알겠습니다. 감사위원장님, 그렇게 하시겠습니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 정확하게 숙지하지 못한 상태에서 미숙한 답변을 드려서 너무 죄송스럽게 생각합니다. 위원장님께서 허락해 주신다면 그때 당시에 실제로 감사를 수행했던 공공기관감사팀장으로 하여금 답변드리도록 양해를 부탁드리겠습니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 네, 그렇게 하시겠습니다. 그러면 저희가 알기에도 위원장님께서 그 시간들의 정서를 다 알 수가 없으세요. 그게 맞으시고 열심히 숙지를 하셔서 오시지 못한 부분 정승현 위원님께서 말씀하신 것처럼 아쉽기는 하지만 그럴 수 없음을 저희가 양해는 되는 바입니다. 해서 담당자가 말씀하셔도 좋습니다. 그렇게 해도 좋겠습니까, 위원님들?
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 담당자에게 말씀 듣도록 하겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 화성 출신 박진영 위원입니다. 저 발언해도 되겠죠?
</p>
<p><b>○ 부위원장 이경혜 </b> 네.
</p>
<p><b>○ 박진영 위원 </b> 아까 드리던 말씀 이어서 합니다. 이게 아까 좀 끊겨 가지고 정리를 드리면 왜 기재위 회의 행감에 아트센터 얘기가 나오냐고 물어보시면 지금 그 아트센터를 종합감사한 감사위원회에 질의를 드리고 있는 거고요. 그리고 합리적으로 철저하게 감사가 되었음이 아닐 거라는 상당한 의심이 들어서 그 부분에 대한 의문을 제기드리는 겁니다.
</p>
<p style="padding-left:1.2em">  팀장님, 대답하시기 전에 다시 한번 또 말씀드리겠습니다. 거짓증언 시 고발될 수 있음을 주지해 주십시오.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네, 알겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 아까 여쭤봤던 사항 중에 가장 중요한 사항이 경기아트센터 관련 직장 내 괴롭힘, 갑질 등에 관련해서, 당시 감사관실이죠. 감사관실에서 제보받은 사항들 있었나요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 공공기관감사팀장 추성아입니다. 답변드리겠습니다. 제보사항은 있었고요. 저희가 제보사항에 대해서는 공식적으로 처리해서 처분이 나간 건은 확인 결과…….
</p>
<p><b>○ 박진영 위원 </b> 그걸 여쭤보는 게 아닙니다. 제보사항이 있었으면 그 업무를 처리했던 절차를 여쭤보는 겁니다. 제보사항이 있었다면 그 제보사항과 관련해서 대상자, 제보를 했던 제보자 만약 확인된다면 및 피제보자를 불러서 그 내용을 확인하셨나요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네, 저희가 현장에서…….
</p>
<p><b>○ 박진영 위원 </b> 기록 있으면 기록 주세요. 기록이 있나요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 아니, 위원님, 양해를 해 주실 게요. 저희가 현장에서 감사를 할 때는 그 사항들을 확인한 후 문제점이 확인되면 확인서를 받고 그다음에 처분요구서 검토대상이 되는지를 확인하고 있습니다. 그래서 지금 저희가…….
</p>
<p><b>○ 박진영 위원 </b> 하나만 더 여쭤보겠습니다, 팀장님. 이게 좀 빨리 끝내야 돼서. 
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네.
</p>
<p><b>○ 박진영 위원 </b> 제보가 몇 건이었나요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네?
</p>
<p><b>○ 박진영 위원 </b> 제보가 몇 건이었나요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 제보사항 전체적으로는 52건이었습니다. 
</p>
<p><b>○ 박진영 위원 </b> 제보가 52건이었으면 52건에 대해서 다 확인을 하셨는데 그 누구도 갑질을 안 했다고 하나요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 그러니까 말씀하신 갑질 사항에 대해서 저희가 확인을 했는데요.
</p>
<p><b>○ 박진영 위원 </b> 몇 건이었죠, 그게?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 갑질 건은 감사실장 1건으로 알고 있습니다.
</p>
<p><b>○ 박진영 위원 </b> 아, 갑질 건은 감사실장 1건이었어요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 그거 1건하고 다른 사건과 연관된…….
</p>
<p><b>○ 박진영 위원 </b> 갑질 관련된 건이요, 네. 감사실장님이 갑질을 하면 그거에 대해서 제재할 수 있는 사람이 있나요, 경기아트센터에서? 갑질에 관련해서 갑질을 하면 그 갑질을 감사하셔야 되는 분이 감사실장님인데 그거에 대해서 통제할 수단이 있나요? 없죠? 통상 그러면 전체 직원을 대상으로 해서 갑질이 있었는지 없었는지에 대한 여부를 여쭤봤어야 되는 거 아닌가요, 상당한 의심이 가는 부분에 대해서? 
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 저희가 제보된 사항에 대해서는요, 그거와 관련된 분들한테 확인을 했고요. 그다음에 내부적으로…….
</p>
<p><b>○ 박진영 위원 </b> 그거는 특정감사 때죠. 이거 종합감사시잖아요. 종합감사 때 어떤 사항이 의심이 되면 그 사항을 철저하게 검사하셔야 되는 거 아니에요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네, 맞습니다. 그래서 현장에 갔었을 때 이미 직장 내 괴롭힘으로 서류가 나와 있거나 그런 상황들에 대해서는…….
</p>
<p><b>○ 박진영 위원 </b> 그 내용 주세요. 감사실장님에 대해서 제보됐다는 1건. 그거 1건만 제보됐다고 주세요. 만약에 제가 다른 방식으로 경기도 감사관에 제보된 사항들이 있었는데 1건 이상의 건이 발견될 경우에는 분명히 위증이라고 말씀드립니다. 그 내용 주세요. 그 내용 리스트 해서 작성해서 주십시오.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 아니…….
</p>
<p><b>○ 박진영 위원 </b> 확인 가능한 사항만 주세요. 제가 확인하고 싶은 거는 제보된 건이 1건이었다라는 것만 확인하고 싶은 거고요. 그리고 이런저런 얘기하면 너무 길어질 것 같아서 말씀드릴게요. 이 건, 헬프라인에 관한 건 이거 아까 답변 주세요.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네, 알겠습니다. 
</p>
<p><b>○ 박진영 위원 </b> 이거 공공감사에 관한 법률, 지금 말씀해 주세요, 법률상 비밀유지의 의무에 해당되지 않는지. 그리고 경기도 감사 규칙의 비밀유지의 의무 업무에 해당되지 않는지.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네, 위원님 말씀해 주신 사항에 대해서 답변드리겠습니다. 당시에 저희가 헬프라인 제보사항에 대해서 처리 절차 미준수라고 이 처분을 했던 이유는 말씀 주신 대로 언론보도상에 감사실…….
</p>
<p><b>○ 박진영 위원 </b> 처리 절차 미준수 말씀드리는 거 아닙니다. 지금 황대호 위원님이 공개적으로 감사실장님이 헬프라인에서 얻은 정보를 전체 직원에게 메일을 뿌렸다라고 합리적인 의심을 제기하셨고 그거에 대해서 조사하셨는지요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네. 저희가 현장에서 언론보도 제기된 그 사항에 대해서 말씀 주신 대로 공공감사법 등 비밀유지 의무와 내부감사규정 위반 의혹에 대한 검토를 추가로 했었습니다. 그런데 이 사용을 확인할 때 저희가 내부에도 그때 당시에 늘품팀장님하고 공익제보지원팀장님이 법률전문가시기 때문에 내부 자문을 먼저 거쳤는데요. 우선 아까 말씀하신 첫 번째 공공감사에 관한 법률은 제2조 및 제3조에 따르면 엄밀히 따지면 지금 아트센터는 지방출자ㆍ출연기관이지 이 공공감사에 관한 법률의 적용대상이 아닙니다. 이거는 감사원에서 매년 고시를 하고 있는데 거기에 해당되는 기관은 GH하고 킨텍스만 해당이 되고요. 그래서 일단…….
</p>
<p><b>○ 박진영 위원 </b> 내부감사규칙은요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 그리고 말씀 주신 대로 아트센터 내부감사규정에 비밀누설 저촉 여부가 있습니다. 그런데 이 사항을 확인한 결과 제보자가 주장하는 그 개인정보가 이 익명제보는 본인만이 확인할 수 있기 때문에, 다른 사람들한테 간 것으로 노출된 것이 아니기 때문에 성립할 수 없고 그다음에 헬프라인 특성상 제보자 외 타인한테는 공개되지 않고 있습니다. 그리고 말씀 주신 대로 혹시 이게 그러면 형법상의 위법상 다툼 소지가 있느냐 이 사항을 보면 아트센터 내부감사규정 제12조제1항제2호에 따르면…….
</p>
<p style="padding-left:2.4em">    (타임 벨 울림) 
</p>
<p><b>○ 박진영 위원 </b> 시간이 없어서 그거 보고 주시고요. 그리고 말씀드리는데 진짜 합리적으로 이해가 안 돼서 그래요. 헬프라인이라는 익명제보시스템에 제보된 사항을 감사실만 볼 수 있고 감사실장님이 그와 관련된 메일을 3일 후에 전체 메일로 뿌렸으면 헬프라인이라는 게 필요한가요? 법률적인 부분을 떠나서 헬프라인이라는 걸 신뢰할 수 있으세요? 
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 지금 그래서 말씀 주신 대로…….
</p>
<p><b>○ 박진영 위원 </b> 헬프라인 열람자, 열람 시간 로그 제출해 주세요. 이것도 없다 하실 건가요? 헬프라인이 익명제보 감사시스템인데 이 시스템에 로그인해서 확인하신 분에 대한 로그조차 없다고 말씀하시지는 않겠죠? 아트센터 헬프라인 열람하신 분 열람자, 열람 시간 로그 주세요.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 저희 감사자가 확인한 걸 요청하시는 걸까요?
</p>
<p><b>○ 박진영 위원 </b> 아니요. 아트센터에 요청해서 주십시오. 당연히 감사자도 그걸 확인하셨어야죠, 그 상황에서.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 그런데 위원님, 그러면 저희가 지금 감사가 끝났는데 자료를 요청해서 제출해 달라는 말씀으로 이해하면 될까요?
</p>
<p><b>○ 박진영 위원 </b> 감사실에서 그 자료를 확인했는지 확인해서 주세요. 확인 안 하셨다면 감사를 충분히 하지 않으신 걸로 생각하고요. 제가 자료 따로 그쪽에 요청할게요. 
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네, 알겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 일단 사실관계부터 확인하셨어야 되는 게 맞잖아요, 이런 상황이면.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 맞습니다. 확인하겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 헬프라인에 접속을 하셨는지 그리고 그 정보를 확인하셨는지 그리고 그 정보를 확인해서 전체 메일을 뿌릴 때 연관성 있는지 확인하셨어야 되는 건데, 당연히 합리적인 절차인데 그거조차 감사실에서 확인 안 하셨다면 감사실의 감사도 충분히 문제가 있는 것 같고요. 전체적으로 지금 상황들을 모두 바라볼 때요. 경기아트센터를 감사함에 있어 경기도 감사실이 과연 합리적이고 충분한 감사를 하셨는지 그리고 하나의 케이스를 빗대어 볼 때 경기도 감사실이 공공기관을 감사하실 때 충분한 사항들을 고려해서 감사를 하시는 건지 상당한 의심이 되고요. 이 건에 대해서는 상황상은 행정조사를 해야 될 상황도 있다라고 생각합니다. 이상입니다.
</p>
<p><b>○ 부위원장 이경혜 </b> 박진영 위원님 수고하셨습니다. 하고 싶은 말이 많습니다만 저도 참고 다음 질의를 이어가도록 하겠습니다. 다음 이혜원 부위원장님 질의하십시오.
</p>
<p><b>○ 이혜원 위원 </b> 이혜원 위원입니다. 지금 저도 박진영 위원님이 말씀하신 부분에 충분히 공감을 하고 2023년 문화체육관광위원회 경기아트센터 행정감사장에 있었습니다. 이 질문에 대한 부분들에 대해서도 같이 진행을 했습니다. 여기 감사실에서 지금 답변하는 부분들이 너무 답답하고요. 어떻게 감사위원회에서 공공기관 감사를 하는데 이게 감사인 건지 지도점검을 하신 건지 내부 자체감사를 하는 것만큼도 감사를 안 하시는 것 같습니다. 감사위원회가 감사위원회다워야 되는 거 아닙니까? 이거 어떻게 신뢰를 하고 감사위원회 말씀을 들어야 될지 참 의구심이 듭니다. 
</p>
<p style="padding-left:1.2em">  제가 감사위원회에 요청한 자료 아직 안 왔습니다. 미제출 자료는 아직 안 왔고요. 요청한 자료 중에 왔었던 게 그 감사에 따른 아트센터 처분 요구 및 통보 공문 사본을 좀 달라고 했고 그 사항을 요구할 때 만약에 이메일로 통보된 내용이 있으면 이메일 통보 결과에 대한 내용까지 좀 달라고 했는데 이거 하나 딱 왔습니다, 사본. 
</p>
<p style="padding-left:2.4em">    (자료를 들어 보이며)
</p>
<p style="padding-left:1.2em">  경기아트센터의 종합감사 결과 통보 이 내용 왔고요. 밑에 붙임에 “종합감사 결과 보고 담당자 이메일로 비번 해서 통보했다, 이메일로 통보했다.”라는 내용이 있어요. 제가 제보받은 내용 중에 제보자한테 담당자, 제보 당사자한테 개인 메일로 답변을 하신 것 같아요. 그런데 답변 내용이 “해당 없음. 조치하였음. 향후 이런 일 없도록 하겠음.” 이게 통보 내용입니다. 부원장님, 이해가 되십니까? 감사실 감사위원회 이렇게 이끄실 겁니까, 앞으로도? 이거 행정사무조사 해야겠죠? 이렇게 답변이 안 나오고 계속 어떤 절차도 밟지 않고 52명이 접수가 됐는데 증언도 하나도 듣지 않고. 누가 답변하시겠습니까? 답변 가능하신 분이 답변해 주십시오.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 제가 잠깐 말씀을 드리겠습니다. 아까 말씀드린 자료들에 대한 것은 행정사무감사를 위해서 공개된 감사자료는 제출하는 게 맞는 것 같습니다. 다만 정보보호와 관련된 부분 그런 부분들 때문에 저희가 공개된 자료를 좀 구체적으로 설명을 드릴 수 있으면 위원님들께 설명드리는 방법으로…….
</p>
<p><b>○ 이혜원 위원 </b> 참 희한합니다, 위원장님. 진짜 무슨 제출할 수가 없다고 해 놓고 행감장에서 이렇게 얘기를 하니까 7분 만에 경기연구원에서도 자료를 주시지를 않나 감사위원회도 못 주겠다고 하시더니 제출해야 되는 게 마땅하다고 하시는데 도대체 어떤 기준으로 자료를 주고 안 주고를 판단하시는 건지 심히 유감입니다. 이 부분에 대해서는 행정사무조사 관련된 부분은 위원님들과 심도 있게 논의를 해서 결정해야 될 사안인 것 같고요. 감사위원장님, 앉으십시오. 
</p>
<p style="padding-left:1.2em">  경기연구원에 질의를 해야 될 것 같습니다. 부원장님, 자리에 계시죠?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 이혜원 위원 </b> 아까 제출하지 못하겠다고 비공개 요청해서 대외주의 하셨던 부분 사유 답변해 주십시오. 
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네. 당시 대외비를 했던 이유는 저희가 가맹점 관리 기준이다 보니까 그 보고서 내용에도 있습니다만 예를 들어서 대형점포와의 포함 여부라든가 그다음에 지역마다 다른 기준들을 조정하는 그런 민감한 사안들이 있어서 그런 것들이 경기도가 공식적으로 정리해서 정책을 추진한다라는 것을 전제했으면 발표할 수 있었을 텐데 그 이후에 뚜렷한 정책 추진이 없어서 보고서의 내용을 당분간 연구만 하고…….
</p>
<p><b>○ 이혜원 위원 </b> 네. 부원장님, 알겠습니다. 이게 21년도에 마무리된 거예요. 그렇죠?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 그렇습니다. 
</p>
<p><b>○ 이혜원 위원 </b> 21년 5월 10일. 3월 10일 날 해서 5월 10일 날 끝났습니다. 그런데도 대외비예요?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 그 부분에 대해서는 저희가 그 대외비 관리 절차를 다시 한번 들여다보겠습니다.
</p>
<p><b>○ 이혜원 위원 </b> 이게 제가 결론을 잠깐 아까 와서 보니까 이거 7분 만에 주셨는데 제로섬 게임에 대한 부분들이 있어요, 계속 얘기가 나왔던. 경기화폐가 이게 효과가 있느냐, 제로섬일 수 있다라는 결과가 있고요. 그렇죠?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.  
</p>
<p><b>○ 이혜원 위원 </b> 또 가맹 등록에 대한 제한이 불가피하다는 내용도 있고 이런 부분 때문에 대외주의를 지정을 하신 것 같은데 대외주의 지정 누가 합니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 대외주의 지정은 현재 저희가 관련 부서와 협의를 통해서 경기도의 요청에 의해서 저희가 대외주의 지정하고 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그러면 경기도 요청해서 누가 결정을 하냐고요, 최종 결정권자.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 당시에 그 과제를 요청했던 부서에서 예를 들어서 민감한 사안이다 그러면 대외비 요청을 하시면 저희가 대외비를 하고 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 그러니까 그 대외비 결정을 누가 하냐고요. 도지사가 합니까? 
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 아닙니다. 저희 연구원에서 자체적으로 하고 있습니다.
</p>
<p><b>○ 이혜원 위원 </b> 자체적으로 합니까? 
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네. 
</p>
<p><b>○ 이혜원 위원 </b> 그러니까 자체 누가 하시냐고, 그 당시에 그럼 원장님이 결정하시는 거예요?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 연구성과보고회 위원장이 결정합니다.
</p>
