<p><b>○ 정승현 위원 </b> 정승현입니다. 행정사무감사 굉장히 중요한 자리임은 다들 인식하고 또 그러실 텐데 여러 가지로 아쉬움이 좀 있습니다. 또 그 부분에 대해서는 충분히 이해하고 남음이 있습니다. 업무 파악을 하시기에는 물리적으로 좀 어려운 부분이 없지 않아 있다라고 보여지기 때문에 그 부분에 대해서는 이후에는 이런 일들이 없도록 충분히 업무 파악에 심혈을 기울여서 의회와 함께할 수 있었으면 좋겠다는 말씀을 드리면서 저는 지난 과정에 대한 문제 부분에 대해서 여쭙는 것은 또 답변과정에서 서로가 원만하지 못할 것 같아서 우리가 지금 감사위원회 출범 이후에 계획하고 있는 부분에 대해서 좀 여쭙도록 하겠습니다.
