<p><b>○ 정승현 위원 </b> 또한 지금 시대적 변화의 흐름에 맞춰서 여러 가지 행정환경들이 변하고 그렇기 때문에 이러한 감사업무에 대응하고자 이런 용역을 실시하고 감사시스템을 구축하겠다라고 하는 건데 그렇게 봤을 때 저는 굉장히 많은 준비가 좀 필요하다라는 생각을 해 보게 돼요. 그런 측면에서 이 용역과정이 지금 내년 1월 중순경에 최종 완료되는데 그렇다면 약 두 달이에요. 두 달 동안 이 용역을 통해서 우리가 당초 목적에 부합하는, 맞는 혁신적인 감사업무를 선도할 수 있을 만한 그런 용역이 나올 수 있을까 하는 그런 의구심이 한편으로는 들게 돼 있어요. 어떻게 생각하세요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 그래서 지금 지난 금요일 날 착수보고회를 하면서 그런 부분도 아울러서 여러 전문가들 모시고 검토를 함에 있어서, 검토를 하는데 최소한 3명은 상주하면서 참여율을 90에서 한 100% 정도 하고 전체 6명 정도가 참여하면서 이 용역업무를 수행하게 한 계획입니다. 당시에 IT 전문가들도 이런 인원이 상주하면서 이런 ISP 용역을 한다는 것에 대해서 크게 기대를 하고 염려와 우려에 대해서는 조금 안심하는 그런 의견 표명들을 많이 하셨습니다.
</p>
<p><b>○ 정승현 위원 </b> 제가 왜 이거를 우려하냐면 과업내용이나 시스템 구성도를 보니까 굉장히 복잡하고 정말 정밀하게 세밀하게 준비하지 않으면 감사시스템 구축 또한 허점이 많이 있을 거다라는 측면에서 다소 용역기간이 짧지 않냐라는 생각을 해 보게 되는 거죠. 용역 제안요청서 내용만 보면 굉장히 우리 도민들을 포함한 도민 눈높이에 맞는 그런 감사업무 혁신을 기대할 수도 있겠다. 또한 제안요청서 추진전략에도 보면 각 기관별로 보유하고 있는 행정정보시스템 상호 연계를 통한 감사체계 고도화 또 대내외의 감시환경 및 기존 감사업무 분석을 통해서 불필요한 업무 제거 등 효과적인 감사 지원체계 구현 그리고 도민과 소통하는 쌍방향 체계를 구축하겠다. 또 감사정보 공유를 위한 지식분류체계를 마련해서 지식 창출 내지는 공유를 활성화하겠다라는 이런 내용들이에요. 이런 내용들을 세부적으로 담아내려면 용역 자체의 어떤 질도 좋고 그 질에 따른 시스템 구축하려면 별도로 사업 발주를 또 해야 되는 거잖아요. 그런데 그 사업 발주라는 게 이 용역결과에 따라서 하게 되는 거잖아요. 그래서 이 용역이 말 그대로 효율성이 있고 실질적으로 우리가 추구하는 그런 용역이 될 수 있도록 지속적으로 같이 대화가, 용역사와 같이 얘기들이 있어야 될 것 같아요. 그렇죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 좋은 말씀 감사합니다.
</p>
<p><b>○ 정승현 위원 </b> 또 하나는 이 추진전략 중에서 하나가 행정정보시스템 연계를 위한 기관별 시스템, 행정정보시스템을 연계한다고 했는데 그러려면 각 기관별 시스템에 대한 표준화가 전제돼야 될 필요성도 없지 않아 있겠다라는 생각을 해 보게 되는 거죠. 그런데 감사업무 특성상 각 여러 가지 사안들이 있기 때문에 시스템 하나로 표준화하기가 결코 쉽지 않을 거라는 그런 생각도 들거든요. 이런 부분에 대해서는 고민해 보셨어요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 앞서 염려하시는 부분, 처음 작업이라서 많은 욕심은 부리지 않고 천천히 가는 방식입니다. 그래서 처음에 초기와 천천히 가면서 고도화하고 그런 방식이고요. 그다음에 아까 말씀하신 부분과 관련해서 전문적인 감사인들과 함께 TF 구성해서 용역사하고 같이 할 거고요. 표준화도 가장 중요한 대목이긴 합니다. 그래서 한국지역정보개발원이라는 곳을 통해서 연계받을 수 있는 경우 시스템들을 연계하고요. 또 아울러서 그 외에 모든 수동으로 다운받아서 업로드하는 상황에 맞는 방식으로 일단 표준화를 하고 그 이후에 고도화들을 할 수 있는 초기 작업들을 표준화 속에 담아내는 그런 방식이어서 염려되는 부분들 잘 체크해서 성실히 수행하도록 하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 감사정보 구축 시스템 이거는 보도자료에도 냈던 것처럼 전국 최초로 지금 이 시스템을 구축한다는 것 아니에요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 그렇다 그러면 다른 지방자치단체에서도 굉장히 예의주시를 하고 있을 거예요. 그런 만큼 늘 제가 말씀드리지만 경기도의 정책은 정말 표준화, 기준화가 돼야 된단 말이에요. 그런데 경기도에서 이런 감사정보시스템 구축을 했는데 그게 별 효율성이 없다 그런 평가를 받으면 안 되겠죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 그래서 그런 부분에 대해서 만전을 기해서 준비를 좀 하시라는 당부말씀을 드리겠습니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 좋은 말씀 감사합니다.
</p>
<p><b>○ 정승현 위원 </b> 또 하나는 공공기관 감사협의체에 대해서 한번 여쭤볼게요. 얼마 전에 공공기관 감사협의체 회의를 하셨죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 거기에서 이해충돌 방지제도 운영지침 등 부패취약분야와 관련해서 해결방안들을 논의한 걸로 알고 있는데 일반감사도 그렇지만 공공기관감사에서도 주로 지적된 사항이 매번 반복해서 똑같이 지적이 되고 있어요. 물론 케이스별로 다른 부분들도 있지만. 용역 적격심사 관련 지방계약법 위반 그리고 또 하나는 이해충돌방지법 위반 이런 부분들이 계속해서 반복적으로 지금 지적되고 있는데 이 공공기관 감사협의체에서 이런 회의를 통해서 실질적으로 이런 부분들을 사전에 방지할 수 있는 그런 구체적 대안들이 논의가 돼야 될 필요가 있다. 그래서 이런 반복된 지적들이 나오지 않아야 된다라는 생각이거든요. 그런 측면에서 이 협의체가 구성됐다라면 거기에서 각 공공기관에 어떤 선한 영향력을 발휘할 수가 있을 것인지에 대한 기대감 굉장히 큰데 한번 말씀 좀 해 주세요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 답변드리겠습니다. 공공기관 감사협의체는 일단은 자체감사기구, 말하자면 공공기관의 자체감사기구의 역량이 조금 미약해서 이런 반복되는 지적사항들이 많이 나오기 때문에 이 공공기관 자체감사기구의 역량을 키우면서 그들을 교육하고 그다음에 소그룹으로 성공사례들을 공유하고 또 아울러 여러 가지 공공기관에서 지적되어질 수 있고 반복되어지는 문제점들을 어떻게 감사를 해 갈 것인가 같은 것들을 발굴하고 아울러 아까 위원님께서 말씀하셨지만 그런 반복되는 점들을 어떻게 예방적으로 막을 것인가 이런 것들을 같이 고민하는 협의체여서 이걸 잘, 연 2회 하는데요. 잘 운영을 해서 염려하는 부분 없도록 하겠습니다.
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p><b>○ 정승현 위원 </b> (위원장석을 향하여) 조금만 더 쓰겠습니다.
</p>
<p style="padding-left:1.2em">  지금 아트센터 얘기가 많이 나오는데 아트센터를 포함해서 최근의 경기도청소년수련원, 경기평생교육진흥원 종합감사 결과를 보더라도 보면 어떻게 이런 지적사항들이 지금도 나오나 싶은 생각을 해 보게 되는 거죠. 예를 들면 협상에 의한 계약 추진 시 관련 규정 미준수, 다시 말씀드리면 추정가격이 10억 원 미만 1억 원 이상일 경우에는 20일 이상 입찰공고해야 하는데 이 공고기간을 지키지 않은 부분 또 입찰공고에 따른 개찰 후에 1순위부터 적격심사를 하면서 적격심사 통과가 예상되는 선순위 업체에게 심사포기서를 받거나 심사포기서도 받지 않은 채 후순위 업체와 계약을 체결한 사례. 입찰심사에서 경영상태 정량평가 시 A업체의 최저 배점이 2.6이에요. 근데 0점을 부여했어요. 또 입찰참가자격이 없는 자와 수의계약 그리고 이해충돌과 관련해서 직무 관련자가 사적 이해관계자임을 안 경우에는 안 날로부터 14일 이내에 그 사실을 서면으로 신고하고 회피를 신청해야 하는데 이행하지 않은 것. 어떻게 보면 가장 상식적인 이런 부분들이 지적되고 있다는 거예요, 그것도 공공기관에서. 이거 있어서는 안 되는 일 아니에요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다. 그래서 그런 부분과 관련해서는 지속적으로 계도를 하고 있는데 위원님들이 지적하는 바와 같이 반복되고 있어서 그런데 대한, 예방과 방지에 대한 고민들을 하고 있습니다.
</p>
<p><b>○ 정승현 위원 </b> 이런 부분들을 해결하기 위해서는 정말 뭔가 좀 이 협의체 운영을 통해서 시스템적으로 접근을 해야 돼요. 그래야지 이런 가장 상식적인 부분들이 계속해서 반복적으로 지적되고 오류를 범하는 일이 없도록 해야 된다라는 거예요. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 그래서 저희도 공공기관에 가이드북을 만들어서 반복되는 것들에 대한 예방조치로서 그런 것들을 홍보뿐만이 아니라 교육적 가이드북도 많이 만들어서 배포하고 개선이 됐다고는 하나 물론 아직도 그런 부분, 위원님이 지적한 부분들은 분명히 있습니다.
</p>
<p><b>○ 정승현 위원 </b> 각 기관에 있는 감사시스템만 가지고 공공기관의 이런 행태들을 개선하기는 쉽지 않다라는 것들이죠. 그래서 그런 측면에서 우리 감사위원회의 역할이 굉장히 크다라는 거예요. 다 지금 주목하고 있다라는 거예요. 그렇기 때문에 감사위원회가 출범한 만큼 그런 부분들도 다소 시일은 걸릴 수 있겠습니다마는 그런 부분들이 해소될 수 있도록 역할을 충분히 해 주시기를 당부드립니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 잘 알겠습니다. 그러니까 공공기관 감사에 대한 시스템화 지적하신 부분들 숙지해서 감사하는 데 활용을 하도록 하겠습니다. 고맙습니다. 
</p>
<p><b>○ 정승현 위원 </b> 이상입니다.
</p>
<p style="padding-left:2.4em">    (이경혜 부위원장, 이혜원 부위원장과 사회교대)
</p>
<p><b>○ 부위원장 이혜원 </b> 정승현 위원님 수고하셨습니다. 다음 질의는 양우식 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 양우식 위원 </b> 양우식 위원입니다. 아침부터 긴 시간 고생들 많이 하십니다. 왜 이렇게 자꾸 정회와 개의가 반복될까요? 그 뒤에 계신 분들 고개 좀 들어보세요. 위원님들 질의하시는데 집중하셔야죠. 왜들 그러시나요? 
</p>
<p style="padding-left:1.2em">  그렇습니다. 어제부터 이렇게 감사를 하는데 저희 기재위 소관 기조실뿐만 아니라 어제 기조실 끝난 이후에 위원님들이 감사태도와 수감태도가 정말 예전 같지 않다. 특히 작년에 기재위가 감사를 안 받은 이후 여파가 지금까지 미치는 것 같다, 등등 여러 가지 말씀들을 많이 하셨어요. 조금 더 적극적으로 수감에 임해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  경기도연구원의 우리 부원장님, 잠깐 앞으로 좀 나와보십시오.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 양우식 위원 </b> 제가 지금 경기연구원의 자료들 좀 보니까 연구실적들이 굉장히 저조합니다? 목표 달성치를 못 이루고 있죠, 지금? 
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 양우식 위원 </b> 그 이유가 어디에 있습니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 저희 연구과제가 통상적으로 연초에 이렇게 한꺼번에 이루어지는 건 아니고요. 연구과제 수요라든가 이런 걸 고려해서 연중 나눠지는데 저희가 조금 목표 대비 저조는 하고 있습니다마는 연말까지 다 계획 달성을 할 거라고 예상을 하고 있습니다.
</p>
<p><b>○ 양우식 위원 </b> 그 답변이 저는 잘못됐다고 생각합니다. 부원장님! 
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
