<p style="padding-left:1.2em">  과거에 어떤 도지사가 취임을 하든지 간에 꼭 2025년도, 내년 3년 차가 되면 특정 연구들이 무작위로 쏟아지는 경우들이 많아요. 우리 부원장님이 하셔야 될 역할이 차기에 원장님이 오시면 또 말씀드리겠지만 내년도 연구계획은 사전에 잘 수립해서 연말 이전에 끝내야 됩니다. 연구과제 지금 11월 달인데 목표치 이제 3분의 2도 못 채우고서는 연말에 하겠다. 연말까지는 목표치 달성하겠다. 그럼 올해 연구과제 한 건 언제 적용해서 언제 쓰실 거예요? 그런 연구과제는 하나 마나예요. 안 하는 게 나아요, 그런 건. 그렇지 않아요? 답변이 안 된단 말입니다, 그런 건.
