<p><b>○ 양우식 위원 </b> 아니, 규정대로 하시면 되잖아요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그래서 지금은 그런 고민들이 있었고요. 그런 고민 후에 우리가 그런 한계는 있지만 의회의 요청이 있었으니 이제 할 수 있는 범주 내에서 의회사무처에 대해서 감사를 할 수 있지 않겠는가라는 의견 수렴이 있어서 그와 관련해서…….
</p>
<p><b>○ 양우식 위원 </b> 제가 의회에 무분별한 감사를 하라고 요청하는 게 아닙니다, 이거는.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 양우식 위원 </b> 허위공문서, 직인이 찍히지 않은 문서가 효력을 가질 수 있는지에 대해서 핀셋 검증만 하고 그거에 대한 의견만 제출하면 되는 거예요. 이게 뭐가 그렇게 어려워요? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 그런데 이게…….
</p>
<p><b>○ 양우식 위원 </b> 아니, 그냥 법과 규정에 딱 정해져 있잖아요. 의장은 교섭단체 대표의원과 협의하여 추천하여야 한다. 대표는 직무 정지됐어요. 협의할 대상이 없어. 그런데 밑에 공무원이 직인 없는 문서를 만들어서 의사담당관실 보내서 그게 의장을 거쳐서 도지사한테 넘어가. 이게 공문서의 효력이 있어요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 위원님이 말씀하신 부분들도 물론 충분히 공감이 가는데요.
</p>
<p><b>○ 양우식 위원 </b> 아니, “충분히 공감이 가는데요.”는 뭐예요? 공감, 그게 아니라고 얘기를 하셔야 되는 거 아니에요? 위원장님이 그렇게 명확히 답변도 못 해 주시면 어떻게 해서 그 감사를 할 수 있어요, 그게?
</p>
<p><b>○ 감사위원장 안상섭 </b> 그래서 그런 고민 속에서 이제 감사를 할 수 있다라고 해서 조사할 예정으로 아마…….
</p>
<p><b>○ 양우식 위원 </b> 언제 하실 거예요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 지금 문답 등 일정들을 조율하고 있어서요. 문답, 맞는 일정들을 조율하고 있어서 곧 조사에 착수할 예정이고 아마 관련 서류를…….
</p>
<p><b>○ 양우식 위원 </b> 자, 그거에 대해서 여기 진술서 나온 거 이거에 대해서 후속조치 해서 이거 작성한 사람 누구의 지시로 했는지 그리고 여기에다 추가적으로, 이걸 갖다가 의사담당관실에서 받았어요. 교섭단체에서 의사담당관실로 보냈는데 대표의 직인이 없는데 의사담당관실에서 이걸 문서로 인정한 여부, 그 의사담당관실까지 확인하세요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 양우식 위원 </b> 의사담당관실에서는 여기에서 의장님이 도지사한테 보낸 서류에 대해서는 그 과정의 적법함이 논외일 수 있겠지만 교섭단체에서 의사담당관실로 보냈는데 의사담당관실은 직인이 없는데, 대표가 없는데 그 서류를 갖다가 문서로 인정한 부분, 이 부분에 대해서 정확히 다시 한번 점검하십시오.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 무슨 말씀인지 잘 알겠습니다. 그런데 그러기 위해서는 또 이제 대표님에 대한, 교섭단체에 대한 조사 필요가 있을…….
</p>
<p style="padding-left:2.4em">    (타임 벨 울림) 
</p>
<p><b>○ 양우식 위원 </b> 어떻게…….
</p>
<p><b>○ 부위원장 이혜원 </b> 보충질의 5분 쓰셨는데 더 쓰시겠습니까?
</p>
<p><b>○ 양우식 위원 </b> 네, 2분만 금방 쓰겠습니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 조사가 있을 수 있어서 그런 의사활동, 의원님들의 의사활동들에 대해서 감사가 가능한가 그런 고민들이 있습니다.
</p>
<p><b>○ 양우식 위원 </b> 다시 한번 제가 정리해 드릴게요. 의원님들에 대해서 조사하라는 게 아닙니다. 규정에 권한이 없는 자가 공문서를 만들어서 발송한 거에 대한 문서가 효력이 있는지를 확인하라는 거예요. 그 문서를 공무원이 작성을 해도 되는지, 지시권자가 없는데 만들어진 문서가 효력이 있는지, 그 문서를 공무원이 만들어도 되는지를 확인하는 거예요, 이거는. 의원님들을 감사하라는 게 아닙니다. 의정활동을 감사하라는 게 아니에요. 여기에 계신 분들은 교섭단체에 소속이 돼 있어도 공무원 신분이에요. 무슨 말씀인지 아시겠어요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 충분히 이해합니다. 그런데 권한이 있는지 없는지와 관련해서 또 저희도 조심스러운 부분이 있어서 그런 것들에 대한 말씀을 위원님한테 호소를 드리는 겁니다.
</p>
<p><b>○ 양우식 위원 </b> 규정대로만 하십시오, 규정대로만. 네?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 양우식 위원 </b> 빨리 진행해서 보고하십시오.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 어쨌든 문답 일정 잡히면 조사를 하기로 지금 예정은 되어져 있습니다.
</p>
<p><b>○ 양우식 위원 </b> 신속하게 하십시오.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 양우식 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 이혜원 </b> 양우식 위원님 수고하셨습니다.
</p>
<p style="padding-left:1.2em">  감사위원장님, 답변을 좀 명확하게 하십시오. 지금은 현재 감사위원장이시지 않습니까? 명확하게 해 주시고요.
</p>
<p style="padding-left:1.2em">  다음 사전에 협의한 대로 지금 질의 순서대로 위원님들 질의를 드리고 있습니다, 기회를. 다음은 박상현 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 박상현 위원 </b> 부천 오쇠리 출신 박상현입니다. 일단 경기연구원부터 얘기하겠습니다, 분위기도 좀 쇄신할 겸.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 박상현 위원 </b> 일단 먼저 제가 요청했던 경기연구원에 관련된 정책연구 과제가 어떻게 도정에 반영이 되는지에 대해서 적시해 주셔서 대단히 감사합니다. 다만 이 도정에 반영이 될 때 담당 협업과라든지 협업 담당자가 있을 텐데 추후에 누가 주무부서이고 누구랑 협업을 했는지에 대해서 꼭 기재를 좀 해 주세요.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 알겠습니다.
</p>
<p><b>○ 박상현 위원 </b> 나중에 사실관계 확인을 위한 겁니다. 그리고 사실 우리 경기연구원은 경기도정에 관련된 정책연구를 통해서 발전시키는 핵심부서이죠. 그런데 아까 말씀드렸다시피 그 정책이 죽으면 안 됩니다. 어떻게 해서든지 경기도정에 반영이 돼야 됩니다. 그러기 위해서는 협력이 정말 잘 되고 있는지를 확인해야 되는데요. 제가 이번 올해 같은 경우에는 경기연구원의 김국동 박사님하고 추진했던 경기도형 의료기기 전 주기 사업 정책연구에 관련돼서 굉장히 어떻게 보면 협력적인 관계를 이루었어요. 그래서 그분들과 논의를 하면서 느꼈던 점은 딱 이거더라고요. 경기연구원에 관련된 어떻게 보면 박사급 과제책임자분들은 자신들은 정말 정책연구만 잘하면 된다라고 하는 생각이 확고하시고 그리고 그분들은 연구만 잘하면 되지, 이 정책을 가져다 쓰는 것은 경기도가 해야 할 일이다라는 생각들이 많이 있는 것 같아요. 그런 부분에서 생각의 차이를 많이 극복하기 위해서 많이 만났고 다행스럽게 그런 정책사업들이 어떻게 보면 담당 협력부서하고 협력하는 관계를 가지게 됐습니다.
</p>
<p style="padding-left:1.2em">  하지만 이게 비단 김국동 박사님만 그러지는 않을 것 같고 아마 경기연구원이 연구집단이다 보니까, 연구단체지 않습니까? 이런 생각들이 굉장히 강할 거라 생각이 돼서 오늘 주문할 것은 이런 좋은 정책들이 어떻게 하면 공식적인, 아니면 검증된 절차에 의해서 경기도정과 협력할 수 있는가에 대한 얘기를 조금 하고 싶습니다. 그래야지 비로소 경기연구원에 관련된 정책연구원으로서의 관련된 궁극적인 목적이 아마 반영될 거라 생각이 되는 거고요. 그래야지만 그때 시간과 많은 노력을 써서 정책연구를 했던 그분들의 노고가 우리 경기도정에 반영이 돼서 그 결과를 볼 수 있지 않을까 생각이 됩니다.
</p>
<p style="padding-left:1.2em">  이에 대해서 몇 가지 문의를 드리고 싶은데요. 현재 정책연구를 통해서 경기도정에 그 정책이 반영됐을 시 경기연구원이 이번과 같이 확인을 했지만 이 확인하는 절차가 공식화되어 있는 건가요?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 공식적인 절차가 있느냐는 질문이십니까?
</p>
<p><b>○ 박상현 위원 </b> 네.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 그러니까 그게 문서로 예를 들어서 도하고 저희 연구원 사이에 교환되는 그런 공식적인 절차는 없고요.
</p>
<p><b>○ 박상현 위원 </b> 그럼 공식적인 절차가 없이 어떻게 보면 과제책임자 주도하에 의지가 있는 과제책임자는 담당 부서를 만나서 열심히 협의를 하는 거고 그러지 않은 연구원 같은 경우에는 그냥 자기 연구에 과몰입을 해서 몰두하는 경우라는 말씀이신 거죠?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 개인적인 편차는 있습니다. 그런 것을 방지하기 위해서 저희가 연구부서와 도 실국 간에 간담회를 정례적으로 개최해서 양쪽의 의견을 조율할 수 있는 기회를 만들려고 노력은 하고 있습니다.
</p>
<p><b>○ 박상현 위원 </b> 아, 노력을 한다는 말씀이신 거죠?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 그렇습니다.
</p>
<p><b>○ 박상현 위원 </b> 그러면 부탁을 하나 드리겠습니다. 그 간담회라든지 정담회 같은 것들을 연구하신 분들에 다소 방해가 되실 수는 있겠지만 담당 부서하고 협력하는 것을 정례화할 수 있는 그 규칙을 만들어 주셨으면 감사하겠습니다.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 알겠습니다.
</p>
<p><b>○ 박상현 위원 </b> 그러면 그렇게 만약 정책적으로 반영이 됐을 때 그런 연구원분들의 어떻게 보면 인센티브 같은 거라든지 어떤 성과급 같은 것들이 혹시 있나요?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 그러니까 직접적으로 어떤 연구과제의 대안이 반영됐다고 해서 바로 이렇게 인센티브를 하는 건 아니고요. 저희가 연말에 평가를 개인평가를 통해서 성과 부분에 대한 인센티브를 차등해서 지급을 하고 있습니다.
</p>
<p><b>○ 박상현 위원 </b> 그러면 실질적으로 여기에 많은 리스트를 해 주신 걸 보면 굉장히 주옥 같은 연구들이 많아요. 어떤 근거로 활용됐다든지 어떤 계획을 수립하는 데 있어 굉장히 핵심적인 역할을 많이 하는데 성과급 차등지급을 통한 것이 그 연구원들에게 충분한 성과 보상이 된다고 생각하시나요, 혹시?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 충분한 성과에 대한 보상이라고 생각하지는 않습니다. 물론 개별 연구자들이 전력을 다해서 연구한 결과이기 때문에 사실 더 가치가 있는 것일 수도 있음에도 불구하고 저희가 제도적으로 공공기관에서 할 수 있는 최선의 방법이라고 생각을 하고 있고요. 지금 현재 사실은 제일 현실적인 금전적 인센티브를 운영하고 있다고 생각을 하고 있습니다.
</p>
