<p><b>○ 이채명 위원 </b> 장시간 수고 많으십니다. 제가 자료를 좀 늦게 받아서요. 어제 제가 기조실의 공공담당관에도 질의를 했었는데요. 연이어서 감사위원회도 같은 질의내용이기는 하지만 자료를 받았기 때문에 구체적으로 질의 좀 드리겠습니다.
</p>
<p style="padding-left:1.2em">  제가 어제 질의했던 내용들이 보니까는 아트센터가 감사에 지적이 됐어요. 감사의 지적사항이기는 한데 처리결과를 보니까 수원지방법원에 이해충돌방지법 위반으로 사실 통보를 올해 7월 5일 날 했습니다. 그리고 사적으로 사용한 운행거리에 대한 유류비 추산 및 환수도 8,048원을 완료했어요. 좀 기가 막힙니다. 이 부분도 조금 이따 질의드릴 건데.
</p>
<p style="padding-left:1.2em">  그리고 제가 어제 이 지적된 내용을 모르고 제안했던 게 전자적 방식의 공용차량 관리시스템 도입을 마련할 것을 제안드렸는데 보니까 사업계획 수립 완료라고 되어 있습니다. 이런 부분들 혹시, 오늘 분명히 제가 자료 요청을 했고 질의를 드릴 거라는 생각을 했기 때문에 분명히 자료 확인하셨겠죠? 이 부분은 제가 자료 요청을 하지 않았습니다. 완료했는지 한번 확인해 주시고요. 그리고 전 아트센터 대상으로 공용차량 이용수칙 공지를 7월 15일 날 했다라고 했는데 그 자료도 추가적으로 요청했는데 그 자료는 아직 오지 않았기 때문에 한번 확인해 주시면 고맙겠습니다.
</p>
<p style="padding-left:1.2em">  사실은 여기서 관련자 1명은 경징계 처분하고 관련자 1명은 훈계 처분했습니다. 이 징계하고, 지금 경징계하고 훈계 처분된 분이 직원인가요, 아니면 대표이사인가요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 위원님, 말씀 중에 죄송한데 제가 이걸 내용을 잘 몰라서 담당했던 과장님을 통해서 양해해 주시면 답변드리도록 하겠습니다.
</p>
<p><b>○ 이채명 위원 </b> 네, 담당 과장님 답변해 주시기 바랍니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 담당 팀장님이 답변드리도록 하겠습니다.
</p>
<p><b>○ 이채명 위원 </b> 네, 담당 팀장님께서 답변해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  먼저 답변하시기 전에 공용차량 중에서 전용차량 배정된 공무원이 업무, 즉 출장이나 행사 등과 관계없는 경우에는 관사 출퇴근 시 사용이 가능한 것인지 먼저 제가 여쭤보도록 하겠습니다. 왜냐하면 제가 대표이사의 차량 운행일지를 보니까 대체적으로 오전과 오후에 아침 3시간, 오후 3시간 거의 약 5시간에서 6시간을 출퇴근 차량으로 모든 차량을 다 지금 소비를 했거든요. 이 부분에 대해서 보니까 감사가 지적이 된 것 같아요. 이 부분의 이해충돌방지법 위반사실이 통보가 된 것 같습니다. 제가 얘기한 게 맞나요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 공공기관감사팀장 추성아입니다. 위원님께서 질문하신 사항에 대해서 제가 다시 한번 말씀드리겠습니다. 이해충돌방지법 위반으로 걸린 분은 공무직으로서 운전을 하시는 분인데요. 원래는 차고지가 아트센터기 때문에 운전을 해서 나갔다 복귀하시게 되면 차고지에다 다시 놓고 본인의 차량으로 출차를 하셔야 되는데 시간외를 찍으신 다음에 그 공용차량을 갖고 나가셔서 그분이 지적된 케이스입니다.
</p>
<p><b>○ 이채명 위원 </b> 그러면 이건 잘못된 거죠. 지금 제가 질의드리고 싶은 거는요, 공무직 관련된 분도 사실은 이해충돌방지법에 위반이 되기는 하겠지만 대표이사 같은 경우도 “공공기관의 장이 전용차량을 이용해서 출퇴근하는 것이 이해충돌방지법 위반에 해당되는지요?”라고 질의를 했을 때 “사적인 용도로 사용ㆍ수익하거나 제3자로 하여금 사용ㆍ수익하게 하여서는 안 된다.”라고 지금 명시가 되어 있습니다. 이 부분은 저희가 감사를 했는데도 불구하고 제대로 감사가 잘못 이루어진 것 같습니다. 
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 아니요. 설명드리도록 하겠습니다. 
</p>
<p><b>○ 이채명 위원 </b> 네. 
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 공용차량에 대해서는 전용차량은 내부 규정상에 대표가 사용할 수 있도록 조항이 되어 있으면 사용을 하실 수 있도록 되어 있습니다. 다만 지금 문제는 뭐였냐면 운전자를 하시는 공무직분께서 이 차량을 원래는 그렇게 해서 수행을 다 마친 후 차량을 아트센터에 반납을 하시고 개인차량으로 이동을 하셨어야 되는데 그 공용차량을 끌고 나가셨기 때문에 이분이 이해충돌방지법 위반이 되신 겁니다.
</p>
<p><b>○ 이채명 위원 </b> 아니, 말씀 주신 건 맞아요. 그 기사분도 당연히 이해충돌방지법에 위법한 건 맞죠. 하지만 지금 제가 자료를 찾아보니까 지자체는 행안부가 만든 공용차량 관리 매뉴얼의 적용을 받지는 않는데 권익위에서는요, 출퇴근을 사적 사용으로 보고 있습니다. 그래서 예외적으로 통상적인 근무시간 이전, 이후 업무현장 방문 및 회의 참석 등 업무와 긴밀하게 연계된 경우다라고 되어 있어요. 그렇기 때문에 기관장이 출퇴근용으로 공용차량을 썼을 때는 이건요, 권익위에서는 위법하다라고 나와 있습니다. 
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네, 지금 위원님께서 말씀하신 사항 맞고요. 다만 그 기관에서 내부적으로 전용차량에 대해서 그 기관장이 사용할 수 있도록 그 규정이 되어 있으면…….
</p>
<p><b>○ 이채명 위원 </b> 그럼 내부 규정이 더 중요하나요? 아니면, 권익위에서 위법하다라고 지금 나와 있잖아요.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 그런데 그게 전부 다 안 되는 게 아니고요. 예외적으로 할 수 있는 부분들에 대해서는 이해충돌방지법도 그 운영사례집상에 나와 있습니다. 저희가 그 사항도 저희 감사자가 확인을 했던 사항입니다.
</p>
<p><b>○ 이채명 위원 </b> 그러면 감사실에서 확인했었을 때, 지금 제가 운행일지를 봤잖아요. 오전 3시간, 오후 3시간 6시간을 지금 운행일지에는 온리(only) 대표이사의 출퇴근용으로 차량을 썼어요. 이게 가능한 겁니까? 지금 대체적으로 보면 모든 운행일지에 출퇴근용 외에는요, 오전 거의 8시 40분, 9시 이후에 퇴근시간 전까지는 기사가 움직임이 없습니다. 이런 부분에 대해서도 체크하셨나요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네, 저희 감사자가 확인한 걸로 알고 있습니다. 
</p>
<p><b>○ 이채명 위원 </b> 확인한 이후에 조치는 어떻게 했나요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 그런데 그 부분에 대해서는 위법성이 없다고 판단을 했기 때문에 저희가 거기 현장에서 자료 확인했을 때는 추가적인 그 사장에 대한 별도의 위법사항이 없으니까 그 부분에 대해서는 발견하지 못한 걸로 알고 있습니다.
</p>
<p><b>○ 이채명 위원 </b> 그러면 예를 들면 28개 공공기관의 모든 대표이사께서 차량을 출퇴근용으로 다 사용해도 무방하다는 거네요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 지금 저희가…….
</p>
<p><b>○ 이채명 위원 </b> 왜냐하면 제가 알고 있는 타 기관의 공공기관장께서는 댁이 서울이라고 하더라도요, 관사에서 출퇴근합니다. 그리고 수원역이나 근방, 인근에 오셔서 기사차량을 운행합니다. 그런데 유독 아트센터만 하루에 6시간을 출퇴근용으로 이 차량을 지금 쓰고 있습니다. 이 부분에 대해서는 감사위원회에서 심도 있게 이거를 지적했었어야죠. 지금 보면 감사실에서, 제가 생각했을 때는 감사위원회를 위해서 감사를 누가 더 감사를 다시 해야 될 거라는 생각이 듭니다. 왜냐하면 대표이사를 감사를 한 게 아니라, 지금 보면 처리 결과 내용도 보니까 제가 놀랐던 거는 사적으로 사용한 운행거리에 대한 유류비가 추산했는데 환수금액이 8,048원이에요. 이거는 기사에 대한 유류비 환급이잖아요?
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네, 맞습니다.
</p>
<p><b>○ 이채명 위원 </b> 대표이사에 대한 유류비도 환급해야 되죠. 예를 들어 연료비, 통행료, 시간외 등 이런 부분들도 다 환수조치를 해야 되는 거 아닙니까? 왜 직원들만 징계를 받았고 대표이사에 대해서는 특별한 징계조치가 없었는지 이게 저는 좀 궁금해요.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 그러니까 아트센터 공용차량 사용 규칙상에 보면 그 내용이 전용차량을 쓰실 수 있도록 되어 있어서 그 부분에 대해서는 지적할 수 없는 부분이 있었습니다. 그리고 저희가 감사를 몇 개 기관을 해 봤는데 기관마다 이런 규정들이 다 다르게 되어 있어서 그런 부분에서는…….
</p>
<p><b>○ 이채명 위원 </b> 그러면 기관마다 규정이 다르면 감사위원회에서 그걸 지적을 했었어야죠. 각 기관마다 공통적으로 공통적 기준을 만들었어야 되죠. 예를 들면 아트센터만 이렇게 출퇴근용으로 차량을 이용할 수 있게 만드는 건 말도 안 되는 거잖아요.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 아, 그렇지 않고요. 다른 기관…….
</p>
<p><b>○ 이채명 위원 </b> 그럼 출퇴근용 차량 운전기사를 따로 두고요, 업무용 차량을 따로 뒀었어야죠. 하루에 한 번, 운행일지를 한번 보세요. 전체적으로 출퇴근용으로만 사용했습니다.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 위원님, 잠시 답변드려도 될까요? 
</p>
<p><b>○ 이채명 위원 </b> 네, 답변 간단하게 주시기 바랍니다.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 저희가 다른 기관에 갔었을 때도 거기에는 전용차량 그 기사를 또 외부에서 용역식으로 쓰고 있었습니다. 그게 기관마다, 저희도 안타까운 게 뭐냐 하면 저희 공무원들을 규율하고 있는 공무원법하고 똑같이 적용이 되면 되게 좋은데 기관은 안타깝게도 기관마다 자체 이사회가 있고 거기에서 또 노조와 협의가 있고 이런 단계들을 거치다 보니까 규정 개정이나 이런 부분에 어려운 점이 있습니다.
</p>
<p><b>○ 이채명 위원 </b> 시간이 얼마 남지 않아서 팀장님, 제가 다시 한번 말씀드릴게요. 출퇴근 이외에는 사실은 특별하게 운행이 없는데도 불구하고 특별한 사유 없이 지금 대체적으로 아침 10시까지, 오후 저녁 7시나 6시까지 기다리고 있습니다. 그래서 하이패스 내역을 자료 요청하겠습니다. 시간, 날짜 그리고 차량번호 확인할 수 있게끔 해서 구분해서 자료 주시고요. 그리고 출퇴근 몇 건 그리고 비출퇴근 몇 건 해서 구분해서 이것 또한 같이 자료를 첨부해서 제출해 주시기 바랍니다.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네, 알겠습니다.
</p>
<p><b>○ 이채명 위원 </b> 네, 그리고 좀 더 감사위원회에서 이 부분에 대해서 이해충돌방지법에 위반되는지 여부도 다시 한번 재검토해 주시기 바랍니다.
</p>
<p><b>○ 감사위원회공공기관감사팀장 추성아 </b> 네, 알겠습니다.
