<p><b>○ 이채명 위원 </b> 네, 이상입니다.
</p>
<p><b>○ 부위원장 이혜원 </b> 이채명 위원님 수고하셨습니다. 지금 본질의 두 분 남으셨는데 위원님이 조금 늦었지만 본질의까지 마치는 것에 동의해 주시겠습니까?
