<p><b>○ 이경혜 위원 </b> 그런데 저는 이렇게 생각합니다. 제가 받은 계획안을 보면 너무 황당하고 화가 나서 견딜 수가 없어요. 이게 물론 예상이죠. 예상이고 본예산에, 이 예산을 달라고 했을 때는 이 계획이 어느 정도 선 거라고 보는 전제하에서 말씀을 드려볼게요. 이전하는 부지 임차하는 데 들어가는 비용과 소요예산이 35억이에요. 임차계약 1월 달에 하고 내부공사 25년 1월부터 3월까지 하는 계획을 가지고 있어요. 그리고 사무실 이전을 25년 4월에 합니다. 그런데 여기에 들어가는 계약기간이 얼마냐라고 물어봤더니 1년 계약으로 한답니다. 그런데 인테리어 비용이 12억이라고 합니다.
</p>
<p style="padding-left:1.2em">  경기연구원 원장 직무대행께서는 집안의 이사를 한다면 임차해서 계약하고 이사를 갈 때 그 집에 1년밖에 살 수 없는데 12억이라는 인테리어 비용을 넣어서 가는 것에 대해서 쉽게 생각할 수 있습니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 쉽게 생각할 수 있는 사안은 아니라고 생각합니다.
</p>
<p><b>○ 이경혜 위원 </b> 그렇죠. 저는 1년 만에, 이 계획이 1년 만에 나온 것도 아닌 것 같아요. 제가 분명히 부지를 선정 못 해서 고민하고 있다고 들었는데 불구하고 이런 계획안이 몇 달도 안 된 사이에 나와서 내년 본예산에 편성되는, 이런 급조되는 예산을 편성하는 경기연구원과 기획조정위원회실에 대해서 굉장히 큰 화가 나요. 어떻게 이럴 수 있지? 내 집의 살림이면 과연 이런 예산을 편성할 수 있을까? 임차 계약기간을 1년으로 예상한다면서 12억의 예산을 들이고 간다는 이런 문제에 대해서 심각하게 고민해야 된다라고 생각해서 제가 이거는 보류를 요청했어요. 이전에 대한 보류하고 예산도 보류하고 다시 나머지 공공기관들은 어떻게 갔는지 살펴보겠다 이 말씀을 드렸는데요. 첫 번째가 이렇게 예산이 제대로 쓰이고 있는지에 대한 문제가 하나 있고요.
</p>
<p style="padding-left:1.2em">  두 번째가 그렇게 간다고 한다면 경기연구원에서 근무하고 있는 모든 직원들은 갑자기 이렇게 준비해서 갑자기 가는 것에 대해서 모두가 동의가 될까? 직원들의 가족과 아이들과 모두가 이전을 해야 되는데 이 계획이 1년, 2년 전에 세운 것도 아니고 24년 말쯤에 준비해 가지고 25년 4월에 사무실 이전을 해요. 그러면 거기에 딸린 공무원들은 거기에 맞춰서 다 준비가 돼야 되잖아요. 그러면 불과 6개월도 안 되는 사이에 그곳으로 이전하는 이전인원이 지금 현재 40명이라고 하거든요, 예상 인원이. 40명의 가족들은 6개월 만에 갑자기 친구들이 있는 학교도 이전하고 엄마들도 마찬가지고 모든 가정들이 그거에 대한 준비를 급조해서 해야 되잖아요. 그럼 다 안 가고 여기에 나머지는 그대로 있고 공무원들만 간다는 얘기인가. 그럼 공무원들만 간다라는 것은 그러면 이게 지역발전, 경기특구 북부에 대한 균형발전을 위해서 가는 건가 의구심이 듭니다.
</p>
<p style="padding-left:1.2em">  북부 균형발전을 위해서 공공기관들을 여기저기 곳곳에 확장을 하고 이전을 해서 그것들을 통해서 균형발전을 이루겠다는 의지에서 경기도지사 김동연 지사님께서 말씀하셨겠지만 저는 사람이 먼저라고 생각합니다. 어제도 제가 인구정책에서도 사람이 먼저라고 그래서 사람들이 아이를 낳고 싶은 조건을 만들어야 된다고 생각했는데 이것 또한 마찬가지라고 생각합니다. 공공기관을 이전하는 것이 중요한 게 아니라 이전의 과정, 절차가 얼마나 거기 안에 일하는 사람들 그리고 균형발전을 위해서 거기에 갔을 때 그 지역에서 균형발전할 수 있는, 활성화시킬 수 있는 그런 환경을 만들고 가는 것인지. 이것들이 먼저 다 준비가 돼서 그때 가는 게 맞다고 저는 생각을 합니다. 지금 이렇게 급조해서 간다면 제가 볼 때는 40여 분 가셔서 일하시는 것도 굉장히 힘들게 멀리 출퇴근하셔야 될 수도 있죠. 그렇게 하면 어떻게 하시겠어요? 차량 어떻게 이동하시나요? 만약에 내년 4월에 이전을 한다. 공무원분들은 어떻게 가실 거예요? 출퇴근.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 답변드리도록 하겠습니다.
</p>
<p><b>○ 이경혜 위원 </b> 네, 해 주시죠.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 먼저 저희 연구원 이전과 관련해서 원칙적으로 이전을 하게 된다는 전제하에 임차로 가는 것보다는 한꺼번에 부지를 매입하고 건물을 지어서 전체 이전하는 게 더 효율적이라는 점은 위원님이 말씀하신 바가 맞습니다. 다만 지금 북부 관련돼서 저희가 2022년도에 지연이 되면서 여러 가지 의구심이 제기돼서 경기연구원이 오는 거냐, 안 오는 거냐 이런 여러 가지 논란이 있는 점을 감안한다면 저희가 이전의 의지를 보여준다는 측면에서 일부 간다고 이렇게 이해해 주셨으면 좋겠고요. 1년 계약을 한 이유는 1년만…….
</p>
<p><b>○ 이경혜 위원 </b> 출퇴근에 대해서만 주세요, 시간이 1분밖에 안 남아서.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 죄송합니다. 저희가 직원 부분에 있어서는 특히 당연히 직원들의 동의를 구해서 이전을 선호하는 직원을 우선적으로 배치할 계획이고요. 그 과정에서 필요하다면 교통비 지원이나 또는 관사 이런 편의시설들 제공을 예산범위 내에서 해서 직원들이 불편하지 않도록 한 다음에 직원들의 근무지 이전을 진행하려고 생각하고 있습니다.
</p>
<p><b>○ 이경혜 위원 </b> 그러면 직무대행께서 말씀하신 두 가지 갖고 제가 다시 한번 말씀드려볼게요. 의정부에 살고 계신 경기도민들은 경기연구원이 하루빨리 와서 지역이 활성화가 되기를 반드시 원하고 있을 겁니다. 그런데 만약에 지금처럼 임대차계약을 하고 인테리어 비용을 그만큼 12억이라는 돈을 들여서 의정부에 결국 40명밖에 안 오는 이 내용을 알면, 도민 혈세 12억이 인테리어 비용에 그렇게 급조해서 들어간다는 걸 알면 그걸 원하는 의정부에 사는 도민들은 안 계실 겁니다. 그렇게 의정부시민들도 다 깨어 있습니다. 무조건 오는 걸 원하는 게 아니에요.
