<p><b>○ 부위원장 이혜원 </b> 네.
</p>
<p><b>○ 이경혜 위원 </b> 의정부 도민들도 원하는 것은 모두가 다 같이 와서 지역을 활성화시킬 수 있고 지역상권을 활성화시키는 이런 일들을 했으면 좋겠다는 거지 보여주기식으로 40명 훌쩍 그냥 임대차해서 어느 민간 건물 하나 빌려 가지고 들어와서 있는 그런 요식행위를 바라는 게 아닙니다. 그래서 그렇게 가는 걸 원하는 거 아니고요.
</p>
<p style="padding-left:1.2em">  두 번째가 지금부터 관사 알아보고, 내년 1월에 계약하실 건데 계약이 아직 확정된 것도 아니니 될지도 안 될지도 모르는데 지금부터 관사 알아보실 수 없잖아요. 그럼 그때부터 관사 알아보고 그때부터 직원들 누구 누구 갈지 희망하는 사람들 정리하고 그렇게 해서 내년 4월에 가실 수 있을 것 같으세요? 그렇게 가시면 가족들은 그리고 직원들은 다 좋아할까요?
</p>
<p style="padding-left:1.2em">  저는 이렇게 급조되는 일들을, 다른 데도 아니고 경기연구원이잖아요. 늘 그런 일들을 연구하고 어떻게 하면 더 잘할지에 대한 고민을 하는 데잖아요. 그런 데서 이런 일들이 일어난다는 거는 저는 좀 문제가 있다, 이런 부분 다시 고려하셔야 되고 제가 앞서 말씀드렸지만 사람이 중심입니다. 직원들의 복지가 중요하고 직원들 복지가 이루어지지 않는데 그들이 가서 무슨 일을 얼마나 잘할 수 있겠어요. 그들이 일할 수 있는 환경이 만들어지는 게 우선이기 때문에 좀 더 세밀하게 준비하신 이후에 이전을 고려하시는 게 맞다. 내년에 아마 예산들도 그런 부분에 위원님들 동의하실 거라고 보고요. 함께 그 부분을 좀 더 검토해서 가셨으면 좋겠다는 그 말씀을 같이 드려봅니다. 그렇게 검토하시겠어요?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 말씀 주신 부분 세심하게 살펴서 계획을 하는 데 있어서 차질 없이 되도록 준비하도록 하겠습니다.
</p>
<p><b>○ 이경혜 위원 </b> 네, 그렇게 부탁드립니다. 자리로 돌아가셔도 좋습니다.
</p>
<p style="padding-left:1.2em">  두 번째 감사위원회 위원장님 잠깐 자리로 이동해 주십시오. 앉은 자리에 마이크가 있으시면 쓰셔도 좋습니다. 괜찮으시겠어요?
</p>
<p style="padding-left:1.2em">  제가 지금 두 번째로 여쭙고 싶은 것은 감사위원회에서, 정보시스템 아침에 자료 제가 요청했어요. 그렇죠?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 사업비 관련 자료 제출한 것으로 알고 있습니다.
</p>
<p><b>○ 이경혜 위원 </b> 저도 잠깐 자료를 좀 펴도록 하겠습니다. 제가 아직 자료를 못 펼쳐서. 감사정보화시스템 전략계획을 착수하셨잖아요? 착수보고회도 하셨고.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다.
</p>
<p><b>○ 이경혜 위원 </b> 그래서 저는 이게 궁금해요. 개요를 혹시 갖고 있나요? 앞으로의 계획에 대한 착수보고회를 했으니까 계획을 갖고 계실 텐데 이 계획에 개발의 방식 그리고 그 예산 그리고 그렇게 된다면 이 개발자는 어떻게 입찰을 하시는 건지, 어떤 업체를 선정하시는 방식으로 하시는 건지에 대한 걸 제가 궁금해서 여쭙고 싶었는데 저한테 자료를 주셨을까요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 개발 방식, 예산, 개발자 입찰 관련 자료명으로 아니고 아마 위원님께서 저희들한테 제출 요구하신 것은 감사정보시스템 구축 사업비 관련 자료로 이렇게 해서 저희가…….
</p>
<p><b>○ 이경혜 위원 </b> 제가 세 가지로 부탁을 드렸는데. 업체를 어떻게 선정할 건지 그 방식까지도 여쭤봤는데 준비가 안 되셨으면 그거는 추후에 주셔도 됩니다. 지금 당장 하고 계신 일이 아니니 그거 추후에 주셔도 되는데 제가 다만 그 부분에 대해서 여쭤보고 싶은 건 뭐냐 하면, 이 개발을 해요. 어떤 업체를 선정해서 개발을 했을 경우에 업체와의 교류가 어느 정도 진행이 되다가, 이 업체가 계속 진행을 하다가 만약에 예산을 더 확대해야 한다, 사업비를 더 추가로 요청한다 했을 때 예산을 계속 증액을 원한다고 한다면 그 사업비가 들어가는 부분에 대해서 업체와의 연계를 계속할 수 있을지, 없을지에 대한 고민. 어떤 거냐 하면 우리 스스로 주체가 되어서 시스템정보를 만들어내는 게 아니라면 다른 외부에 있는 업체에 발주를 줘서 외주업체에서 이 사업들을 계속 관리를 하게, 데이터를 관리를 하거나 시스템 관리를 하게 됐을 경우에 그들이 만약에 예산을 증액해 달라고 했을 때 못 해 줬을 경우 어떻게 되는지에 대한 걱정이 있는 거예요. ‘그럼 예산을 우리 계속 달라는 대로 증액해 줘야 되나?’ 이런 걱정이 하나 있고 또 하나가 ‘그러면 우리 내부적으로 그런 전문가들을 불러서 우리가 그걸 직접 이 안에서 할 수 있는 직원들을 채용해서 하면 예산이 좀 덜 들까?’ 이 고민에 대한 걸 한번 고민해 보고 싶어서 여쭤보는 겁니다. 어떠세요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 앞서 감사정보시스템 구축 사업비 관련 자료 안에 제가 내용물을 보니까 그 예산과 관련된 비용, 업종 선정계획 이렇게 해서 나누어서 안에 들어가 있습니다. 그거 한번 참조해 주시면 고맙겠고요. 그다음에…….
</p>
<p style="padding-left:2.4em">    (타임 벨 울림)
</p>
<p><b>○ 이경혜 위원 </b> 그러면 시간이 다 돼서 제가 계속 쓸 수는 없으니까 마지막 추가질의에서 답변 조금만 다시 들을게요. 제가 자료 온 거 다시 한번 확인하고 그 이후에 답변 다시 듣도록 하겠습니다. 이따가 다시 뵙겠습니다. 자리로 돌아가시고 저 이상입니다.
</p>
<p><b>○ 부위원장 이혜원 </b> 이경혜 위원님 수고하셨습니다.
</p>
<p style="padding-left:1.2em">  위원님들 본질의는 모두 마치셨습니다. 이에 본질의를 마치도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 보충질의를 실시하겠습니다. 질의하실 위원님 거수로 신청해 주시기 바랍니다. 박진영 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 박진영 위원 </b> 안녕하십니까? 화성 출신 박진영 위원입니다. 제가 아트센터 얘기를 안 하려고 그랬는데 짧게 하고 넘어가야겠네요. 제 거 화면 좀 틀어주세요.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  아트센터에서 지금 자료가 왔는데, 지금 감사실에서 아트센터의 헬프라인 로그기록 요구에 대한 자료를 주셨는데 시스템 관리업체에서 로그를 관리하고 있기 때문에 아트센터에는 없다. 로그인 기록 보존기간은 6개월이다. 그리고 그 밑에 라인에 당시 헬프라인 접수상황에 대하여 담당자 및 감사실장이 접수 사실을 알고 있다고 인정한 사항으로 추가 확인 절차는 진행하지 않았다라고 해 주셨는데, 13번 봐주실래요? 추가 확인 절차를 진행하지도 않고서 어떻게 이 내용에 대해서 조사를 하시고 이 당시의 업무 처리 미숙에 대해서, 답변 안 해 주셔도 될 것 같습니다. 그냥 말해야 될 것 같아요, 시간상. 추가 확인 절차를 진행하지도 않으셨고 이거 로그인해서 본지 안 한지 그런 것도 확인 안 하시고 그냥 그 업무 처리 절차에 대해서 당시에 입력 결과를 통보하지 않고 이걸로 답변한 것으로 처리해서 하면 이유로는 업무 절차의 미숙이다라고 해서 이런 부분들은 어떻게, 신기하네요, 어떻게 이거는 감사 절차를 진행하셨는지.
</p>
<p style="padding-left:1.2em">  또 하나 여쭤볼게요. 또 하나 보여드릴게요. 제가 아까 이 자료 달라고 말씀드렸고 이 자료 이제 어느 정도 설명은 받은 걸로 알고 있는데 여러 가지 상황들이 있기 때문에 비공개라서 조심스럽게 말씀드리는 건데, 이 자료 달라고 했던 내용들이 작년에 제가 문화체육관광위원회 행정감사 할 때 어떤 노무사분이 신고하신 분에 대해서 연락을 해서 이런저런 얘기를 하셨는데 그때 제가 개인정보 보호법 위반을 얘기했어요. 그리고 계약이 안 돼 있는데 이렇게 되면 개인정보 보호법 심각한 문제가 있지 않냐라고 얘기했는데 이게 보니까 사장의 결재를 받지 않고 했기 때문에 업무 처리 절차 미준수라고 해서 훈계가 갔는데 그런 부분의 문제가 아닌 것 같은데요? 사장의 결재를 받지 않았으면 정식적으로 계약을 하지 않은 거고 정식적으로 계약을 하지 않은 상태에서 노무사에게 개인정보를 넘겨주신 거예요. 대답하실 필요는 없을 것 같습니다. 
</p>
<p style="padding-left:1.2em">  그리고 마지막으로 분명히 서약하셨고 아까 갑질 신고 관련된 거 1건이라고 말씀하셨습니다. 만약에 종합감사 때 갑질 신고 관련된 사항들 제가 접수된 내역들 더 확인해서 열게 되면 고발조치 당하십니다. 감사위원회는 이 정도로 말씀드리겠고요. 
</p>
<p style="padding-left:1.2em">  도민권익위에 여쭤보려고 합니다. 이것도 시간이 없으니까 그냥 그 자리에서 답변 주시죠. 감사위원회랑 도민권익위 관련된 운영규정인데 둘 다 보면 시행일이 9월 2일이에요. 동시에 출범하셨고, 홈페이지도 지금 내용 보시면 “도민에게 듣습니다. 도민에게 알립니다.” 거의 비슷하세요. 근데 감사위원회 같은 경우에는 9월 9일 날 경기도감사위원회 규정의 발령 및 관리에 관한 규정 제정 행정예고하셨고요. 그리고 감사위원회 감사사무 처리 규정 행정예고하셨고 감사위원회 회의 운영규정 행정예고하셨습니다. 밑에 거는 감사위원회에만 별도로 적용되는 거라 예외로 하겠습니다. 근데 도민 권익위원회는 도민권익위원회 규정의 발령 및 관리에 관한 규정만 행정예고하셨어요. 이거 나머지 규정 있나요? 도민권익위 사무처리 규정이랑 도민권익위 회의 운영규정이요. 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 발령에 관한 규정 1개 외에는 지금 운영규정 행정예고돼 있는 규정이 전부입니다. 
</p>
<p><b>○ 박진영 위원 </b> 이게 말이 되나요, 지금? 9월 2일 날 출범하셨고 감사위원회는 9월 9일 날 모든 규정들을 행정예고했는데 도민권익위원회는……. 도민권익위원회 사실 합의제 행정기구라서 회의를 운영해야 되고 회의를 운영하기 위해서 운영규정이 필요하시죠? 그리고 사무처리 하시는 데 있어서 단순히 도민의 민원을 접수하는 게 아니라 그 접수된 민원을 갖고 조사권을 행사하시기 때문에 엄밀하게 사무처리 규정이 있어야 되는 것 같은데요? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 더 세밀하게 규정을…….
</p>
<p><b>○ 박진영 위원 </b> 그 정도의 문제가 아니에요. 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네?
</p>
<p><b>○ 박진영 위원 </b> 있으세요, 없으세요, 규정?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 지금 운영규정은 보시다시피 제정 중에 있고 또 다른 규정들을 준용해서 업무를 하고 있습니다. 속히 만들도록 하겠습니다. 
</p>
<p><b>○ 박진영 위원 </b> 보시면 이게 도민권익위의 업무인데요. 여기 민원 처리 비위공무원 조사, 감사원 이첩 민원 처리 조사, 국민권익위 부패 신고 처리 조사, 공공사업 감시 및 평가 및 참관 활동 운영. 도민권익위가 하는 업무가 그렇게 가벼운 업무가 아닌 것 같은데요? 맞나요? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 맞습니다. 그리고 저희 운영규정은 법무담당관실에 검토를 의뢰해 놓은 상황입니다. 그리고…….
</p>
<p><b>○ 박진영 위원 </b> 제가 다시 말씀드리기 그런데, 이거 답변을 들을 것도 없을 것 같은데요, 죄송하지만. 9월 2일 날 시행하셨고요. 조례 제정은 7월 18일이에요. 
</p>
<p style="padding-left:2.4em">    (타임 벨 울림) 
</p>
<p style="padding-left:1.2em">  7월 18일 기준으로 9월 2일 날 시행하셨고 감사위원회는 9월 9일 날 모든 규정을 마련해서 행정예고를 했는데 9월 2일부터 지금까지 따져도 2개월이 지났습니다. 지금까지 하신 업무들은 규정 없이 진행하신 건가요? 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 그런 건 아니고요.
</p>
<p><b>○ 박진영 위원 </b> 이런 업무를 진행하시는데 준용으로 진행하신 건가요?
</p>
<p><b>○ 부위원장 이혜원 </b> 박진영 위원님 마무리해 주시기 바랍니다.
</p>
<p><b>○ 박진영 위원 </b> 네, 알겠습니다.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 죄송합니다만 저희가 9월 2일에…….
</p>
<p><b>○ 박진영 위원 </b> 마무리하겠습니다. 그리고 하나만 더 여쭤볼게요. 이거는 말씀드려야 되는데, 위원님들 도민권익위에 관련된 상당히 지금 중요한 업무를 하시고 있고, 비밀유지 엄수 조항이 있으시죠?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 그렇습니다.
</p>
<p><b>○ 박진영 위원 </b> 빨리 답변해 주셔야 될 것 같습니다. 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 그렇습니다.
</p>
<p><b>○ 박진영 위원 </b> 지금 도민권익위 홈페이지 들어가 보셨나요? 들어가 보시면 비밀유지 엄수의 조항이, 의무가 있으신 위원님들이 다 공표돼 있어요. 
</p>
<p><b>○ 도민권익위원장 장진수 </b> 위원님 명단을 공표하신 점에 대해서 말씀하시는 겁니까?
</p>
<p><b>○ 박진영 위원 </b> 네, 비밀유지 의무가 계신 분들이 지금 다 공표가 돼 있으십니다, 사진, 이력, 성함. 이 부분에서 법률적으로 검토해서 검토 결과 주십시오.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네.
</p>
<p><b>○ 박진영 위원 </b> 그리고 지금 당장 내려주십시오. 이상입니다.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 그렇게 하겠습니다.
</p>
<p><b>○ 부위원장 이혜원 </b> 박진영 위원님 수고하셨습니다. 보충질의하실 위원님 손 들어주시고 거수로 신청해 주시기 바랍니다. 먼저 이성호 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이성호 위원 </b> 용인 출신 이성호 위원입니다. 경기연구원 원장님. 요구자료 41페이지에 보시죠. 여기 5번 보시면 일산대교 통행료 인하 방안 연구 있지 않습니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 이성호 위원 </b> 이게 2019년 8월 1일 날 시작해서 2020년 2월 28일 날 끝난 게 맞습니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 그렇습니다.
</p>
<p><b>○ 이성호 위원 </b> 용역비는 지금 3,800만 원이죠?
</p>
