<p><b>○ 이성호 위원 </b> 용역 내용 및 용역 결과에 대해서 설명해 주세요.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 이 부분은 당시에 일산대교의 통행료를 인하하기 위해서 일산대교 통행량에 대한 장래 통행 수요라든가 그다음에 통행료를 어느 정도 인하하는 것이 맞는지 재무적인 검토를 했던 걸로 알고는 있습니다. 그래서 그 자세한 내용은 보고서를 제출하도록 하겠습니다.
</p>
<p><b>○ 이성호 위원 </b> 내용을 잘 모르시나요?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 구체적인 연구보고서의 내용은 제가 잘 숙지를 못 해서 이거는 담당 연구를 하신 분이 답변을 드리도록…….
</p>
<p><b>○ 이성호 위원 </b> 어떻게 된 게 여기 나와 있는 이 내용만큼도 얘기를 못 하시네요. 여기 쓰여져 있는 내용이 있잖아요. 
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 이성호 위원 </b> 전혀 숙지가 안 되어 계신 것 같은데? 
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 이게 개별 연구책임자가 진행한 사항이라서 저희가…….
</p>
<p><b>○ 이성호 위원 </b> 아니, 수감 자세가 그게 제대로 되신 겁니까? 여기 나와 있는 자료 정도는 설명할 수 있으셔야죠. 
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네. 이 당시에 말씀 주신 것처럼 일산대교 통행료가 적정한지에 대한 재무적 검토를 한 과제로 알고 있습니다. 그래서 그걸 조정할 수 있는 방안을 마련하는 내용을 정책 대안으로 제시하는 게 연구의 주요내용으로 알고 있습니다. 
</p>
<p><b>○ 이성호 위원 </b> 지금 이게 시기가 2019년 8월이잖아요?
