<p><b>○ 이성호 위원 </b> 이게 언제인지 아십니까? 경기도가 일산대교 주식회사하고 재정지원금 청구의소하고 재무구조 원상회복 명령 등 취소소송에서…….
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네. 대법원 판결이 난…….
</p>
<p><b>○ 이성호 위원 </b> 7개의 판결이 난 이후입니다.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 그렇게 알고 있습니다.
</p>
<p><b>○ 이성호 위원 </b> 전부 패소한 이후인데도 이 용역을 수행한 이유가 뭡니까? 발주를 한 이유가 뭡니까, 이거를?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 이거는 대법원에서 패소한 내용은 2015년에 내려진 재무구조 원상회복 명령 및 처분 통지에 대한 그 내용이 대법원에서 패소 판결된 것으로 알고 있습니다. 그래서 그 패소 판결 이후에 그럼에도 불구하고 판결의 내용이 감독 명령이 취소돼야 된 것이지 구체적인 요금수준이나 이런 것들에 대한 내용까지를 다루고 있지는 않아서 그 부분이 적정한지를 다시 검토했던 것으로 알고 있고요. 이 이후에도 일산대교의 통행료 부분이 비싼 것이 아니냐라는 것에 대해서 그와 유사한 여러 차례의 검토가 있었던 것으로 알고 있습니다.
</p>
<p><b>○ 이성호 위원 </b> 그거는 이런 분쟁들이, 그 이후에 조건부 통행료 징수 금지 처분 취소소송도 있었던 거 아시죠?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 이성호 위원 </b> 이런 판결의 내용들을 다 보셨나요?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 판결의 내용까지는 제가 다 읽어보지는 않았습니다.
</p>
<p><b>○ 이성호 위원 </b> 내용을 보시면 이런 통행료 인하 문제가 먼저 이렇게 검토가 될 수가 있는 것이 아닙니다. 그러면서 소송의 결과가 다 나온 상태에서 이거를 했다는 것 자체가 말이 안 되는 것 같고. 
</p>
<p style="padding-left:1.2em">  52페이지 또 보시죠. 72번에 일산대교 민간투자도로사업 시행조건 조정을 위한 협상 지원 이 용역의 내용과 결과는 어떻습니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 이것도 당시에 일산대교의 통행료 무료화를 추진하기 위한 자료로 활용하기 위해서 재구조화할 수 있는 방안이 있는지 그 가능성에 대해서 수요 재검증이라든가 그다음에 협상 관련된 내용을 대행하는 그런 과제로 알고 있습니다.
</p>
<p style="padding-left:2.4em">    (타임 벨 울림) 
</p>
<p><b>○ 부위원장 이혜원 </b> 이성호 위원님, 마무리해 주시고 이후에 추가질의가 있으니까 추가질의에서 이어서 해 주시길 바랍니다.
</p>
<p><b>○ 이성호 위원 </b> 네. 일산대교 이거 민간투자도로사업 이것도 2016년에 하신 건데 재정지원금 청구의소 1심 패소 이후고 그다음에 지금 말씀하신 그런 통행료 무료화를 위해서는 이런 소송들의 분쟁에서 결과가 나와야 되는 거죠. 이거를 그냥 지금 그런 게 확정되지도 않은 상태에서 하는 거는 말이 안 되지 않습니까? 이게 매몰비용이 되지 않았습니까, 나중에 전부 패소하는 바람에. 8,000만 원하고 3,800만 원이요.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 이성호 위원 </b> 이런 식으로 계속하실 겁니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 이거는 수탁과제로 경기도와의 계약에 의해서 진행된 과제로 사실은 그간에 여러 차례 아마 그 상황이 변화함에 따라서 계약이 변경된 것으로 알고 있습니다. 그래서 말씀 주신 내용은 굉장히…….
</p>
<p><b>○ 부위원장 이혜원 </b> 이성호 위원님, 마무리해 주십시오.
</p>
<p><b>○ 이성호 위원 </b> 네. 이따 또 추가질의로 하겠습니다.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 알겠습니다.
</p>
<p><b>○ 부위원장 이혜원 </b> 이성호 위원님 수고하셨습니다. 다음 보충질의하실 위원님? 이석균 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이석균 위원 </b> 남양주의 이석균입니다. 우리 감사위원회에 질의를 좀 드리겠습니다. 사전컨설팅감사제도라는 게 있는데 이 제도가 공무원 등이 사무처리 근거 법령의 불분명한 유권해석, 법령과 현실과의 괴리 등으로 인하여 능동적인 업무 추진을 하지 못하고 있는 경우에 적극행정을 할 수 있도록 사전에 그 업무의 적법성과 타당성을 검토하여 컨설팅하는 것 맞습니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다.
</p>
<p><b>○ 이석균 위원 </b> 우리 사전컨설팅 실적을 보게 되면 2022년 의뢰 건수가 129건, 23년도에 135건, 2024년도는 현재까지 101건 그렇게 되어 있는데 맞습니까? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 접수 처리 건수가 그렇게 맞습니다.
</p>
<p><b>○ 이석균 위원 </b> 그중에 사전컨설팅감사를 공기관이 의뢰를 한 거는 2022년 4건, 2023년 6건, 2024년 2건 이렇게 되어 있는데 맞습니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 맞습니다. 
</p>
<p><b>○ 이석균 위원 </b> 맞나요? 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 이석균 위원 </b> 22년도 보니까 경기도일자리재단, 경기주택도시공사, 경기도농수산진흥원, 2023년도에 한국도자재단, 경기관광공사, 경기주택도시공사, 24년도는 경기농수산진흥원, 경기도일자리재단 이렇게 신청을, 의뢰를 했던데. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 이석균 위원 </b> 혹시 사전컨설팅감사를 의뢰하면 처리 결과를 어떻게, 몇 가지 종류가 있나요? 처리 결과를 어떤 식으로 하나요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 그게 불분명하게 신청요건이 갖춰지지 못하면 각하 처리를 하고요.
</p>
<p><b>○ 이석균 위원 </b> 제가 말씀드릴게요. 처리 결과가 의견 제시 그리고 제외대상 통보, 신청기관 취하, 감사원 이송 그리고 해당 정부부서로 이송 이렇게 처리 결과가 나눠지는데 맞나요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 맞습니다. 의견 제시, 취하, 반려, 이송 이렇게 처리를 하고 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 사전컨설팅을 했을 때 의견 제시하는 비율이 어느 정도라고 생각하십니까? 그건 하여튼 나중에 별도로 보고를 해 주시고…….
</p>
<p><b>○ 감사위원장 안상섭 </b> 36.3%가 되겠습니다. 전체 신청건수의 36.3%…….
</p>
<p><b>○ 이석균 위원 </b> 나머지는 제외대상 통보가 좀 제일 많은 것 같고요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 취하, 반려, 이송 이렇게 다른 처리들을 하고 있는 경우가 많습니다.
</p>
<p><b>○ 이석균 위원 </b> 제외대상 통보는 이게 부족해서 그런가요? 자료가?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그렇습니다. 요건이 불분명하거나 그다음에 미비 첨부를 한 사안이거나 해서 명백하게 신청요건을 갖추지 못한 경우를 말하는 겁니다.
</p>
<p><b>○ 이석균 위원 </b> 의뢰하는 기관 입장에서 보게 되면, 우리 표출자료 한번 보여주시겠어요? 7번. 
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  사전컨설팅 참가 요청 절차도를 보시게 되면 사실은 우리 감사위원회에서는 저게 익숙한 프로세스인데 의뢰하는 입장에서는 되게 힘든 부분들일 수 있어요. 그리고 아까 말씀하셨다시피 미비한 서류라든지 증거가 이런 부분들에 대해서는 제출하려고 그러면 다시 문서를 제출하거나 이렇게 해야 되는데, 제가 2022년도의 행정사무감사 지적을 봤어요. “사전컨설팅 업무대상에서 제외되는 민원이 많음. 사전컨설팅 대상과 제외되는 업무는 어떤 것인지 기준을 더 공개하고 홍보하여 행정력이 낭비되지 않게 하기 바람.” 지적사항이 나왔는데 처리 결과는 “사전컨설팅감사제도 및 제외대상에 대하여 지속적으로 안내 및 홍보를 추진하였음.”이라고 완료를 표시했는데 제외대상 통보가 엄청 많아요. 그러면 이게 홍보가 안 된 건지 저게 안 된 건지. 지금 시간이 다 돼서 또 간략하게만 말씀을 드릴게요. 그러면 이렇게 좀 프로세스를 줄이기 위해서 온라인으로 신청하는 또 보완자료를 하는 시스템을 구축할 용의가 있습니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 지금 현재 사전컨설팅을 자료를 접수해서 온라인으로 가능하게, 접수가 가능합니다.
</p>
<p><b>○ 이석균 위원 </b> 지금 그렇게 되어 있나요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 죄송합니다. 감사부서를 통해서 오는 거기 때문에, 죄송합니다. 
</p>
<p><b>○ 이석균 위원 </b> 지금은 안 돼요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 맞습니다. 위원님 말씀대로 온라인으로 안 되고 있는…….
</p>
<p><b>○ 이석균 위원 </b> 이런 부분들은 사실은 이게 감사를 목적으로 하는 게 아니라 사전컨설팅이에요. 그래서 온라인 신청 시스템과 그리고 쉽게 접근할 수 있는 예비 자문, 그니까 이거는 어떤 구속력 없이 좀 항시 물어볼 수 있는 이런 통로를 만들어 주시기를 바라며 나머지는 추가에 다시 하도록 하겠습니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 방금 말씀하신 건 잘 활용을 해 보겠습니다. 온라인화와 쉽게 예비적인 심사를 할 수 있는 부분들은 좀 고민을 해 보겠습니다.
</p>
<p><b>○ 부위원장 이혜원 </b> 감사위원장님 들어가 주시고요. 이석균 위원님 수고하셨습니다. 보충질의하실 위원님 더 계십니까? 보충질의하실 위원님 안 계십니까? 추가질의로 넘어가도 되겠습니까? 
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  동의해 주시면 보충질의를 마치도록 하겠습니다. 다음은 추가질의를 하도록 하겠습니다. 추가질의하실 위원님 계십니까? 
</p>
<p><b>○ 이석균 위원 </b> 몇 개에 대해서 질의하겠습니다.
</p>
<p><b>○ 부위원장 이혜원 </b> 이석균 위원님 하십시오.
</p>
<p><b>○ 이석균 위원 </b> 바로 추가질의 시간이 돌아왔습니다. 아니, 피곤하신데 앉아서 하셔도 돼요. 그렇게 제안드린 거에 대해서 검토를 하시겠다고 그래서 제가 감사를 드리고요. 
</p>
<p style="padding-left:1.2em">  두 번째는 아까 그 공기관에 대한 사전컨설팅입니다. 앞서 말씀드렸다시피 2022년도에 129건 중에 4건, 23년도에 135건 중에 6건, 24년도에 101건 중에 2건. 그런데 제가 경기도 공공기관 감사 결과보고서를 보게 되면 여기서 최소한 주의라든지 여러 가지 기관 경고도 있을 수도 있고 여기에 해당되는 부분이 공공기관 감사 결과가 2020년도에 150건, 21년도에 88건, 22년도에 135건, 23년도에 85건 이렇게 있습니다. 그러니까 수가 작지는 않아요. 근데 이 감사 내용의 결과가 사전컨설팅에 해당되는 것도 있고 안 되는 것들도 있기는 있어요. 그런데 이 숫자에 비해서 우리 공공기관에서 사전컨설팅감사를 요청하는 숫자가 너무나 미비하다. 이유가 뭐라고 생각합니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 아마 그 요건이 관계법령이나 유권해석이 명확함에도 민원 떠넘기기 목적이거나…….
</p>
<p><b>○ 이석균 위원 </b> 공공기관감사관실들과 한번 대화해 본 적 있으세요, 간담회나?
</p>
<p><b>○ 감사위원장 안상섭 </b> 사전 컨설팅과 관련해서는 항상 홍보책자나…….
</p>
<p><b>○ 이석균 위원 </b> 아니, 제가 말씀드린 게 공공기관의 감사실 직원이나 실장, 부장이나 같이 이렇게 한번 간담회 자리를 마련해 본 적이 있으십니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 간담회는 잘 모르겠습니다. 현장 컨설팅 협력, 협의나 이런 것들은 하는 걸로 알고 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 제가 그럼 다시 한번 말씀을 드립니다. 이분들이 사전 컨설팅에 대한 개념이 안 나와 있을 수도 있어요. 사전 컨설팅은 말 그대로 사전 컨설팅인데 이거를 받게 되면 마치 감사를 받는 듯한 느낌을 가진 분들도 있을 수 있어요. 그러니까 다 그렇다는 얘기는 아니고. 그러면 이분들과 간담회를 통해서 사전 컨설팅이 이러이러한 거고 법적 구속력이나 이러이런 부분들이 좀 자유롭게 기관에서 징계를 많이 받지 말고, 감사를 많이 받지 말고 사전 컨설팅을 적극 이용하라고 간담회를 하실 의향이 있으십니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 그것도 고민을 해 보겠습니다. 그리고 앞서 말씀드린 바와 같이 현장 사전 컨설팅 설명이나 안내책자나 이런 것들은 많이 보내고 있어서, 이제 별도 협의체 부분도 한번 고민을 해 보겠습니다.
</p>
<p><b>○ 이석균 위원 </b> 근데 책자 두껍죠? 두꺼우면 안 읽…….
