<p><b>○ 감사위원장 안상섭 </b> 현장에 가서 많이 설명하고는 있습니다.
</p>
<p><b>○ 이석균 위원 </b> 그런데 이런 소통을 좀 더 해 주십사 하는 얘기를 하고 싶어요. 여기 경기도 공공기관 감사 결과보고서에 보게 되면 많은 부분이 계약이라든지 또 이렇게, 특히 수의계약이라든지 그다음에 사전 컨설팅 감사대상이 되는 것임에도 불구하고 이런 제도를 이용하지 않고 관행적으로 추진하다가 감사에 지적이 되는 사례들이 되게 많은 것 같아요. 제가 보기에는 이런 활동들을 하시면 우리 감사위원회의 업무량도 줄어들 수 있을 것 같아요. 그래서 협의를 하시고 또 설명회나 간담회를 좀 하실 것을 부탁을 드립니다.
