<p><b>○ 이석균 위원 </b> 이상입니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 다만 조금 덧붙이면 저희 사전 컨설팅을 하게 되면 적극행정 면책, 아까 수의계약이나 이런 경우에 사례 수가 아까 정확하게 지적하신 대로 사전 컨설팅에 많이 올라오게 됩니다. 사전 컨설팅을 하게 되면 이게 면책이 되는 적극행정…….
