<p><b>○ 감사위원장 안상섭 </b> 네, 면책이 됩니다. 그런데 이거를 좀 염려되는 부분, 아까 오남용이 많다, 제외대상이 많다 하는 부분은 이제 공공기관에서 많이…….
</p>
<p><b>○ 이석균 위원 </b> 아니, 그거는 전반적인 사전 컨설팅에 대해서 말씀드린 거고요. 저는 공공기관에 대해서 말씀드린 거예요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 아까 좋은 말씀 주셔서 협의체를…….
</p>
<p><b>○ 이석균 위원 </b> 면책도 되고 하는데 이용을 안 해요. 4건, 6건, 2건 이러잖아요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 알겠습니다. 협의체 관련 말씀 주신 부분은 잘 활용해서 적극적으로 많이 활용할 수 있도록 노력하도록 하겠습니다.
