<p><b>○ 이경혜 위원 </b> 감사위원장님 일어나지는 않으셔도 되고요. 아까 주신 자료가 다른 자료들 사이에, 너무 많은 자료 속에 끼어서 제가 미처 못 봤던 점에 대해서는 양해 부탁드립니다. 그래서 그 자료를 봤는데 그거는 그냥 공식적으로 우리가 사업을 하거나 할 때 일어나는 일들에 대한 이야기인데 제가 그걸 길게 지금 말씀드리고 싶지는 않고 다만 저희가 효율적으로 이 시스템을 관리하고 개발하고 이럴 수 있는 예산소요액, 향후 지속적으로 이게 늘어날 거잖아요. 양은 방대해질 거고. 그랬을 때 늘어나는 예산들을, 계속 관리비가 늘어날 거고 이랬을 때 우리가 쓰는 예산을 효율적으로 쓸 수 있는 방안까지 검토해서 정보시스템 개발을 해 주시기를 바란다는 말씀을 드리면서 감사위원회 저의 감사는 그걸로 마치도록 하겠습니다. 잘 부탁드립니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 아까 주신 말씀 답변을 좀 드리도록 하겠습니다.
</p>
<p><b>○ 이경혜 위원 </b> 짧게 해 주셔야 다음 질문을 할 수 있어서요.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네, 알겠습니다. 어쨌든 예산이 많이 들어가고 이러한 부분들을 만약에 우리 직원도 또 투입되어야 되는 거 아닌가 하는 그런 고민들이 있으셨습니다. 저희들이 TF를 만들어서 용역사들과 협업을 같이 합니다, 착수에서부터 종료될 때까지. 그리고 그 예산은 딱 정해져 있기 때문에 증감의 우려는 없다고 보면 되겠습니다.
</p>
<p><b>○ 이경혜 위원 </b> 알겠습니다. 자세한 답은 나중에 혹시 시간이 되면 따로 좀 듣도록 하겠습니다. 수고하셨습니다.
</p>
<p style="padding-left:1.2em">  다음 도민권익위원회 여쭙겠습니다. 제가 옴부즈만에 관련된 말씀을 계속 어제오늘 자료를 요청하면서 드렸어요. 그랬던 이유는 옴부즈만이 해야 하는 역할과 기능에 대해서는 저한테 자료를 주셔서 충분히 봤습니다. 그런데 제가 궁금한 것은 옴부즈만의 의결을 조례를 좀 같이 살펴보도록 한 다음에 말씀을 드릴게요. 경기도 옴부즈만 구성 및 운영에 관한 조례 시행규칙의 제12조 권고 등 이행실태의 확인ㆍ점검 “옴부즈만은 조례 제30조에 따라 권고 등의 이행실태를 관련 부서의 장에게 다음 각 호의 방법으로 확인ㆍ점검할 수 있다. 이 경우 관련 부서의 장은 정당한 사유가 없는 한 이에 따라야 한다.” 그리고 그 아래 부분 호는 제가 따로 말씀드리지 않겠어요.
</p>
<p style="padding-left:1.2em">  제가 말씀드리고 싶은 것은 이행실태 확인ㆍ점검에 대한 이야기를 좀 드려보고 싶어서인데요. 2024년 5월 16일에 있었던 옴부즈만 의결이 하나 있어요. 혹시 내용을 여러 가지가 있을 테니까 잘 모르실 것 같아서 제가 민원 표시로 읽어드리면 818 경기도 공공기관 운영 기본계획 및 정원관리 지침 폐기 필요, 이 부분에 대해서 어떤 의결을 하셨냐면 피신청인은 공공기관 별도 정원의 인정 범위 확대를 위한 지방공기업 인사ㆍ조직 운영 기준의 개정 등을 중앙부처로 건의할 것과 육아휴직 별도 정원에 대한 실효성 있는 관리를 할 것을 촉구하고 해당 공공기관에 대한 전반적인 점검을 통해 업무량을 분석하고 그에 따른 적정 인원을 산정할 것을 의견 표명한다. 이런 의결을 옴부즈만에서 내렸어요. 그런데 제가 아까 말씀드린 것처럼 확인ㆍ점검이 필요하다라는 것에서 제가 말씀을 드리는 이유는 이 부분을 담당 부서하고 논의하거나 점검하신 일이 있으십니까?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 담당 부서에 결정내용을 통보했고 담당 부서가 이를 수용을 해서 그 해당 내용을 행정안전부 등에 건의한 것으로 확인하였습니다.
</p>
<p><b>○ 이경혜 위원 </b> 건의는 했고 그 이후의 결과에 대해서 받으셨습니까? 답변을 다시 받으셨어요?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 행정안전부가 이 사항을 불수용하였다고 확인을 하였습니다.
</p>
<p><b>○ 이경혜 위원 </b> 그러면 앞으로 경기도에서는 의결한 이후에 지금 이 의결한 부분들을 행정안전부에서는 그렇게 검토를 했고 그다음에 이 부서에서는 이 부분에 대해서 별도의, 이게 행정안전부에서의 지침으로 하지 않아도 된다라는 사실은 알고 계시죠, 이 내용이? 도지사의 권한으로 있는 거는 알고 계신 일인 거 아세요? 내용이, 별도 정원에 관련된 게. 그 부분은 정확히 알고 계신가요?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 아니요, 그 부분은 제가 아직 알지 못했습니다.
</p>
<p><b>○ 이경혜 위원 </b> 제가 정확하게 모르고 있는 건지 모르겠지만 제가 아는 한은 별도 정원에 관련돼서 공무원은 경기도 공무원 복무 조례와 경기도 공공기관의 조례가 연계되어 있거든요. 고양시가 아니, 경기도가. 그런데 이것을 연계하지 않고 할 수 있다로 되어 있는 걸로 알아요. 도지사의 권한으로 되어 있다로 제가 알고 있거든요. 이거는 다시 한번 나중에 확인하겠지만 그렇다면 옴부즈만에서 그리고 도민권익위에서 해야 할 일은 이것들이 관철될 수 있도록 도와주는 일까지 하는 게 도민권익위원회의 할 일이다. 그냥 거기서 그런 결정을 받았고 통보를 받았으니 우리의 일은 다 했다 이것이 아니라는 거죠. 이런 민원을 제기했던, 도민권익위원회에 제보하고 민원을 냈던 모든 사람들은 저희 공무원들이고 저희의 직원들입니다. 이분들이 그것에 대한 불편으로 인해서 요청을 했던 건데 통보를 받았으니 그걸로 끝인 게 아니라 계속 관여하고 확인ㆍ점검할 수 있다라고 되어 있지 않습니까?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 맞습니다.
</p>
<p><b>○ 이경혜 위원 </b> 이 부분을 지속적으로 관리해서 관철될 수 있도록 돕는 것도 국민권익위원회의 할 일이라고 보거든요. 이 부분도 앞으로 같이 신경 써주시기를 부탁드립니다.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 위원님 말씀 새겨서 최선의 노력을 다하겠습니다.
</p>
<p><b>○ 이경혜 위원 </b> 네. 시간이 끝나서 더 이상은 없겠지만, 하여튼 오늘 고생 많으셨고요. 도민권익위원회의 일들이 그렇게 결정을 통보하는 것이 아니라 해결해 주는, 사람이 필요로 한다는 것들을 챙겨주는 일들로 마무리가 되도록 했으면 좋겠습니다. 이상입니다.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네.
</p>
<p><b>○ 부위원장 이혜원 </b> 이경혜 위원님 수고하셨습니다. 지금 추가질의 시간이기 때문에 위원님들 다른 건으로 또 추가질의하실 수 있기 때문에 추가질의 있으시면 계속 요청해 주시기 바랍니다. 다음 이성호 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이성호 위원 </b> 경기연구원 부원장님.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 이성호 위원 </b> 직전의 그 판결내용을 보지 못하셨다는 말씀을 듣고 제가 좀 많이 놀랐는데요. 지금 이 용역내용이 통행료 인하, 사업 재구조화, 통행료 무료화 이렇게 돼 있지 않습니까? 2개의 용역이요.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 이성호 위원 </b> 그거는 다 승소를 전제로 한 내용들입니다. 경기도가 이걸 할 수 있어야지 이게 가능한, 의미가 있는 거 아닙니까? 그런데 지금 그 판결내용을 보지 못하셨다고 그러니까 내용을 말씀드리면 판결내용에서는 통행료가 과다하지 않다고 판단하고 있고 사업 재구조화의 필요성도 없는 것으로 판단을 하고 있습니다. 그런데 그런 내용을 알았어도 이게 추진을 하는 게 맞습니까? 지금 이런 내용이 나왔는데 실현 가능성도 없는 거를 혈세 1억 2,000만 원을 들여 가지고 하는 게 맞습니까, 이게? 그걸 파악조차 하지 못하고 있었다는 거는 더더욱 말이 안 됩니다, 그게.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 말씀하신 수탁과제는 사실은 2016년부터 시행이 됐던 거고요. 사실 이 판례, 판결은 19년도에 나왔던 걸로…….
</p>
<p><b>○ 이성호 위원 </b> 2016년에 한 거는 52페이지에 있는 거고 41페이지 건 2019년에 한 거 아닙니까? 8월에.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 41페이지는 사실은 무료화라든가 이런 걸 전제로 했던 건 아니고요. 주요내용은 여러 가지…….
</p>
<p><b>○ 이성호 위원 </b> 통행료 인하 수준 및 재무모델을 검토하고 있는데 이게 그게 아니고 뭡니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 그래서 결론적으로는 이 보고서에서 무엇을 주장했냐면 최적의 대안은 통행료를 한 200원 정도 하향 조정하기 위해서는 무상 사용기간을 한 5년 정도 그리고 통행료를 400원으로 2배 정도 더 내리기 위해서는 15년 정도 무상 사용허가 기간을 연장해 주는 것이 좋겠다는 정책제안을 하고 있습니다. 그래서 이 보고서의 내용에 보면…….
</p>
<p><b>○ 이성호 위원 </b> 그러니까 제가 말씀드리는 것은 그런 것도 다 경기도가 할 수 있을 때 의미가 있는 거지 않습니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 그렇습니다.
</p>
<p><b>○ 이성호 위원 </b> 지금 그런데 그 소송을 다 진 상태에서 그런 제안을 하는 게 무슨 의미가 있냐는 말씀이에요.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 결과적으로는 2,000…….
</p>
<p><b>○ 이성호 위원 </b> 그래서 결국에는 실현 가능성이 없는 그런 제안이지 않습니까, 지금? 혈세를 이런 식으로 낭비를 해도 되냐고요. 본인 돈이면 소송 다 진 거를 그렇게 용역 수행을 하겠습니까? 용역비를 지출하겠습니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 그러니까 이 당시에는 통행료 인하에 대해…….
</p>
<p><b>○ 이성호 위원 </b> 게다가 72번 그것도 마찬가지인데 2016년이라고 면책되시는 게 아니고 이때도 재정지원금 청구소송 1심은 이미 나온 상태였어요. 그것도 모르셨죠? 그것도 당연히 확인 안 해 보셨을 거 아닙니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네.
</p>
<p><b>○ 이성호 위원 </b> 이런 식으로 방만하게 운영을 해도 됩니까, 이게? 이게 8,000만 원 들어갔잖아요, 지금 용역비가. 설령 모르셨다고 하더라도 지금 소송이 진행 중인 건 알고 계셨을 거 아닙니까?
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 그렇습니다.
</p>
<p><b>○ 이성호 위원 </b> 그럼 그게 1심 결과가 나오고 이게 민사소송, 행정소송이라는 게 1심, 2심, 3심 거치려면 최소 3년 이상 소요가 되는데 결과도 나오기 전에 이런 거를 먼저 선집행을 8,000만 원을 하고 한다는 것 자체도 불합리하고, 굉장히 부당하고 그런 부분이 있다는 건 어떻게 생각하십니까? 1심 결과를 보고 그때 시작해도 전혀 늦지를 않습니다. 근데 지금 아예 확인조차 안 하시고. 이게 굉장한 도덕적 해이지 않습니까? 이런 용역비에 대해서. 앞으로 좀 시정해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 말씀 주신 사항에 대해서는 저희가 면밀히 살펴보고 이런 일이 반복되지 않도록 그렇게 하겠습니다.
</p>
<p><b>○ 이성호 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 이혜원 </b> 이성호 위원님 수고하셨습니다. 다음은 박진영 위원님 추가질의해 주시기 바랍니다.
</p>
<p><b>○ 박진영 위원 </b> 아까 좀 급하게 마무리 지어 가지고. 도민권익위원장님.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네.
</p>
<p><b>○ 박진영 위원 </b> 제 거 화면 좀 띄워주세요.
</p>
<p style="padding-left:2.4em">    (영상자료를 보며)
</p>
<p style="padding-left:1.2em">  아까 제가 말씀드렸던 규정 위배에 관한 거 이거 근데 이 규정 위배에 대해서 도민권익위는 어디에서 이걸 검토받아야 돼요? 보통 다른 부서인 경우에는 감사실에서 검토를 받는데.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 지금 저희가 고충민원 처리는 기존에 하던 고충민원을 처리하고 있었기 때문에 계속 이어서 갔고요. 새로 만든 도민감사청구나 공공사업 감시ㆍ평가제도 같은 것들을 위원님 말씀대로 운영규정이 아직 완성이 안 돼서 실행을 하지 못하고 있습니다.
</p>
<p><b>○ 박진영 위원 </b> 이거를 어디서 검토해야 돼요? 아까 감사위원회 같은 경우에는 도내 집행부나 공공기관을 감사해 가지고 규정 위배인 경우에는 그 규정 위배에 대한 시정명령을 내리시잖아요. 그리고 감사위원회는 그걸 관리하는 부서인 만큼 본인들의 부서에 대한 규정들을 철저하게 빠르게 만들어서 정비하셨고요.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 다만…….
</p>
<p><b>○ 박진영 위원 </b> 도민권익위는 이거를 어디에서 검토받아 가지고…….
</p>
<p><b>○ 도민권익위원장 장진수 </b> 저희한테만 조금, 해명의 말씀을 잠시만 드리자면…….
</p>
<p><b>○ 박진영 위원 </b> 이 법령에 대한 문제가 아니에요. 지금 도민권익위 설치ㆍ운영규정에 관한 조례에 보시면 지금 이 조례에서 차용하고 있는 상위법이 뭔지 아세요? 2개예요. 부패방지권익법이랑 공익감사법. 이거 가벼운 법들이 아니에요. 공공감사법이 가벼운 법이라고 생각하시나요?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 그렇지 않습니다.
</p>
<p><b>○ 박진영 위원 </b> 조사를 할 수 있는 책임이, 권한이 가벼운 거라고 생각하시나요?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 그렇지 않습니다.
</p>
<p><b>○ 박진영 위원 </b> 운영규정 없이 조사를 한다는 건 엄청나게 큰 문제고 도민권익위의 위원님들이 회의를 운영하시는 데 그 운영규정이 없는 것도 큰 문제인 것 같은데요. 이거 그러니까 어디서 검토받아서 시정명령 받으셔야 되냐고요.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 저희가…….
</p>
<p><b>○ 박진영 위원 </b> 검토해서 갖다 주십시오. 이거 어디서 검토해서…….
</p>
<p><b>○ 도민권익위원장 장진수 </b> 다만 좀 말씀을…….
</p>
<p><b>○ 박진영 위원 </b> 어디서 도민권익위가 잘못하신 것에 대한 시정명령 받을 수 있는지 검토해서 말씀 주십시오.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 저희가…….
</p>
<p><b>○ 박진영 위원 </b> 저 분명히 이거…….
</p>
<p><b>○ 부위원장 이혜원 </b> 도민권익위원장님, 위원님이 질문을 하시면 질문 후에 답변을 하세요.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 죄송합니다.
</p>
<p><b>○ 박진영 위원 </b> 위원장님, 규정 미비에 대해서, 도민권익위가 아닌 다른 곳에서 도민권익위가 규정 미비한 사항에 대해서 검토해서 어디서 하실 수 있는지 알아 가지고 말씀 주세요.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 그렇게 하겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 지금 몇 달이 지났는데 규정 미비니까 이건 심각한 문제가 맞는 것 같습니다.
</p>
<p style="padding-left:1.2em">  그리고 또 하나 여쭤볼게요. 도민권익위 관련돼서 아까 말씀드렸다시피 부패방지권익법이랑 공공감사법을 상위법으로 하고 계신 것 같은데, 조례에서. 물론 저희가 조례를 만들었지만.
</p>
<p style="padding-left:1.2em">  여쭤볼게요. 위원장님, 조례가 상위법을 위반할 수 있어요?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 없습니다.
</p>
<p><b>○ 박진영 위원 </b> 지금 도민권익위 설치 및 운영에 관한 조례 부칙에 따라서 도민 옴부즈만 구성 및 운영에 관한 조례에 있는 이 위촉위원들을 해촉기간까지 계속 적용한다라고 돼 있는데 지금 공공감사법에는 위원회에 대한 구성인원을 7명으로 해 놨고요. 부패방지법에는 위원회의 인원 규정이 없습니다. 근데 지금 상위법을 2개의 법이라고 했으면 더 타이트하게 적용하면 7명 이하의 위원으로 구성해야 된다고 생각하는데 어떻게 생각하세요?
</p>
<p><b>○ 도민권익위원장 장진수 </b> …….
</p>
<p><b>○ 박진영 위원 </b> 답변…….
</p>
<p><b>○ 도민권익위원장 장진수 </b> 만족드릴 만한 말씀을 아직, 답변을 드리기가 어려운 것 같고요.
</p>
<p><b>○ 박진영 위원 </b> 죄송합니다. 제가 만족하는 거랑은 상관없이 명확한 입장을 표명해 주시기 바랍니다.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 좀 검토를 해서 따로 보고를 드리면 어떨지 양해를 해 주시면 감사하겠습니다.
</p>
<p><b>○ 박진영 위원 </b> 하나만 더 여쭤보겠습니다. 부패방지권익법에 따르면 시민고충위원회 위원의 자격이 보면 1ㆍ2ㆍ3ㆍ4ㆍ5호, 5개가 있습니다. 지금 선정되신 도민권익위 위원분들 열 분이시죠?
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 그렇습니다.
</p>
<p><b>○ 박진영 위원 </b> 열 분이 각각 어떤 거에 해당하는지 꼭 주시고요. 다섯 번째 같은 경우에는 사회적 신망이 높고 앤드 규정인 것 같은데 행정에 관한 식견과 경험이 있는 자로서 이거 플러스 시민사회단체로부터 추천을 받아야 되는데 시민사회단체로부터 추천받은 내용 꼭 첨부해 주시기 바랍니다. 이상입니다.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네, 알겠습니다.
</p>
<p><b>○ 부위원장 이혜원 </b> 박진영 위원님 수고하셨습니다. 추가질의하실 위원님 더 계십니까?
</p>
<p><b>○ 이채명 위원 </b> 간단하게 제가 좀 질의하겠습니다.
</p>
<p><b>○ 부위원장 이혜원 </b> 이채명 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 이채명 위원 </b> 늦은 시간까지 고생이 많으십니다. 감사담당관님께서 답변을 못 하시면 또 팀장님께서 답변을 주시겠어요? 아까 질의에 이어서 좀 더 구체적으로 답변을 요하도록 하겠습니다. 감사위원장님, 혹시 제가 받은 자료 경기아트센터 차량 운행일지를 확인해 보셨나요?
</p>
<p><b>○ 감사위원장 안상섭 </b> 아, 네. 운행일지 아까 보여주신 거.
</p>
<p><b>○ 이채명 위원 </b> 사실은 아까 팀장님이 답변할 때 어떻게 얘기했었냐면요, 경기아트센터 공용차량 관리 내부 규정에 명확하게 출퇴근을 할 수 있다라고 명시가 되어 있다라고 답변을 주셨거든요. 그런데 제가 규정을 받아봤어요. 12조에 “전용차량 지원 제한”이라는 규정에 어떻게 돼 있냐면 “아트센터의 전용차량은 사장에 한하여 지원하며 배기량 3,000㏄ 이하로 한다.”, “아트센터의 전용차량은 사장에 한하여 지원하며” 이 문구를 가지고 출퇴근용으로 사용할 수 있기 때문에 이해충돌방지법에 위배되지 않는다라고 아까 저한테 따박따박 반박하고 하셨거든요. 이 부분에 대해서 어떻게 생각하시는지 답변을 주시기 바랍니다.
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 아마 이게 지금…….
</p>
<p><b>○ 이채명 위원 </b> 그리고 저한테 해석 사례도 사실은 보여주셨어요. 관용차량의 사적 사용에 대해서 국민권익위원회에 문의를 하신 것 같아요. “공공기관의 장이 전용차량을 이용하여 출퇴근하는 것이 이해충돌방지법 위반에 해당하는지요?”라고 이렇게 질문을 던졌단 말이에요. 질문을 어떻게 하느냐에 따라서 국민권익위원회에서 분명히 답변이 다르게 나올 수 있습니다. 어떻게 여기서는 답변을 줬냐면요. “행정안전부 공용차량 관리 규정 제10조제2항에 전용차량을 이용한 출퇴근을 일반적으로 제한하지는 않는 것으로 보입니다. 다만 각급 공공기관은 위 규정 및 매뉴얼을 참고하여 공용차량을 엄격히 운용해야 할 것이며”라고 “구체적인 사안과 관련해서는 해당 기관의 공용차량 운영 목적 및 관련 법령기준을 종합적으로 검토해서 사적인 사용 여부를 자체적으로 판단하여야 한다.”라고 이렇게 명시되어 있거든요. 이렇게 봤을 때 제가 아까 감사팀장님께 운행일지를 정확하게 보여드렸습니다. 이 운행일지를 보시면 일률적으로 아침 5시에 출근해 출발을 해서 도착 6시 10분, 센터에서 서울까지 그리고 또 서울에서 센터까지 6시 40분에 출발을 다시 해서 8시 26분에 도착을 해서 그러고 나서 그 중간에는, 예를 들어서 감시단속적근로자로 등록이 됐으면 한 3시간 정도는 휴식시간을 아마 의무로 보장할 겁니다. 그럼에도 불구하고 또 8시 45분에서 이후에 11시 47분까지 퇴근 시간에 지금 이 차를 운행했어요. 그런데 이 일지가 하루만 이런 게 아니라요, 지금 저한테 주신 자료에 거의 대부분이 이렇게 출퇴근 3시간, 출근 3시간, 퇴근 3시간 반 약 6시간을 출퇴근으로 관용차를 개인의 출퇴근 차량으로 이용했어요. 이런데도 불구하고 내부 규정에 명확하게 명시가 되어 있어서 이해충돌방지법에 위배되지 않는다라고 답변하실 수 있습니까, 감사위원장님?
</p>
<p><b>○ 감사위원장 안상섭 </b> 위원님, 제 해석이니까요, 저도 법률을 좀 해 봐서. 오해는 하지 마시고요. 아마 12조에 전용차량 지원 제한 이렇게 되어 있는 것은요, 물론 해석은 여러 가지 다를 수는 있는데요. 아트센터의 전용차량은 사장에 한한다는 게 전용차량의 용도가 보통은 출퇴근인 것 같아서 그렇게 말을 했던 것 같습니다.
</p>
<p><b>○ 이채명 위원 </b> 답변이 바뀌셨어요. 그렇다면 앞부분의 정의에 전용차량이라는 정의가 있었어야죠. 정의가 없습니다. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 그러니까 보통 공공기관의 전용차량은 사장이나 임원들한테 아마 있는 것 같은데, 보통은 출퇴근용으로 사용을 하는데 여기는 기재를 안 해 놨습니다.
</p>
