<p><b>○ 부위원장 이혜원 </b> 그 답변은 앞서 드렸습니다, 위원장님. 
</p>
<p><b>○ 감사위원장 안상섭 </b> 네. 그거는 아까 말씀하신 것처럼 공개된 자료는 더 그런 부분을 비공개로 소상하게 설명을 드릴 수는 있을 수 있다라는…….
