<p><b>○ 이석균 위원 </b> 이석균 위원입니다. 장진수 도민권익위원장님. 우리 행정사무감사 요구자료 78쪽인데요. 도민 참여 기반의 경기도형 특화 모델을 구축하겠다 하시는 말씀이 있는데 내용은 좋습니다마는 여기 내용 보면 위법행위 등의 자체감사 활동이라고 돼 있어요. 우리 도민권익위원회가 감사 활동을 할 수 있나요? 감사를? 
