</p>
<p><b>○ 도민권익위원장 장진수 </b> 저희가 도민감사청구라는 제도를 도민권익위원회가 출범하면서…….
</p>
<p><b>○ 이석균 위원 </b> 그러니까 조사를 해서 감사를 청구하는 거지 감사위원회처럼 감사를 하는 건 아닌 것 같아요.
</p>
<p><b>○ 도민권익위원장 장진수 </b> 네. 도민들께서 저희한테 도민권익위원회로 감사를 청구하게 되면 그 감사 업무를 수행하게 됩니다. 그 기능을 수행토록 하기 위해서 감사기구로서의 기능을 일부 저희에게 부여한 것으로…….
