</p>
<p><b>○ 이석균 위원 </b> 그러니까 감사가 아니라 조사를 해서 이송을 하거나 이렇게 해서 감사위원회나 이런 데서 처분을 하는 거지 감사 활동을 해서 처분을 하는 것은 아니잖아요.
