<p><b>○ 이석균 위원 </b> 네. 아니, 그런데 이 단어는 좀 안 쓰시는 게 좀 더 명확하지 않을까. 그러니까 조사, 확인, 감시 이런 단어로 좀 써주시면 좋을 것 같아요.
