<p><b>○ 경기연구원장직무대행 박충훈 </b> 네, 확인했습니다. 당시에 연구부원장으로 있던 송미영 부원장이 연구결과보고서 때 이런 내용을 수용했고요. 최종 결재는 당시에 원장 직무대행을 했던 허성관 이사장까지 결재가 돼서 대외주의가 신청이 되었습니다.
