<p><b>○ 위원장 조성환 </b> 이상으로 추가질의까지 모두 끝났습니다. 오늘 회의 내용 외에 혹시 서면질의 있으신 위원님 계십니까? 이혜원 위원님.
</p>
<p><b>○ 이혜원 위원 </b> 서면질의 요청하겠습니다. 먼저 앞서 자료 요구했던 갑질 관련 신고 처리현황 다시 정리해서 장진수 도민권익위원장님, 내용은 충분히 이해하셨죠?
