</p>
<p style="padding-left:1.2em">  오늘 늦은 시간까지 수고 많으셨습니다. 위원님들 질의에 답변하시느라 또 장시간 수감받으시면서 고생 많으셨습니다. 아마 오늘 행정사무감사를 받으신 우리 집행부 여러분들께서는 향후에 감사 업무를 진행하면서 오늘의 경험이 많은 도움이 될 것이라고 생각을 합니다. 우리 감사위원장님, 어떠세요? 수감받아보시니까.
