</p>
<p><b>○ 위원장 조성환 </b> 네. 그래서 수감받는 입장에서 성실하고 최선을 다해서 수감을 받으시면 감사를 하는 입장에서도 그런 부분들이 충분히 전달이 됩니다. 오늘 하루 종일 고생 많으셨는데 앞으로도 그런 일들을 많이 참조하시면 좋겠고요. 오늘 피감기관께서는 위원님들께서 요청하신 서면질의 내용에 대해서 충실히 답변해 주시기 바라고 오늘 제출된 서면질의서와 답변서의 내용은 회의록에 게재토록 하겠습니다.
