<p><b>○ 감사위원장 안상섭 </b> 네.
</p>
<p><b>○ 위원장 조성환 </b> 아까 말씀 안 드렸지만 오늘 질의 받는 내내 그런 태도가 있었다고 보고받았습니다. 그래도 따로 질책 안 하고 전체적으로 이렇게 말씀을 드렸는데 방금 지금 또 위원장이 발언하는데 또 그런 태도를 보이십니까?
</p>
<p><b>○ 감사위원장 안상섭 </b> 죄송합니다.
</p>
<p><b>○ 감사위원회감사총괄과주무관 김동일 </b> 죄송합니다.
</p>
<p><b>○ 위원장 조성환 </b> 앉으세요. 할 말이 많지만 저희가 또 다음 일정이 있기 때문에 마무리하겠습니다.
</p>
<p style="padding-left:1.2em">  오늘 감사 중에 위원님들께서 개선이나 시정을 요구한 사항들도 조속히 조치될 수 있도록 노력해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  위원님 여러분! 고생 많으셨습니다. 그리고 위원님들의 자료 요구와 질의에 성의를 다해 답변해 주신 감사위원장, 도민권익위원장, 경기연구원장 직무대행을 비롯한 모든 관계자분들께도 감사드립니다. 오는 11월 18일 월요일에는 감사위원회, 도민권익위원회 및 경기연구원 업무 전반에 관한 종합감사가 실시될 예정이오니 위원님들께서는 꼭 참석해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  이상으로 금일 예정되었던 감사위원회, 도민권익위원회, 경기연구원 소관 사항에 대한 행정사무감사 종료를 선언합니다.
</p>
<p class=''ar''>(21시14분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원(12명)
</b></p>
<p class=''aMan''>김정호박상현박진영양우식오창준이경혜이석균이성호이채명이혜원</p>
<p class=''aMan''>정승현조성환</p>
<p><b>○ 출석전문위원
</b></p>
<p class=''em15''>   수석전문위원 이태헌
</p>
<p><b>○ 피감사기관참석자
</b></p>
<p class=''em05''>ㆍ감사위원회</p>
<p class=''em15''>위원장 안상섭감사총괄과장 김상팔</p>
<p class=''em15''>감사1과장 이선범감사2과장 성현숙</p>
<p class=''em15''>계약심사과장 유용철</p>
<p class=''em05''>ㆍ도민권익위원회 위원장 장진수</p>
<p class=''em05''>ㆍ경기연구원</p>
<p class=''em15''>원장 직무대행 박충훈기획조정본부장 김점산</p>
<p class=''em15''>북부자치연구본부장 유영성미래전략연구본부장 김을식</p>
<p class=''em15''>감사실장 민철기</p>
<p class=''em15''>경기도공공투자관리센터 소장 직무대행 박정환</p>
<p><b>○ 기록공무원
</b></p>
<p class=''em15''>정다현</p>
