            <p class="skip">맨위로 이동</p>

            <div','경기도의회',false,'{"legacy_id": "audit-14879", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=14879"}'::jsonb,'2024-11-12'::date,'2024-11-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-14879');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2022.11.09. 수요일] 경기연구원 — 기획재정위원회 2022년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제11대 경기도의회 기획재정위원회</b> · 2022년도 행정사무감사(2022. 11. 04. ~ 2022. 11. 17.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=13928" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2022년도 행정사무감사
</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관: 경기연구원
</p>
<p><hr /></p>
<p>일  시: 2022년 11월 9일(수)
</p>
<p>장  소: 기획재정위원회 회의실
</p>
<p><hr /></p>
<p class=''ar''>(16시26분 감사개시)
</p>
<p><b>○ 위원장 지미연 </b> 의석을 정돈하여 주시기 바랍니다. 성원이 되었으므로 감사를 속개하겠습니다.
</p>
<p style="padding-left:1.2em">  지금부터 지방자치법 제49조, 동법 시행령 제43조제1항과 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기연구원 소관에 대한 2022년도 행정사무감사를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  위원님 여러분 그리고 관계자 여러분! 안녕하십니까? 기획재정위원회 감사위원장 지미연 위원입니다.
</p>
<p style="padding-left:1.2em">  감사관 소관에 이어 계속해서 수고하시는 위원님들과 경기도의 싱크탱크로서 도정 선도를 위한 정책연구에 애쓰시는 송미영 연구부원장을 비롯한 관계자 여러분의 노고에 감사와 격려를 표합니다. 
</p>
<p style="padding-left:1.2em">  그럼 우리 위원회 감사일정에 따라 경기연구원에 대한 2022년도 행정사무감사를 실시하겠습니다.
</p>
<p style="padding-left:1.2em">  경기연구원 관계자 여러분께서 잘 아시는 바와 같이 지방의회 행정사무감사는 집행기관의 행정사무 전반에 관한 실태를 파악하고 나아가 2023년도 예산안 심사에 반영함은 물론 도민의 삶의 질 향상에 기여하는 것이 그 목적인 만큼 매우 중요한 의미가 있습니다. 따라서 감사에 임하는 경기연구원 관계자 여러분께서도 본 위원회가 이번 행정사무감사를 통해 얻고자 하는 소기의 목적이 달성될 수 있도록 감사에 충실히 임해 주시기 당부드립니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 송미영 연구부원장과 각 본부장, 실장 등은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 선서를 하셔야 합니다. 선서를 하는 이유는 경기도의회가 2022년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김 없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 한 때에는 지방자치법 제49조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있으며 증언을 거부한 때에는 동법 규정 및 동 조례 제31조에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 아울러 형사소송법 제148조 근친자의 형사책임과 증언 거부 또는 제149조 업무상 비밀과 증언 거부에 해당하는 때에는 선서와 증언 그리고 서류 제출을 거부할 수 있음을 함께 알려드립니다. 
</p>
<p style="padding-left:1.2em">  참고로 경기연구원장은 현재 공석이어서 송미영 연구부원장이 원장의 직무를 대행함을 알려드립니다. 아울러 류시균 시군연구센터장과 박인숙 재정지원부장은 코로나19 확진으로 불참하게 되었음을 위원님들께서 양지하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인출석 여부를 확인하겠습니다. 피감사기관의 증인들께서는 모두 자리에서 일어나 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  송미영 연구부원장 나오셨습니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 봉인식 연구기획본부장 나오셨습니까? 
</p>
<p><b>○ 연구기획본부장 봉인식 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 김동성 균형발전본부장 나오셨습니까? 
</p>
<p><b>○ 균형발전본부장 김동성 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 이정훈 북부연구센터장 나오셨습니까?
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 박충훈 자치분권연구실장 나오셨습니까?
</p>
<p><b>○ 자치분권연구실장 박충훈 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 이성룡 도시주택연구실장 나오셨습니까?
</p>
<p><b>○ 도시주택연구실장 이성룡 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 성영조 경제사회연구실장 나오셨습니까?
</p>
<p><b>○ 경제사회연구실장 성영조 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 빈미영 교통물류연구실장 나오셨습니까?
</p>
<p><b>○ 교통물류연구실장 빈미영 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 이기영 생태환경연구실장 나오셨습니까?
</p>
<p><b>○ 생태환경연구실장 이기영 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 이수진 연구기획부장 나오셨습니까?
</p>
<p><b>○ 연구기획부장 이수진 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 김정훈 전략정책부장 나오셨습니까?
</p>
<p><b>○ 전략정책부장 김정훈 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 손호철 행정지원부장 나오셨습니까?
</p>
<p><b>○ 행정지원부장 손호철 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 배미성 성과관리부장 나오셨습니까?
</p>
<p><b>○ 성과관리부장 배미성 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 이덕환 홍보정보부장 나오셨습니까?
</p>
<p><b>○ 홍보정보부장 이덕환 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 김도일 공공투자관리센터 소장 나오셨습니까?
</p>
<p><b>○ 경기도공공투자관리센터소장 김도일 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 김병석 공공투자관리센터 총괄기획부장 나오셨습니까?
</p>
<p><b>○ 경기도공공투자관리센터총괄기획부장 김병석 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 한명주 공공투자관리센터 투자분석평가1부장 나오셨습니까?
</p>
<p><b>○ 경기도공공투자관리센터투자분석평가1부장 한명주 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 이상미 공공투자관리센터 투자분석평가2부장 나오셨습니까?
</p>
<p><b>○ 경기도공공투자관리센터투자분석평가2부장 이상미 </b> 네.
</p>
<p><b>○ 위원장 지미연 </b> 다음은 선서의 요령에 대하여 설명드리겠습니다. 선서는 증인들을 대표해서 송미영 연구부원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손을 들어주시면 되겠습니다. 그러면 증인들께서는 선서를 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 선서! 본인은 경기도의회가 지방자치법 제49조, 같은 법 시행령 제30조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2022년도 행정사무감사를 실시함에 있어 증인으로서 성실하게 감사를 받을 것이며 또한 증언과 자료제출에 있어서는 지방자치법 시행령 제46조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2022년 11월 9일 경기연구원 원장 직무대행 송미영.
</p>
<p><b>○ 위원장 지미연 </b> 모두 자리에 앉아 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (일동착석)
</p>
<p style="padding-left:1.2em">  계속해서 간부인사와 업무보고를 받도록 하겠습니다. 송미영 연구부원장 나오셔서 간부소개와 업무보고를 해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 안녕하십니까? 경기연구원 원장 직무대행을 맡고 있는 송미영입니다. 저희 경기연구원 발전을 위해 관심을 가지시고 항상 염려해 주시고 성원해 주시는 지미연 위원장님을 비롯한 기획재정위 위원님들께 감사드립니다. 지금 현재 저희 연구원에는 아까 위원장님 말씀하셨듯이 원장님이 공석이기는 하지만 이사회를 통해서 주형철 원장 후보자를 선임한 상태이고 인사청문회를 준비 중에 있습니다. 오늘 기재위 위원장님을 비롯하여 위원님들을 모시고 2022년 저희 연구원의 행정사무감사 보고를 드리게 돼서 뜻깊게 생각합니다. 
</p>
<p style="padding-left:1.2em">  저희 연구원은 대내외 여건 변화에 따른 정책대응을 위해 연구원의 비전을 새로운 경기 정책플랫폼 GRI로 설정하고 경기도민의 삶의 질 향상을 위해 전 직원이 합심하여 노력하고 있습니다. 향후에도 연구원의 발전을 위해 기재위 위원님들의 많은 관심과 고언을 부탁드립니다.
</p>
<p style="padding-left:1.2em">  업무보고에 앞서 위원장님 말씀해 주신 대로 저희 연구원의 주요간부를 소개하겠습니다. 
</p>
<p style="padding-left:1.2em">  봉인식 연구기획본부장입니다.
