</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  한명주 공공투자관리센터 투자분석평가1부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상미 공공투자관리센터 투자분석평가2부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  참고로 아까 위원장님 말씀해 주신 것처럼 류시균 시군센터장하고 박인숙 재정지원부장은 코로나 확진으로 인해서 오늘 불참을 했습니다. 양해를 부탁드립니다.
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 저희 연구원의 주요업무를 보고드리겠습니다. 자료는 2022년도 주요업무보고 자료를 보시면 되겠습니다. 보고순서는 목차에 보시는 것처럼 기본현황, 2022년도 경영목표 및 사업방향 그리고 주요연구사업 성과 순으로 말씀드리겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 1쪽 기본현황입니다. 저희 연구원은 95년 개원 이래 경기도와 시군의 중장기 비전 제시와 정책개발 기능을 수행해 오고 있습니다. 연구원의 조직은 본원의 2부원장, 1실, 2본부, 5연구실, 2센터, 7부로 구성되어 있고 부설기관인 경기도공공투자관리센터가 3부로 구성되어 있습니다. 저희 원 전체 인력은 정규직 정원 187명 중에 현원 160명이고 비정규직인 기간제근로자 23명이 근무하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 2쪽 주요기능입니다. 원장 직속으로 감사실이 편재되어 있으며 연구부원장 산하에 연구기획본부, 균형발전본부 2개의 본부가 있고 각 연구실이 그 아래에 구성되어 있습니다. 경영부원장 산하에는 5개의 행정부서가 편재되어 있고 부설기관으로 아까 소개해 드린 경기도공공투자관리센터 조직을 두고 있습니다. 부서별 주요업무 등 상세한 내용은 2쪽 자료로 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 3쪽 예산현황에 대해서 보고드리겠습니다. 올해의 총예산 규모는 289억 원으로 일반회계 263억 원, 공투센터특별회계 26억 원으로 구성되어 있습니다. 세부적으로 보시면 수입항목 중에 일반회계 233억 중 경기도 출연금이 188억 원으로 80.7%를 차지하고 있으며 수탁회계전입금은 10억 원이고 전기이월금 31억 원, 이자수입 3억 원 등이 포함되어 있습니다. 지출항목으로는 인건비가 143.8억 원으로 일반회계 예산의 61.7%로 대부분을 차지하고 있고 연구사업비는 56억 원으로 24%를 차지하고 있습니다. 이외에 경상경비 24억 원이 추가로 편성되어 있습니다. 일반회계하고 공공투자관리센터특별회계는 자료를 참조하여 주셨으면 감사하겠습니다.
</p>
<p style="padding-left:1.2em">  다음에 저희 경영목표 및 사업방향에 대해서 설명드리겠습니다. 저희의 미션, 비전, 핵심가치, 경영목표는 4쪽을 보시면 알 수 있는데 저희 연구원은 경기도민의 삶의 질 향상과 도정 선도를 위한 정책연구로 비전을 설정하고 4대 경영목표로 도민 삶의 질 향상에 기여하는 연구선도, 현장과 소통하는 연구체계 수립, 환경변화에 대응한 새로운 사업 확대, 공정하고 투명한 경영관리체계 수립으로 설정하여 추진 중에 있습니다. 
</p>
<p style="padding-left:1.2em">  2022년 주요연구사업은 5쪽에 나와 있습니다. 주요이슈로는 코로나19 팬데믹, 위드 코로나의 전환, 인구구조 변화 및 고용여건 악화 등으로 사각지대 발생, 심화되는 지역 양극화, 기후변화에 대응하는 신사회시스템, 변화하는 국제정세 속 불안정성 증가 등에 대응하는 것을 주요내용으로 하고 있습니다. 2022년 4대 연구사업 방향은 이러한 여건을 반영해서 위드 코로나 변화된 일상에 대한 적응을 1번으로 하고 다음으로 공정한 경기도, 보편적 복지 강화 그다음으로는 지속가능발전 기반 조성 및 생활환경의 질 개선 그리고 마지막으로 분권, 균형발전과 남북평화시대를 선도하는 지방정부 실현을 연구사업 방향으로 설정해 두고 있습니다. 물론 이러한 내용은 원장 내정자가 임명받게 되면 지금 현재 민선8기의 정책이나 시책방향하고 조금 더 긴밀한 연계 조정이나 미세한 조정이 있을 것으로 생각하고 있습니다.
</p>
<p style="padding-left:1.2em">  6쪽에 연구사업의 주요성과입니다. 현재 민선8기에서는 기회의 경기, 변화의 중심을 위한 4대 연구방향으로 여러 가지 시책을 추진하고 있는데 저희도 거기에 맞추어 183건의 연구과제를 수행하여 왔고 앞서 말씀드린 여러 가지 일상적인 연구과제의 일부로 경기도형 경제위기대응시스템 도입 방안, 경기도 상권활성화 지원정책 개선방안 연구들을 수행했습니다. 그다음에 공정한 경기도나 보편적 복지 강화에 관련해서는 공정한 플랫폼 경제 생태계를 위한 규제 방안 연구, 경기도 비정규직 공정수당 제도에 대한 평가와 개선방안 연구 등을 수행하였습니다. 그다음에 지속가능발전 기반이나 생활환경의 질 개선 관련해서는 경기도 대기오염물질 배출량 변화분석 및 장래전망, 자율주행 실도로 실증 서비스 및 안전 운영에 관한 연구 그다음에 경기도 탄소중립을 위한 정의로운 전환 플랫폼 구축 기초연구 등을 수행해 왔습니다. 마지막 분권이나 남북평화시대 균형발전하고 연계해서는 지방정부 실현 연구를 위해서 민선8기 세입 분야 지방재정 지속가능성 관리방안 연구, 경기북부특별자치도 설치 및 북부발전전략 수립 기초 연구 등을 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음 7쪽에 보시면 저희가 민선8기 도정 현안에 적시 대응하기 위해서 추진하고 있는 사항을 말씀드리겠습니다. 우선 경기북부특별자치도 연구단을 설치해서 TF를 계속 운영 중에 있고 긴밀한 자료와 협조 그다음에 정보공유를 시행하고 있습니다. 또한 경기도 민생대책특별위원회 연구단을 설치하여 민생 현황 모니터링 강화 및 특별위원회 대책반을 밀착 지원하고 종합적인 민생대책 수립 연구도 추진하고 있습니다. 또한 경기도 도정자문위원회에 대한 정책, 주요현안 점검 지원을 위해서 생활밀착형 및 문제해결형 정책기획 확대에 기여하고 있습니다. 또한 도민이 참여하는 다양한 아이디어나 연구 이슈를 발굴하기 위해서 도민이 참여하는 도민을 위한 연구라는 의미로 도도한 연구 공모전을 추진해 왔습니다. 경기도민을 대상으로 새로운 경기도를 만들 수 있는 연구 아이디어를 공모하고 연구과제로 발전시켜 활용함으로써 도민체감형 정책 발굴, 현장밀착형 연구수행 등을 목표로 하고 있습니다. 올해는 공모전 결과 연구 아이디어 부문에 6건, 위탁연구과제 부문에 5건의 우수 아이디어를 선정하고 관련 연구를 수행하고 있습니다. 
</p>
<p style="padding-left:1.2em">  8쪽을 보시면 거기에는 국내외 연구기관과 협력을 통한 공동연구에 관한 자료가 있습니다. 저희는 연구원 특성상 다양한 국내외 연구기관과 협력을 통한 공동연구를 추진하고 있는데 특히 국책, 지역 연구기관 등과의 협력을 통해서 융합연구 아니면 연구 네트워크를 강화하는 방안을 계속해서 추진해 왔습니다. 국책연구원, 시도 연구원, 국제기구와의 MOU를 통한 성과는 미래형 국토도시를 위한 국토계획법 개선방안, 버스 운전자 안전 운전 지원시스템 개발 등의 과제로 진행하고 있습니다. 이외에도 정책세미나 등 대외협력 사업을 지속적으로 추진하고 있습니다. 올해에는 경기도 인구정책토론회 등 12건의 세미나를 개최해서 핵심현안 및 연구결과를 발표하고 여론을 선도하는 역할을 해 왔습니다. 또한 경기지방재정포럼 등 7개 포럼을 운영해서 실용적인 정책대안 제시 및 연구역량 강화에 노력하고 있습니다. 국내외 MOU 협약기관 등과의 포럼, 교류협력, 공공기관으로서의 사회적 책임 수행을 위해서 사회공헌 활동도 추가로 진행하고 있습니다. 대표적 기관으로는 서울과학기술대학교, 전국 시도 연구원 업무교류, 중국산동사회과학원과의 공동포럼 등등이 진행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  9쪽을 보시면 저희 연구원에서는 또한 경기도 내 각 기관의 정책연구 자료를 등록ㆍ조회하는 온라인 정책연구도서관을 플랫폼을 형성해서 운영하고 있으며 22년 945건을 게시하여 정책 공개를 통한 행정의 투명성, 연구수행 중복에 따른 예산 방지 등에 기여하기 위해 노력하고 있습니다. 동영상 제작, 시각화 등 2차 가공을 통해서 저희 연구원의 연구성과 홍보를 강화하고 도민과의 접점도 더 확대해 나가려고 노력 중에 있습니다. 22년에는 G퀴즈, 숏폼 등 콘텐츠를 7건 업로드했고 31건을 제작 중에 있습니다. 또한 22년에는 연구정보 블로그, 페이스북 운영 등 연구성과 확산을 인정받아 대한민국 SNS 대상 공공연구소 부문 최우수상을 수상하기도 하였습니다. 이외에도 연구에 필요한 공간정보 관리, 정보접근성 강화를 위한 홈페이지 개선 사업 등도 꾸준히 추진해 오고 있습니다.
</p>
<p style="padding-left:1.2em">  10쪽을 보시겠습니다. 공공투자관리센터를 통한 도 재정 효율화 지원에 대한 연구 부문입니다. 먼저 경기도에는 제1ㆍ2투자심사위원회가 있는데 그 위원회들이 심사 대상으로 하고 있는 다양한 사업, 올해 들어서는 대략 199건 정도 되는데 이들에 대한 사전분석 및 검토의견을 센터에서 제공하고 있습니다. 지방재정영향평가 사전검토도 하고 있는데 5건 정도로 수행을 하였고 이 내용 중에는 경기도 대규모 행사ㆍ축제ㆍ공모사업 등에 대한 사전분석 및 검토의견을 포함합니다. 또한 중앙투자심사 지원 사업으로 행안부에서 투자심사 대상 사업으로 하고 있는 내용들의 논리 개발, 데이터 등 필요한 자료를 지원해 오고 있습니다. 재정사업 평가로는 경기도 재정건전성 확보, 재원의 효율적 배분을 위하여 727건의 재정사업평가를 수행해 왔습니다. 민간투자사업 조사 및 지원 10건을 실시하여 타당성 분석, 적격성 조사, 사업제안서 평가, 자금조달 검토, 실시협약서 검토 등 협상을 지원하기도 합니다. 또한 공공투자사업 관련한 분석, 평가지침 개발, 방법론 등 연구소로서의 역할을 위한 지침 및 정책연구도 함께 병행 수행하고 있습니다.  
</p>
<p style="padding-left:1.2em">  다음 11쪽입니다. 의정연구교류도 저희 연구원의 연구사업 분야 중에 하나인데 경기도의회와의 정책소통 강화와 지역현안 해결방안 등을 모색하기 위해 의정포럼 및 지역현안토론회 등을 개최하고 있습니다. 경기도의회와의 정책교류 및 상호협력을 통한 생산적 의정지원을 위해서 2022년 의정포럼을 운영하고 있는데 위원님들도 아시다시피 의회와의 협력이 조금 미진해서 지금 현재 신임 의정포럼위원 구성을 하고 있는 중입니다.
</p>
<p style="padding-left:1.2em">  마지막으로 12쪽부터의 21년도 행정사무감사 조치결과는 우선 자료로 참조해 주시고 혹시 질문이나 확인사항 등이 필요하신 게 있으면 질의시간에 조금 더 상세하게 답변드리도록 하겠습니다. 이상으로 연구원의 주요업무보고를 모두 마치겠습니다. 경청해 주신 위원님들께 감사드립니다.
</p>
<p><hr /></p>
<p>업무보고서(경기연구원)
</p>
<p><hr /></p>
<p><b>○ 위원장 지미연 </b> 송미영 연구부원장 수고하셨습니다. 다음은 이태헌 수석전문위원 나오셔서 경기연구원의 2021년도 행정사무감사 지적사항 처리결과에 대해 검토보고해 주시기 바랍니다. 
</p>
<p><b>○ 수석전문위원 이태헌 </b> 수석전문위원 이태헌입니다. 경기연구원 소관 2021년도 행정사무감사 처리결과에 대하여 검토보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  배부해 드린 검토보고서 19쪽입니다. 경기연구원은 총 29건 가운데 시정요구사항은 1건이 완료, 처리요구사항은 3건이 완료, 추진 중은 2건, 건의사항는 21건이 완료입니다. 주요처리결과 내용으로는 첫째, 시정요구사항 중 경기연구원 공식 블로그가 9개월 이상 게재되지 않고 있는바 블로그에 올리는 관련 자료는 필요한 시기에 게재되어야 하는데 몰라서 못 올리는 것은 연구원 본연의 역할과 동떨어져 있는 부분이고 신뢰성이 떨어지게 되므로 시정하기 바란다는 내용에 대해서 체계적으로 자료를 관리하고 즉시 등록하는 등 블로그 관리를 철저히 하겠다고 하였는데 경기연구원 공식 블로그 외에도 공공투자관리센터 홈페이지 관리 운영 부실도 문제가 대두된 바 있어 도민들의 알권리를 위해 앞으로도 도민들이 체감할 수 있도록 경기연구원의 각별한 노력이 필요합니다. 
</p>
<p style="padding-left:1.2em">  둘째, 처리요구사항 중 공공투자관리센터에서 일몰사업이나 감액사업들을 평가할 때 기준들을 객관화하고 사업부서의 의견들을 충분히 반영하는 것이 필요하다는 지적에 대해서는 행정안전부 예규 제132호 지방자치단체 주요재정사업 평가기준과 경기도 재정사업 평가지표에 의거하여 평가하며 일몰ㆍ감액사업 평가안에 대해서는 사업부서 이의신청을 받는 절차를 두고 이의가 제기된 사업에 대해서는 다시 담당자 면담과 전문가 검토 그리고 예산담당관실 검토ㆍ확인 절차를 거치고 있으며 차년도 예산 반영을 목적으로 하는 평가인 만큼 객관성을 담보할 수 있도록 추진하고 있다고 하였는데 2022년 재정사업 평가 추진계획에 의하면 재정사업 평가의 자체 평가 및 전문가 평가 비중이 변경되었는데 전문가 평가의 비중이 40%에서 50%로 상향 조정됨에 따라 재정사업 평가의 객관성을 담보할 수 있도록 하여야 할 것입니다. 
</p>
<p style="padding-left:1.2em">  셋째, 건의사항 중 28개 시군에서 연구 수탁, 의뢰 등 적극적으로 자생력을 키워야 하고 수탁연구과제에 대해 적극적으로 경기연구원에서 대응할 수 있도록 하기 바란다는 내용에 대해서는 자체수입 증대 및 자생력 증진 방안으로 경기도와 시군, 공공기관 등에서 발주하는 수탁연구과제 학술연구용역 경쟁입찰에 적극적으로 참여하고 있고 연구원은 연구직의 수탁연구 참여 활성화를 위해 수탁과제 수행실적을 개인성과 평가에 반영하고 있으며 연구원 차원에서 입찰제안서 작성 등 행정업무를 적극 지원하는 등 입찰공모 독려를 위해 노력하고 있다고 하였는데 경기연구원에서 수탁연구과제를 다음 해로 이월하는 경우가 43% 증가했다는 지적에 따라 연구과제 이월 사유에 대한 분석과 함께 이를 개선할 수 있는 방안을 마련해야 할 것입니다. 한편 연구원들의 수탁연구 참여 활성화로 연구원들의 활발한 연구활동을 도모할 수는 있겠으나 이로 인해 자칫 본연의 연구과제 수행에 지장을 받게 되어서는 안 될 것입니다.
</p>
<p style="padding-left:1.2em">  다음 인구 50만 이상인 시에서 시군 연구원이 설립될 예정인데 이러한 흐름에 맞춰서 경기연구원에서도 적절한 대응방안을 마련하는 것이 필요하다는 내용에 대해서는 인구 100만 이상의 수원, 고양, 용인 등의 시군 연구원과 활발하게 교류를 하고 있으며 향후 설립될 50만 이상 시군 연구원과도 교류를 활성화하여 시군 간에 발생할 수 있는 갈등문제 해소, 권역별 발전방안 구상 등 경기도가 종합연구원으로서의 역할을 수행할 계획이라고 하였는데 시군 연구원의 설립으로 경기연구원의 해당 지역에 대한 정책이나 사업을 추진함에 있어 시군 연구원의 역할이 더 중요해질 수 있다는 지적이 일부 언론 등에서 제기된바, 향후 경기연구원의 역할과 지위를 재정립하여 경기도가 주도적으로 시군과의 연계 정책 및 사업을 활성화해야 할 것입니다. 
</p>
<p style="padding-left:1.2em">  이상으로 2021년도 경기연구원 소관 행정사무감사 처리결과에 대한 검토보고를 마치며 기타 자세한 사항은 배부해 드린 검토보고서를 참고해 주시기 바랍니다.
</p>
<p><hr /></p>
<p>검토보고서(2021년도 행정사무감사 처리결과(경기연구원))
</p>
<p><hr /></p>
<p><b>○ 위원장 지미연 </b> 이태헌 수석전문위원 수고하셨습니다. 
</p>
<p style="padding-left:1.2em">  다음은 행정사무감사 질의 답변 순서입니다. 질의 답변은 계속해서 본질의는 10분 이내로 하고 보충질의는 5분 이내 일문일답 형식으로 진행하겠으며 추가질의는 별도 신청을 받아 진행하겠으니 위원님들의 많은 협조 부탁드립니다. 또한 위원님들의 질의사항 중 구체적이고 실무적인 내용에 대해서는 담당 부서장께서 답변하셔도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대로 나와 소속과 직ㆍ성명을 분명히 밝히고 답변을 해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  질의에 앞서 자료요청하실 위원께서는 거수로 신청해 주시기 바랍니다. 최민 위원 자료요청하시기 바랍니다.
</p>
<p><b>○ 최민 위원 </b> 최민 위원입니다. 지난 8월에 저한테 제출한 자료에 보면 최근 3년간 연구 결과의 정책 활용 실적에 대해 주신 게 있는데 구체적으로 정책 반영 내용들이 좀 너무 짧고 포괄적으로 쓰여 있어서 연구한 내용들이 많지만 그 부분 상세 자료를, 어떻게 정책에 반영됐는지 상세한 정책 반영 결과를 요청드립니다. 그리고 제가 양이 너무 많기 때문에 표시를 해 왔습니다. 표시를 해 왔으니까 제가 표시한 자료만 확보해서 주시면 감사하겠습니다.
</p>
<p><b>○ 위원장 지미연 </b> 최민 위원님 수고하셨습니다. 서정현 위원님 자료요청하시기 바랍니다.
</p>
<p><b>○ 서정현 위원 </b> 안산 서정현 위원입니다. 경기연구원 정관에서 정하고 있는 하위 별도 규정 그리고 지침 일체를 제출해 주시면 좋겠습니다. 규정집이 있다면 규정집을 제출해 주시고요. 규정집이 없다고 그러면 하위 규정에 있는 서식 부분은 제외를 하고 주셔도 괜찮을 것 같습니다. 그리고 경기연구원 등기사항전부증명서도 부탁드리고요. 그리고 경기연구원 육성기금 현황, 출연금 등 세부내역을 포함해서 제출 부탁드립니다. 그리고 감사 규정에 따른 정기감사 계획과 그에 따른 감사 결과, 계획 미이행 부분이 있다면 그 사유를 함께 기재해서 제출해 주시기 바라겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 지미연 </b> 서정현 위원님 수고하셨습니다. 이채명 위원님 자료요청하시기 바랍니다.
</p>
