<p><b>○ 정경자 위원 </b> 코인 채굴이라니요. 아니, 이거는 오늘 오전에 저희가 감사관도 했지만 경기연구원도 경기도의 싱크탱크 역할을 하셔야 됩니다. 하시는 겁니다. 그러니까 어떻게 보면 경기도의 부심을 가지고 있는 기관인데 어떻게 좀 더 강한 도덕적 잣대를 가지고 우리가 해야 되는 상황인데 그 직원 부서가 행정직입니까, 연구직입니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 정보전산직입니다.
</p>
<p><b>○ 정경자 위원 </b> 언제 임용됐습니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 2021년 11월에 아마…….
</p>
<p><b>○ 정경자 위원 </b> 21년?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 21년 11월 1일에 채용된 직원입니다.
</p>
<p><b>○ 정경자 위원 </b> 얼마 되지 않았네요. 얼마나 이 경기연구원을 우습게 알았으면, 어떻게 보면 임용된 지 얼마 안 된 직원이 세상에 근무시간에 코인을 채굴한다고요? 너무너무 부끄러워서 얼굴을 들 수가 없어요. 경기도에서 경기도 직원이 이랬다는 사실이 너무 부끄러운 일입니다. 얼마나 관리가 태만했으면 이렇게 됐을까요? 거기다가 봤더니 채굴을 통해서 얻은 수익이 16만 5,600원이고 채굴하기 위한 전기사용료가 5만 208원이기 때문에 절도죄로 해서 이 부분에 대해 했다고. 이거는 절도죄 문제를 떠나서 봤더니 수원지검에 송치는 됐는데 지금 자체적으로는 보니까 감봉처분이요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 정경자 위원 </b> 지금 제가 직원 징계 및 소청 규정을 봤더니 3조에 징계의 종류를 봤더니 중징계와 경징계가 있네요. 
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 있습니다.
</p>
<p><b>○ 정경자 위원 </b> 중징계는 파면, 해임, 강등, 정직이 있고 경징계는 감봉, 견책입니다. 그러니까 근무시간에 코인 채굴이라는 말도 안 되는 행위를 했는데 이 부분이 감봉처분이요? 경징계네요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 그렇게 처리를 저희가 했습니다.
</p>
<p><b>○ 정경자 위원 </b> 이게 경징계 수준이라고 생각하시는 거예요, 스스로?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 저도 그렇게 생각하지는 않습니다. 그리고 코인 관련한 이런 행위를 한 것에 대해서는 저도…….
</p>
<p><b>○ 정경자 위원 </b> 이 근무태만에 대해서 너무 안일하게 생각하시는 것 같습니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 어떤 질책을 하셔도 제가 드릴 말씀이 없습니다.
</p>
<p><b>○ 정경자 위원 </b> 그리고 저는 좀 그때 생각을 했는데 위원장님과도 얘기했지만 이거는 직위해제가 없어요, 징계 거기서. 이거는 지금 당연히 업무에서 배제해야 되는 거 아닙니까, 이런 상황이면? 어떻게 보면 옆에 있는 동료들한테는 사기저하 수준입니다. 이거는 말이 안 되는 거죠. 그런데 감봉처분으로 끝나버리고 자연 퇴직처리를 해 버렸네요. 좀 이런 부분은 나중에 관련 규정을 손을 봐야 될 것 같습니다. 직위해제라는 것 자체가 없어요. 
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 말씀 다 마치시고 나면 답변하겠습니다.
</p>
<p><b>○ 정경자 위원 </b> 그리고 또 한 가지 경기연구원 정관에 보면 제3장에서 제16조 원장은 공개모집을 통한 경쟁의 방식으로 선발된 자에 한해서 이사회 의결을 거쳐서 이사장이 임명한다고 되어 있습니다, 그렇죠? 지금 연구원에는 이사장 1명과 원장 1명을 포함해서 30명 이내의 이사와 감사 2명 등의 임원을 둔다고 하는데 어떻게 보면 이사장과 원장은 서로 견제와 균형을 하기 위해서 하는 그런 관계이지 않습니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 그렇게 보실 수도 있습니다.
</p>
<p><b>○ 정경자 위원 </b> 그런데 지금 원장을 이사회 의결을 거쳐 이사장이 임명을 하네요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 현재 규정은 그렇게 되어 있습니다.
</p>
<p><b>○ 정경자 위원 </b> 네, 그러니까요. 저는 그래서 이 부분이 조금 약간 의아스러워서 제가 질의하는 겁니다. 그리고 또 원장이 궐위됐을 때 이사장 또는 이사장이 지명한 인사가 직무를 대행한다. 그러면 이거는 서로 견제, 균형 개념이 아니지 않습니까? 말씀하세요.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 앞의 건부터 먼저 말씀드릴까요, 코인 건부터?
</p>
<p><b>○ 정경자 위원 </b> 네.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 코인을 하고 있는 것을 저희가 발견한 것도 사실 내부 직원이 내부고발을 해서 저희도 알게 됐고 그 과정에서 그 직원에 대해서 사실확인을 하고 사실확인과 관련된 처벌을 결정하는 과정 중에 말씀하신 것처럼 저희도 이런 일이 처음이고 그다음에 이분하고 사실확인을 하는 과정에서 이분이 계속 그게 아니라고 자꾸 주장을 하시고 그래서 사실관계의 충돌이 있었습니다. 그래서 한 한 달 정도 이 사람이 말하는 것을 저희가 추적하기 위해서 카드지갑 그런 것을 제출해라 아니면 그걸 추적할 수 있는 방법에 대해서 저희가 형사적으로 뭘 해야 되는지 법률자문도 받아보고 하느라고 한 달이 걸렸고 그 당시에는…….
</p>
<p><b>○ 정경자 위원 </b> 잠시만요, 그럼 내부고발을, 저는 지금 외부고발이라고 여기 있어 가지고 외부고발로 생각했는데 내부고발이면…….
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 내부고발로 시작된 일입니다.
</p>
<p><b>○ 정경자 위원 </b> 그러면 동료이지 않습니까? 한 달 동안 계속 그러면 고발하고, 그러니까 고발당하신 사람하고 같이 지금 한 공간에서 근무하고 있었다는 거였네요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 부서는 달랐지만 같이 근무하고 있었습니다.
</p>
<p><b>○ 정경자 위원 </b> 그러면 이 부분 위험하죠. 내부고발하신 분은 좌불안석, 뭔가 불안하지 않겠습니까? 그런 사람이 당연히 지금 있는 사람, 도대체 누가 나를 고발했을까 생각하지 않을까요? 누구나 100이면 100 전부 다 그렇게 생각하고 누구일까 하고 찾아다니지 않을까요? 그러면 내부고발한 사람은 너무너무 불안하겠죠.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 내부고발하신 분은 충분히 보호조치를 저희는 했다고 생각하는데 아마 불안한 마음은 있으셨을 겁니다.
</p>
<p><b>○ 정경자 위원 </b> 당연하죠. 말씀하세요.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그래서 법률적인 자문을 받고 확인을 하는 과정에서 실랑이가 상당히 있었고요. 이 직원이 저희가 요구하는 것에 이렇게 순순히 응하지 않은 측면도 있었습니다. 그리고 빅데이터를 조사하는 과정에 연구하는 거였다는 둥 이런 여러 소리를 해서 그거를 정리하는 과정이 저희가 좀 오래 걸렸고 그다음에 법률적인 자문의 결과를 받을 때 첫 번째 자문에서는 이게 특별히, 그러니까 아주 심각한 중징계를 내릴 정도의 것이 아니라는 법률자문이 한 번 있었고 그것을 저희가 다시 한번 의견을 물었더니 거기에서 고발이나 이런 걸 할 수 있는 혐의가 있다고 해서 그걸 결정하는 데에 한 달이 걸렸습니다. 그리고 이게 절도죄냐 아니냐 이런 것들도 저도 사실은 처음해 보는 거라서 그런 점이 있었는데…….
</p>
<p><b>○ 정경자 위원 </b> 시간이 없기 때문에 나중에…….
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그래서 다음번에는 저희가 만약에 이런 똑같은 일을 한다면…….
</p>
<p><b>○ 정경자 위원 </b> 있으면 안 되죠. 절대로 안 되죠.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 있으면 안 되죠.
</p>
<p><b>○ 정경자 위원 </b> 그래서 저는 이 부분에 있어서 절대로, 시간이 없기 때문에 제가 그냥 말하고 가겠습니다. 그래서 이 부분에 있어서 아까도 말씀드렸지만 관련 규정에서 직위해제 부분이 없는 부분은 좀 짚고 갔으면 좋겠습니다. 그래서 이 부분은…….
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 말씀해 주시면 저희가 고려하겠습니다.
</p>
<p><b>○ 정경자 위원 </b> 나중에 좀 바꿨으면 좋겠고요. 그래서 어쨌든 다시는 이러지 않도록 좀, 아까도 말씀드렸지만 좀 더 엄중한 도덕적 잣대를 가지고 했으면 좋을 것 같고요. 그러니까 이런 일이 다시는 발생하지 않도록 내부기강을 좀 더 확실하게 했으면 좋을 것 같습니다. 이상입니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 말씀하신 거하고 연관해서 저희가 유해사이트 차단을 사실은 연구기관이어서 안 하고 있었는데 그 부분도 도박이나 증권, 코인 관련한 것은 다 유해사이트 차단 조치를 했고 그다음에 이분한테도 저희가 추가적인 중징계를 하려고 했는데 이게 근로기준법에 감봉의 기준이 어떤 기준 이상은 할 수가 없다는 법률자문이 있어서 저희가 감봉처분을 했는데 이분이 저희가 이런 조사를 하고 본인을 압박하니까 그 사이에 이직할 준비를 아마 했던 모양입니다. 그래서 이직을 하게 돼서 저희가 사실은 감봉처리도 3개월을 했는데 한 달밖에 못 했습니다. 그런데 그다음에 말씀하신 대로 직원들한테 교육이나 여러 차례 간부회의를 통해서 이런 일이 절대 있어서는 안 되고 그런 것을 원천적으로 차단하는 유해사이트 차단 절차도 다 밟았습니다. 어쨌든 말씀하신 점은 저희 연구원에서 정말 죄송하게 생각하고 더 이상 드릴 말씀이 없다는 점을 다시 한번 말씀드립니다. 그다음에 이후의 직위해제 조치 등 저희가 필요한 강화조치는 충분히 하고 일정 기간 정기적으로 직원들이 어떤 사이트에 접속하는지도 모니터링하는 그런 절차를 밟을 계획입니다.
</p>
<p style="padding-left:2.4em">    (지미연 위원장, 이동현 부위원장과 사회교대)
</p>
<p><b>○ 부위원장 이동현 </b> 정경자 위원님, 충분히 질문, 보충질의, 추가질의 때 해 주시고요. 그거 관련해서는 아마 다른 위원님들 추가질의를 계속하실 테니까 성실하게 답변해 주시고 다음은 최민 위원님 질의해 주시겠습니다.
</p>
<p><b>○ 최민 위원 </b> 광명 출신 최민 위원입니다. 송미영 부원장님과 임직원 여러분, 행감 준비로 너무 고생하셨습니다. 일단 제 질의에 앞서서 방금 존경하는 정경자 위원님이 말씀하신 그 건 한번 여쭤보면 수사 의뢰를 하시지 왜 직접 수사에 대한 공부를 하시고 법률자문을 구하셨나요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 수사 의뢰를 하기 위해서 저희가 알아본 거죠. 저도 경험이 없다 보니 법률자문을 받아서 이게 어떤 프로세스를 하는 것이 적절한지 저도  처음이다 보니 알아보고 그거에 관련된 프로세스를 한 겁니다. 그게 조금 미진하거나 미흡했던 점도 있습니다.
</p>
<p><b>○ 최민 위원 </b> 알겠습니다. 일단 제 질의를 시작하겠습니다. 경기연구원의 연구성과 핵심 지표는 저는 정책이 실제로 현장에서 반영되는 비율과 미래의 정책개발에 얼마나 연구원이 능동적으로 접근하고 있는지 여부가 저는 연구원을 평가하는 핵심 지표라고 보는데요. 지난 8월 업무보고 질의 때, 한 3개월 됐죠? 제가 몇 가지 요청드렸던 것들이 있는데 기억하시나요, 내용을?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 일단 말씀해 주시면 제가…….
</p>
<p><b>○ 최민 위원 </b> 그러실 것 같았어요. 중요한 건 뭐냐면 의회에서 하는 모든 내용들은 다 기록화됩니다. 그리고 여기서 말하는 것들은 저희 사적인 대화가 아니고요. 도민들을 대표해서 기관과 토론하고 필요하면 정책 제언하는 그런 귀한 자리예요. 부원장님께서는 이런 상임위도 기회가 많지 않잖아요. 상세하게 검토하고 와주세요, 항상. 그러니까 제가 그 당시에 말씀드렸던 것은 민선8기 도정 주요과제에 맞춘 연구계획들 속히 수립해 달라. 원장이 있든 없든 부원장이 직무대행을 하고 있으니 그 내용도 충분히 가능할 거고 백서나 인수위 이후에 도정 과제가 특정됐기 때문에 그 내용들을 빨리 조속히 수립해 달라고 했는데 했나요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 말씀하셨습니다.
</p>
<p><b>○ 최민 위원 </b> 했나요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 저희가요?
</p>
<p><b>○ 최민 위원 </b> 맞춤 연구계획을 수립하셨어요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 수립하고 있습니다.
</p>
<p><b>○ 최민 위원 </b> 수립하고 있나요? 그리고 제가 추가적으로 그 당시에 수해가 발생했었는데 재난안전망 구축에 대한 여러 가지 내용들을 이야기했었어요. 기억하시죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 최민 위원 </b> 그 두 가지 내용에 대한 연구계획을 수립해 달라고 요청했는데 재난안전망 구축에 대한 내용도 연구계획이나 혹시 기이 착수된 연구들이 있나요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그거는 아직 저희가 못 하고 있는데 저희 원래 안전 분야 연구원이 있었는데 그분이 이직을 하셔서 저희가 이 부분은 지금 추가로 어떻게 처리할지를 의논 중에 있습니다.
</p>
<p><b>○ 최민 위원 </b> 경기도정에서 운영하는 연구원이 제가 저번에 업무보고 때도 말씀을 드렸는데 그 당시에는 수해 피해 제가 얘기를 하니까 토목 관련된 인원이 없다고 말씀하셨고 오늘은 또 재난에 관련된, 재난과 안전에 관련된 직원이 퇴사를 해서라고 말씀을 하시면 이건 진짜 문제 있는 거 아니에요, 부원장님?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그러니까 여건은 그런데 필요한 계획은 저희가 수립하도록 하겠습니다.
</p>
<p><b>○ 최민 위원 </b> 행정감사는 정말 행정사무가 잘 이루어졌는지 감사하는 자리입니다. 서로 정책 고견이 오가고 향후에 그렇게 하겠습니다로 넘어갈 수 있는 자리가 아니에요. 이미 업무보고 3개월 전에, 100일도 전에 제가 말씀드린 거예요. 그런데 아직도 그런 답변을 주시면 좀 그렇습니다. 일단 전략정책부를 보니까 도의회의 정책개발 및 지원, 주요도정의 과제 연구, 미래정책 선제 대응 등 제가 연구원에 요청하고 싶은 내용이 정확하게 기술돼 있어요. 그런데도 앞서 질문한 내용에는 이제서 방안들을 마련해 가겠다는 답변을 주셨습니다. 이 부분에서 반드시 시정이 필요할 것 같고요. 
</p>
<p style="padding-left:1.2em">  서울연구원을 보면 서울연구원은 2020년 발간한 신종 대형 도시재난 전망과 정책 방향에서 세월호 참사나 메르스 대유행, 경주 지진 등과 같이 예측 범위를 벗어난 신종 재난에 대한 정책적 대응 필요성에 대한 연구결과를 내놓았어요. 이 내용에서는 다중 안전사고 등이 분석돼 있고 고밀 사회에서 축제와 공연, 경기, 집회 등이 크게 늘어나면서 압사사고의 발생 잠재성도 커진다고 발표한 바 있습니다. 이런 연구들을 우리가 해야 된다는 거예요. 이태원 참사를 겪으셨잖아요. 이런 연구자료가 있음에도 불구하고 서울에서 발생했어요, 그 사고가. 그래서 제가 정책반영 비율 이것들이 너무 중요하다는 거예요. 연구하고 학술지로 발표되는 것이 중요한 것이 아니라 실제로 우리 도정의 가장 핵심 브레인인 우리 연구원에서 연구한 내용들이 도정의 다양한 정책 개선으로 와야 되기 때문에 제가 자료요구도 그렇게 했던 거예요. 근데 자료요구 답변들을 보니까, 한번 보세요, 부원장님이 가셔서. 저한테 8월에 답변했던 내용들. 서면으로 주셨습니다. 전산 자료로 주지도 않았어요. 메일도 준 게 아니고 그냥 다가오셔서 우리 직원들한테 서면자료 주고 가셨어요. 다음부터는 모든 게 자료유통시스템으로 보고되길 바라고요. 
</p>
<p style="padding-left:1.2em">  일단은 최근 3년간 경기연구원 연구결과의 정책 반영률을 보니까 2018년도 96.4%, 2019년도 95.7%, 2020년도 88.4% 매우 높습니다. 매우 높아요. 근데 매년 줄고 있어요, 정책 반영률이. 물론 코로나 등으로 정책을 실행하기가 좀 어려운 국면이 있지만 정책 반영률 개선이 좀 필요해 보이는데 2021년도는 어느 정도였고 2022년도 금년 목표치는 어느 정도 되나요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 저희가 사실 목표치는 설정하고 있지 않고 최대한 반영될 수 있도록 하는 시스템으로 하고 있습니다.
</p>
<p><b>○ 최민 위원 </b> 그런 것 같았습니다. 자료를 보니까 반영 내용에 구체적인 내용을 달라고 하니까 무슨 내용이냐면 기초자료로 검토됐다, 정책 방향 설정에 활용된 바 있다, 청년농부 육성 활성화에 일부 기여한 바 있다, 재난안전서비스 확대에 기여한 바 있다. 아주 포괄적인 언어로 분석이 돼 있습니다. 이게 정책에 반영된 겁니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 위원님들이 생각하시기에는 부족한 점이 있을 겁니다.
</p>
<p><b>○ 최민 위원 </b> 위원님들이 생각하시기에 부족한 것이 아니라 도민들이 생각하기에 부족한 거예요.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 그렇죠.
</p>
<p><b>○ 최민 위원 </b> 정책이 됐다, 안 됐다를 구분하는 판단 기준이 매우 명확해야 됩니다. 인용돼서 정책에 투입돼서 A를 인용했으면 A-가 나왔다는 등, 법제나 법령들의 개선 요구를 했는데 실제로 입법화했다는 등 이런 것들이 구체적으로 분석이 돼야 경기연구원의 효용을 확인할 수 있는 거예요. 어떻게 생각하세요, 부원장님?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 입법자료를 개정하거나 법률 개정하는 말씀하신 것 같은 것은 저희가 명확히 했고 그다음에 저희 연구 중에 상당 부분은 기초연구라든가 아니면 앞으로 해야 될 연구를 하는 연구 분야가 있기 때문에 그 분야에 대한 답변이 아마 그렇게 비춰졌을 겁니다.
</p>
<p><b>○ 최민 위원 </b> 아니, 그렇지 않습니다. 저한테 수백 건의 정책 반영률 내용을 주셨는데 이 정도 % 나올 수밖에 없어요. 95%, 96%. 그거는 그냥 기여한 바 있다. 그건 다시 한번 생각해 볼 필요가 있습니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 저희도 고민을 해 보겠습니다.
</p>
<p><b>○ 최민 위원 </b> 네, 사실 저는 경기연구원은 매우 우수한 조직이라고 생각해요. 그리고 굉장히 자부심도 있고. 제가 경기도의원으로서 경기연구원의 자료들을 항상 보고 제가 그전에는 입법부 관련 실무자로서 경기연구원의 자료들을 항상 검토했었는데 그러면 그만큼 사실 우리가 이제는 100만 인구 도시의 연구원을 넘어서서 이번에 성남, 화성, 부천, 남양주, 안산, 안양, 평택, 시흥과 같이 50만 인구 이상의 연구원들도 생길 텐데 거의 모 법인처럼 정말 경기원구원이 어떤 기준이 되어줄 필요가 있다. 그러기 위해서는 이런 지표들, 반영률에 대한 평가들을 아주 구체화된 지표로 관리할 필요가 있습니다. 그래야 예를 들면 부천연구원을 만들더라도 거기서 여기의 경영 실적이나 혹은 연구 실적이나 이런 것들을 벤치마킹하지 않겠습니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그러겠습니다. 저도 동의합니다.
</p>
<p><b>○ 최민 위원 </b> 시간이 얼마 없어서 좀 빨리 말씀드리면 최근에 제가 경기 남북 간 산업단지 불균형 해소해야 한다는 기조의 경기연구원 자료를 봤어요. 경기도 산업단지 생산성 및 효율성 분석 그 내용 아세요, 혹시?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 상세 내용까지는 모르지만 제목은 압니다.
</p>
<p><b>○ 최민 위원 </b> 제목처럼 북부산단과 남부산단의 비율을 구분하고 효율성을 비교하고 북부산단이 좀 더 치중해야 될 방향성을 제시한 거예요. 연구자료를 보면 아쉬웠던 것은 도정 현안의 분석은 매우 구체적으로 돼 있어요. 사실 이거는 담당 부서에서 받아도 저도 작성할 수 있는 어떤 수준인데 제가 원하는 것은 솔루션이에요. 이런 것들의 정말 대안 제시가 필요한데 대안 제시가 있긴 있어요. 있긴 있는데 그런 제도적인 어떤 정책적인 변화에 대한 구체화된 내용도 필요한데 그런 게 좀 부족하더라고요. 그래서 향후에 다양한 자료들을 발간하실 텐데 그때마다 대안 제시, 특히 정책을 입안하고 의사결정을 할 수 있는 사람들이 참고하고 반영할 수 있게끔 주시면 아까 말씀드린 정책 반영률이 훨씬 더 좋아질 거라고 생각합니다. 이미 잘하고 계시지만 더 잘하라는 의미에서 제가 질의드렸습니다. 감사합니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 답변을 잠깐만 드려도 될까요?
</p>
<p><b>○ 최민 위원 </b> 네, 말씀하세요.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 저희가 정책 반영률을 결정하는 여러 가지 유형이 있는데 그중에 법령 제ㆍ개정 아까 말씀하신 것하고 정책 수립 그다음에 제도 개선한 거가 하나의 카테고리고 다른 것은 또 도정 사업 개발이나 기본계획 수립하는 것 법정계획이죠, 그런 내용이 있고. 또 도의 정책 판단의 근거나 현안 해결을 지원해 주는 그런 유형이 있습니다. 그리고 정책 홍보나 참고 자료 같은 것을 저희가 생산하는 그런 유형으로 하고 있는데…….
</p>
<p><b>○ 최민 위원 </b> 그러면 그런 유형들이 있으면 아까 제가 감사 개의하기 전에 자료요구한 거 있잖아요. 표시를 다 해 드렸으니까 그 해당 연구실적이 어떤 유형에 맞게 정책에 반영된 건지를 분류해서 표현해 주세요, 자료로.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그렇게 해서 답변드리도록 하겠습니다.
</p>
<p><b>○ 최민 위원 </b> 종합감사 전에 꼭 주시길 부탁드립니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그렇게 준비하겠습니다.
</p>
<p><b>○ 최민 위원 </b> 이상입니다.
</p>
<p><b>○ 부위원장 이동현 </b> 최민 위원님 수고하셨습니다. 위원님들 양해해 주시면 부원장님 계속 서서 질의응답 받으시면 자료 받으시는 거나 또 다른 부장님들에게 질문, 센터장님에게 질문할 때 불편하니까 양해해 주시면 자리에 앉아서 답변하도록 하겠습니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 감사합니다.
</p>
<p><b>○ 부위원장 이동현 </b> 자리에 앉아주셔도 됩니다. 다음은 서정현 위원님 질의해 주시겠습니다.
</p>
<p><b>○ 서정현 위원 </b> 안산 서정현 위원입니다. 먼저 공공감사에 관한 법률 적용 관련해서 질의와 건의, 시정요구를 좀 드릴게요. 저희 행정사무감사 자료제출 요구한 것에 대한 회신을 보면 경기연구원이 공공감사에 관한 법률 적용 대상 기관이 아니라는 취지로 회신을 하고 계시고 그 판단 근거를 고문변호사 자문 의견에 기초를 하고 계세요. 그렇죠? 그런데 이게 변호사 자문 외에 다른 근거가 혹시 있나요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 질의를 계속해 주시면 안 되겠습니까? 찾아보겠습니다.
</p>
<p><b>○ 서정현 위원 </b> 본 위원이 자문서 내용, 자문 외에는 다른 근거가 있는 것 같지가 않아서 질의를 드렸고요. 혹시나 있으신가 해서 여쭤봤습니다. 본 위원이 자문서 내용도 검토를 해 보고 그리고 법령도 모두 검토를 해 봤는데요. 물론 이 자문서 내용이 일응 타당한 부분도 있습니다. 그러나 쟁점 사항과 관련해서는 이견이 있을 수 있는 부분 또한 있는 것 같아요. 전반적으로 일응 타당한 부분이 있다라는 거는 저도 충분히 공감을 하는데 쟁점과 관련해서 이견이 있을 수 있다. 그래서 이 부분에 대한 의문의 해소는 좀 필요하지 않을까 싶습니다. 그래서 이 부분을 변호사 자문에만 의존하지 않고 같은 결과가 나오더라도 법제처든 감사원이든 통해서 검토의견을 공식적으로 받으셔서 그것을 근거로 해서 업무처리가 이루어지면 좋겠다. 그 부분의 시정을 요구드립니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 말씀하신 대로 검토해 보겠습니다.
</p>
<p><b>○ 서정현 위원 </b> 그리고 두 번째 질의드리겠습니다. 주신 자료 231페이지 제가 페이지를 특정해 드리겠습니다. 국민권익위원회 제도 개선 권고 관련한 부분인데요. 대부분 이행이 되었습니다만 불이행된 몇 가지가 있어요. 그리고 불이행 사유로 기재해 주신 것 보면 성과급 지급 방법 개선 계획, 계획은 수립하였지만 노동조합과 합의가 되지 않았다. 이 부분이 조합과의 협의가 필요한 부분인지 여하를 떠나서 이 부분은 불이행 사유라고 이해는 됩니다. 그러나 나머지 부분 추진 예정으로 표시한 부분은 왜 지금 이게 개선이 안 되고 있는지를 알 수가 없습니다. 그리고 지금 추진 중인지 추진을 안 하고 있는데 할 것이라는 건지 그 부분 또한 판단하기가 조금 어렵습니다. 나아가서 저희가 자료 제출 요구를 드렸던 부분은 2017년부터 2021년까지 무려 5개년 동안의 제도 개선 권고 사항들에 대한 이행 여부인데 일자도 특정이 되어 있지 않아요, 시기 또한. 그러다 보니 개선 의지나 개선 현황이나 이런 부분들을 저희 의회에서 판단하기가 조금 어려운 부분이 있는 것 같습니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그러네요. 자료에서 저희가 부족한 부분은 더 보완해서 제출하도록 하겠습니다.
</p>
<p><b>○ 서정현 위원 </b> 앞에 이행 완료된 부분에 보면 정관이나 규정을 간단하게 개정하는 것으로 이행을 완료하신 부분들도 있어서 지금 추진 예정이라고 하는 사항들 중에서도 간단하게 규정 개정으로 가능한 부분들도 있을 것이라고 본 위원이 생각이 되고요. 그래서 이 부분 국민권익위원회 제도 개선 권고와 관련해서 권고 시점이 언제인지를 정확하게 특정을 해서 언제까지 어떻게 추진할 것인지 구체적인 계획을 수립하셔서 이행도 하셔야 되고 그 계획과 이행 결과를 저희 의회에 보고해 주시면 감사하겠습니다. 그렇게 좀 시정요구를 드리고요.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 말씀하신 거를 저희가 별도로 보고를 드리거나 자료 준비되는 대로 말씀드리도록 하겠습니다, 상세한 내용을.
</p>
<p><b>○ 서정현 위원 </b> 잘 알겠습니다. 그리고 제가 아까 시작하면서 관련 규정을 요청드렸는데 규정을 보면 조금 해결이 될 것 같은 부분이긴 합니다만 아직 규정이 안 와서 그냥 질의 순서가 돼서 질의로 제가 먼저 드릴게요.
