<p><b>○ 서정현 위원 </b> 해외연수 후에 퇴직 이후에 재취업하시는 것 관련해서 왜냐하면 어쨌든 해외연수가 우리 도민의 혈세로 운영되는 것이니까요. 그런 부분에 대해서는 우리 연구원 차원에서 검토가 필요하지 않을까 합니다. 반드시 조금 확인해 주십시오.
