<p><b>○ 서정현 위원 </b> 네, 잘 알겠습니다. 그런데 이게 그런 사례가, 아까 채굴 관련해서 제가 질의는 안 드립니다만 있으면 안 되는 사례인데 발생했지 않습니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 말씀하신 대로 예방 차원에서 말씀하신 내용을 검토해서 만들도록 하겠습니다.
</p>
<p><b>○ 서정현 위원 </b> 그런 문제가 있을 수 있으니 검토를 해 주십시오. 그리고 273페이지 제가 보다 보니까 재임용 관련해서 소송 중인 사건이 하나 있더라고요. 그냥 이건 단순한 호기심인데 이분 계약기간 만료 전에 업무능력 강화 조치는 있었나요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 여러 차례 권고도 드리고 그다음에 원장님을 통해서 다른 연구트랙 같은 것을 조금 조정해서 제안도 해 보고 했는데 잘 이행이 안 됐습니다. 
</p>
<p><b>○ 서정현 위원 </b> 아, 그래요? 제가 이 부분 재임용 거부하신 이 판단 부분에 대해서 문제 제기를 하거나 의문을 갖는 건 아니고요. 제가 이 부분에 대해서 의문이 들어서 확인을 해 보니까 변호사 자문도 받으셨더라고요. 
