<p><b>○ 경기연구원장직무대행 송미영 </b> 이분이 다시 재계약이 안 되셔서 연구원을 떠나셨는데 떠나시고 나서 소송을 제기하셔서 그 관련된 자문을 받는 내용입니다.
</p>
<p><b>○ 서정현 위원 </b> 지금 제가 자문서도 읽어보고 했는데 변호사 자문 시점이 2020년 1월 28일 자 그리고 재임용 관련 심의위원회 심의가 있었던 게 2021년 2월 23일 자더라고요. 심의위원회가 열리기 1년 전에 이 자문을 받으셨더라고요.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그때는 제가 날짜가…….
</p>
<p><b>○ 서정현 위원 </b> 그래서 제가 질문을 쭉 드릴게요. 그래서 제가 이 부분에 의문을 가졌던 부분은 재임용 거부와 직접적인 것이 아니라 이게 자문 결과를 받고 나서, 그러니까 심의위원회 있기 전에 자문 결과를 받고 심의위원회가 있었는데 이미 심의위원회 전에 재임용 거부를 예정을 하고 있었던 것 아닌가 하는 의문이 들었어요. 그 말인 즉 과연 이 심의위원회가 그렇다면 독립적으로 정상적으로 이렇게 작동하고 있는가에 대한 의문으로 귀결이 되는 겁니다. 그래서 이 심의위원회 위원분들의 명단을 보니 다 또 내부, 연구원님들을 비롯한 내부 위원들만 있어요. 그리고 제가 이 규정을 아직 못 받아봤습니다만 이 심의위원회가 우리 연구원의 인사ㆍ복무 등과 관련된, 이런 재임용과 관련된 사안들을 집중해서 심의하는 것으로 보여집니다, 맞죠? 심의위원회에서 대부분 이루어지죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 심의위원회에서 이루어집니다.
</p>
<p><b>○ 서정현 위원 </b> 그렇습니다. 그래서 제 생각에는 이 위원회가 견제와 감시가 조금 작동할 수 있도록 그런 장치가 좀 있어야 될 것 같습니다. 그게 반드시 외부 위원, 보통은 외부 위원을 포함시키는 경우가 일반적인데요. 그것도 또 하나의 방법일 것이고 심의위원회가 심의하고 의결하는 사항들이 굉장히 독립성이 요구되고 그리고 견제와 균형이 필요한 영역들이 많으니까 심의위원회 구성의 다변화라든가 이 독립성을 조금 강화할 수 있는 방안을 모색해 주시면 좋겠다 하는 말씀을 드립니다. 이상입니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 제가 이제 답변드려도 될까요?
</p>
<p><b>○ 서정현 위원 </b> 네, 말씀하십시오.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 저희 연구원에서 사실 3년 연속 최하등급 평가를 받은 분이 이분이 처음이었습니다, 저희가 25년 정도 됐는데. 그리고 연속 3회 최하등급을 받게 될 때까지는 연구원 내에서 여러 가지 자정작용이나 아니면 연구의 양, 질 관련한 모든 것들을 조금이라도 개선하기 위한 상호 노력이 항상 있습니다. 그런데 연구원의 특성상 전문가 집단이다 보니 각자 자기가 생각하는 방식, 연구의 방향 그다음에 연구하는 여러 가지 제반여건에 대해서 이견이 상충되면 이런 부분을 조정하기 어려운 점이 있습니다. 그래서 말씀하신 것처럼 이 부분은 아주 저희 연구원 역사 전체에서는 굉장히 특이한 사례이고요. 그래서 그런 점에서 저희가 심의위원회에서 이걸 신중하지 않게 검토를 했거나 충분한 고려가 없지는 않았다는 것을 말씀드리고 대신 말씀하신 것처럼 어떤 한 사람의 인사 아니면 해고와 관련된 일이기 때문에 말씀하신 외부 위원이라든가 여러 가지 다른 조치에 대해서는 검토해 보도록 하겠습니다.
</p>
<p><b>○ 부위원장 이동현 </b> 서정현 위원님 수고하셨습니다. 다음은 박상현 위원님 질의해 주시겠습니다.
</p>
<p><b>○ 박상현 위원 </b> 박상현입니다. 일단 사실 경기연구원과 같이 전문 연구기관 같은 경우는 사실상 연구원들 자체가 굉장히 자부심으로 업무를 수행하기 때문에 청렴도라든지 업무수행 능력은 굉장히 높다라고 생각이 됩니다, 같은 연구자로서. 하지만 오늘 몇 가지 말씀드리는 거는 그래도 더욱더 발전하는 경기도연구원이 되기를 바라는 마음에 몇 가지 질문을 좀 드리겠습니다.
</p>
