<p><b>○ 박상현 위원 </b> 제가 마지막 코멘트 하나 드리면 우리나라에 국가과학기술개발인력원이라고 하는 정부 출연 연구소가 있어요. 거기에서는 장애인에 관련된 석박사분들을 지원해 주는 사업이 하나 있고요. 두 번째로는 국회의원인 최혜영 의원님 같은 경우에 장애인에 관련된 관리 리스트가 따로 있습니다, 석박사 고급. 그러니까 장애인에 관련돼서 관심 있는 국회의원이라든지 기관들과 연계를 해서 가급적 그분들에게 양질의 일자리를 줄 수 있는 그런 경기연구원이 되기를 바라는 마음입니다.
