<p><b>○ 경기연구원장직무대행 송미영 </b> 우선 여러 가지 저희 연구원의 운영에 대해서 관심을 가져 주시고 조언을 해 주셔서 감사합니다. 그런데 여러 가지 다른 의견들은 지적해 주신 대로 저희가 할 수 있는데 수탁과제 관련해서는 아까도 제가 말씀드렸지만 저희가 공공기관 그리고 저희의 관리부서가 있지 않습니까? 그래서 그 관리부서에서 수탁과제를 정말 늘리는 게 더 중요하다고 생각하면 아마 그런 정책적 판단을 할 것 같습니다. 그러면 저희가 더 늘릴 수가 있는데 지금 몇 년 사이에 도의 기조는 수탁과제보다는 시군 전략과제라 그래서 시군에서 그냥 요청을 하면 그걸 수탁과제 성격에 거의 가깝거나 그거를 대변할 수 있는 과제를 저희가 많이 해 주기를 원해서 그런 과제들을 주로 하고 있었습니다. 그러니까 저희도 박사님마다 연간 수행할 수 있는 과제의 최대 수가 정해져 있기 때문에 어떤 한쪽으로 과제를 많이 하다 보면 다른 과제는 수행할 여력이 부족합니다. 그래서 그런 측면에서 수탁과제를 그냥 일방적으로 그쪽만 너무 확대하기가 어려운 여건도 있다는 것을 제가 말씀드리고 수탁과제는 특히 발주부서에서 그 기간의 연장이라든가 이월에 대한 권한을 절대적으로 가지고 있습니다. 그래서 저희가 일방적으로 수탁과제를 늦게 하는 게 아니고 대부분의 경우에는 발주부서에서 법적인 협의과정이나 이행과정 아니면 뭔가를 조정하거나 확장해야 되거나 아니면 추가해야 되는 내용을 계속 저희한테 요구하시기 때문에 사실 저희가 과제를 완료를 못 하는 경우가 대부분입니다. 그래서 그 부분은 좀 이해를 해 주셨으면 합니다.
