<p><b>○ 재정지원부대리 민성원 </b> 안녕하세요? 경기연구원 재정지원부에서 일하고 있는 민성원 대리라고 합니다. 경기연구원의 지출시스템에 대해서 먼저 말씀드리기 전에 저희 경기연구원의 재정지원부에 입사하고 직을 맡게 되면 먼저 신용보증보험에 가입을 의무적으로 하게 되어 있습니다. 1차적으로 거기에서 보증보험 가입이 이루어지고 있고요. 그리고 저희가 부서 내에 직위와 별도로 회계관직을 운영하면서 지출원과 그리고 분임경리관을 각각 별도로 운영을 하고 있는데요. 일단 지출결의서 같은 경우에는 담당자 그리고 분임경리관의 결재를 먼저 맡은 후에 그리고 지출 시기에 또 다른 지출원이 결재를 하면서 일단 지출결의를 마치게 됩니다. 그리고 그 이후에는 지출시스템 그러니까 인터넷뱅킹 시스템이죠. 인터넷뱅킹 시스템에서 담당자가 또 결재를 올리면 그거를 다시 한번 지출원이 먼저 결재를 한 후에 회계부서의 부서장이 총 출납결재를 통해서 돈을 지출하고 있습니다. 이제 그 과정에서 저희가 내부 시스템을 사용하면서 전표 그리고 일계표와 모두 금액을 맞추고 있고요. 그렇게 지출시스템이 이루어지고 있습니다.
