<p><b>○ 재정지원부대리 민성원 </b> 네, 현금 계정은 매일매일 저희 내부 시스템적으로 맞추고 있습니다. 또한 월말마다 저희가 가지고 있는 모든 계좌의 잔액증명서를 통해서 시스템 내부와 실제 현재 계좌의 금액을 맞추고 있습니다.
