<p><b>○ 최병선 위원 </b> 잔액증명서도 중요하지만 한 달 이내에 유용을 하는 그런 사고도 많잖아요. 매일매일 지금 마감하신다고 하시니까 이 횡령이나 유용 자체가 가지고 갔다가 다시 넣는 거잖아요, 그렇죠? 계좌를 주체로 보자면. 그런 시스템을 좀 다시 한번 확인을 부탁드리고요.
