<p style="padding-left:1.2em">  네, 그렇습니다. 저희 결산 담당자가 별도로 있고요. 재무제표 작성은 저희 시스템과 연동을 통해서 나오는 부분이 있고 그거에 대한 검증 또한 저희가 직접 하고 있습니다.
