<p><b>○ 연구기획부차장 박정환 </b> 네, 맞습니다. 경기연구원이 직접 작성을 하고요. 실제로 경기연구원 담당자가 직접 작성을 하고 저희 시스템에 구축돼 있는 재무제표와 직접 확인해서 검증을 하고 있습니다.
