<p><b>○ 최병선 위원 </b> 그렇다면 지금 결산 담당자가 연구원 자체에 재석을 하고 계시다고 하니까 지금 실시간으로 제 메일로 현금흐름표랑 주석을 작성하는 엑셀 파일 있잖아요. 그걸 바로 저한테 좀 보내주시기 바랍니다.
