<p><b>○ 연구기획부차장 박정환 </b> 현금흐름표 자체는 저희 지금 재무제표시스템에서, ERP에서 구축돼 있는 것은 재무상태표하고 운영성과표 이 두 가지가 실시간으로 다 들어가 있고요.
