<p><b>○ 연구기획부차장 박정환 </b> 현금흐름표랑 주석은 저희가 작성은 하고 있는데 작년까지 재무제표는 작성했지만 ERP에서 직접 주석 자체가 작성돼 있지는 않습니다. ERP에서는 우리 현금 흐름이나 기존에 있는 회계전표, 우리가 분개처리하는 이런 것들이 다 ERP에서 집계는 되지만 주석은 마지막에 저희가 재무제표를 결산 마감하고 나서 실제로 우리 결산감사보고서를 꾸밀 때 그때 저희가 직접 작성하고 있습니다.
