<p><b>○ 최병선 위원 </b> 경기연구원 이전 문제가 있잖아요. 경기도 의정부로. 제가 자료요구를 하신 위원님의 자료를 봤는데요. 결국은 또 인재 유출의 문제가 대두가 될 것입니다. 그래서 지금 경기연구원 직원 의견수렴 내역이라고 해 가지고 웹사이트를 활용한 무기명조사, 다수 직원 무기명 실시 이 자료가 있는데 요청 내용들이 크게 보면 네다섯 가지가 있어요. 여기서 모든 직원분들의 의견을 사사로이 여기지 말고 경기연구원 이전 건에 대해서 철저히 준비를 해 주실 것을 당부드리고요.
