<p style="padding-left:1.2em">  그다음에 딱 하나만 더 질의를 드리면 재무제표 부속명세서 2021년도 현금 예금명세서에 기말잔액이 0원인 계좌가 몇 개 있어요. 지금 제가 요구한 자료에 9개 정도가 있는데 이런 계좌들은 특별히 지금 살려두고 있는 이유가 있나요? 다른 분이 답변해 주셔도 좋습니다.
