<p><b>○ 재정지원부대리 민성원 </b> 재정지원부 민성원 대리입니다. 일단 결산 기준에 따라서 작성을 하게 되면 저희가 보유하고 있는 모든 현금계좌를 작성하게 되는데 그중에서 저희가 먼저 수탁 용역사업 같은 경우에는 정산이 필요한 경우에 별도의 계좌를 운영하고 있습니다. 그리고 말씀하셨던 0원인데 연내에 131원이라고 말씀하신 거는 계좌가 존재하기 때문에 발생하는 이자 부분인데요. 다만 그 수탁 용역을 위한 계좌를 해지할 때는 그 수탁 용역이 완료가 되어야 합니다. 아직 완료가 12월 30일 기준으로 되지 않았기 때문에 살아있는 것으로 보이고 수탁 용역이 완료가 되면 그 계좌는 해지 처리를 하고 있습니다. 또한 저희가 수탁 용역을 진행함에 있어서 어떠한 사업 같은 경우에는 발주처에서 직접적으로 돈을 입금해 주고 그러고 나서야 저희가 출금을 하는 경우가 있습니다. 그런 경우에는 수탁 용역사업이 진행되면서 항상 0원을 유지합니다. 그날 들어오고 그날 나가기 때문입니다.
