<p><b>○ 이채명 위원 </b> 안양 출신 이채명 위원입니다. 앞서 장애인 의무 고용은 충족을 했다라고 얘기를 들었습니다. 그 연장선에서 제가 자료를 보다 보니까 중증장애인의 생산품을 우선구매할 수 있게끔 법적, 의무적으로 중증장애인생산품 우선구매 특별법에 따라서 중증장애인의 고용 촉진을 위해서 매년 전체 구매액의 1% 이상을 중증장애인이 생산한 물품으로 우선 구매하여야 한다라고 이렇게 돼 있습니다. 그런데 지금 받아본 자료에 의하면 보니까 일단 3년간 구입실적 현황을 보니까 우선구매율은 2020년도는 0.15%, 21년도는 0.28, 2022년도는 0.37%에 그치고 있어요. 단 한 번도 3년 동안 1%를 넘긴 적이 없습니다. 특별한 이유가 있나요?
