<p><b>○ 이채명 위원 </b> 왜냐하면 아시다시피 장애인들의 최저임금 보장도 안 되는 그 현실을 감안해서 저희가 구매 독려를 하게 되잖아요. 그래서 임금의 어떤 선순환 차원에서 사실은 특별법이 저는 제정됐다고 지금 생각하고 있습니다. 이 부분에 대해서는 고민을, 공공기관의 자료를 지금 찾아보니까 경기도 전체에서는 거의 1%가 됐더라고요. 그런데 지금 현재 경기연구원 같은 경우는 현저하게 낮아요. 연구원의 어떤 특성상 이렇게 구매율이 낮은 건지에 대해서 설명 좀 부탁드리도록 하겠습니다.
