<p><b>○ 경기연구원장직무대행 송미영 </b> 저희가 구매하는 게 아까 말씀하신 대로 사무용품하고 전산용품 정도만 구매를 하고 나머지는 대부분이 다 연구 용역 같은 위탁이나 인건비 기준의 용역이 대부분입니다. 지금까지 저희가 최선을 다한다고 했지만 기대에 미치지 못하고 있으나 앞으로 조금 더 노력을 해 보겠습니다.
