<p><b>○ 이채명 위원 </b> 앞으로 신경 써 주시기를 바라겠고요. 또 한 가지는 제가 질문드린 것 중에 산업안전보건 법적 의무교육이잖아요. 2021년도 산업안전보건 교육현황을 보니까는 이수율이 52.3%밖에 되질 않습니다. 올해 2022년도 같은 경우는 지금 현재 그냥 추진 중으로만 이렇게 저희한테 자료를 주셨는데요. 이 부분에 대해서 설명을 좀 부탁드리겠습니다. 이수하지 않은 분들은 그럼 어떤 조치를 취하고 있는지 이런 부분들에 대해서 간단히 설명 좀 부탁드리겠습니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 사실은 지금은 이수를 권고하고 독려하는 차원만 되어 있고 이수하지 않은 분들한테 어떤 페널티는 없습니다. 그런데 위원님 지적해 주신 대로 자꾸 이수율이 올라가지 않고 있어서 이거를 성과에 반영해야 될지 아니면 페널티를 둬야 될지 저도 고민 중입니다.
</p>
<p><b>○ 이채명 위원 </b> 그런데 업종별에 대해서 상이할 수는 있겠지만 지금 요즘에는 안전사고가 많이 나잖아요. 그러다 보니 재해 발생을 예방하기 위해서 가장 기본이 사실은 정기적으로 이렇게 충실히 산업안전보건교육을 받아야만 하거든요. 그런데 받지 않았을 때 지금 현재 보니까 산업안전보건법에는 최대 500만 원까지 과태료를 부과하게 돼 있습니다. 이거는 어떻게 된 거죠? 혹시 알고 계시나요? 지금 제가 자료를 찾아보니까 법적 의무교육을 받지 않았을 때는 업종별로 상이하기는 하지만 최대 500만 원의 과태료를 부과한다라고 이렇게 되어 있습니다. 이 부분에 대해서는 아직 검토를 해 보시지 않으셨나 봐요.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 아니, 검토는 해 봤는데 저희도 산업안전보건법이나 이런 취지는 다 이해를 하는데 아직 저희 연구원 같은 직종에서는 이런 부분에 말씀하신 것처럼 중요성을 아직 공감을 충분히 못 한 점도 있고 그다음에 앞으로 조금 더 이수 상황을 높이기 위한 노력을 저희가 해야 된다고 봅니다. 
</p>
<p><b>○ 이채명 위원 </b> 지속적으로, 왜냐하면 지금 가장 중요한 게 또 2022년도에 전 직원 안전보건교육 2분기에 보니까 감정노동의 이해와 관리 방안이라는 교육이 있습니다. 그런데 여기에서도 이수 인원이 103명이고요. 이수율도 56%밖에 되지 않아요. 이런 부분들도 시정을 했으면 좋겠다라는 생각이 듭니다.
