<p><b>○ 이채명 위원 </b> 이상입니다. 잠시만요. 그리고 한 가지 제가 업무보고를 받다 보니까 저희가 경기연구원에 대해서 자료가 사실은 저는 조금 보완됐으면 좋겠다라는 생각이 들어서 추가로 업무보고를 저희한테 하실 때요. 지금 행정사무감사를 하든가 아니면 업무보고 때 지금 연구하는 거에 대해서 부서명, 연번, 유형은 예를 들어서 수시ㆍ기초연구라든가 약간 구분을 해 주시고요. 연구 과제명 그리고 연구 기간이 언제부터 언제까지다라는 것 그리고 상태가 완료됐다 아니면 현재 진행 중이다. 그리고 연구 예산은 어느 정도 들어가고 주요내용은 어떻다라고 하는 것을 주요업무보고 책자 안에 저는 같이 이렇게 첨부가 됐으면 좋겠다라는 생각이 듭니다. 왜냐하면 사실은 저희가 이 책자만 보더라도 한눈에 업무의 흐름을 사실은 좀 알았으면 좋겠다라는 생각이 듭니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그렇게 하겠습니다.
</p>
<p><b>○ 이채명 위원 </b> 그래야지 경기연구원이 좀 더 한 단계 성장하지 않을까라는 그런 생각이 듭니다. 사실은 경기연구원이 성장하기 위해서는 우리 위원들이 많은 관심을 가져야 된다고 생각을 하거든요. 그러기 위해서는 한눈에 책자에 우리 경기연구원에서 어떤 연구를 주로 하고 있는지 기본연구가 무엇이고 정책연구가 어떤 것인지 이런 것 등등에 대해서 조금은 관심도를 높일 수 있는 방법을 고민했으면 좋겠다라는 생각이 들고요.
</p>
<p style="padding-left:1.2em">  한 가지 제가 칭찬해 드리고 싶은 것은 작년에 지적사항이기는 하지만 경기연구원이 적시에 블로그에 게재하지 않고 한꺼번에 올리는 사례가 있어서 그거를 지적을 받았던 것 같아요. 그래서 제가 올해, 저 같은 경우는 경기연구원하고 블로그 친구 맺기가 되어 있습니다. 이웃 친구인데 제가 예를 들어서 어떤 정보를 얻기 위해서 키워드를 검색하게 되면 바로 경기연구원의 모든 정보가 다 들어있습니다. 그래서 경기연구원의 블로그에서 많은 공부를 제가 하게 됩니다. 그런 부분들을 감안했을 때 저뿐만 아니라 모든 분들, 우리 도민들 이하 모든 분들께서 경기연구원에 들어가면 내가 원하는 그런 정보들을 바로바로 체득할 수가 있겠구나라는 생각을 하게 되면 굉장히 경기연구원의 블로그가 더 활성화가 되지 않을까라는 생각이 듭니다. 그래서 아까 전에도 제가 제안을 드리기는 했습니다만 일단 경기연구원 블로그에 들어와서 검색하는 계층이라든가 세대라든가 이런 것 등을 분류해서 어떤 분류가 주로 많이 경기연구원을 이용하는지에 대해서 그런 것을 좀 데이터를 뽑아봤으면 좋겠다라는 생각이 드는데 혹시 부원장님은 어떻게 생각하세요?
