</p>
<p><b>○ 이채명 위원 </b> 꼭 한번 통계를 내보시고요. 내보시고 나서 어떤 계층이 더 많이 이용률이 높다라고 하면 그 계층에 대한 연구를 좀 더 할 수 있는 근거가 되지 않을까라는 생각이 듭니다. 
