<p><b>○ 김철현 위원 </b> 안양 출신 김철현 위원입니다. 송미영 연구부원장님이 지금 맡고 있는 직책이 원장 직무대행도 맡고 계시고요. 그다음에 지금 경영부원장도 겸직하고 계시죠?
