<p><b>○ 김철현 위원 </b> 그리고 등기이사로도 올라가 계시고요. 그래서 김근용 위원님이 많이 걱정을 하시는 것 같아요. 여러 가지 직책을 맡고 계시는데 권한은 없고 책임만 많이 주어지는 것 같은데요. 현재 경영부원장님이 공석이 된 지가 얼마나 됐죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 1년 이상 됐습니다.
</p>
<p><b>○ 김철현 위원 </b> 원장님이나 경영부원장님이 거의 1년이 넘는 시간을 장기간 결원이 되다 보니 주위에서는 상당히 경기연구원이 부실 경영이 되지 않나 하는 우려가 있었는데 직원들의 근무 기강 해이와 공공기관 평가에서 연속적으로 하위 등급을 받았는데 송미영 원장 대행님께서는 이러한 결과를 초래한 것이 원장이나 일부 간부의 장기간 결원과 어떤 연관관계가 있다고 생각을 하십니까?
