<p><b>○ 경기연구원장직무대행 송미영 </b> 원장님이나 다른 경영진이 없어서 그런 면도 일부 작용을 하고요. 제가 부족한 점이 있어서 그렇다고도 생각을 합니다.
</p>
<p><b>○ 김철현 위원 </b> 송미영 연구부원장님은 원래 연구 쪽에 담당을 하셨던 분인데 경영까지 그렇게 책임지는 발언은 안 하셔도 될 것 같고요. 정관에 따르면 원장이 직무를 수행할 수 없을 때에는 이사장 또는 이사장이 지명하는 이사가 직무를 대행해야 한다 이것이 지금 경기연구원의 정관에 있죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 김철현 위원 </b> 그런데 정관에 따라서 지난번에 이사장님께서 원장 직무대행을 하시다가 이사님들 중에서 왜 직무대행자를 선임하지 않고 하나 건너뛰어서 연구부원장님을 굳이 이렇게 직무대행자로 선임한 이유가 있습니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 제가 이해하기로는 이사들이 전부 비상근이기 때문에 이사장님 본인도 그러시고 이사 중에 사실 직무대행을 하실만한 여건이 되는 분이 안 계시고 저희가 그런 여건을 조성해 드릴 수가 없어서 제가 대표 겸 직무대행을 하게 되었습니다.
</p>
<p><b>○ 김철현 위원 </b> 정관상으로는 문제가 없습니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 정관상으로는 그렇다고 하는데 거기에 걸맞은 대우나 보수나 이런 거를 드릴 수 있는 여건이 없습니다.
</p>
<p><b>○ 김철현 위원 </b> 경기연구원의 정관 제25조의 정원에 보면 정원은 103명으로 되어 있다고 그래요. 근데 여기 업무보고서에 보면 187명으로 되어 있는데 이거는 또 어떻게 되는 거죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그거는 아마 자료에 무기직을 빼고 표기한 것 때문에 그런 것 같습니다.
</p>
<p><b>○ 김철현 위원 </b> 여기 업무보고서에 보면 정규직으로 해서 무기계약직까지 집어넣어 있는데 그러면 정관하고 지금, 정관에 위배되는 건 아니에요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 이 부분은 관련 부서장이 답변을 드려도 되겠습니까?
</p>
<p><b>○ 김철현 위원 </b> 네, 그렇게 하세요.
</p>
<p><b>○ 행정지원부장 손호철 </b> 안녕하십니까? 행정지원부장 손호철입니다. 정관 25조에 정원 103명은 저희 본원에 대한 정원을 말씀드리는 거고요. 그 밑에 보면 공투센터 부설기관에 대한 정원이 18명으로 표기가 돼 있습니다. 그리고 저희가 무기계약직을 66명 운영을 하고 있습니다. 아마 그거 포함해서 저희가 187명으로 그렇게 표현을 한 겁니다.
</p>
<p><b>○ 김철현 위원 </b> 무기계약직은 원래 그러면 정관에 안 들어가 있는 인원입니까?
</p>
<p><b>○ 행정지원부장 손호철 </b> 정관에는 없고요. 저희 따로 무기계약직 운영 규정이 있습니다.
</p>
<p><b>○ 김철현 위원 </b> 무기계약직도 여기에는 정규직으로 되어 있는데요. 정관에다가 이렇게 올려야 되는 거 아닙니까? 정관을 수정하든지.
</p>
<p><b>○ 행정지원부장 손호철 </b> 사실 저희가 무기계약직은 계약직으로 그동안에 분류를 해 왔었습니다. 그래서 정원 개념에는 포함을 안 시켰는데 최근에 무기계약직도 경기도에서도 공무직 이렇게 표현을 하면서 이분들도 정원 개념으로 보는 그런 경향이 많아서 업무보고자료에다가 저희도 무기계약직 분들도 같이 포함해서 그렇게 표현을 좀 했습니다.
</p>
<p><b>○ 김철현 위원 </b> 그러니까 서류상으로만 정규직으로 해 놓은 거고 실제적으로는 정관에 들어가 있지 않으면 정규직 직원은 아니라는 소리 아닙니까? 무기계약직이 되는 거잖아요.
</p>
<p><b>○ 행정지원부장 손호철 </b> 그렇습니다.
</p>
