<p><b>○ 경기연구원장직무대행 송미영 </b> 정관에 따라서 수정하도록 하겠습니다.
</p>
<p><b>○ 위원장 지미연 </b> 아니죠. 누구 마음대로요. 2021년 4월 1일도 정원은 103명입니다. 그 얘기는 본예산 때 경기연구원 인건비는 여기서 넘어갈 수가 없어요. 이거는 철저하게 모든 걸 다 조사할 겁니다. 무슨 근거로, 103명에서 지금 현재 187명의 정원을 갖고 현원 183이다라고 써놓은 거 근거 갖고 오세요.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 제출하겠습니다.
</p>
<p><b>○ 위원장 지미연 </b> 근거 제출하지 아니하면 경기연구원은 모든 예산 없습니다, 이제. 대행으로 오셨으면 정확하게 숙지를 하고 와야 되는 거고. 기본 아닙니까?
</p>
<p style="padding-left:1.2em">  다음에는 정승현 위원님 질의하시기 바랍니다.
</p>
<p><b>○ 정승현 위원 </b> 정승현입니다. 장시간 답변하시느라고 고생 많으신데 우선 앞서 위원장님께서 질문 주셨는데 정원ㆍ현원 관련해서요. 지금 현재 산하기관, 공공기관들이 비정규직 그러니까 앞서 무기계약직 얘기하셨잖아요? 그리고 기간제들 이분들은 정원에 포함이 돼요, 안 돼요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 정관에는 포함이 안 돼 있지만 현실적으로는 저희가 포함해서 하고 있습니다.
</p>
<p><b>○ 정승현 위원 </b> 현원에는 포함되지만 정원 규정에는 포함이 안 되는 거죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그 부분에 대해서 좀 명확히 하셨으면 좋겠고요. 부원장님, 지금 직대 맡으신 지가 얼마나 됐죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 제가 부원장이 된 지는 2020년 1월 1일에 됐으니까 거의 3년이 돼 갑니다.
</p>
<p><b>○ 정승현 위원 </b> 경기연구원이 우리 경기도에서 차지하고 있는 포지션이라고 할까요, 그러니까 경기연구원은 곧 우리 경기도의 어떤 역할, 어느 정도의 중요성을 갖고 있다고 보세요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 어떤 의미에서 말씀하시는지.
</p>
<p><b>○ 정승현 위원 </b> 제가 말씀드릴게요. 앞서 오전에 우리 정경자 위원님께서도 말씀하셨습니다만 말 그대로 우리 경기도의 싱크탱크입니다, 그렇죠? 
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그런 중요한 기구가 지금까지 원장을 선임하지 못하고 있는 부분에 대해서는 참으로 안타까운 일입니다. 그렇다고 우리 부원장님께 이 책임을 묻고자 하는 건 아니고 또 책임도 없고 결국은 내부적인 문제가 아니라 외적 요인에서 사실 지금까지 선임을 못 하고 있는 거잖아요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그런 의미에서 또 약 3년 가까이 지금 부원장님께서 직대를 맡아 오시면서 정말…….
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 아니, 제가 직무대행을 한 거는 올해 초부터입니다.
</p>
<p><b>○ 정승현 위원 </b> 올해 초부터. 아까 20년부터 하셨다고 해서.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 연구부원장을 그때부터 했다는 얘기입니다.
</p>
<p><b>○ 정승현 위원 </b> 그래서 어쨌든 연구부원장으로서 정말 연구에 몰입해야 될 위치에 계신 분이 경영에 지금 몰입하고 계셔서 그리고 또 짧은 기간 동안에 답변하신 거 보니까 어쨌든 많은 업무들을 꿰뚫고 계신 것 같아서 상당히 고생하셨다는 말씀을 드리겠습니다.
</p>
<p style="padding-left:1.2em">  앞서 정관 얘기했는데 저는 정관을 많이 수정해야 될 필요가 있다라는 생각을 해 보게 됩니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 아까 지적 주신 대로 검토해 보겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 우선 좀 하나하나 더듬어 보면 제16조 원장이죠. 16조 원장이 궐위로 그 직무를 수행할 수 없을 때 이사장 또는 이사장이 지명하는 이사가 직무를 대행한다고 그렇게 돼 있죠, 그렇죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그리고 직무대행자가 선임될 때까지 원장의 직무를 대행하는 자는 별도의 규정으로 정한다 그렇게 돼 있고요, 그렇죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 그래서 우리 경기연구원 정관 규정 제7조 직무대행에 보면 원장이 불가피한 사유로 직무를 수행할 수 없을 때에는 정관 제16조3항이죠, 그러니까 이사장이 이사를 선임하는 부분. 3항에 따른 직무대행자가 선임될 때까지 연구부원장, 경영부원장 등 직제순으로 대행을 한다고 그렇게 돼 있어요. 그런데 앞서 답변 과정에서 사실 지금 경기연구원의 이사들은 지금 전부 다 비상근 이사들이죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 현실적으로 그분들이 원장 직대를 할 수가 있는 거예요, 없는 거예요? 못 하죠? 원장 외에는 다 비상근이잖아요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 다 비상근입니다.
</p>
<p><b>○ 정승현 위원 </b> 그럼 부원장님 말씀하셨던 것처럼 원장 궐위 시에는 이사장이 지명하는 이사가 직무를 대행한다고 했는데, 정관상에 그렇게 돼 있어요. 그러나 현실적으로 이사가 직대를 할 수가 없는 거죠? 어려운 상황이죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 현실적으로는 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 현실적으로 어려운 거죠. 그러면 이 정관 고쳐야 되겠죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 서울시 정관을 한번 보세요. 서울시는 “원장이 궐위될 때에는 규정으로 정한다.” 그리고 서울시 정관 규정 제14조1항1호에 “원장이 직무를 수행할 수 없을 때는 부원장과 그리고 이하 직제순으로 정한다.” 그렇게 딱 명확히 돼 있어요.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 저희도 이전에는 그런 적이 있었습니다. 
</p>
<p><b>○ 정승현 위원 </b> 그런데 왜 이렇게 돼 있어요, 지금 정관이?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그런데 여러 가지 이유로 이렇게 바뀐 겁니다.
</p>
<p><b>○ 정승현 위원 </b> 다시 한번 여쭤보겠습니다. 지금 이사가 원장 직대를 현실적으로 할 수 있어요, 없어요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 저는 없다고 봅니다.
</p>
<p><b>○ 정승현 위원 </b> 없다고 보죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 비상임이기 때문에.
</p>
<p><b>○ 정승현 위원 </b> 그런데 정관에는 지금 그렇게 된다고 돼 있죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 그러니까 그런 점은 불일치하는 겁니다.
</p>
<p><b>○ 정승현 위원 </b> 그럼 이 정관 수정하셔야 되겠죠? 이사회 열어서 당장 정관 수정하세요.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 검토 요청드리겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 그리고 두 번째, 이사장 선임하잖아요, 이사장. 이사장은 정관 제13조에 “이사장은 노동이사를 제외한 비상근이사 중 이사회에서 호선한다.” 이렇게 돼 있죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 지금 경기연구원에 노동이사가 있죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 있습니다. 
</p>
<p><b>○ 정승현 위원 </b> 노동이사 권한이 어디까지죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 노동이사 관할이요?
</p>
<p><b>○ 정승현 위원 </b> 권한, 권한. 노동이사가 할 수 있는 거.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 노동이사는 이사회에 참여하는 거하고 노동조합 관련한 업무를 관장하게 돼 있습니다. 그다음에 노조를 대표하고.
</p>
<p><b>○ 정승현 위원 </b> 굳이 제가 여기서 부원장님 말씀하신 것에 대해서는 다른 얘기를 않겠습니다. 기본적으로 노동이사가 이사회에 참석해서 할 수 있는 것은 자료요구하고 그리고 발언권이 있고 의결권을 갖습니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 그런 건 당연히 있습니다.
</p>
<p><b>○ 정승현 위원 </b> 경영에 참여할 수가 있죠? 경영에 참여할 수가 있는 거죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 정승현 위원 </b> 의결권을 갖는다 그랬죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 그렇습니다.
</p>
<p><b>○ 정승현 위원 </b> 그러면 우리 정관 제4장22조 의결에 보면 1항제4호에 임원 선임에 관한 사항이 있어요. 의결권을 갖고 이 같은 내용들을 의결하는 거죠. 임원 선임할 때 의결하는 거죠. 그렇게 돼 있죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그렇게 돼 있습니다.
</p>
<p><b>○ 정승현 위원 </b> 그런데 우리 정관 제3장13조 이사장 선임 건에 대해서는 이사장은 노동이사를 제외한 비상근이사 중 이사회에서 호선한다고 돼 있어요. 그럼 이게 맞지 않는 거잖아요. 노동이사는 이사회에 참여해서 의결권을 갖고 있는데 이사장을 선임하는 데에서는 노동이사를 제외한다? 이건 맞지 않는 거 아니에요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그것도 검토해 보겠습니다. 
</p>
<p><b>○ 정승현 위원 </b> 네?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그것도 검토해 보겠습니다. 제가 법적인 사항은 잘 이해를 못 해서요. 그것도…….
</p>
<p><b>○ 정승현 위원 </b> 이것도 서울시 정관에는 노동이사도 다 참여하게끔 돼 있어요. 왜 이렇게 뒤떨어진 정책을 쓰고 있어요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 저희 정관이 좀 그런 점이 있을 겁니다. 그런 점은 저희가 시정하도록 하겠습니다.
</p>
<p><b>○ 정승현 위원 </b> 앞서 제가 다른 부서 행감하면서도 말씀드렸는데 저는 우리 경기도 그리고 경기도 각 산하기관에서 하는 일은 정말 전국 최대 광역지자체로서 모범이 돼야 된다라고 생각합니다. 또 실질적으로 경기도에서 행하고 있는 모든 법령이나 정관이나 이런 부분들을 산하기관도 마찬가지고 경기도 거를 많이 벤치마킹해서 하고 있습니다. 다시 말씀드리면 경기도에서 시행하면 그게 대한민국 정책이 되는 거예요. 그럼 이런 부분들도 저는 정말 모범이 돼야 된다라는 측면에서 좀 말씀을 드리면 이거는 분명히 상호 모순된 내용을 담고 있다. 그래서 이 부분도 반드시 개정하는 논의를 하셨으면 좋겠다. 어떻게 생각하세요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 아까 위원장님 말씀하신 것 포함해서 지금 위원님 말씀해 주신 것까지 검토하도록 하겠습니다.
</p>
