<p><b>○ 이동현 위원 </b> 보통의 경우 기관의 이전은 사실 모든 업무보다 매우 중요한 업무잖아요. 그런데 행감 업무보고에는 들어있지 않아서 현재 진행 상황이 어떤 거죠?
