<p><b>○ 경기연구원장직무대행 송미영 </b> 원래는 의정부하고 얘기했을 때는 2025년까지 완료하는 것으로 서로 얘기를 했었는데 저희가 3차 대상 기관이다 보니 아직 세부적인 계획이 나오지 않았고 또한 대상지인 캠프카일이, 의정부가 지금 감사원 감사를 받고 있습니다. 이전 대상지를 적격 대상자 선정하는 과정에서 문제가 있었다는 얘기가 있어서 감사원 감사를 계속 받고 있어서 저희가 그 내용이 확정되지 않아서 아직 여기에 올리지를 못 했습니다, 계속 지연될 것 같은 일정이라서요.
</p>
<p><b>○ 이동현 위원 </b> 그러면 어쨌든 경기연구원은 이전에 대해서 다시 검토할 수도 있는 거겠네요?
