</p>
<p><b>○ 이동현 위원 </b> 특별자치도를 또 경기연구원에서 관련된 정책 자료나 연구를 통해서 김동연 지사를 서포트하게 되는데 지원하게 되는데 저는 산하기관의 이전과 특별자치도는 병행하기 어렵다. 현실적으로 병행할 수 없는 사안이다라고 생각을 하고 그런 부분에서 약간 가볍게 여쭤봤습니다. 한 가지만 더 지역 현안 관련해서 부원장님한테 여쭤볼게요. 부원장님, 전공이 옛날에도 뵀을 때 수리나 물 관리 관련된…….
