<p><b>○ 경기연구원장직무대행 송미영 </b> 수질 관리 정책 쪽입니다, 저는.
</p>
<p><b>○ 이동현 위원 </b> 제가 이걸 말씀드리는 이유 중에 하나가 시화호가 연안오염 총량제로 돼 있죠? 연안오염 총량제 대상인데 원래 이게 시화호를 대상으로 연안오염 총량 규제 대상 지역입니다. 그런데 이명박 정부 때 해수 유통을 하면서 시화호가 이제는 막힌 호수가 아니라 일종의 바닷물이 섞이는 형태의 담수호가 아닌 상태가 돼버렸거든요. 그런데 현재도 시화호가 연안오염 총량제 규제 지역이다 보니까 농도 규제 그리고 총량 규제에서 현실과 안 맞는 거죠. 예를 들면 시화호 주변에 도시개발 같은 게 이루어지고 그러면 예를 들면 추가적인 배수, 물이 나가는 것들이 시화호 쪽으로 나가는 것들이 있는데 시화호가 예전에는 담수호여서 호수였기 때문에 시화호 연안오염 총량제가 맞는데 현재는 이게 해수랑 유통이 되는 상태에서 현실과는 좀 안 맞는다는 부분이 지역 내에서 건의들이 많이 있거든요. 그거에 대해서 혹시 의견 주실 수 있으신가요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 시화호는 특별연안관리지역인데 시화호의 실제 문제는 뭐냐 하면 내부에서 나오는 유역의 오염원이 외부로 배출되는 중입니다, 지금 현재. 그다음에 조력발전소가 있는 곳을 통해서 해수 유통도 되고 있고 그래서 실제로는 겉보기 총량을 하는 중입니다. 그래서 겉보기 총량을 하는데 그걸 실질적으로 하기 위해서 여러 가지 대안들을 마련하는 게 연안오염 총량의 내용이고요. 특히 연안오염 총량을 할 때 지금 제일 문제가 되고 있는 건 시화호의 앞으로의 발전 방향, 그러니까 이게 열려 있는 호수니까 이 호수를 어떤 기준을 가지고 관리할 거냐에 대한 새로운 목표 그다음에 새로운 기준들 그다음에 관련된 제도들을 운영해야 되는데 시화호 같은 연안호들은 대부분 해수부하고 환경부하고 영역이 중첩되거나 상충되는 부분이 있는데 제도적인 측면이 아직 조정이 되지 않았습니다. 그래서 그런 부분이 조정이 되는 과정 중에 이 특별연안 총량을 하는 중입니다.
</p>
<p><b>○ 이동현 위원 </b> 짧게만 말씀 더 드리면 그러니까 현상이 그렇게 발생한 거죠. 시화호가 연안오염 총량제 규제 지역으로, 시화호를 규제하다 보니까 추가적인 물의 방류에 대해서 이건 눈 가리고 아웅이지만 바로 관로로 돌려서 인천 앞바다로 그냥 내보내는 거예요. 그렇게 대응을 하고 계획을 잡는 거거든요. 이게 예산도 낭비되고 실제 시화호 연안오염 총량 관리에도 맞지 않는다. 이 부분에 대해서 좀 규제에 대한 새로운 접근이 필요하지 않나 이런 고민들이 있어서 그냥 질의 말미에 한번 여쭤봤습니다.
