<p><b>○ 지미연 위원 </b> 다음에 40페이지 존경하는 이병숙 위원님이 질의하신 거 보충하겠습니다. 여기 40페이지에 보시면 경기연구원 원장 직무대행 사인이 우리 연구부원장 사인입니까, 이사장 사인입니까? 누가 한 겁니까, 이거는? 누가 직무대행했어요, 이때? 40페이지하고 41페이지에 있는 직인 누구입니까?
</p>
<p><b>○ 감사부장 이용원 </b> 이 부분은 원장 직무대행까지 결재를 받고…….
</p>
<p><b>○ 지미연 위원 </b> 그러니까 누가. 이때 누구, 누가 했냐고, 사람.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 접니다. 송미영입니다.
</p>
<p><b>○ 지미연 위원 </b> 연구부원장이 하신 거예요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 제가 한 걸로 기억됩니다.
</p>
<p><b>○ 지미연 위원 </b> 그러세요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 지미연 위원 </b> 그러면 답변하시면 돼요. 제가 질문하겠습니다. 자리에 앉아서 하세요. 아까 앉아서 하셨잖아요.
</p>
<p style="padding-left:1.2em">  거기 40페이지 보시면 “암호화폐 채굴하여 경기연구원에서 이렇게 금액에 추정되는 피해를 주었으나 해당 직원이 적발 당시에 범죄 관련성을 몰랐고” 어느 범죄자가 알았다고 얘기합니까? 몰랐고 그래서 이렇게 경징계로 넘어간 거 아니겠습니까? 이런 판단이 옳다고 보세요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 여러 차례 말씀드린 것처럼 제가 이거에 대해서는 말씀드릴 게 없습니다. 질책을 하시면 질책받겠습니다.
</p>
<p><b>○ 지미연 위원 </b> 그리고 41페이지 보세요. 중간에 혐의자의 평소 소행 나옵니다. “직무태만 여부에 대한 해당 부서장과 타 부서장의 의견이 다르다.” 이거는 부서장이 직무유기한 겁니다. 아까 말씀드렸잖아요. 아까 발언하셨죠? 컴퓨터를 자기 개인 컴퓨터를 가지고 왔다. 사무실에서 그 짓거리를 하는데도 몰라요, 부서장이? 무슨 조직이 그렇습니까? 그러니 자기 부서는 이쁘지. 타 부서장 보니까 아닌 사람인 거예요. 그래 놓고 난 다음에 기타 하단부에 유해사이트 차단계획 수립에 기여하고 있다는 점으로 이것도 예뻐하는 거야. 범죄자한테 뭘. 이거 유해사이트 차단계획 언제 하십니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 이미 완료했습니다.
</p>
<p><b>○ 지미연 위원 </b> 이미 완료해서 그래서 예뻐서 경징계 주신 거예요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그건 아닙니다.
</p>
<p><b>○ 지미연 위원 </b> 그다음에 42페이지 보세요. 이렇게 쭉 요구서 나가는데 왜 날짜하고 반장 인이고 이거 다 없습니까? 이거 제출하려고 그냥 만드신 거예요? 가라로?
</p>
<p><b>○ 감사부장 이용원 </b> 감사실 이용원 부장입니다. 이 처분요구서 자료는 저희가 정기감사 결과…….
</p>
<p><b>○ 지미연 위원 </b> 마이크 켜세요.
</p>
<p><b>○ 감사부장 이용원 </b> 이 처분요구서 자료는 자체 정기감사 결과 보고에 있는 처분요구서를 저희 인사위원회 징계 의결 요구를 할 때는 붙이게 돼 있어서 그대로 첨부하였습니다.
</p>
<p><b>○ 지미연 위원 </b> 경기연구원 정신 차리세요. 여기까지 하겠습니다. 이상입니다.
</p>
<p><b>○ 부위원장 김철현 </b> 지미연 위원님 수고하셨습니다. 다음은 김현석 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김현석 위원 </b> 과천 출신 김현석 위원입니다. 부원장님, 장시간 고생 많으십니다. 좀 환기하는 의미에서 질문 하나 드릴게요. 경기연구원의 설립 목적이 무엇인가요? 마이크를 켜 주시고요.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 경기도민의 삶의 질을 증진하고 경기도에 정책 지원을 하는 것을 목적으로 하고 있습니다.
</p>
<p><b>○ 김현석 위원 </b> 네, 홈페이지 보면 경기도 발전을 위한 정책 개발에 기여함을 목적 이렇게 정확히 명시가 되어 있어요. 그래서 질의 이제 본격 들어가겠습니다. 지금 기본소득 관련 연구과제가 총 몇 건 경기연구원에서 진행이 됐나요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그 부분은 제가 다 기억을 할 수는 없는데 다수 저희가 했습니다. 왜냐하면 민선7기의 핵심 시책이었기 때문에 과제를 많이 했습니다.
</p>
<p><b>○ 김현석 위원 </b> 제가 읽어드릴게요. 책자를 훑어보니까 8건 나오더라고요. 7건은 집행부 의뢰로 한 거죠? 하나는 도의회에서 수탁연구한 거고.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 김현석 위원 </b> 그래서 이게 책자를 보니까 활용 결과는 도 정책 수립 및 정책 지원 자료로 활용됐다 이렇게 나오더라고요, 모든 건이. 그래서 지금 자료를 봤어요. 집행부 책자 Ⅱ권 791페이지 보니까 집행부 의뢰 연구사업 목록 및 도정 반영 현황이라고 나와요. 그런데 지금 연구과제가 총 8건 돼 있는데 반영된 것은 딱 한 건 나오더라고요. 기본소득 재원으로서 탄소세 도입 검토. 청년기본소득, 농민기본소득 그건 빼고 그냥 기본소득만 했을 때 총 8건인데 지금 총 8건에 대해서 읽어드릴게요. 기본소득과 사회투자정책의 결합 가능성 연구, 주권화폐 발행과 금융제도 개혁, 이건 부제가 기본소득 재원과의 연계성 고찰, 기본소득 기반 사회보장 개혁방안 연구 이렇게 등등 8건이 있는데 1개만 들어가 있어요. 8건 중에 1건만 도 정책 수립 및 정책 지원 자료로 활용됐다 이렇게 보면 맞는 건가요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 죄송한데 어떤 자료를 보고 말씀하시는 건지…….
</p>
<p><b>○ 김현석 위원 </b> 책자 Ⅱ권 791페이지 집행부 의뢰 연구사업 목록 및 도정 반영 현황에 기본소득 관련해 가지고 연구한 것 중에서 딱 한 건이 나와 있더라고요. 경기연구원에서는 총 8건을 기본소득 관련 연구를 진행했는데 집행부 의뢰 연구사업 목록에는 한 건밖에 안 들어가 있어요. 7건은 활용을 안 했다는 거네요, 도 정책 수립 및 정책 지원 자료로? 어떻게 된 겁니까? 7건은 예산 지원 받아서 운영하고 있는데 정책 반영 안 되고 어디에 쓴 거예요, 그러면 이 7건은? 자료만 보고 말씀드린 거예요. 이게 궁금해 가지고.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 저희가 도 의뢰 정책과제에 대해서만 정책 반영도를 제시하고 저희가 자체 발굴하거나 한 내용들은 여기에 포함되지 않아서 그렇다고 합니다.
</p>
<p><b>○ 김현석 위원 </b> 그래서 처음에 8건 중 7건이 집행부 의뢰 과제라고 했는데 맞다고 말씀하셔서 말씀드린 거거든요. 그게 아니라는 건가요? 8건 중에 7건이 집행부 의뢰라고 하셨고 하나는 도의원 수탁연구라고 돼 있어서 8건 중에서 7개는 들어가야 되는데 1개만 들어가 있고 없어요. 정책연구라고 딱 목에는 되어 있는데.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그거는 제가 다시 확인해 보고 보고드리면 안 되겠습니까?
</p>
<p><b>○ 김현석 위원 </b> 네, 그러면 월요일 날 할 때 그때 보고해 주시고요. 자료를 아까 4시에 요구해서 좀 전에 받았어요. 연구과제 영문 보고서의 발행 기준이 뭔가요? 연구하시는 분이 그냥 영어 하면 되는 거예요, 아니면 번역을 서비스를 해 주는 겁니까? 경기연구원 자체에서?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그보다는 연구성과가 영문 보고서를 냄으로 해서 조금 더 배가되거나 도움이 될 수 있다고 저희가 판단하는 내용들을 영문 보고서로 발간하고 있습니다.
</p>
<p><b>○ 김현석 위원 </b> 아까 자료를 받았어요. 3년 치 연구과제 연구보고서 목록이 있는데 2020년, 21년에 총 5건의 연구과제가 있습니다. 4건이 다 베이직 인컴, 기본소득이에요. 연구보고서가 2022년, 21년 대선 전이죠? 5건 중에 4건이 다 기본소득에 관한 연구보고서가 나온 거예요. 이걸 어떻게 해석을 해야 될까요, 부원장님?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 기본소득 연구가 우리나라에서도 처음 시작하는 거였고 그것을 외국에 있는 기관하고 네트워킹해서 하기 위해서 여러 가지 연구 성과를 만들다 보니 이게 외부하고 소통하는 차원에서도, 국외 연구자들하고 소통하기 위해서도 이런 게 필요해서 영문 보고서가 기본소득 관련한 게 더 많이 치중돼서 발간됐다고 보시면 됩니다.
</p>
<p><b>○ 김현석 위원 </b> 전임 원장님 지시하신 건 아닌가요? 그리고 예전에 경기도 국감 자료 보니까 기본소득 관련해서 해외 언론매체 광고가 한 몇십억 나왔다 이렇게 본 것 같은데 이게 다 결부되어 있는 거 아닌지 합리적 의심이 들 수밖에 없어요. 경기연구원의 목적이 아까 부원장님 말씀하신 경기도 발전을 위한 정책 개발에 기여할 목적으로 하는 걸로 되어 있는데 실제적으로는 대권 공략을 위해서 이게 존재하는 거 아닌가. 자료를 보면 그렇지 않습니까? 영문 보고서 5건 중 4건이 다 기본소득이에요. 이거 어떻게 봐야 돼요? 경기연구원이 지사 개인을 위한 거 아니지 않습니까? 어떻게 봐야 됩니까, 이거?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 제가 어떤 답변을 드릴 수가 없는 질문이어서.
</p>
<p><b>○ 김현석 위원 </b> 알겠습니다. 답변드릴 수 있는 질문으로 넘어갈게요. 전임 원장님이 2021년 언제 퇴임하셨죠? 9월 6일 날 퇴임을 하셨어요. 그런데 사표를 8월 16일 날 제출하셨고요. 그런데 퇴임 전까지는 일단은 직위가 유지된다 이렇게 보면 되는 거죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 김현석 위원 </b> 그런데 경기연구원 정관 제26조에 저게 돼 있더라고요. 정치적 중립 유지 및 집단행위 금지. 직원은 정치적 중립을 유지해야 한다라고 되어 있는데 이분께서 8월 18일 날 보니까 이재명 전 지사의 대선 정책자문그룹 공동대표 맡고 그다음에는 정책본부장 맡고 이렇게 나와 있더라고요. 그러면 정관 위반 아닙니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 그거는 저도 날짜를 확인해 봐야 알겠습니다.
</p>
<p><b>○ 김현석 위원 </b> 언론에만, 그 기사 구글에 검색하면 바로 나와요, 이거.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 김현석 위원 </b> 이사회에서 이거와 관련돼서 논의조차 안 됐겠죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 논의된 적이 없습니다.
</p>
<p><b>○ 김현석 위원 </b> 이건 논의하셔야 될 것 같습니다. 지금 경기연구원 기본소득 관련된 거 자료요구를 하나 할게요. 기본소득연구단 관련돼서 3년간 8억 8,000만 원 쓴 걸로 되어 있어요. 기본소득 박람회 이런 거 빼고. 2020년도에 1억 9,000여만 원, 21년도에 5억 2,000여만 원, 22년도에 한 1억 7,000여만 원 이렇게 썼는데 사용내역 좀 서류로 부탁드리겠습니다. 
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 김현석 위원 </b> 이제 발언 마무리하기 전에 이거 한마디 좀 할게요. 작년 9월 우리 경기도의회 기획재정위원회 회의에서 전임 원장님이 이렇게 퇴임 인사를 하셨더라고요. “그동안 경기연구원이 어떤 역할들을 해야 하는지 조금 더 배우게 됐다.”며 “제 역할이 뭔가 조금 더 알게 되면서 떠나게 됐다.” 언론 인용입니다. 이렇게 말씀하셨는데. 글쎄요, 다음 경기연구원장님 내정됐고 이제 인사청문회 앞두고 있는데 저는 진짜 정말 바라고 싶어요. 경기연구원의 설립 목적대로 경기도의 발전을 위한 정책 개발에 기여할 목적으로 운영이 됐으면 좋겠어요.
</p>
<p style="padding-left:1.2em">  우리가 지금 도의회 도정질의 때도 그랬고 현 지사님 김동연 지사님께서 경기도정을 대권을 위한 발판으로 만들지 않았으면 좋겠다 말씀드렸거든요. 2020년도, 21년도 경기연구원 연구과제 연구보고서 보더라도 경기연구원 연구 부분들이 대권에 관해서 기여를 했다라고밖에 볼 수가 없어요, 이 자료들만 봤을 때는. 이 부분들에 대해서 다음 원장님께서는 제발 경기도민을 위해서 경기연구원의 설립 목적대로 운영을 했으면 하는 바람입니다. 이상입니다.
</p>
<p style="padding-left:2.4em">    (김철현 부위원장, 지미연 위원장과 사회교대)
</p>
<p><b>○ 위원장 지미연 </b> 김현석 위원님 수고하셨습니다. 이제 본질의를 마치고요. 보충질의를 하겠습니다. 먼저 신청하시는 위원님 먼저 하겠습니다. 김근용 위원님 보충질의하시기 바랍니다.
</p>
<p><b>○ 김근용 위원 </b> 평택 출신 김근용입니다. 간단한 질문 좀 하나 빠뜨린 게 있어서 드리겠습니다, 부원장님. 우리가 연구원에서 연구물을 결과물이 나오면 이걸 갖다가 배포도 하고 홍보도 하고 하시잖아요. 물론 홈페이지에 하는 거는 기본일 것 같고 책자 발행을 하시죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 김근용 위원 </b> 몇 부 정도 합니까, 보통?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 50부에서 100부 정도 합니다, 과제당.
</p>
<p><b>○ 김근용 위원 </b> 그러면 책자 말고 또 다른 예를 들어 CD라든지 USB 이런 걸로도 저기를 하나요, 책을?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> PDF하고 한글로 만들어서 파일로 저희 연구원 홈페이지에 게시합니다.
</p>
<p><b>○ 김근용 위원 </b> 게시하고 CD나 USB로 따로 또 해 가지고 어디 기관에 보낸다든지 그런…….
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 요청하시면 그렇게 하지만 홈페이지에 올리면 거기서 다운받으실 수 있기 때문에 별도로 하고 있지는 않습니다.
</p>
<p><b>○ 김근용 위원 </b> 그러면 책자하고 홈페이지 게재하는 걸로, 그 두 가지로 끝난다는 얘기죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 그다음에 연구 결과를 가공해서, 아까 말씀하신 유튜브나 여러 가지 다른 형태로 가공해서 만들어서 홍보에 활용하고 있습니다.
</p>
<p><b>○ 김근용 위원 </b> 지금 같은 방식의 홍보를 언제부터 했는지 혹시 기억하십니까, 대충? 예를 들어서 2000몇 년도부터는 이런 식으로 지금까지 진행이 되고 있다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 예전에 한 5~6년 전에는 저희가 연구보고서를 한 250부 이상 이렇게 발행을 했습니다. 그런데 최근 들어서는 발행부수는 점차 줄이고 그다음에 다운받을 수 있는 디지털 파일 형태로 하는 것 쪽으로 전환하고 있는데 그거는 지난 원장님 오셔서 더 강화됐습니다.
</p>
<p><b>○ 김근용 위원 </b> 그러면 출판 비용이라든지 이런 건 별로 들지 않겠네요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 출판 비용을 많이 줄였습니다.
</p>
<p><b>○ 김근용 위원 </b> 네, 알겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 지미연 </b> 김근용 위원님 수고하셨습니다. 이채명 위원님 질의하시기 바랍니다.
</p>
<p><b>○ 이채명 위원 </b> 안양 출신 이채명 위원입니다. 간단하게 제가 부연설명을 좀 드리고 싶은데요. 부원장님, 아까 정원이 현원 대비해서 지금 4명이 더 많잖아요? 정원이 187명이고 현원이 지금 183명이라고 말씀을 주셨습니다, 맞죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 이채명 위원 </b> 제가 아는 상식으로는 지금 지방출자ㆍ출연기관 예산편성지침과 집행기준에는 이 정원은 현원 대비 결원 5%를 초과할 수 없습니다. 지금 5% 초과 안 됐어요. 그리고 지방출자ㆍ출연기관의 예산편성지침이라든가 집행기준은 행안부 예산편성 기준에 있습니다. 그리고 정원에 대한 인건비가 지출 예산상의 인건비 항목 안에 들어 있고요. 제가 알고 있는 기준으로는요. 그리고 정원 외 임시적으로 쓰시는 분들 있잖아요, 수탁연구를 위해서. 그분들 직원에 대한 인건비는 사업계정 안에 들어 있는 수탁연구비 안의 인건비로 아마 잡혀 있을 것입니다. 그래서 그런 부분들을 다시 한번 검토해 주시기 바랍니다.
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네, 검토해 보겠습니다.
</p>
<p><b>○ 이채명 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 지미연 </b> 이채명 위원님 수고하셨습니다. 김철현 위원님 질의하시기 바랍니다.
</p>
<p><b>○ 김철현 위원 </b> 안양 출신 김철현입니다. 아까 시간이 없는 관계로 준비했던 질의가 하나 빠져 가지고요. 간단하게 한번 질의를 해 보겠습니다. 지난 도정질문에서도 저는 김동연 지사의 핵심 공약인 경기북부특별자치도 설치와 현재 추진되고 있는 공공기관 이전은 양립될 수 없는 관계가 아니냐라고 질문을 던졌었는데요. 그 당시에 대답은 행정의 일관성이라든가 이런 부분들 때문에 공공기관 이전은 계속 추진된다라고 이런 답변을 하는데 지금 우리가 경기연구원 외 연구기관에서는 경기도의 중장기 비전 제시와 정책 개발 기능을 수행하고 있죠?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 네.
</p>
<p><b>○ 김철현 위원 </b> 그런데 도지사에 따라서 연구 방향이 바뀌거나 이런 중장기적인 정책을 제시하지 못하는 상황들이 발생을 하고 있는 것 같습니다. 당초에 남경필 지사 때는 경기북부 10개년 계획이라는 용역을 수행했고요. 이재명 지사 때는 경기북부 4대 전략이라는 용역을 수행해서 대부분이 그때만 해도 경기동북부, 경기북부 지역에 대해서 규제라든가 이런 낙후된 지역에 대한 발전을 위해서 균형 발전을 추진하기 위해서 공공기관을 이전한다고 했다가 어느 날 갑자기 대선주자들이 어떻게 보면 정말 경기북부 분도를 주장하면서 북부특별자치도 설치를 공약으로 내세우게 되고 인수위원회에서 이 부분을 주요공약으로 채택을 해서 지금 TF팀이 만들어진 걸로 알고 있습니다. 이 업무보고서에 따르면 6페이지에요, 맨 밑에. 경기북부특별자치도 설치 및 북부 발전전략 수립 기초연구 이 부분이 지금 연구가 완료가 된 겁니까, 아니면 연구를 하겠다는 겁니까?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 이 부분도 관련 센터장이 답변드려도 되겠습니까?
</p>
<p><b>○ 김철현 위원 </b> 네.
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 북부연구센터장 이정훈입니다. 이 연구는 TF가 만들어지고 저희들이 기초적인 경기북부에 관련된 데이터와 기본적인 사항들을 파악하고 경기도의 TF와 코웍(co-work)을 하는 그런 차원에서 지금 현재 진행되고 있는 과제입니다.
</p>
<p><b>○ 김철현 위원 </b> 현재 그러면 북부 이전 관련 문제점 등에 대한 검토도 지금 하고 있습니까?
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 저희 연구에는 공공기관 이전에 관한 문제는 기본적으로 다루지는 않고요. 특별자치도 혹은 분도가 되게 되면 행정부의 정원 그다음에 기관들을 어떻게 할지에 대해서는 본격적으로 연구를 해야 되는데요. 이건 아직 기초연구 단계이기 때문에 그런 구체적인 검토까지는 저희가 하고 있지는 않습니다.
</p>
<p><b>○ 김철현 위원 </b> 분도 관련해서 연구의 필요성들이 계속적으로 제기가 되고 있었죠, 전에도요.
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 논의는 있었습니다.
</p>
<p><b>○ 김철현 위원 </b> 혹시 경기연구원에서 이 부분에 대해서 용역을 수행한 실적이 있습니까?
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 저도 그런 거에 대해서 지금 연구단을 맡고 있는 차원에서 좀 찾아봤는데요. 공개된 연구보고서는 제가 찾지를 못해서 사실상 새로 시작을 하는 연구로 보시면 됩니다. 
</p>
<p><b>○ 김철현 위원 </b> 저는 질의를 정리하게 되면 현재 김동연 지사의 북부특별자치도 설치와 공공기관 이전에 대한 부분들은 전면적으로 재검토를 해야 되지 않느냐라는 생각을 합니다. 거기에서 경기연구원은 3차 대상으로서 이전하고 이러는 부분들은 아직 멀리 있지만 실제적으로 1차든 2차든 이렇게 다가오는 공공기관들에서는 직원들뿐만 아니라 지금 상당히 혼선이 오고 가고 있는데요. 북부특별자치도가 만들어진다라고 할 경우에는 결국은 그곳에서도 따로 또한 공공기관들이 다 설치가 될 텐데 결국은 이 부분들은 이중적인 투자가 되지 않나 그래서 저는 이 부분에 대해서는 경기연구원에서 공공기관 이전에 대한 부분들을 재검토할 필요가 있다라고 생각을 합니다. 그런 부분들에 대해서 주제를 가지고 한번 검토해 보실 의향이 있으십니까?
</p>
<p><b>○ 북부연구센터장 이정훈 </b> 일단 그 문제는 저희가 맡고 있는 특별자치도 문제와 아주 직접적 관련을 갖고 있다고 보기는 조금 어려워서요. 그 문제는 도하고 한번 이런 질의가 있으셨다고 논의를 해서 검토를 해 보겠습니다.
</p>
<p><b>○ 김철현 위원 </b> 알겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 지미연 </b> 김철현 위원님 수고하셨습니다. 또 질의하실 위원님 안 계십니까? 정경자 위원님 질의하시기 바랍니다.
</p>
<p><b>○ 정경자 위원 </b> 늦게까지 수고 많으십니다. 저도 간단하게 질의하겠습니다. 서울연구원과 연구과제 실적 비교했을 때도 정규 박사 수가 서울은 2020년, 2021년 73명이고 우리 경기연구원은 62명입니다. 그런데 연구 결과를 봤을 때 정책연구 과제를 서울은 65개, 2021년은 75개 그런데 우리 경기연구원은 141개, 148개. 연구 박사님 인원 수는 훨씬 적은데 어떻게 보면 곱절의 연구를 해 주셨습니다. 이렇게 능력치 많으신 연구원들께서 2022년에는 물론 연구직 박사 수가 3명이 줄어들기는 했네요. 그런데 보니까 2020년, 21년에 비해서 현저하게 지금 연구 과제가 줄어들었어요. 2020년 205개, 2021년 201개 근데 2022년은 69개. 그니까 지금 이게 기준은 9월 30일이라고 하지만 거의 올해 2022년 4분의 3이 지나갔지 않습니까? 최소 절반 이상은 돼야 되는데 어떻게 이렇게 현저하게 지금 과제 건수가 줄어들었을까요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 저희가 이렇게 앞에 보신 것처럼 엄청난 숫자의 과제를 수행하다 보니 연구원들이 굉장히 질 관리를 하기가 힘들고 어려움을 많이 표했습니다. 그래서 지난 원장님이 퇴임하시기 전에 저희가 얘기를 해서 전체 대표 과제 수를 원래는 최소 세 과제였는데 최소 두 과제로 낮췄습니다. 그래서 연구의 질적인 관리하고 질적인 부분에 조금 신경을 쓸 수 있도록 해 달라고 해서 그 부분을 수정하고 난 첫 번째 해이기 때문에 전체적으로 아마 저희가 12월 말이 되면 180과제 정도 할 예정입니다. 그런데 연구과제 특성상 대개 이렇게 연말에 끝나는 과제들이 많다 보니 지금 9월 현재 완료된 과제가 69개이고 12월 말에는 한 180과제 정도 저희 예상하고 있습니다.
</p>
<p><b>○ 정경자 위원 </b> 수치상으로만 우선 보다 보니 그동안은 1인당 수행 건수가 이제 거의 3건 이상은 됐는데 지금까지는 봤을 때 겨우 1건이 되다 보니까 좀 그렇고. 지금 제가 안 그래도 경기연구원 홈페이지 들어가서도 보고 하는데 참 양질의 연구 부분에 있어서 저희가 보는 데 참 많은 도움이 되고 있습니다. 그래서 이런 좋은 정책들에 대해서 환류라고 하지 않았습니까? 정책 반영이 분명히 많이 될 텐데 그 부분에 대해서 어떻게 경기원구원에서 따로 이렇게 체크하거나 하는 그런 부분이 있나요?
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 예를 들면 저희가 도하고는 굉장히 긴밀한 관계를 가지고 있고 연구의 수요라든가 제안 같은 것을 적극적으로 수용해서 항상 늘상 협의를 해서 수행하고 있고요. 도의회하고는 원래는 의정포럼이나 아니면 의원님들이 연구회 활동하시면 그 연구회 지원도 하고 그다음에 의원님들 각각의 연구활동하실 때 저희가 포럼이나 지역 현안 세미나나 여러 가지 다양한 측면에서 지원을 해 드리는데 올해 여러 가지 정치적 여건이 조금 그게 어려워서 저희가 의정포럼도 아직 구성을 못 하고 구성 중에 있고 그다음에 다른 여타 의정활동 지원은 조금 미진한 형편입니다. 그런데 어쨌든 저희는 집행부하고 입법부하고의 사이에서 적절하게 균형을 가지고 아까 말씀하신 대로 어떤 특정한 분의 정치적인 활동을 지원하는 게 아니라 도정하고 도의회의 활동을 지원하는 역할에 충실하려고 노력을 하고 있습니다.
</p>
<p><b>○ 정경자 위원 </b> 네, 앞으로도…….
</p>
<p><b>○ 경기연구원장직무대행 송미영 </b> 많이 활용해 주셨으면 좋겠고 오늘 제안해 주신 것처럼 여러 제안이나 고견을 주시면 저희가 저희 연구 활동에 반영하도록 하겠습니다.
</p>
<p><b>○ 정경자 위원 </b> 경기연구원 아까도 말씀드렸듯이, 저도 저녁, 밤이 되니까 이제 말이 꼬이네요. 힘드시죠? 전부 다 힘드실 것 같습니다. 그러니까 우리 경기도의 싱크탱크로서 부심을 가지고 정말 앞으로도 많이 노력해 주시길 바라겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 지미연 </b> 정경자 위원님 수고하셨습니다. 더 질의하실 위원님 안 계십니까?
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음) 
</p>
<p style="padding-left:1.2em">  질의하실 위원님이 안 계시므로 이상으로 경기연구원 소관 사항에 대한 질의와 답변을 모두 마치겠습니다. 
</p>
<p style="padding-left:1.2em">  위원님 여러분 그리고 송미영 연구부원장을 비롯한 관계자 여러분! 아직 안 끝났습니다. 앉으십시오. 행정사무감사를 준비하신 위원님들과 위원님들의 자료요구 준비와 질의에 성의를 다해 답변해 주신 경기연구원 관계자 여러분께 감사드립니다. 송미영 연구부원장을 비롯한 경기연구원 관계자 여러분께서는 오늘 여러 위원님들께서 지적해 주신 사항은 도민의 의견인 만큼 도정에 적극 반영해 주시기 바랍니다. 또한 오늘 감사 중에 위원들께서 개선을 요구한 사항에 대해서도 조속히 시정될 수 있도록 노력해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  위원님 여러분 그리고 관계자 여러분! 수고하셨습니다. 이상으로 경기연구원 소관 사항에 대한 2022년도 행정사무감사를 종료합니다. 내일은 평화협력국 소관 사항에 대해 북부청에서 행정사무감사를 실시하고 11월 14일에는 기획재정위원회 소관 전체 기관을 대상으로 종합감사를 실시하겠습니다. 오늘의 행정사무감사를 모두 마치겠습니다. 산회를 선포합니다.
</p>
<p class=''ar''>(21시41분 감사종료)
</p>
<p><hr /></p>
